-- BSB verses (4427). Requires books and chapters first.
insert into public.verses (chapter_id, number, osis_ref, text)
select c.id, x.verse, x.ref, x.body
from (values
('JER', 23, 15, 'JER.23.15', 'Therefore this is what the LORD of Hosts says concerning the prophets: “I will feed them wormwood and give them poisoned water to drink, for from the prophets of Jerusalem ungodliness has spread throughout the land.”'),
('JER', 23, 16, 'JER.23.16', 'This is what the LORD of Hosts says: “Do not listen to the words of the prophets who prophesy to you. They are filling you with false hopes. They speak visions from their own minds, not from the mouth of the LORD.'),
('JER', 23, 17, 'JER.23.17', 'They keep saying to those who despise Me, ‘The LORD says that you will have peace,’ and to everyone who walks in the stubbornness of his own heart, ‘No harm will come to you.’'),
('JER', 23, 18, 'JER.23.18', 'But which of them has stood in the council of the LORD to see and hear His word? Who has given heed to His word and obeyed it?'),
('JER', 23, 19, 'JER.23.19', 'Behold, the storm of the LORD has gone out with fury, a whirlwind swirling down upon the heads of the wicked.'),
('JER', 23, 20, 'JER.23.20', 'The anger of the LORD will not turn back until He has fully accomplished the purposes of His heart. In the days to come you will understand this clearly.'),
('JER', 23, 21, 'JER.23.21', 'I did not send these prophets, yet they have run with their message; I did not speak to them, yet they have prophesied.'),
('JER', 23, 22, 'JER.23.22', 'But if they had stood in My council, they would have proclaimed My words to My people and turned them back from their evil ways and deeds.”'),
('JER', 23, 23, 'JER.23.23', '“Am I only a God nearby,” declares the LORD, “and not a God far away?”'),
('JER', 23, 24, 'JER.23.24', '“Can a man hide in secret places where I cannot see him?” declares the LORD. “Do I not fill the heavens and the earth?” declares the LORD.'),
('JER', 23, 25, 'JER.23.25', '“I have heard the sayings of the prophets who prophesy lies in My name: ‘I had a dream! I had a dream!’'),
('JER', 23, 26, 'JER.23.26', 'How long will this continue in the hearts of these prophets who prophesy falsehood, these prophets of the delusion of their own minds?'),
('JER', 23, 27, 'JER.23.27', 'They suppose the dreams that they tell one another will make My people forget My name, just as their fathers forgot My name through the worship of Baal.'),
('JER', 23, 28, 'JER.23.28', 'Let the prophet who has a dream retell it, but let him who has My word speak it truthfully. For what is straw compared to grain?” declares the LORD.'),
('JER', 23, 29, 'JER.23.29', '“Is not My word like fire,” declares the LORD, “and like a hammer that smashes a rock?”'),
('JER', 23, 30, 'JER.23.30', '“Therefore behold,” declares the LORD, “I am against the prophets who steal from one another words they attribute to Me.”'),
('JER', 23, 31, 'JER.23.31', '“Yes,” declares the LORD, “I am against the prophets who wag their own tongues and proclaim, ‘The LORD declares it.’”'),
('JER', 23, 32, 'JER.23.32', '“Indeed,” declares the LORD, “I am against those who prophesy false dreams and retell them to lead My people astray with their reckless lies. It was not I who sent them or commanded them, and they are of no benefit at all to these people,” declares the LORD.'),
('JER', 23, 33, 'JER.23.33', '“Now when this people or a prophet or priest asks you, ‘What is the burden of the LORD?’ you are to say to them, ‘What burden? I will forsake you, declares the LORD.’'),
('JER', 23, 34, 'JER.23.34', 'As for the prophet or priest or anyone who claims, ‘This is the burden of the LORD,’ I will punish that man and his household.'),
('JER', 23, 35, 'JER.23.35', 'This is what each man is to say to his friend and to his brother: ‘What has the LORD answered?’ or ‘What has the LORD spoken?’'),
('JER', 23, 36, 'JER.23.36', 'But refer no more to the burden of the LORD, for each man’s word becomes the burden, so that you pervert the words of the living God, the LORD of Hosts, our God.'),
('JER', 23, 37, 'JER.23.37', 'Thus you are to say to the prophet: ‘What has the LORD answered you?’ and ‘What has the LORD spoken?’'),
('JER', 23, 38, 'JER.23.38', 'But if you claim, ‘This is the burden of the LORD,’ then this is what the LORD says: Because you have said, ‘This is the burden of the LORD,’ and I specifically told you not to make this claim,'),
('JER', 23, 39, 'JER.23.39', 'therefore I will surely forget you and will cast you out of My presence, both you and the city that I gave to you and your fathers.'),
('JER', 23, 40, 'JER.23.40', 'And I will bring upon you everlasting shame and perpetual humiliation that will never be forgotten.”'),
('JER', 24, 1, 'JER.24.1', 'After Nebuchadnezzar king of Babylon had carried away Jeconiah son of Jehoiakim king of Judah, as well as the officials of Judah and the craftsmen and metalsmiths from Jerusalem, and had brought them to Babylon, the LORD showed me two baskets of figs placed in front of the temple of the LORD.'),
('JER', 24, 2, 'JER.24.2', 'One basket had very good figs, like those that ripen early, but the other basket contained very poor figs, so bad they could not be eaten.'),
('JER', 24, 3, 'JER.24.3', '“Jeremiah,” the LORD asked, “what do you see?” “Figs!” I replied. “The good figs are very good, but the bad figs are very bad, so bad they cannot be eaten.”'),
('JER', 24, 4, 'JER.24.4', 'Then the word of the LORD came to me, saying,'),
('JER', 24, 5, 'JER.24.5', '“This is what the LORD, the God of Israel, says: ‘Like these good figs, so I regard as good the exiles from Judah, whom I have sent away from this place to the land of the Chaldeans.'),
('JER', 24, 6, 'JER.24.6', 'I will keep My eyes on them for good and will return them to this land. I will build them up and not tear them down; I will plant them and not uproot them.'),
('JER', 24, 7, 'JER.24.7', 'I will give them a heart to know Me, that I am the LORD. They will be My people, and I will be their God, for they will return to Me with all their heart.'),
('JER', 24, 8, 'JER.24.8', 'But like the bad figs, so bad they cannot be eaten,’ says the LORD, ‘so will I deal with Zedekiah king of Judah, his officials, and the remnant of Jerusalem—those remaining in this land and those living in the land of Egypt.'),
('JER', 24, 9, 'JER.24.9', 'I will make them a horror and an offense to all the kingdoms of the earth, a disgrace and an object of scorn, ridicule, and cursing wherever I have banished them.'),
('JER', 24, 10, 'JER.24.10', 'And I will send against them sword and famine and plague, until they have perished from the land that I gave to them and their fathers.’”'),
('JER', 25, 1, 'JER.25.1', 'This is the word that came to Jeremiah concerning all the people of Judah in the fourth year of Jehoiakim son of Josiah king of Judah, which was the first year of Nebuchadnezzar king of Babylon.'),
('JER', 25, 2, 'JER.25.2', 'So the prophet Jeremiah spoke to all the people of Judah and all the residents of Jerusalem as follows:'),
('JER', 25, 3, 'JER.25.3', '“From the thirteenth year of Josiah son of Amon king of Judah until this very day—twenty-three years—the word of the LORD has come to me, and I have spoken to you again and again, but you have not listened.'),
('JER', 25, 4, 'JER.25.4', 'And the LORD has sent all His servants the prophets to you again and again, but you have not listened or inclined your ear to hear.'),
('JER', 25, 5, 'JER.25.5', 'The prophets told you, ‘Turn now, each of you, from your evil ways and deeds, and you can dwell in the land that the LORD has given to you and your fathers forever and ever.'),
('JER', 25, 6, 'JER.25.6', 'Do not follow other gods to serve and worship them, and do not provoke Me to anger with the works of your hands. Then I will do you no harm.’'),
('JER', 25, 7, 'JER.25.7', '‘But to your own harm, you have not listened to Me,’ declares the LORD, ‘so you have provoked Me to anger with the works of your hands.’'),
('JER', 25, 8, 'JER.25.8', 'Therefore this is what the LORD of Hosts says: ‘Because you have not obeyed My words,'),
('JER', 25, 9, 'JER.25.9', 'behold, I will summon all the families of the north, declares the LORD, and I will send for My servant Nebuchadnezzar king of Babylon, whom I will bring against this land, against its residents, and against all the surrounding nations. So I will devote them to destruction and make them an object of horror and contempt, an everlasting desolation.'),
('JER', 25, 10, 'JER.25.10', 'Moreover, I will banish from them the sounds of joy and gladness, the voices of the bride and bridegroom, the sound of the millstones, and the light of the lamp.'),
('JER', 25, 11, 'JER.25.11', 'And this whole land will become a desolate wasteland, and these nations will serve the king of Babylon for seventy years.'),
('JER', 25, 12, 'JER.25.12', 'But when seventy years are complete, I will punish the king of Babylon and that nation, the land of the Chaldeans, for their guilt, declares the LORD, and I will make it an everlasting desolation.'),
('JER', 25, 13, 'JER.25.13', 'I will bring upon that land all the words I have pronounced against it, all that is written in this book, which Jeremiah has prophesied against all the nations.'),
('JER', 25, 14, 'JER.25.14', 'For many nations and great kings will enslave them, and I will repay them according to their deeds and according to the work of their hands.’”'),
('JER', 25, 15, 'JER.25.15', 'This is what the LORD, the God of Israel, said to me: “Take from My hand this cup of the wine of wrath, and make all the nations to whom I send you drink from it.'),
('JER', 25, 16, 'JER.25.16', 'And they will drink and stagger and go out of their minds, because of the sword that I will send among them.”'),
('JER', 25, 17, 'JER.25.17', 'So I took the cup from the LORD’s hand and made all the nations drink from it, each one to whom the LORD had sent me,'),
('JER', 25, 18, 'JER.25.18', 'to make them a ruin, an object of horror and contempt and cursing, as they are to this day—Jerusalem and the cities of Judah, its kings and officials;'),
('JER', 25, 19, 'JER.25.19', 'Pharaoh king of Egypt, his officials, his leaders, and all his people;'),
('JER', 25, 20, 'JER.25.20', 'all the mixed tribes; all the kings of Uz; all the kings of the Philistines: Ashkelon, Gaza, Ekron, and the remnant of Ashdod;'),
('JER', 25, 21, 'JER.25.21', 'Edom, Moab, and the Ammonites;'),
('JER', 25, 22, 'JER.25.22', 'all the kings of Tyre and Sidon; the kings of the coastlands across the sea;'),
('JER', 25, 23, 'JER.25.23', 'Dedan, Tema, Buz, and all who cut the corners of their hair;'),
('JER', 25, 24, 'JER.25.24', 'all the kings of Arabia, and all the kings of the mixed tribes who dwell in the desert;'),
('JER', 25, 25, 'JER.25.25', 'all the kings of Zimri, Elam, and Media;'),
('JER', 25, 26, 'JER.25.26', 'all the kings of the north, both near and far, one after another—all the kingdoms on the face of the earth. And after all of them, the king of Sheshach will drink it too.'),
('JER', 25, 27, 'JER.25.27', '“Then you are to tell them that this is what the LORD of Hosts, the God of Israel, says: ‘Drink, get drunk, and vomit. Fall down and never get up again, because of the sword I will send among you.’'),
('JER', 25, 28, 'JER.25.28', 'If they refuse to take the cup from your hand and drink it, you are to tell them that this is what the LORD of Hosts says: ‘You most certainly must drink it!'),
('JER', 25, 29, 'JER.25.29', 'For behold, I am beginning to bring disaster on the city that bears My Name, so how could you possibly go unpunished? You will not go unpunished, for I am calling down a sword upon all the inhabitants of the earth, declares the LORD of Hosts.’'),
('JER', 25, 30, 'JER.25.30', 'So you are to prophesy all these words against them and say to them: ‘The LORD will roar from on high; He will raise His voice from His holy habitation. He will roar loudly over His pasture; like those who tread the grapes, He will call out with a shout against all the inhabitants of the earth.'),
('JER', 25, 31, 'JER.25.31', 'The tumult will resound to the ends of the earth because the LORD brings a charge against the nations. He brings judgment on all mankind and puts the wicked to the sword,’” declares the LORD.'),
('JER', 25, 32, 'JER.25.32', 'This is what the LORD of Hosts says: “Behold! Disaster is spreading from nation to nation; a mighty storm is rising from the ends of the earth.”'),
('JER', 25, 33, 'JER.25.33', 'Those slain by the LORD on that day will be spread from one end of the earth to the other. They will not be mourned, gathered, or buried. They will be like dung lying on the ground.'),
('JER', 25, 34, 'JER.25.34', 'Wail, you shepherds, and cry out; roll in the dust, you leaders of the flock. For the days of your slaughter have come; you will fall and be shattered like fine pottery.'),
('JER', 25, 35, 'JER.25.35', 'Flight will evade the shepherds, and escape will elude the leaders of the flock.'),
('JER', 25, 36, 'JER.25.36', 'Hear the cry of the shepherds, the wailing of the leaders of the flock, for the LORD is destroying their pasture.'),
('JER', 25, 37, 'JER.25.37', 'The peaceful meadows have been silenced because of the LORD’s burning anger.'),
('JER', 25, 38, 'JER.25.38', 'He has left His den like a lion, for their land has been made a desolation by the sword of the oppressor, and because of the fierce anger of the LORD.'),
('JER', 26, 1, 'JER.26.1', 'At the beginning of the reign of Jehoiakim son of Josiah king of Judah, this word came from the LORD:'),
('JER', 26, 2, 'JER.26.2', '“This is what the LORD says: Stand in the courtyard of the house of the LORD and speak all the words I have commanded you to speak to all the cities of Judah who come to worship there. Do not omit a word.'),
('JER', 26, 3, 'JER.26.3', 'Perhaps they will listen and turn—each from his evil way of life—so that I may relent of the disaster I am planning to bring upon them because of the evil of their deeds.'),
('JER', 26, 4, 'JER.26.4', 'And you are to tell them that this is what the LORD says: ‘If you do not listen to Me and walk in My law, which I have set before you,'),
('JER', 26, 5, 'JER.26.5', 'and if you do not listen to the words of My servants the prophets, whom I have sent you again and again even though you did not listen,'),
('JER', 26, 6, 'JER.26.6', 'then I will make this house like Shiloh, and I will make this city an object of cursing among all the nations of the earth.’”'),
('JER', 26, 7, 'JER.26.7', 'Now the priests and prophets and all the people heard Jeremiah speaking these words in the house of the LORD,'),
('JER', 26, 8, 'JER.26.8', 'and as soon as he had finished telling all the people everything the LORD had commanded him to say, the priests and prophets and all the people seized him, shouting, “You must surely die!'),
('JER', 26, 9, 'JER.26.9', 'How dare you prophesy in the name of the LORD that this house will become like Shiloh and this city will be desolate and deserted!” And all the people assembled against Jeremiah in the house of the LORD.'),
('JER', 26, 10, 'JER.26.10', 'When the officials of Judah heard these things, they went up from the king’s palace to the house of the LORD and sat there at the entrance of the New Gate.'),
('JER', 26, 11, 'JER.26.11', 'Then the priests and prophets said to the officials and all the people, “This man is worthy of death, for he has prophesied against this city, as you have heard with your own ears!”'),
('JER', 26, 12, 'JER.26.12', 'But Jeremiah said to all the officials and all the people, “The LORD sent me to prophesy against this house and against this city all the words that you have heard.'),
('JER', 26, 13, 'JER.26.13', 'So now, correct your ways and deeds, and obey the voice of the LORD your God, so that He might relent of the disaster He has pronounced against you.'),
('JER', 26, 14, 'JER.26.14', 'As for me, here I am in your hands; do to me what you think is good and right.'),
('JER', 26, 15, 'JER.26.15', 'But know for certain that if you put me to death, you will bring innocent blood upon yourselves, upon this city, and upon its residents; for truly the LORD has sent me to speak all these words in your hearing.”'),
('JER', 26, 16, 'JER.26.16', 'Then the officials and all the people told the priests and prophets, “This man is not worthy of death, for he has spoken to us in the name of the LORD our God!”'),
('JER', 26, 17, 'JER.26.17', 'Some of the elders of the land stood up and said to the whole assembly of the people,'),
('JER', 26, 18, 'JER.26.18', '“Micah the Moreshite prophesied in the days of Hezekiah king of Judah and told all the people of Judah that this is what the LORD of Hosts says: ‘Zion will be plowed like a field, Jerusalem will become a heap of rubble, and the temple mount a wooded ridge.’'),
('JER', 26, 19, 'JER.26.19', 'Did Hezekiah king of Judah or anyone else in Judah put him to death? Did Hezekiah not fear the LORD and seek His favor, and did not the LORD relent of the disaster He had pronounced against them? But we are about to bring great harm on ourselves!”'),
('JER', 26, 20, 'JER.26.20', 'Now there was another man prophesying in the name of the LORD, Uriah son of Shemaiah from Kiriath-jearim. He prophesied against this city and against this land the same things that Jeremiah did.'),
('JER', 26, 21, 'JER.26.21', 'King Jehoiakim and all his mighty men and officials heard his words, and the king sought to put him to death. But when Uriah found out about it, he fled in fear and went to Egypt.'),
('JER', 26, 22, 'JER.26.22', 'Then King Jehoiakim sent men to Egypt: Elnathan son of Achbor along with some other men.'),
('JER', 26, 23, 'JER.26.23', 'They brought Uriah out of Egypt and took him to King Jehoiakim, who had him put to the sword and his body thrown into the burial place of the common people.'),
('JER', 26, 24, 'JER.26.24', 'Nevertheless, Ahikam son of Shaphan supported Jeremiah, so he was not handed over to the people to be put to death.'),
('JER', 27, 1, 'JER.27.1', 'At the beginning of the reign of Zedekiah son of Josiah king of Judah, this word came to Jeremiah from the LORD.'),
('JER', 27, 2, 'JER.27.2', 'This is what the LORD said to me: “Make for yourself a yoke out of leather straps and put it on your neck.'),
('JER', 27, 3, 'JER.27.3', 'Send word to the kings of Edom, Moab, Ammon, Tyre, and Sidon through the envoys who have come to Jerusalem to Zedekiah king of Judah.'),
('JER', 27, 4, 'JER.27.4', 'Give them a message from the LORD of Hosts, the God of Israel, to relay to their masters:'),
('JER', 27, 5, 'JER.27.5', 'By My great power and outstretched arm, I made the earth and the men and beasts on the face of it, and I give it to whom I please.'),
('JER', 27, 6, 'JER.27.6', 'So now I have placed all these lands under the authority of My servant Nebuchadnezzar king of Babylon. I have even made the beasts of the field subject to him.'),
('JER', 27, 7, 'JER.27.7', 'All nations will serve him and his son and grandson, until the time of his own land comes; then many nations and great kings will enslave him.'),
('JER', 27, 8, 'JER.27.8', 'As for the nation or kingdom that does not serve Nebuchadnezzar king of Babylon and does not place its neck under his yoke, I will punish that nation by sword and famine and plague, declares the LORD, until I have destroyed it by his hand.'),
('JER', 27, 9, 'JER.27.9', 'But as for you, do not listen to your prophets, your diviners, your interpreters of dreams, your mediums, or your sorcerers who declare, ‘You will not serve the king of Babylon.’'),
('JER', 27, 10, 'JER.27.10', 'For they prophesy to you a lie that will serve to remove you from your land; I will banish you and you will perish.'),
('JER', 27, 11, 'JER.27.11', 'But the nation that will put its neck under the yoke of the king of Babylon and serve him, I will leave in its own land, to cultivate it and reside in it, declares the LORD.”'),
('JER', 27, 12, 'JER.27.12', 'And to Zedekiah king of Judah I spoke the same message: “Put your necks under the yoke of the king of Babylon; serve him and his people, and live!'),
('JER', 27, 13, 'JER.27.13', 'Why should you and your people die by sword and famine and plague, as the LORD has decreed against any nation that does not serve the king of Babylon?'),
('JER', 27, 14, 'JER.27.14', 'Do not listen to the words of the prophets who say, ‘You must not serve the king of Babylon,’ for they are prophesying to you a lie.'),
('JER', 27, 15, 'JER.27.15', 'For I have not sent them, declares the LORD, and yet they are prophesying falsely in My name; therefore I will banish you, and you will perish—you and the prophets who prophesy to you.”'),
('JER', 27, 16, 'JER.27.16', 'Then I said to the priests and to all this people, “This is what the LORD says: Do not listen to the words of your prophets who prophesy to you, saying, ‘Look, very soon now the articles from the house of the LORD will be brought back from Babylon.’ They are prophesying to you a lie.'),
('JER', 27, 17, 'JER.27.17', 'Do not listen to them. Serve the king of Babylon and live! Why should this city become a ruin?'),
('JER', 27, 18, 'JER.27.18', 'If they are indeed prophets and the word of the LORD is with them, let them now plead with the LORD of Hosts that the articles remaining in the house of the LORD, in the palace of the king of Judah, and in Jerusalem, not be taken to Babylon.'),
('JER', 27, 19, 'JER.27.19', 'For this is what the LORD of Hosts says about the pillars, the sea, the bases, and the rest of the articles that remain in this city,'),
('JER', 27, 20, 'JER.27.20', 'which Nebuchadnezzar king of Babylon did not take when he carried Jeconiah son of Jehoiakim king of Judah into exile from Jerusalem to Babylon, along with all the nobles of Judah and Jerusalem.'),
('JER', 27, 21, 'JER.27.21', 'Yes, this is what the LORD of Hosts, the God of Israel, says about the articles that remain in the house of the LORD, in the palace of the king of Judah, and in Jerusalem:'),
('JER', 27, 22, 'JER.27.22', '‘They will be carried to Babylon and will remain there until the day I attend to them again,’ declares the LORD. ‘Then I will bring them back and restore them to this place.’”'),
('JER', 28, 1, 'JER.28.1', 'In the fifth month of that same year, the fourth year, near the beginning of the reign of King Zedekiah of Judah, the prophet Hananiah son of Azzur, who was from Gibeon, said to me in the house of the LORD in the presence of the priests and all the people:'),
('JER', 28, 2, 'JER.28.2', '“This is what the LORD of Hosts, the God of Israel, says: ‘I have broken the yoke of the king of Babylon.'),
('JER', 28, 3, 'JER.28.3', 'Within two years I will restore to this place all the articles of the house of the LORD that Nebuchadnezzar king of Babylon removed from here and carried to Babylon.'),
('JER', 28, 4, 'JER.28.4', 'And I will restore to this place Jeconiah son of Jehoiakim king of Judah, along with all the exiles from Judah who went to Babylon,’ declares the LORD, ‘for I will break the yoke of the king of Babylon.’”'),
('JER', 28, 5, 'JER.28.5', 'Then the prophet Jeremiah replied to the prophet Hananiah in the presence of the priests and all the people who were standing in the house of the LORD.'),
('JER', 28, 6, 'JER.28.6', '“Amen!” Jeremiah said. “May the LORD do so! May the LORD fulfill the words you have prophesied, and may He restore the articles of His house and all the exiles back to this place from Babylon.'),
('JER', 28, 7, 'JER.28.7', 'Nevertheless, listen now to this message I am speaking in your hearing and in the hearing of all the people.'),
('JER', 28, 8, 'JER.28.8', 'The prophets of old who preceded you and me prophesied war, disaster, and plague against many lands and great kingdoms.'),
('JER', 28, 9, 'JER.28.9', 'As for the prophet who prophesies peace, only if the word of the prophet comes true will the prophet be recognized as one the LORD has truly sent.”'),
('JER', 28, 10, 'JER.28.10', 'Then the prophet Hananiah took the yoke off the neck of Jeremiah the prophet and broke it.'),
('JER', 28, 11, 'JER.28.11', 'And in the presence of all the people Hananiah proclaimed, “This is what the LORD says: ‘In this way, within two years I will break the yoke of Nebuchadnezzar king of Babylon off the neck of all the nations.’” At this, Jeremiah the prophet went on his way.'),
('JER', 28, 12, 'JER.28.12', 'But shortly after Hananiah the prophet had broken the yoke off his neck, the word of the LORD came to Jeremiah:'),
('JER', 28, 13, 'JER.28.13', '“Go and tell Hananiah that this is what the LORD says: ‘You have broken a yoke of wood, but in its place you have fashioned a yoke of iron.’'),
('JER', 28, 14, 'JER.28.14', 'For this is what the LORD of Hosts, the God of Israel, says: ‘I have put a yoke of iron on the neck of all these nations to make them serve Nebuchadnezzar king of Babylon, and they will serve him. I have even given him control of the beasts of the field.’”'),
('JER', 28, 15, 'JER.28.15', 'Then the prophet Jeremiah said to the prophet Hananiah, “Listen, Hananiah! The LORD did not send you, but you have persuaded this people to trust in a lie.'),
('JER', 28, 16, 'JER.28.16', 'Therefore this is what the LORD says: ‘I am about to remove you from the face of the earth. You will die this year because you have preached rebellion against the LORD.’”'),
('JER', 28, 17, 'JER.28.17', 'And in the seventh month of that very year, the prophet Hananiah died.'),
('JER', 29, 1, 'JER.29.1', 'This is the text of the letter that Jeremiah the prophet sent from Jerusalem to the surviving elders among the exiles and to the priests, the prophets, and all the others Nebuchadnezzar had carried into exile from Jerusalem to Babylon.'),
('JER', 29, 2, 'JER.29.2', '(This was after King Jeconiah, the queen mother, the court officials, the officials of Judah and Jerusalem, the craftsmen, and the metalsmiths had been exiled from Jerusalem.)'),
('JER', 29, 3, 'JER.29.3', 'The letter was entrusted to Elasah son of Shaphan and Gemariah son of Hilkiah, whom Zedekiah king of Judah sent to King Nebuchadnezzar in Babylon. It stated:'),
('JER', 29, 4, 'JER.29.4', 'This is what the LORD of Hosts, the God of Israel, says to all the exiles who were carried away from Jerusalem to Babylon:'),
('JER', 29, 5, 'JER.29.5', '“Build houses and settle down. Plant gardens and eat their produce.'),
('JER', 29, 6, 'JER.29.6', 'Take wives and have sons and daughters. Take wives for your sons and give your daughters in marriage, so that they too may have sons and daughters. Multiply there; do not decrease.'),
('JER', 29, 7, 'JER.29.7', 'Seek the prosperity of the city to which I have sent you as exiles. Pray to the LORD on its behalf, for if it prospers, you too will prosper.”'),
('JER', 29, 8, 'JER.29.8', 'For this is what the LORD of Hosts, the God of Israel, says: “Do not be deceived by the prophets and diviners among you, and do not listen to the dreams you elicit from them.'),
('JER', 29, 9, 'JER.29.9', 'For they are falsely prophesying to you in My name; I have not sent them, declares the LORD.”'),
('JER', 29, 10, 'JER.29.10', 'For this is what the LORD says: “When Babylon’s seventy years are complete, I will attend to you and confirm My promise to restore you to this place.'),
('JER', 29, 11, 'JER.29.11', 'For I know the plans I have for you, declares the LORD, plans to prosper you and not to harm you, to give you a future and a hope.'),
('JER', 29, 12, 'JER.29.12', 'Then you will call upon Me and come and pray to Me, and I will listen to you.'),
('JER', 29, 13, 'JER.29.13', 'You will seek Me and find Me when you search for Me with all your heart.'),
('JER', 29, 14, 'JER.29.14', 'I will be found by you, declares the LORD, and I will restore you from captivity and gather you from all the nations and places to which I have banished you, declares the LORD. I will restore you to the place from which I sent you into exile.”'),
('JER', 29, 15, 'JER.29.15', 'Because you may say, “The LORD has raised up for us prophets in Babylon,”'),
('JER', 29, 16, 'JER.29.16', 'this is what the LORD says about the king who sits on David’s throne and all the people who remain in this city, your brothers who did not go with you into exile—'),
('JER', 29, 17, 'JER.29.17', 'this is what the LORD of Hosts says: “I will send against them sword and famine and plague, and I will make them like rotten figs, so bad they cannot be eaten.'),
('JER', 29, 18, 'JER.29.18', 'I will pursue them with sword and famine and plague. I will make them a horror to all the kingdoms of the earth—a curse, a desolation, and an object of scorn and reproach among all the nations to which I banish them.'),
('JER', 29, 19, 'JER.29.19', 'I will do this because they have not listened to My words, declares the LORD, which I sent to them again and again through My servants the prophets. And neither have you exiles listened, declares the LORD.”'),
('JER', 29, 20, 'JER.29.20', 'So hear the word of the LORD, all you exiles I have sent away from Jerusalem to Babylon.'),
('JER', 29, 21, 'JER.29.21', 'This is what the LORD of Hosts, the God of Israel, says about Ahab son of Kolaiah and Zedekiah son of Maaseiah, who are prophesying to you lies in My name: “I will deliver them to Nebuchadnezzar king of Babylon, and he will kill them before your very eyes.'),
('JER', 29, 22, 'JER.29.22', 'Because of them, all the exiles of Judah who are in Babylon will use this curse: ‘May the LORD make you like Zedekiah and Ahab, whom the king of Babylon roasted in the fire!’'),
('JER', 29, 23, 'JER.29.23', 'For they have committed an outrage in Israel by committing adultery with the wives of their neighbors and speaking lies in My name, which I did not command them to do. I am He who knows, and I am a witness, declares the LORD.”'),
('JER', 29, 24, 'JER.29.24', 'You are to tell Shemaiah the Nehelamite that'),
('JER', 29, 25, 'JER.29.25', 'this is what the LORD of Hosts, the God of Israel, says: “In your own name you have sent out letters to all the people of Jerusalem, to the priest Zephaniah son of Maaseiah, and to all the priests. You said to Zephaniah:'),
('JER', 29, 26, 'JER.29.26', '‘The LORD has appointed you priest in place of Jehoiada, to be the chief officer in the house of the LORD, responsible for any madman who acts like a prophet—you must put him in stocks and neck irons.'),
('JER', 29, 27, 'JER.29.27', 'So now, why have you not rebuked Jeremiah of Anathoth, who poses as a prophet among you?'),
('JER', 29, 28, 'JER.29.28', 'For he has sent to us in Babylon, claiming: Since the exile will be lengthy, build houses and settle down; plant gardens and eat their produce.’”'),
('JER', 29, 29, 'JER.29.29', '(Zephaniah the priest, however, had read this letter to Jeremiah the prophet.)'),
('JER', 29, 30, 'JER.29.30', 'Then the word of the LORD came to Jeremiah:'),
('JER', 29, 31, 'JER.29.31', '“Send a message telling all the exiles what the LORD says concerning Shemaiah the Nehelamite. Because Shemaiah has prophesied to you—though I did not send him—and has made you trust in a lie,'),
('JER', 29, 32, 'JER.29.32', 'this is what the LORD says: ‘I will surely punish Shemaiah the Nehelamite and his descendants. He will have no one left among this people, nor will he see the good that I will bring to My people, declares the LORD, for he has preached rebellion against the LORD.’”'),
('JER', 30, 1, 'JER.30.1', 'This is the word that came to Jeremiah from the LORD:'),
('JER', 30, 2, 'JER.30.2', '“This is what the LORD, the God of Israel, says: ‘Write in a book all the words that I have spoken to you.'),
('JER', 30, 3, 'JER.30.3', 'For behold, the days are coming, declares the LORD, when I will restore from captivity My people Israel and Judah, declares the LORD. I will restore them to the land that I gave to their fathers, and they will possess it.’”'),
('JER', 30, 4, 'JER.30.4', 'These are the words that the LORD spoke concerning Israel and Judah.'),
('JER', 30, 5, 'JER.30.5', 'Yes, this is what the LORD says: “A cry of panic is heard—a cry of terror, not of peace.'),
('JER', 30, 6, 'JER.30.6', 'Ask now, and see: Can a male give birth? Why then do I see every man with his hands on his stomach like a woman in labor and every face turned pale?'),
('JER', 30, 7, 'JER.30.7', 'How awful that day will be! None will be like it! It is the time of Jacob’s distress, but he will be saved out of it.'),
('JER', 30, 8, 'JER.30.8', 'On that day, declares the LORD of Hosts, I will break the yoke off their necks and tear off their bonds, and no longer will strangers enslave them.'),
('JER', 30, 9, 'JER.30.9', 'Instead, they will serve the LORD their God and David their king, whom I will raise up for them.'),
('JER', 30, 10, 'JER.30.10', 'As for you, O Jacob My servant, do not be afraid, declares the LORD, and do not be dismayed, O Israel. For I will surely save you out of a distant place, your descendants from the land of their captivity! Jacob will return to quiet and ease, with no one to make him afraid.'),
('JER', 30, 11, 'JER.30.11', 'For I am with you to save you, declares the LORD. Though I will completely destroy all the nations to which I have scattered you, I will not completely destroy you. Yet I will discipline you justly, and will by no means leave you unpunished.”'),
('JER', 30, 12, 'JER.30.12', 'For this is what the LORD says: “Your injury is incurable; your wound is grievous.'),
('JER', 30, 13, 'JER.30.13', 'There is no one to plead your cause, no remedy for your sores, no recovery for you.'),
('JER', 30, 14, 'JER.30.14', 'All your lovers have forgotten you; they no longer seek you, for I have struck you as an enemy would, with the discipline of someone cruel, because of your great iniquity and your numerous sins.'),
('JER', 30, 15, 'JER.30.15', 'Why do you cry out over your wound? Your pain has no cure! Because of your great iniquity and your numerous sins I have done these things to you.'),
('JER', 30, 16, 'JER.30.16', 'Nevertheless, all who devour you will be devoured, and all your adversaries—every one of them—will go off into exile. Those who plundered you will be plundered, and all who raided you will be raided.'),
('JER', 30, 17, 'JER.30.17', 'But I will restore your health and heal your wounds, declares the LORD, because they call you an outcast, Zion, for whom no one cares.”'),
('JER', 30, 18, 'JER.30.18', 'This is what the LORD says: “I will restore the fortunes of Jacob’s tents and have compassion on his dwellings. And the city will be rebuilt on her own ruins, and the palace will stand in its rightful place.'),
('JER', 30, 19, 'JER.30.19', 'Thanksgiving will proceed from them, a sound of celebration. I will multiply them, and they will not be decreased; I will honor them, and they will not be belittled.'),
('JER', 30, 20, 'JER.30.20', 'Their children will be as in days of old, and their congregation will be established before Me; and I will punish all their oppressors.'),
('JER', 30, 21, 'JER.30.21', 'Their leader will be one of their own, and their ruler will arise from their midst. And I will bring him near, and he will approach Me, for who would dare on his own to approach Me?” declares the LORD.'),
('JER', 30, 22, 'JER.30.22', '“And you will be My people, and I will be your God.”'),
('JER', 30, 23, 'JER.30.23', 'Behold, the storm of the LORD has gone out with fury, a whirlwind swirling down upon the heads of the wicked.'),
('JER', 30, 24, 'JER.30.24', 'The fierce anger of the LORD will not turn back until He has fully accomplished the purposes of His heart. In the days to come you will understand this.'),
('JER', 31, 1, 'JER.31.1', '“At that time,” declares the LORD, “I will be the God of all the families of Israel, and they will be My people.”'),
('JER', 31, 2, 'JER.31.2', 'This is what the LORD says: “The people who survived the sword found favor in the wilderness when Israel went to find rest.”'),
('JER', 31, 3, 'JER.31.3', 'The LORD appeared to us in the past, saying: “I have loved you with an everlasting love; therefore I have drawn you with loving devotion.'),
('JER', 31, 4, 'JER.31.4', 'Again I will build you, and you will be rebuilt, O Virgin Israel. Again you will take up your tambourines and go out in joyful dancing.'),
('JER', 31, 5, 'JER.31.5', 'Again you will plant vineyards on the hills of Samaria; the farmers will plant and enjoy the fruit.'),
('JER', 31, 6, 'JER.31.6', 'For there will be a day when watchmen will call out on the hills of Ephraim, ‘Arise, let us go up to Zion, to the LORD our God!’”'),
('JER', 31, 7, 'JER.31.7', 'For this is what the LORD says: “Sing with joy for Jacob; shout for the foremost of the nations! Make your praises heard, and say, ‘O LORD, save Your people, the remnant of Israel!’'),
('JER', 31, 8, 'JER.31.8', 'Behold, I will bring them from the land of the north and gather them from the farthest parts of the earth, including the blind and the lame, expectant mothers and women in labor. They will return as a great assembly!'),
('JER', 31, 9, 'JER.31.9', 'They will come with weeping, and by their supplication I will lead them; I will make them walk beside streams of waters, on a level path where they will not stumble. For I am Israel’s Father, and Ephraim is My firstborn.”'),
('JER', 31, 10, 'JER.31.10', 'Hear, O nations, the word of the LORD, and proclaim it in distant coastlands: “The One who scattered Israel will gather them and keep them as a shepherd keeps his flock.'),
('JER', 31, 11, 'JER.31.11', 'For the LORD has ransomed Jacob and redeemed him from the hand that had overpowered him.'),
('JER', 31, 12, 'JER.31.12', 'They will come and shout for joy on the heights of Zion; they will be radiant over the bounty of the LORD—the grain, new wine, and oil, and the young of the flocks and herds. Their life will be like a well-watered garden, and never again will they languish.'),
('JER', 31, 13, 'JER.31.13', 'Then the maidens will rejoice with dancing, young men and old as well. I will turn their mourning into joy, and give them comfort and joy for their sorrow.'),
('JER', 31, 14, 'JER.31.14', 'I will fill the souls of the priests abundantly, and will fill My people with My goodness,” declares the LORD.'),
('JER', 31, 15, 'JER.31.15', 'This is what the LORD says: “A voice is heard in Ramah, mourning and great weeping, Rachel weeping for her children and refusing to be comforted, because they are no more.”'),
('JER', 31, 16, 'JER.31.16', 'This is what the LORD says: “Keep your voice from weeping and your eyes from tears, for the reward for your work will come, declares the LORD. Then your children will return from the land of the enemy.'),
('JER', 31, 17, 'JER.31.17', 'So there is hope for your future, declares the LORD, and your children will return to their own land.'),
('JER', 31, 18, 'JER.31.18', 'I have surely heard Ephraim’s moaning: ‘You disciplined me severely, like an untrained calf. Restore me, that I may return, for You are the LORD my God.'),
('JER', 31, 19, 'JER.31.19', 'After I returned, I repented; and after I was instructed, I struck my thigh in grief. I was ashamed and humiliated because I bore the disgrace of my youth.’'),
('JER', 31, 20, 'JER.31.20', 'Is not Ephraim a precious son to Me, a delightful child? Though I often speak against him, I still remember him. Therefore My heart yearns for him; I have great compassion for him,” declares the LORD.'),
('JER', 31, 21, 'JER.31.21', '“Set up the road markers, put up the signposts. Keep the highway in mind, the road you have traveled. Return, O Virgin Israel, return to these cities of yours.'),
('JER', 31, 22, 'JER.31.22', 'How long will you wander, O faithless daughter? For the LORD has created a new thing in the land—a woman will shelter a man.”'),
('JER', 31, 23, 'JER.31.23', 'This is what the LORD of Hosts, the God of Israel, says: “When I restore them from captivity, they will once again speak this word in the land of Judah and in its cities: ‘May the LORD bless you, O righteous dwelling place, O holy mountain.’'),
('JER', 31, 24, 'JER.31.24', 'And Judah and all its cities will dwell together in the land, the farmers and those who move with the flocks,'),
('JER', 31, 25, 'JER.31.25', 'for I will refresh the weary soul and replenish all who are weak.”'),
('JER', 31, 26, 'JER.31.26', 'At this I awoke and looked around. My sleep had been most pleasant to me.'),
('JER', 31, 27, 'JER.31.27', '“The days are coming,” declares the LORD, “when I will sow the house of Israel and the house of Judah with the seed of man and of beast.'),
('JER', 31, 28, 'JER.31.28', 'Just as I watched over them to uproot and tear down, to demolish, destroy, and bring disaster, so I will watch over them to build and to plant,” declares the LORD.'),
('JER', 31, 29, 'JER.31.29', '“In those days, it will no longer be said: ‘The fathers have eaten sour grapes, and the teeth of the children are set on edge.’'),
('JER', 31, 30, 'JER.31.30', 'Instead, each will die for his own iniquity. If anyone eats the sour grapes, his own teeth will be set on edge.'),
('JER', 31, 31, 'JER.31.31', 'Behold, the days are coming, declares the LORD, when I will make a new covenant with the house of Israel and with the house of Judah.'),
('JER', 31, 32, 'JER.31.32', 'It will not be like the covenant I made with their fathers when I took them by the hand to lead them out of the land of Egypt—a covenant they broke, though I was a husband to them,” declares the LORD.'),
('JER', 31, 33, 'JER.31.33', '“But this is the covenant I will make with the house of Israel after those days, declares the LORD. I will put My law in their minds and inscribe it on their hearts. And I will be their God, and they will be My people.'),
('JER', 31, 34, 'JER.31.34', 'No longer will each man teach his neighbor or his brother, saying, ‘Know the LORD,’ because they will all know Me, from the least of them to the greatest, declares the LORD. For I will forgive their iniquities and will remember their sins no more.”'),
('JER', 31, 35, 'JER.31.35', 'Thus says the LORD, who gives the sun for light by day, who sets in order the moon and stars for light by night, who stirs up the sea so that its waves roar—the LORD of Hosts is His name:'),
('JER', 31, 36, 'JER.31.36', '“Only if this fixed order departed from My presence, declares the LORD, would Israel’s descendants ever cease to be a nation before Me.”'),
('JER', 31, 37, 'JER.31.37', 'This is what the LORD says: “Only if the heavens above could be measured and the foundations of the earth below searched out would I reject all of Israel’s descendants because of all they have done,” declares the LORD.'),
('JER', 31, 38, 'JER.31.38', '“The days are coming,” declares the LORD, “when this city will be rebuilt for Me, from the tower of Hananel to the Corner Gate.'),
('JER', 31, 39, 'JER.31.39', 'The measuring line will once again stretch out straight to the hill of Gareb and then turn toward Goah.'),
('JER', 31, 40, 'JER.31.40', 'The whole valley of the dead bodies and ashes, and all the fields as far as the Kidron Valley, to the corner of the Horse Gate to the east, will be holy to the LORD. It will never again be uprooted or demolished.”'),
('JER', 32, 1, 'JER.32.1', 'This is the word that came to Jeremiah from the LORD in the tenth year of Zedekiah king of Judah, which was the eighteenth year of Nebuchadnezzar.'),
('JER', 32, 2, 'JER.32.2', 'At that time the army of the king of Babylon was besieging Jerusalem, and Jeremiah the prophet was imprisoned in the courtyard of the guard, which was in the palace of the king of Judah.'),
('JER', 32, 3, 'JER.32.3', 'For Zedekiah king of Judah had imprisoned him, saying: “Why are you prophesying like this? You claim that the LORD says, ‘Behold, I am about to deliver this city into the hand of the king of Babylon, and he will capture it.'),
('JER', 32, 4, 'JER.32.4', 'Zedekiah king of Judah will not escape from the hands of the Chaldeans, but he will surely be delivered into the hand of the king of Babylon, and will speak with him face to face and see him eye to eye.'),
('JER', 32, 5, 'JER.32.5', 'He will take Zedekiah to Babylon, where he will stay until I attend to him, declares the LORD. If you fight against the Chaldeans, you will not succeed.’”'),
('JER', 32, 6, 'JER.32.6', 'Jeremiah replied, “The word of the LORD came to me, saying:'),
('JER', 32, 7, 'JER.32.7', 'Behold! Hanamel, the son of your uncle Shallum, is coming to you to say, ‘Buy for yourself my field in Anathoth, for you have the right of redemption to buy it.’'),
('JER', 32, 8, 'JER.32.8', 'Then, as the LORD had said, my cousin Hanamel came to me in the courtyard of the guard and urged me, ‘Please buy my field in Anathoth in the land of Benjamin, for you own the right of inheritance and redemption. Buy it for yourself.’” Then I knew that this was the word of the LORD.'),
('JER', 32, 9, 'JER.32.9', 'So I bought the field in Anathoth from my cousin Hanamel, and I weighed out seventeen shekels of silver.'),
('JER', 32, 10, 'JER.32.10', 'I signed and sealed the deed, called in witnesses, and weighed out the silver on the scales.'),
('JER', 32, 11, 'JER.32.11', 'Then I took the deed of purchase—the sealed copy with its terms and conditions, as well as the open copy—'),
('JER', 32, 12, 'JER.32.12', 'and I gave this deed to Baruch son of Neriah, the son of Mahseiah, in the sight of my cousin Hanamel and the witnesses who were signing the purchase agreement and all the Jews sitting in the courtyard of the guard.'),
('JER', 32, 13, 'JER.32.13', 'In their sight I instructed Baruch,'),
('JER', 32, 14, 'JER.32.14', '“This is what the LORD of Hosts, the God of Israel, says: Take these deeds—both the sealed copy and the open copy of the deed of purchase—and put them in a clay jar to preserve them for a long time.'),
('JER', 32, 15, 'JER.32.15', 'For this is what the LORD of Hosts, the God of Israel, says: Houses, fields, and vineyards will again be bought in this land.”'),
('JER', 32, 16, 'JER.32.16', 'After I had given the deed of purchase to Baruch son of Neriah, I prayed to the LORD:'),
('JER', 32, 17, 'JER.32.17', '“Oh, Lord GOD! You have made the heavens and the earth by Your great power and outstretched arm. Nothing is too difficult for You!'),
('JER', 32, 18, 'JER.32.18', 'You show loving devotion to thousands but lay the iniquity of the fathers into the laps of their children after them, O great and mighty God whose name is the LORD of Hosts,'),
('JER', 32, 19, 'JER.32.19', 'the One great in counsel and mighty in deed, whose eyes are on all the ways of the sons of men, to reward each one according to his ways and according to the fruit of his deeds.'),
('JER', 32, 20, 'JER.32.20', 'You performed signs and wonders in the land of Egypt, and You do so to this very day, both in Israel and among all mankind. And You have made a name for Yourself, as is the case to this day.'),
('JER', 32, 21, 'JER.32.21', 'You brought Your people Israel out of the land of Egypt with signs and wonders, with a strong hand and an outstretched arm, and with great terror.'),
('JER', 32, 22, 'JER.32.22', 'You gave them this land that You had sworn to give their fathers, a land flowing with milk and honey.'),
('JER', 32, 23, 'JER.32.23', 'They came in and possessed it, but they did not obey Your voice or walk in Your law. They failed to perform all that You commanded them to do, and so You have brought upon them all this disaster.'),
('JER', 32, 24, 'JER.32.24', 'See how the siege ramps are mounted against the city to capture it. And by sword and famine and plague, the city has been given into the hands of the Chaldeans who are fighting against it. What You have spoken has happened, as You now see!'),
('JER', 32, 25, 'JER.32.25', 'Yet You, O Lord GOD, have said to me, ‘Buy for yourself the field with silver and call in witnesses, even though the city has been delivered into the hands of the Chaldeans!’”'),
('JER', 32, 26, 'JER.32.26', 'Then the word of the LORD came to Jeremiah:'),
('JER', 32, 27, 'JER.32.27', '“Behold, I am the LORD, the God of all flesh. Is anything too difficult for Me?'),
('JER', 32, 28, 'JER.32.28', 'Therefore this is what the LORD says: Behold, I am about to deliver this city into the hands of the Chaldeans and of Nebuchadnezzar king of Babylon, who will capture it.'),
('JER', 32, 29, 'JER.32.29', 'And the Chaldeans who are fighting against this city will come in, set it on fire, and burn it, along with the houses of those who provoked Me to anger by burning incense to Baal on their rooftops and by pouring out drink offerings to other gods.'),
('JER', 32, 30, 'JER.32.30', 'For the children of Israel and of Judah have done nothing but evil in My sight from their youth; indeed, they have done nothing but provoke Me to anger by the work of their hands, declares the LORD.'),
('JER', 32, 31, 'JER.32.31', 'For this city has aroused My wrath and fury from the day it was built until now. Therefore I will remove it from My presence'),
('JER', 32, 32, 'JER.32.32', 'because of all the evil the children of Israel and of Judah have done to provoke Me to anger—they, their kings, their officials, their priests and prophets, the men of Judah, and the residents of Jerusalem.'),
('JER', 32, 33, 'JER.32.33', 'They have turned their backs to Me and not their faces. Though I taught them again and again, they would not listen or respond to discipline.'),
('JER', 32, 34, 'JER.32.34', 'They have placed their abominations in the house that bears My Name, and so have defiled it.'),
('JER', 32, 35, 'JER.32.35', 'They have built the high places of Baal in the Valley of Ben-hinnom to make their sons and daughters pass through the fire to Molech—something I never commanded them, nor had it ever entered My mind, that they should commit such an abomination and cause Judah to sin.'),
('JER', 32, 36, 'JER.32.36', 'Now therefore, about this city of which you say, ‘It will be delivered into the hand of the king of Babylon by sword and famine and plague,’ this is what the LORD, the God of Israel, says:'),
('JER', 32, 37, 'JER.32.37', 'I will surely gather My people from all the lands to which I have banished them in My furious anger and great wrath, and I will return them to this place and make them dwell in safety.'),
('JER', 32, 38, 'JER.32.38', 'They will be My people, and I will be their God.'),
('JER', 32, 39, 'JER.32.39', 'I will give them one heart and one way, so that they will always fear Me for their own good and for the good of their children after them.'),
('JER', 32, 40, 'JER.32.40', 'I will make an everlasting covenant with them: I will never turn away from doing good to them, and I will put My fear in their hearts, so that they will never turn away from Me.'),
('JER', 32, 41, 'JER.32.41', 'Yes, I will rejoice in doing them good, and I will faithfully plant them in this land with all My heart and with all My soul.'),
('JER', 32, 42, 'JER.32.42', 'For this is what the LORD says: Just as I have brought all this great disaster on this people, so I will bring on them all the good I have promised them.'),
('JER', 32, 43, 'JER.32.43', 'And fields will be bought in this land about which you are saying, ‘It is a desolation, without man or beast; it has been delivered into the hands of the Chaldeans.’'),
('JER', 32, 44, 'JER.32.44', 'Fields will be purchased with silver, and deeds will be signed, sealed, and witnessed in the land of Benjamin, in the areas surrounding Jerusalem, and in the cities of Judah—the cities of the hill country, the foothills, and the Negev—because I will restore them from captivity, declares the LORD.”'),
('JER', 33, 1, 'JER.33.1', 'While Jeremiah was still confined in the courtyard of the guard, the word of the LORD came to him a second time:'),
('JER', 33, 2, 'JER.33.2', '“Thus says the LORD who made the earth, the LORD who formed it and established it, the LORD is His name:'),
('JER', 33, 3, 'JER.33.3', 'Call to Me, and I will answer and show you great and unsearchable things you do not know.'),
('JER', 33, 4, 'JER.33.4', 'For this is what the LORD, the God of Israel, says about the houses of this city and the palaces of the kings of Judah that have been torn down for defense against the siege ramps and the sword:'),
('JER', 33, 5, 'JER.33.5', 'The Chaldeans are coming to fight and to fill those places with the corpses of the men I will strike down in My anger and in My wrath. I have hidden My face from this city because of all its wickedness.'),
('JER', 33, 6, 'JER.33.6', 'Nevertheless, I will bring to it health and healing, and I will heal its people and reveal to them the abundance of peace and truth.'),
('JER', 33, 7, 'JER.33.7', 'I will restore Judah and Israel from captivity and will rebuild them as in former times.'),
('JER', 33, 8, 'JER.33.8', 'And I will cleanse them from all the iniquity they have committed against Me, and will forgive all their sins of rebellion against Me.'),
('JER', 33, 9, 'JER.33.9', 'So this city will bring Me renown, joy, praise, and glory before all the nations of the earth, who will hear of all the good I do for it. They will tremble in awe because of all the goodness and prosperity that I will provide for it.'),
('JER', 33, 10, 'JER.33.10', 'This is what the LORD says: In this place you say is a wasteland without man or beast, in the cities of Judah and in the streets of Jerusalem that are deserted—inhabited by neither man nor beast—there will be heard again'),
('JER', 33, 11, 'JER.33.11', 'the sounds of joy and gladness, the voices of the bride and bridegroom, and the voices of those bringing thank offerings into the house of the LORD, saying: ‘Give thanks to the LORD of Hosts, for the LORD is good; His loving devotion endures forever.’ For I will restore the land from captivity as in former times, says the LORD.'),
('JER', 33, 12, 'JER.33.12', 'This is what the LORD of Hosts says: In this desolate place, without man or beast, and in all its cities, there will once more be pastures for shepherds to rest their flocks.'),
('JER', 33, 13, 'JER.33.13', 'In the cities of the hill country, the foothills, and the Negev, in the land of Benjamin and the cities surrounding Jerusalem, and in the cities of Judah, the flocks will again pass under the hands of the one who counts them, says the LORD.'),
('JER', 33, 14, 'JER.33.14', 'Behold, the days are coming, declares the LORD, when I will fulfill the gracious promise that I have spoken to the house of Israel and the house of Judah.'),
('JER', 33, 15, 'JER.33.15', 'In those days and at that time I will cause to sprout for David a righteous Branch, and He will administer justice and righteousness in the land.'),
('JER', 33, 16, 'JER.33.16', 'In those days Judah will be saved, and Jerusalem will dwell securely, and this is the name by which it will be called: The LORD Our Righteousness.'),
('JER', 33, 17, 'JER.33.17', 'For this is what the LORD says: David will never lack a man to sit on the throne of the house of Israel,'),
('JER', 33, 18, 'JER.33.18', 'nor will the priests who are Levites ever fail to have a man before Me to offer burnt offerings, to burn grain offerings, and to present sacrifices.”'),
('JER', 33, 19, 'JER.33.19', 'And the word of the LORD came to Jeremiah:'),
('JER', 33, 20, 'JER.33.20', '“This is what the LORD says: If you can break My covenant with the day and My covenant with the night, so that day and night cease to occupy their appointed time,'),
('JER', 33, 21, 'JER.33.21', 'then My covenant may also be broken with David My servant and with My ministers the Levites who are priests, so that David will not have a son to reign on his throne.'),
('JER', 33, 22, 'JER.33.22', 'As the hosts of heaven cannot be counted and as the sand on the seashore cannot be measured, so too will I multiply the descendants of My servant David and the Levites who minister before Me.”'),
('JER', 33, 23, 'JER.33.23', 'Moreover, the word of the LORD came to Jeremiah:'),
('JER', 33, 24, 'JER.33.24', '“Have you not noticed what these people are saying: ‘The LORD has rejected the two families He had chosen’? So they despise My people and no longer regard them as a nation.'),
('JER', 33, 25, 'JER.33.25', 'This is what the LORD says: If I have not established My covenant with the day and the night and the fixed order of heaven and earth,'),
('JER', 33, 26, 'JER.33.26', 'then I would also reject the descendants of Jacob and of My servant David, so as not to take from his descendants rulers over the descendants of Abraham, Isaac, and Jacob. For I will restore them from captivity and will have compassion on them.”'),
('JER', 34, 1, 'JER.34.1', 'This is the word that came to Jeremiah from the LORD when Nebuchadnezzar king of Babylon, all his army, all the earthly kingdoms under his control, and all the other nations were fighting against Jerusalem and all its surrounding cities.'),
('JER', 34, 2, 'JER.34.2', 'The LORD, the God of Israel, told Jeremiah to go and speak to Zedekiah king of Judah and tell him that this is what the LORD says: “Behold, I am about to deliver this city into the hand of the king of Babylon, and he will burn it down.'),
('JER', 34, 3, 'JER.34.3', 'And you yourself will not escape his grasp, but will surely be captured and delivered into his hand. You will see the king of Babylon eye to eye and speak with him face to face; and you will go to Babylon.'),
('JER', 34, 4, 'JER.34.4', 'Yet hear the word of the LORD, O Zedekiah king of Judah. This is what the LORD says concerning you: You will not die by the sword;'),
('JER', 34, 5, 'JER.34.5', 'you will die in peace. As spices were burned for your fathers, the former kings who preceded you, so people will burn spices for you and lament, ‘Alas, O master!’ For I Myself have spoken this word, declares the LORD.”'),
('JER', 34, 6, 'JER.34.6', 'In Jerusalem, then, Jeremiah the prophet relayed all these words to Zedekiah king of Judah'),
('JER', 34, 7, 'JER.34.7', 'as the army of the king of Babylon was fighting against Jerusalem and the remaining cities of Judah—against Lachish and Azekah. For these were the only fortified cities remaining in Judah.'),
('JER', 34, 8, 'JER.34.8', 'After King Zedekiah had made a covenant with all the people in Jerusalem to proclaim liberty, the word came to Jeremiah from the LORD'),
('JER', 34, 9, 'JER.34.9', 'that each man should free his Hebrew slaves, both male and female, and no one should hold his fellow Jew in bondage.'),
('JER', 34, 10, 'JER.34.10', 'So all the officials and all the people who entered into this covenant agreed that they would free their menservants and maidservants and no longer hold them in bondage. They obeyed and released them,'),
('JER', 34, 11, 'JER.34.11', 'but later they changed their minds and took back the menservants and maidservants they had freed, and they forced them to become slaves again.'),
('JER', 34, 12, 'JER.34.12', 'Then the word of the LORD came to Jeremiah from the LORD, saying,'),
('JER', 34, 13, 'JER.34.13', '“This is what the LORD, the God of Israel, says: I made a covenant with your forefathers when I brought them out of the land of Egypt, out of the house of slavery, saying:'),
('JER', 34, 14, 'JER.34.14', 'Every seventh year, each of you must free his Hebrew brother who has sold himself to you. He may serve you six years, but then you must let him go free. But your fathers did not listen or incline their ear.'),
('JER', 34, 15, 'JER.34.15', 'Recently you repented and did what pleased Me; each of you proclaimed freedom for his neighbor. You made a covenant before Me in the house that bears My Name.'),
('JER', 34, 16, 'JER.34.16', 'But now you have changed your minds and profaned My name. Each of you has taken back the menservants and maidservants whom you had set at liberty to go wherever they wanted, and you have again forced them to be your slaves.'),
('JER', 34, 17, 'JER.34.17', 'Therefore this is what the LORD says: You have not obeyed Me; you have not proclaimed freedom, each man for his brother and for his neighbor. So now I proclaim freedom for you, declares the LORD—freedom to fall by sword, by plague, and by famine! I will make you a horror to all the kingdoms of the earth.'),
('JER', 34, 18, 'JER.34.18', 'And those who have transgressed My covenant and have not fulfilled the terms of the covenant they made before Me, I will treat like the calf they cut in two in order to pass between its pieces.'),
('JER', 34, 19, 'JER.34.19', 'The officials of Judah and Jerusalem, the court officials, the priests, and all the people of the land who passed between the pieces of the calf,'),
('JER', 34, 20, 'JER.34.20', 'I will deliver into the hands of their enemies who seek their lives. Their corpses will become food for the birds of the air and the beasts of the earth.'),
('JER', 34, 21, 'JER.34.21', 'And I will deliver Zedekiah king of Judah and his officials into the hands of their enemies who seek their lives, to the army of the king of Babylon that had withdrawn from you.'),
('JER', 34, 22, 'JER.34.22', 'Behold, I am going to give the command, declares the LORD, and I will bring them back to this city. They will fight against it, capture it, and burn it down. And I will make the cities of Judah a desolation, without inhabitant.”'),
('JER', 35, 1, 'JER.35.1', 'This is the word that came to Jeremiah from the LORD in the days of Jehoiakim son of Josiah king of Judah:'),
('JER', 35, 2, 'JER.35.2', '“Go to the house of the Rechabites, speak to them, and bring them to one of the chambers of the house of the LORD to offer them a drink of wine.”'),
('JER', 35, 3, 'JER.35.3', 'So I took Jaazaniah son of Jeremiah, the son of Habazziniah, and his brothers and all his sons—the entire house of the Rechabites—'),
('JER', 35, 4, 'JER.35.4', 'and I brought them into the house of the LORD, to a chamber occupied by the sons of Hanan son of Igdaliah, a man of God. This room was near the chamber of the officials, which was above the chamber of Maaseiah son of Shallum the doorkeeper.'),
('JER', 35, 5, 'JER.35.5', 'Then I set pitchers full of wine and some cups before the men of the house of the Rechabites, and I said to them, “Drink some wine.”'),
('JER', 35, 6, 'JER.35.6', '“We do not drink wine,” they replied, “for our forefather Jonadab son of Rechab commanded us, ‘Neither you nor your descendants are ever to drink wine.'),
('JER', 35, 7, 'JER.35.7', 'Nor are you ever to build a house or sow seed or plant a vineyard. Those things are not for you. Instead, you must live in tents all your lives, so that you may live a long time in the land where you wander.’'),
('JER', 35, 8, 'JER.35.8', 'And we have obeyed the voice of our forefather Jonadab son of Rechab in all he commanded us. So we have not drunk wine all our lives—neither we nor our wives nor our sons and daughters.'),
('JER', 35, 9, 'JER.35.9', 'Nor have we built houses in which to live, and we have not owned any vineyards or fields or crops.'),
('JER', 35, 10, 'JER.35.10', 'But we have lived in tents and have obeyed and done exactly as our forefather Jonadab commanded us.'),
('JER', 35, 11, 'JER.35.11', 'So when Nebuchadnezzar king of Babylon marched into the land, we said: ‘Come, let us go into Jerusalem to escape the armies of the Chaldeans and the Arameans.’ So we have remained in Jerusalem.”'),
('JER', 35, 12, 'JER.35.12', 'Then the word of the LORD came to Jeremiah:'),
('JER', 35, 13, 'JER.35.13', '“This is what the LORD of Hosts, the God of Israel, says: Go and tell the men of Judah and the residents of Jerusalem: ‘Will you not accept discipline and obey My words?’ declares the LORD.'),
('JER', 35, 14, 'JER.35.14', 'The words of Jonadab son of Rechab have been carried out. He commanded his sons not to drink wine, and they have not drunk it to this very day because they have obeyed the command of their forefather. But I have spoken to you again and again, and you have not obeyed Me!'),
('JER', 35, 15, 'JER.35.15', 'Again and again I have sent you all My servants the prophets, proclaiming: ‘Turn now, each of you, from your wicked ways, and correct your actions. Do not go after other gods to serve them. Live in the land that I have given to you and your fathers.’ But you have not inclined your ear or listened to Me.'),
('JER', 35, 16, 'JER.35.16', 'Yes, the sons of Jonadab son of Rechab carried out the command their forefather gave them, but these people have not listened to Me.'),
('JER', 35, 17, 'JER.35.17', 'Therefore this is what the LORD God of Hosts, the God of Israel, says: ‘Behold, I will bring to Judah and to all the residents of Jerusalem all the disaster I have pronounced against them, because I have spoken to them but they have not obeyed, and I have called to them but they have not answered.’”'),
('JER', 35, 18, 'JER.35.18', 'Then Jeremiah said to the house of the Rechabites: “This is what the LORD of Hosts, the God of Israel, says: ‘Because you have obeyed the command of your forefather Jonadab and have kept all his commandments and have done all that he charged you to do,'),
('JER', 35, 19, 'JER.35.19', 'this is what the LORD of Hosts, the God of Israel, says: Jonadab son of Rechab will never fail to have a man to stand before Me.’”'),
('JER', 36, 1, 'JER.36.1', 'In the fourth year of Jehoiakim son of Josiah king of Judah, this word came to Jeremiah from the LORD:'),
('JER', 36, 2, 'JER.36.2', '“Take a scroll and write on it all the words I have spoken to you concerning Israel, Judah, and all the nations, from the day I first spoke to you during the reign of Josiah until today.'),
('JER', 36, 3, 'JER.36.3', 'Perhaps when the people of Judah hear about all the calamity I plan to bring upon them, each of them will turn from his wicked way. Then I will forgive their iniquity and their sin.”'),
('JER', 36, 4, 'JER.36.4', 'So Jeremiah called Baruch son of Neriah, and at the dictation of Jeremiah, Baruch wrote on a scroll all the words that the LORD had spoken to Jeremiah.'),
('JER', 36, 5, 'JER.36.5', 'Then Jeremiah commanded Baruch, “I am restricted; I cannot enter the house of the LORD;'),
('JER', 36, 6, 'JER.36.6', 'so you are to go to the house of the LORD on a day of fasting, and in the hearing of the people you are to read the words of the LORD from the scroll you have written at my dictation. Read them in the hearing of all the people of Judah who are coming from their cities.'),
('JER', 36, 7, 'JER.36.7', 'Perhaps they will bring their petition before the LORD, and each one will turn from his wicked way; for great are the anger and fury that the LORD has pronounced against this people.”'),
('JER', 36, 8, 'JER.36.8', 'So Baruch son of Neriah did everything that Jeremiah the prophet had commanded him. In the house of the LORD he read the words of the LORD from the scroll.'),
('JER', 36, 9, 'JER.36.9', 'Now in the ninth month of the fifth year of Jehoiakim son of Josiah king of Judah, a fast before the LORD was proclaimed to all the people of Jerusalem and all who had come there from the cities of Judah.'),
('JER', 36, 10, 'JER.36.10', 'From the chamber of Gemariah son of Shaphan the scribe, which was in the upper courtyard at the opening of the New Gate of the house of the LORD, Baruch read from the scroll the words of Jeremiah in the hearing of all the people.'),
('JER', 36, 11, 'JER.36.11', 'When Micaiah son of Gemariah, the son of Shaphan, heard all the words of the LORD from the scroll,'),
('JER', 36, 12, 'JER.36.12', 'he went down to the scribe’s chamber in the king’s palace, where all the officials were sitting: Elishama the scribe, Delaiah son of Shemaiah, Elnathan son of Achbor, Gemariah son of Shaphan, Zedekiah son of Hananiah, and all the other officials.'),
('JER', 36, 13, 'JER.36.13', 'And Micaiah reported to them all the words he had heard Baruch read from the scroll in the hearing of the people.'),
('JER', 36, 14, 'JER.36.14', 'Then all the officials sent word to Baruch through Jehudi son of Nethaniah, the son of Shelemiah, the son of Cushi, saying, “Bring the scroll that you read in the hearing of the people, and come here.” So Baruch son of Neriah took the scroll and went to them.'),
('JER', 36, 15, 'JER.36.15', '“Please sit down,” they said, “and read it in our hearing.” So Baruch read it in their hearing.'),
('JER', 36, 16, 'JER.36.16', 'When they had heard all these words, they turned to one another in fear and said to Baruch, “Surely we must report all these words to the king.”'),
('JER', 36, 17, 'JER.36.17', '“Tell us now,” they asked Baruch, “how did you write all these words? Was it at Jeremiah’s dictation?”'),
('JER', 36, 18, 'JER.36.18', '“It was at his dictation,” Baruch replied. “He recited all these words to me and I wrote them in ink on the scroll.”'),
('JER', 36, 19, 'JER.36.19', 'Then the officials said to Baruch, “You and Jeremiah must hide yourselves and tell no one where you are.”'),
('JER', 36, 20, 'JER.36.20', 'So the officials went to the king in the courtyard. And having stored the scroll in the chamber of Elishama the scribe, they reported everything to the king.'),
('JER', 36, 21, 'JER.36.21', 'Then the king sent Jehudi to get the scroll, and he took it from the chamber of Elishama the scribe. And Jehudi read it in the hearing of the king and all the officials who were standing beside him.'),
('JER', 36, 22, 'JER.36.22', 'Since it was the ninth month, the king was sitting in his winter quarters with a fire burning before him.'),
('JER', 36, 23, 'JER.36.23', 'And as soon as Jehudi had read three or four columns, Jehoiakim would cut them off with a scribe’s knife and throw them into the firepot, until the entire scroll had been consumed by the fire.'),
('JER', 36, 24, 'JER.36.24', 'Yet in hearing all these words, the king and his servants did not become frightened or tear their garments.'),
('JER', 36, 25, 'JER.36.25', 'Even though Elnathan, Delaiah, and Gemariah urged the king not to burn the scroll, he would not listen to them.'),
('JER', 36, 26, 'JER.36.26', 'Instead, the king commanded Jerahmeel, a son of the king, as well as Seraiah son of Azriel and Shelemiah son of Abdeel, to seize Baruch the scribe and Jeremiah the prophet. But the LORD had hidden them.'),
('JER', 36, 27, 'JER.36.27', 'After the king had burned the scroll containing the words that Baruch had written at Jeremiah’s dictation, the word of the LORD came to Jeremiah:'),
('JER', 36, 28, 'JER.36.28', '“Take another scroll and rewrite on it the very words that were on the original scroll, which Jehoiakim king of Judah has burned.'),
('JER', 36, 29, 'JER.36.29', 'You are to proclaim concerning Jehoiakim king of Judah that this is what the LORD says: You have burned the scroll and said, ‘Why have you written on it that the king of Babylon would surely come and destroy this land and deprive it of man and beast?’'),
('JER', 36, 30, 'JER.36.30', 'Therefore this is what the LORD says about Jehoiakim king of Judah: He will have no one to sit on David’s throne, and his body will be thrown out and exposed to heat by day and frost by night.'),
('JER', 36, 31, 'JER.36.31', 'I will punish him and his descendants and servants for their iniquity. I will bring on them, on the residents of Jerusalem, and on the men of Judah, all the calamity about which I warned them but they did not listen.”'),
('JER', 36, 32, 'JER.36.32', 'Then Jeremiah took another scroll and gave it to the scribe Baruch son of Neriah, and at Jeremiah’s dictation he wrote on it all the words of the scroll that Jehoiakim king of Judah had burned in the fire. And many similar words were added to them.'),
('JER', 37, 1, 'JER.37.1', 'Nebuchadnezzar king of Babylon made Zedekiah son of Josiah the king of Judah, and he reigned in place of Coniah son of Jehoiakim.'),
('JER', 37, 2, 'JER.37.2', 'But he and his officers and the people of the land refused to obey the words that the LORD had spoken through Jeremiah the prophet.'),
('JER', 37, 3, 'JER.37.3', 'Yet King Zedekiah sent Jehucal son of Shelemiah and Zephaniah the priest, the son of Maaseiah, to Jeremiah the prophet with the message, “Please pray to the LORD our God for us!”'),
('JER', 37, 4, 'JER.37.4', 'Now Jeremiah was free to come and go among the people, for they had not yet put him in prison.'),
('JER', 37, 5, 'JER.37.5', 'Pharaoh’s army had left Egypt, and when the Chaldeans who were besieging Jerusalem heard the report, they withdrew from Jerusalem.'),
('JER', 37, 6, 'JER.37.6', 'Then the word of the LORD came to Jeremiah the prophet:'),
('JER', 37, 7, 'JER.37.7', '“This is what the LORD, the God of Israel, says that you are to tell the king of Judah, who sent you to Me: Behold, Pharaoh’s army, which has marched out to help you, will go back to its own land of Egypt.'),
('JER', 37, 8, 'JER.37.8', 'Then the Chaldeans will return and fight against this city. They will capture it and burn it down.'),
('JER', 37, 9, 'JER.37.9', 'This is what the LORD says: Do not deceive yourselves by saying, ‘The Chaldeans will go away for good,’ for they will not!'),
('JER', 37, 10, 'JER.37.10', 'Indeed, if you were to strike down the entire army of the Chaldeans that is fighting against you, and only wounded men remained in their tents, they would still get up and burn this city down.”'),
('JER', 37, 11, 'JER.37.11', 'When the Chaldean army withdrew from Jerusalem for fear of Pharaoh’s army,'),
('JER', 37, 12, 'JER.37.12', 'Jeremiah started to leave Jerusalem to go to the land of Benjamin to claim his portion there among the people.'),
('JER', 37, 13, 'JER.37.13', 'But when he reached the Gate of Benjamin, the captain of the guard, whose name was Irijah son of Shelemiah, the son of Hananiah, seized him and said, “You are deserting to the Chaldeans!”'),
('JER', 37, 14, 'JER.37.14', '“That is a lie,” Jeremiah replied. “I am not deserting to the Chaldeans!” But Irijah would not listen to him; instead, he arrested Jeremiah and took him to the officials.'),
('JER', 37, 15, 'JER.37.15', 'The officials were angry with Jeremiah, and they beat him and placed him in jail in the house of Jonathan the scribe, for it had been made into a prison.'),
('JER', 37, 16, 'JER.37.16', 'So Jeremiah went into a cell in the dungeon and remained there a long time.'),
('JER', 37, 17, 'JER.37.17', 'Later, King Zedekiah sent for Jeremiah and received him in his palace, where he asked him privately, “Is there a word from the LORD?” “There is,” Jeremiah replied. “You will be delivered into the hand of the king of Babylon.”'),
('JER', 37, 18, 'JER.37.18', 'Then Jeremiah asked King Zedekiah, “How have I sinned against you or your servants or these people, that you have put me in prison?'),
('JER', 37, 19, 'JER.37.19', 'Where are your prophets who prophesied to you, claiming, ‘The king of Babylon will not come against you or this land’?'),
('JER', 37, 20, 'JER.37.20', 'But now please listen, O my lord the king. May my petition come before you. Do not send me back to the house of Jonathan the scribe, or I will die there.”'),
('JER', 37, 21, 'JER.37.21', 'So King Zedekiah gave orders for Jeremiah to be placed in the courtyard of the guard and given a loaf of bread daily from the street of the bakers, until all the bread in the city was gone. So Jeremiah remained in the courtyard of the guard.'),
('JER', 38, 1, 'JER.38.1', 'Now Shephatiah son of Mattan, Gedaliah son of Pashhur, Jucal son of Shelemiah, and Pashhur son of Malchijah heard that Jeremiah had been telling all the people:'),
('JER', 38, 2, 'JER.38.2', '“This is what the LORD says: Whoever stays in this city will die by sword and famine and plague, but whoever surrenders to the Chaldeans will live; he will retain his life like a spoil of war, and he will live.'),
('JER', 38, 3, 'JER.38.3', 'This is what the LORD says: This city will surely be delivered into the hands of the army of the king of Babylon, and he will capture it.”'),
('JER', 38, 4, 'JER.38.4', 'Then the officials said to the king, “This man ought to die, for he is discouraging the warriors who remain in this city, as well as all the people, by speaking such words to them; this man is not seeking the well-being of these people, but their ruin.”'),
('JER', 38, 5, 'JER.38.5', '“Here he is,” replied King Zedekiah. “He is in your hands, since the king can do nothing to stop you.”'),
('JER', 38, 6, 'JER.38.6', 'So they took Jeremiah and dropped him into the cistern of Malchiah, the king’s son, which was in the courtyard of the guard. They lowered Jeremiah with ropes into the cistern, which had no water but only mud, and Jeremiah sank down into the mud.'),
('JER', 38, 7, 'JER.38.7', 'Now Ebed-melech the Cushite, a court official in the royal palace, heard that Jeremiah had been put into the cistern. While the king was sitting at the Gate of Benjamin,'),
('JER', 38, 8, 'JER.38.8', 'Ebed-melech went out from the king’s palace and said to the king,'),
('JER', 38, 9, 'JER.38.9', '“My lord the king, these men have acted wickedly in all that they have done to Jeremiah the prophet. They have dropped him into the cistern, where he will starve to death, for there is no more bread in the city.”'),
('JER', 38, 10, 'JER.38.10', 'So the king commanded Ebed-melech the Cushite, “Take thirty men from here with you and pull Jeremiah the prophet out of the cistern before he dies.”'),
('JER', 38, 11, 'JER.38.11', 'Then Ebed-melech took the men with him and went to the king’s palace, to a place below the storehouse. From there he took old rags and worn-out clothes and lowered them with ropes to Jeremiah in the cistern.'),
('JER', 38, 12, 'JER.38.12', 'Ebed-melech the Cushite cried out to Jeremiah, “Put these worn-out rags and clothes under your arms to pad the ropes.” Jeremiah did so,'),
('JER', 38, 13, 'JER.38.13', 'and they pulled him up with the ropes and lifted him out of the cistern. And Jeremiah remained in the courtyard of the guard.'),
('JER', 38, 14, 'JER.38.14', 'Then King Zedekiah sent for Jeremiah the prophet and received him at the third entrance to the house of the LORD. “I am going to ask you something,” said the king to Jeremiah. “Do not hide anything from me.”'),
('JER', 38, 15, 'JER.38.15', '“If I tell you,” Jeremiah replied, “you will surely put me to death. And even if I give you advice, you will not listen to me.”'),
('JER', 38, 16, 'JER.38.16', 'But King Zedekiah swore secretly to Jeremiah, “As surely as the LORD lives, who has given us this life, I will not kill you, nor will I deliver you into the hands of these men who are seeking your life.”'),
('JER', 38, 17, 'JER.38.17', 'Then Jeremiah said to Zedekiah, “This is what the LORD God of Hosts, the God of Israel, says: ‘If you indeed surrender to the officers of the king of Babylon, then you will live, this city will not be burned down, and you and your household will survive.'),
('JER', 38, 18, 'JER.38.18', 'But if you do not surrender to the officers of the king of Babylon, then this city will be delivered into the hands of the Chaldeans. They will burn it down, and you yourself will not escape their grasp.’”'),
('JER', 38, 19, 'JER.38.19', 'But King Zedekiah said to Jeremiah, “I am afraid of the Jews who have deserted to the Chaldeans, for the Chaldeans may deliver me into their hands to abuse me.”'),
('JER', 38, 20, 'JER.38.20', '“They will not hand you over,” Jeremiah replied. “Obey the voice of the LORD in what I am telling you, that it may go well with you and you may live.'),
('JER', 38, 21, 'JER.38.21', 'But if you refuse to surrender, this is the word that the LORD has shown me:'),
('JER', 38, 22, 'JER.38.22', 'All the women who remain in the palace of the king of Judah will be brought out to the officials of the king of Babylon, and those women will say: ‘They misled you and overcame you—those trusted friends of yours. Your feet sank into the mire, and they deserted you.’'),
('JER', 38, 23, 'JER.38.23', 'All your wives and children will be brought out to the Chaldeans. And you yourself will not escape their grasp, for you will be seized by the king of Babylon, and this city will be burned down.”'),
('JER', 38, 24, 'JER.38.24', 'Then Zedekiah warned Jeremiah, “Do not let anyone know about this conversation, or you will die.'),
('JER', 38, 25, 'JER.38.25', 'If the officials hear that I have spoken with you, and they come and demand of you, ‘Tell us what you said to the king and what he said to you; do not hide it from us, or we will kill you,’'),
('JER', 38, 26, 'JER.38.26', 'then tell them, ‘I was presenting to the king my petition that he not return me to the house of Jonathan to die there.’”'),
('JER', 38, 27, 'JER.38.27', 'When all the officials came to Jeremiah and questioned him, he relayed to them the exact words the king had commanded him to say. So they said no more to him, for no one had overheard the conversation.'),
('JER', 38, 28, 'JER.38.28', 'And Jeremiah remained in the courtyard of the guard until the day Jerusalem was captured.'),
('JER', 39, 1, 'JER.39.1', 'In the ninth year of Zedekiah king of Judah, in the tenth month, Nebuchadnezzar king of Babylon marched against Jerusalem with his entire army and laid siege to the city.'),
('JER', 39, 2, 'JER.39.2', 'And on the ninth day of the fourth month of Zedekiah’s eleventh year, the city was breached.'),
('JER', 39, 3, 'JER.39.3', 'Then all the officials of the king of Babylon entered and sat in the Middle Gate: Nergal-sharezer of Samgar, Nebo-sarsekim the Rabsaris, Nergal-sharezer the Rabmag, and all the rest of the officials of the king of Babylon.'),
('JER', 39, 4, 'JER.39.4', 'When Zedekiah king of Judah and all the soldiers saw them, they fled. They left the city at night by way of the king’s garden, through the gate between the two walls, and they went out along the route to the Arabah.'),
('JER', 39, 5, 'JER.39.5', 'But the army of the Chaldeans pursued them and overtook Zedekiah in the plains of Jericho. They seized him and brought him up to Nebuchadnezzar king of Babylon at Riblah in the land of Hamath, where he pronounced judgment on him.'),
('JER', 39, 6, 'JER.39.6', 'There at Riblah the king of Babylon slaughtered the sons of Zedekiah before his eyes, and he also killed all the nobles of Judah.'),
('JER', 39, 7, 'JER.39.7', 'Then he put out Zedekiah’s eyes and bound him with bronze chains to take him to Babylon.'),
('JER', 39, 8, 'JER.39.8', 'The Chaldeans set fire to the palace of the king and to the houses of the people, and they broke down the walls of Jerusalem.'),
('JER', 39, 9, 'JER.39.9', 'Then Nebuzaradan captain of the guard carried away to Babylon the remnant of the people who had remained in the city, along with the deserters who had defected to him.'),
('JER', 39, 10, 'JER.39.10', 'But Nebuzaradan left behind in the land of Judah some of the poor people who had no property, and at that time he gave them vineyards and fields.'),
('JER', 39, 11, 'JER.39.11', 'Now Nebuchadnezzar king of Babylon had given orders about Jeremiah through Nebuzaradan captain of the guard, saying,'),
('JER', 39, 12, 'JER.39.12', '“Take him, look after him, and do not let any harm come to him; do for him whatever he says.”'),
('JER', 39, 13, 'JER.39.13', 'So Nebuzaradan captain of the guard, Nebushazban the Rabsaris, Nergal-sharezer the Rabmag, and all the captains of the king of Babylon'),
('JER', 39, 14, 'JER.39.14', 'had Jeremiah brought from the courtyard of the guard, and they turned him over to Gedaliah son of Ahikam, the son of Shaphan, to take him home. So Jeremiah remained among his own people.'),
('JER', 39, 15, 'JER.39.15', 'And while Jeremiah had been confined in the courtyard of the guard, the word of the LORD had come to him:'),
('JER', 39, 16, 'JER.39.16', '“Go and tell Ebed-melech the Cushite that this is what the LORD of Hosts, the God of Israel, says: ‘I am about to fulfill My words against this city for harm and not for good, and on that day they will be fulfilled before your eyes.'),
('JER', 39, 17, 'JER.39.17', 'But I will deliver you on that day, declares the LORD, and you will not be delivered into the hands of the men whom you fear.'),
('JER', 39, 18, 'JER.39.18', 'For I will surely rescue you so that you do not fall by the sword. Because you have trusted in Me, you will escape with your life like a spoil of war, declares the LORD.’”'),
('JER', 40, 1, 'JER.40.1', 'This is the word that came to Jeremiah from the LORD after Nebuzaradan captain of the guard had released him at Ramah, having found him bound in chains among all the captives of Jerusalem and Judah who were being exiled to Babylon.'),
('JER', 40, 2, 'JER.40.2', 'The captain of the guard found Jeremiah and said to him, “The LORD your God decreed this disaster on this place,'),
('JER', 40, 3, 'JER.40.3', 'and now the LORD has fulfilled it; He has done just as He said. Because you people have sinned against the LORD and have not obeyed His voice, this thing has happened to you.'),
('JER', 40, 4, 'JER.40.4', 'But now, behold, I am freeing you today from the chains that were on your wrists. If it pleases you to come with me to Babylon, then come, and I will take care of you. But if it seems wrong to you to come with me to Babylon, go no farther. Look, the whole land is before you. Wherever it seems good and right to you, go there.”'),
('JER', 40, 5, 'JER.40.5', 'But before Jeremiah turned to go, Nebuzaradan added, “Return to Gedaliah son of Ahikam, the son of Shaphan, whom the king of Babylon has appointed over the cities of Judah, and stay with him among the people, or go anywhere else that seems right.” Then the captain of the guard gave him a ration and a gift and released him.'),
('JER', 40, 6, 'JER.40.6', 'So Jeremiah went to Gedaliah son of Ahikam at Mizpah and stayed with him among the people who were left in the land.'),
('JER', 40, 7, 'JER.40.7', 'When all the commanders and men of the armies in the field heard that the king of Babylon had appointed Gedaliah son of Ahikam over the land and that he had put him in charge of the men, women, and children who were the poorest of the land and had not been exiled to Babylon,'),
('JER', 40, 8, 'JER.40.8', 'they came to Gedaliah at Mizpah—Ishmael son of Nethaniah, Johanan and Jonathan the sons of Kareah, Seraiah son of Tanhumeth, the sons of Ephai the Netophathite, and Jezaniah son of the Maacathite—they and their men.'),
('JER', 40, 9, 'JER.40.9', 'Gedaliah son of Ahikam, the son of Shaphan, swore an oath to them and their men, assuring them, “Do not be afraid to serve the Chaldeans. Live in the land and serve the king of Babylon, and it will go well with you.'),
('JER', 40, 10, 'JER.40.10', 'As for me, I will stay in Mizpah to represent you before the Chaldeans who come to us. As for you, gather wine grapes, summer fruit, and oil, place them in your storage jars, and live in the cities you have taken.”'),
('JER', 40, 11, 'JER.40.11', 'When all the Jews in Moab, Ammon, Edom, and all the other lands heard that the king of Babylon had left a remnant in Judah and had appointed Gedaliah son of Ahikam, the son of Shaphan, over them,'),
('JER', 40, 12, 'JER.40.12', 'they all returned from all the places to which they had been banished and came to the land of Judah, to Gedaliah at Mizpah. And they gathered an abundance of wine grapes and summer fruit.'),
('JER', 40, 13, 'JER.40.13', 'Meanwhile, Johanan son of Kareah and all the commanders of the armies in the field came to Gedaliah at Mizpah'),
('JER', 40, 14, 'JER.40.14', 'and said to him, “Are you aware that Baalis king of the Ammonites has sent Ishmael son of Nethaniah to take your life?” But Gedaliah son of Ahikam did not believe them.'),
('JER', 40, 15, 'JER.40.15', 'Then Johanan son of Kareah spoke privately to Gedaliah at Mizpah. “Let me go and kill Ishmael son of Nethaniah,” he said. “No one will know it. Why should he take your life and scatter all the people of Judah who have gathered to you, so that the remnant of Judah would perish?”'),
('JER', 40, 16, 'JER.40.16', 'But Gedaliah son of Ahikam said to Johanan son of Kareah, “Do not do such a thing! What you are saying about Ishmael is a lie.”'),
('JER', 41, 1, 'JER.41.1', 'In the seventh month, Ishmael son of Nethaniah, the son of Elishama, who was a member of the royal family and one of the king’s chief officers, came with ten men to Gedaliah son of Ahikam at Mizpah, and they ate a meal together there.'),
('JER', 41, 2, 'JER.41.2', 'Then Ishmael son of Nethaniah and the ten men who were with him got up and struck down Gedaliah son of Ahikam, the son of Shaphan, with the sword, killing the one whom the king of Babylon had appointed to govern the land.'),
('JER', 41, 3, 'JER.41.3', 'Ishmael also killed all the Jews who were with Gedaliah at Mizpah, as well as the Chaldean soldiers who were there.'),
('JER', 41, 4, 'JER.41.4', 'On the second day after the murder of Gedaliah, when no one yet knew about it,'),
('JER', 41, 5, 'JER.41.5', 'eighty men who had shaved off their beards, torn their garments, and cut themselves came from Shechem, Shiloh, and Samaria, carrying grain offerings and frankincense for the house of the LORD.'),
('JER', 41, 6, 'JER.41.6', 'And Ishmael son of Nethaniah went out from Mizpah to meet them, weeping as he went. When Ishmael encountered the men, he said, “Come to Gedaliah son of Ahikam.”'),
('JER', 41, 7, 'JER.41.7', 'And when they came into the city, Ishmael son of Nethaniah and the men with him slaughtered them and threw them into a cistern.'),
('JER', 41, 8, 'JER.41.8', 'But ten of the men among them said to Ishmael, “Do not kill us, for we have hidden treasure in the field—wheat, barley, oil, and honey!” So he refrained from killing them with the others.'),
('JER', 41, 9, 'JER.41.9', 'Now the cistern into which Ishmael had thrown all the bodies of the men he had struck down along with Gedaliah was a large one that King Asa had made for fear of Baasha king of Israel. Ishmael son of Nethaniah filled it with the slain.'),
('JER', 41, 10, 'JER.41.10', 'Then Ishmael took captive all the remnant of the people of Mizpah—the daughters of the king along with all the others who remained in Mizpah—over whom Nebuzaradan captain of the guard had appointed Gedaliah son of Ahikam. Ishmael son of Nethaniah took them captive and set off to cross over to the Ammonites.'),
('JER', 41, 11, 'JER.41.11', 'When Johanan son of Kareah and all the commanders of the armies with him heard of all the crimes that Ishmael son of Nethaniah had committed,'),
('JER', 41, 12, 'JER.41.12', 'they took all their men and went to fight Ishmael son of Nethaniah. And they found him near the great pool in Gibeon.'),
('JER', 41, 13, 'JER.41.13', 'When all the people with Ishmael saw Johanan son of Kareah and all the commanders of the army with him, they rejoiced,'),
('JER', 41, 14, 'JER.41.14', 'and all the people whom Ishmael had taken captive at Mizpah turned and went over to Johanan son of Kareah.'),
('JER', 41, 15, 'JER.41.15', 'But Ishmael son of Nethaniah and eight of his men escaped from Johanan and went to the Ammonites.'),
('JER', 41, 16, 'JER.41.16', 'Then Johanan son of Kareah and all the commanders of the armies with him took the whole remnant of the people from Mizpah whom he had recovered from Ishmael son of Nethaniah after Ishmael had killed Gedaliah son of Ahikam: the soldiers, women, children, and court officials he had brought back from Gibeon.'),
('JER', 41, 17, 'JER.41.17', 'And they went and stayed in Geruth Chimham, near Bethlehem, in order to proceed into Egypt'),
('JER', 41, 18, 'JER.41.18', 'to escape the Chaldeans. For they were afraid of the Chaldeans because Ishmael son of Nethaniah had struck down Gedaliah son of Ahikam, whom the king of Babylon had appointed over the land.'),
('JER', 42, 1, 'JER.42.1', 'Then all the commanders of the forces, along with Johanan son of Kareah, Jezaniah son of Hoshaiah, and all the people from the least to the greatest, approached'),
('JER', 42, 2, 'JER.42.2', 'Jeremiah the prophet and said, “May our petition come before you; pray to the LORD your God on behalf of this entire remnant. For few of us remain of the many, as you can see with your own eyes.'),
('JER', 42, 3, 'JER.42.3', 'Pray that the LORD your God will tell us the way we should walk and the thing we should do.”'),
('JER', 42, 4, 'JER.42.4', '“I have heard you,” replied Jeremiah the prophet. “I will surely pray to the LORD your God as you request, and I will tell you everything that the LORD answers. I will not withhold a word from you.”'),
('JER', 42, 5, 'JER.42.5', 'Then they said to Jeremiah, “May the LORD be a true and faithful witness against us if we do not act upon every word that the LORD your God sends you to tell us.'),
('JER', 42, 6, 'JER.42.6', 'Whether it is pleasant or unpleasant, we will obey the voice of the LORD our God to whom we are sending you, so that it may go well with us when we obey the voice of the LORD our God!”'),
('JER', 42, 7, 'JER.42.7', 'After ten days the word of the LORD came to Jeremiah,'),
('JER', 42, 8, 'JER.42.8', 'and he summoned Johanan son of Kareah, all the commanders of the forces who were with him, and all the people from the least to the greatest.'),
('JER', 42, 9, 'JER.42.9', 'Jeremiah told them, “Thus says the LORD, the God of Israel, to whom you sent me to present your petition:'),
('JER', 42, 10, 'JER.42.10', '‘If you will indeed stay in this land, then I will build you up and not tear you down; I will plant you and not uproot you, for I will relent of the disaster I have brought upon you.'),
('JER', 42, 11, 'JER.42.11', 'Do not be afraid of the king of Babylon, whom you now fear; do not be afraid of him, declares the LORD, for I am with you to save you and deliver you from him.'),
('JER', 42, 12, 'JER.42.12', 'And I will show you compassion, and he will have compassion on you and restore you to your own land.’'),
('JER', 42, 13, 'JER.42.13', 'But if you say, ‘We will not stay in this land,’ and you thus disobey the voice of the LORD your God,'),
('JER', 42, 14, 'JER.42.14', 'and if you say, ‘No, but we will go to the land of Egypt and live there, where we will not see war or hear the sound of the ram’s horn or hunger for bread,’'),
('JER', 42, 15, 'JER.42.15', 'then hear the word of the LORD, O remnant of Judah! This is what the LORD of Hosts, the God of Israel, says: ‘If you are determined to go to Egypt and reside there,'),
('JER', 42, 16, 'JER.42.16', 'then the sword you fear will overtake you there, and the famine you dread will follow on your heels into Egypt, and you will die there.'),
('JER', 42, 17, 'JER.42.17', 'So all who resolve to go to Egypt to reside there will die by sword and famine and plague. Not one of them will survive or escape the disaster I will bring upon them.’'),
('JER', 42, 18, 'JER.42.18', 'For this is what the LORD of Hosts, the God of Israel, says: ‘Just as My anger and wrath were poured out on the residents of Jerusalem, so will My wrath be poured out on you if you go to Egypt. You will become an object of cursing and horror, of vilification and disgrace, and you will never see this place again.’'),
('JER', 42, 19, 'JER.42.19', 'The LORD has told you, O remnant of Judah, ‘Do not go to Egypt.’ Know for sure that I have warned you today!'),
('JER', 42, 20, 'JER.42.20', 'For you have deceived yourselves by sending me to the LORD your God, saying, ‘Pray to the LORD our God on our behalf, and as for all that the LORD our God says, tell it to us and we will do it.’'),
('JER', 42, 21, 'JER.42.21', 'For I have told you today, but you have not obeyed the voice of the LORD your God in all He has sent me to tell you.'),
('JER', 42, 22, 'JER.42.22', 'Now therefore, know for sure that by sword and famine and plague you will die in the place where you desire to go to reside.”'),
('JER', 43, 1, 'JER.43.1', 'When Jeremiah had finished telling all the people all the words of the LORD their God—everything that the LORD had sent him to say—'),
('JER', 43, 2, 'JER.43.2', 'Azariah son of Hoshaiah, Johanan son of Kareah, and all the arrogant men said to Jeremiah, “You are lying! The LORD our God has not sent you to say, ‘You must not go to Egypt to reside there.’'),
('JER', 43, 3, 'JER.43.3', 'Rather, Baruch son of Neriah is inciting you against us to deliver us into the hands of the Chaldeans, so that they may put us to death or exile us to Babylon!”'),
('JER', 43, 4, 'JER.43.4', 'So Johanan son of Kareah and all the commanders of the forces disobeyed the command of the LORD to stay in the land of Judah.'),
('JER', 43, 5, 'JER.43.5', 'Instead, Johanan son of Kareah and all the commanders of the forces took the whole remnant of Judah, those who had returned to the land of Judah from all the nations to which they had been scattered,'),
('JER', 43, 6, 'JER.43.6', 'the men, the women, the children, the king’s daughters, and everyone whom Nebuzaradan captain of the guard had allowed to remain with Gedaliah son of Ahikam, the son of Shaphan, as well as Jeremiah the prophet and Baruch son of Neriah.'),
('JER', 43, 7, 'JER.43.7', 'So they entered the land of Egypt because they did not obey the voice of the LORD, and they went as far as Tahpanhes.'),
('JER', 43, 8, 'JER.43.8', 'Then the word of the LORD came to Jeremiah at Tahpanhes:'),
('JER', 43, 9, 'JER.43.9', '“In the sight of the Jews, pick up some large stones and bury them in the clay of the brick pavement at the entrance to Pharaoh’s palace at Tahpanhes.'),
('JER', 43, 10, 'JER.43.10', 'Then tell them that this is what the LORD of Hosts, the God of Israel, says: ‘I will send for My servant Nebuchadnezzar king of Babylon, and I will set his throne over these stones that I have embedded, and he will spread his royal pavilion over them.'),
('JER', 43, 11, 'JER.43.11', 'He will come and strike down the land of Egypt, bringing death to those destined for death, captivity to those destined for captivity, and the sword to those destined for the sword.'),
('JER', 43, 12, 'JER.43.12', 'I will kindle a fire in the temples of the gods of Egypt, and Nebuchadnezzar will burn those temples and take their gods as captives. So he will wrap himself with the land of Egypt as a shepherd wraps himself in his garment, and he will depart from there unscathed.'),
('JER', 43, 13, 'JER.43.13', 'He will demolish the sacred pillars of the temple of the sun in the land of Egypt, and he will burn down the temples of the gods of Egypt.’”'),
('JER', 44, 1, 'JER.44.1', 'This is the word that came to Jeremiah concerning all the Jews living in the land of Egypt—in Migdol, Tahpanhes, and Memphis—and in the land of Pathros:'),
('JER', 44, 2, 'JER.44.2', '“This is what the LORD of Hosts, the God of Israel, says: You have seen all the disaster that I brought against Jerusalem and all the cities of Judah; and behold, they lie today in ruins and desolation'),
('JER', 44, 3, 'JER.44.3', 'because of the evil they have done. They provoked Me to anger by continuing to burn incense and to serve other gods that neither they nor you nor your fathers ever knew.'),
('JER', 44, 4, 'JER.44.4', 'Yet I sent you all My servants the prophets again and again, saying: ‘Do not do this detestable thing that I hate.’'),
('JER', 44, 5, 'JER.44.5', 'But they did not listen or incline their ears; they did not turn from their wickedness or stop burning incense to other gods.'),
('JER', 44, 6, 'JER.44.6', 'Therefore My wrath and anger poured out and burned in the cities of Judah and in the streets of Jerusalem, so that they have become the desolate ruin they are today.'),
('JER', 44, 7, 'JER.44.7', 'So now, this is what the LORD God of Hosts, the God of Israel, says: Why are you doing such great harm to yourselves by cutting off from Judah man and woman, child and infant, leaving yourselves without a remnant?'),
('JER', 44, 8, 'JER.44.8', 'Why are you provoking Me to anger by the work of your hands by burning incense to other gods in the land of Egypt, where you have gone to reside? As a result, you will be cut off and will become an object of cursing and reproach among all the nations of the earth.'),
('JER', 44, 9, 'JER.44.9', 'Have you forgotten the wickedness of your fathers and of the kings of Judah and their wives, as well as the wickedness that you and your wives committed in the land of Judah and in the streets of Jerusalem?'),
('JER', 44, 10, 'JER.44.10', 'To this day they have not humbled themselves or shown reverence, nor have they followed My instruction or the statutes that I set before you and your fathers.'),
('JER', 44, 11, 'JER.44.11', 'Therefore this is what the LORD of Hosts, the God of Israel, says: I will set My face to bring disaster and to cut off all Judah.'),
('JER', 44, 12, 'JER.44.12', 'And I will take away the remnant of Judah who have resolved to go to the land of Egypt to reside there; they will meet their end. They will all fall by the sword or be consumed by famine. From the least to the greatest, they will die by sword or famine; and they will become an object of cursing and horror, of vilification and reproach.'),
('JER', 44, 13, 'JER.44.13', 'I will punish those who live in the land of Egypt, just as I punished Jerusalem, by sword and famine and plague,'),
('JER', 44, 14, 'JER.44.14', 'so that none of the remnant of Judah who have gone to reside in Egypt will escape or survive to return to the land of Judah, where they long to return and live; for none will return except a few fugitives.”'),
('JER', 44, 15, 'JER.44.15', 'Then all the men who knew that their wives were burning incense to other gods, and all the women standing by—a great assembly—along with all the people living in the land of Egypt and in Pathros, said to Jeremiah,'),
('JER', 44, 16, 'JER.44.16', '“As for the word you have spoken to us in the name of the LORD, we will not listen to you!'),
('JER', 44, 17, 'JER.44.17', 'Instead, we will do everything we vowed to do: We will burn incense to the Queen of Heaven and offer drink offerings to her, just as we, our fathers, our kings, and our officials did in the cities of Judah and in the streets of Jerusalem. At that time we had plenty of food and good things, and we saw no disaster.'),
('JER', 44, 18, 'JER.44.18', 'But from the time we stopped burning incense to the Queen of Heaven and pouring out drink offerings to her, we have lacked everything and have been perishing by sword and famine.”'),
('JER', 44, 19, 'JER.44.19', '“Moreover,” said the women, “when we burned incense to the Queen of Heaven and poured out drink offerings to her, was it without our husbands’ knowledge that we made sacrificial cakes in her image and poured out drink offerings to her?”'),
('JER', 44, 20, 'JER.44.20', 'Then Jeremiah said to all the people, both men and women, who were answering him,'),
('JER', 44, 21, 'JER.44.21', '“As for the incense you burned in the cities of Judah and in the streets of Jerusalem—you, your fathers, your kings, your officials, and the people of the land—did the LORD not remember and bring this to mind?'),
('JER', 44, 22, 'JER.44.22', 'So the LORD could no longer endure the evil deeds and detestable acts you committed, and your land became a desolation, a horror, and an object of cursing, without inhabitant, as it is this day.'),
('JER', 44, 23, 'JER.44.23', 'Because you burned incense and sinned against the LORD and did not obey the voice of the LORD or walk in His instruction, His statutes, and His testimonies, this disaster has befallen you, as you see today.”'),
('JER', 44, 24, 'JER.44.24', 'Then Jeremiah said to all the people, including all the women, “Hear the word of the LORD, all those of Judah who are in the land of Egypt.'),
('JER', 44, 25, 'JER.44.25', 'This is what the LORD of Hosts, the God of Israel, says: As for you and your wives, you have spoken with your mouths and fulfilled with your hands your words: ‘We will surely perform our vows that we have made to burn incense to the Queen of Heaven and to pour out drink offerings to her.’ Go ahead, then, do what you have promised! Keep your vows!'),
('JER', 44, 26, 'JER.44.26', 'Nevertheless, hear the word of the LORD, all you people of Judah living in Egypt: Behold, I have sworn by My great name, says the LORD, that never again will any man of Judah living in the land of Egypt invoke My name or say, ‘As surely as the Lord GOD lives.’'),
('JER', 44, 27, 'JER.44.27', 'I am watching over them for harm and not for good, and every man of Judah who is in the land of Egypt will meet his end by sword or famine, until they are finished off.'),
('JER', 44, 28, 'JER.44.28', 'Those who escape the sword will return from Egypt to Judah, few in number, and the whole remnant of Judah who went to dwell in the land of Egypt will know whose word will stand, Mine or theirs!'),
('JER', 44, 29, 'JER.44.29', 'This will be a sign to you that I will punish you in this place, declares the LORD, so that you may know that My threats of harm against you will surely stand.'),
('JER', 44, 30, 'JER.44.30', 'This is what the LORD says: Behold, I will deliver Pharaoh Hophra king of Egypt into the hands of his enemies who seek his life, just as I delivered Zedekiah king of Judah into the hand of Nebuchadnezzar king of Babylon, the enemy who was seeking his life.”'),
('JER', 45, 1, 'JER.45.1', 'This is the word that Jeremiah the prophet spoke to Baruch son of Neriah when he wrote these words on a scroll at the dictation of Jeremiah in the fourth year of Jehoiakim son of Josiah, king of Judah:'),
('JER', 45, 2, 'JER.45.2', '“This is what the LORD, the God of Israel, says to you, Baruch:'),
('JER', 45, 3, 'JER.45.3', 'You have said, ‘Woe is me because the LORD has added sorrow to my pain! I am worn out with groaning and have found no rest.’”'),
('JER', 45, 4, 'JER.45.4', 'Thus Jeremiah was to say to Baruch: “This is what the LORD says: Throughout the land I will demolish what I have built and uproot what I have planted.'),
('JER', 45, 5, 'JER.45.5', 'But as for you, do you seek great things for yourself? Stop seeking! For I will bring disaster on every living creature, declares the LORD, but wherever you go, I will grant your life as a spoil of war.”'),
('JER', 46, 1, 'JER.46.1', 'This is the word of the LORD about the nations—the word that came to Jeremiah the prophet'),
('JER', 46, 2, 'JER.46.2', 'concerning Egypt and the army of Pharaoh Neco king of Egypt, which was defeated at Carchemish on the Euphrates River by Nebuchadnezzar king of Babylon in the fourth year of Jehoiakim the son of Josiah king of Judah:'),
('JER', 46, 3, 'JER.46.3', '“Deploy your shields, small and large; advance for battle!'),
('JER', 46, 4, 'JER.46.4', 'Harness the horses; mount the steeds; take your positions with helmets on! Polish your spears; put on armor!'),
('JER', 46, 5, 'JER.46.5', 'Why am I seeing this? They are terrified, they are retreating; their warriors are defeated, they flee in haste without looking back; terror is on every side!” declares the LORD.'),
('JER', 46, 6, 'JER.46.6', '“The swift cannot flee, and the warrior cannot escape! In the north by the River Euphrates they stumble and fall.'),
('JER', 46, 7, 'JER.46.7', 'Who is this, rising like the Nile, like rivers whose waters churn?'),
('JER', 46, 8, 'JER.46.8', 'Egypt rises like the Nile, and its waters churn like rivers, boasting, ‘I will rise and cover the earth; I will destroy the cities and their people.’'),
('JER', 46, 9, 'JER.46.9', 'Advance, O horses! Race furiously, O chariots! Let the warriors come forth—Cush and Put carrying their shields, men of Lydia drawing the bow.'),
('JER', 46, 10, 'JER.46.10', 'For that day belongs to the Lord GOD of Hosts, a day of vengeance against His foes. The sword will devour until it is satisfied, until it is quenched with their blood. For the Lord GOD of Hosts will hold a sacrifice in the land of the north by the River Euphrates.'),
('JER', 46, 11, 'JER.46.11', 'Go up to Gilead for balm, O Virgin Daughter of Egypt! In vain you try many remedies, but for you there is no healing.'),
('JER', 46, 12, 'JER.46.12', 'The nations have heard of your shame, and your outcry fills the earth, because warrior stumbles over warrior and both of them have fallen together.”'),
('JER', 46, 13, 'JER.46.13', 'This is the word that the LORD spoke to Jeremiah the prophet about the coming of Nebuchadnezzar king of Babylon to strike the land of Egypt:'),
('JER', 46, 14, 'JER.46.14', '“Announce it in Egypt, and proclaim it in Migdol; proclaim it in Memphis and Tahpanhes: ‘Take your positions and prepare yourself, for the sword devours those around you.’'),
('JER', 46, 15, 'JER.46.15', 'Why have your warriors been laid low? They cannot stand, for the LORD has thrust them down.'),
('JER', 46, 16, 'JER.46.16', 'They continue to stumble; indeed, they have fallen over one another. They say, ‘Get up! Let us return to our people and to the land of our birth, away from the sword of the oppressor.’'),
('JER', 46, 17, 'JER.46.17', 'There they will cry out: ‘Pharaoh king of Egypt was all noise; he has let the appointed time pass him by.’'),
('JER', 46, 18, 'JER.46.18', 'As surely as I live, declares the King, whose name is the LORD of Hosts, there will come one who is like Tabor among the mountains and like Carmel by the sea.'),
('JER', 46, 19, 'JER.46.19', 'Pack your bags for exile, O daughter dwelling in Egypt! For Memphis will be laid waste, destroyed and uninhabited.'),
('JER', 46, 20, 'JER.46.20', 'Egypt is a beautiful heifer, but a gadfly from the north is coming against her.'),
('JER', 46, 21, 'JER.46.21', 'Even the mercenaries among her are like fattened calves. They too will turn back; together they will flee, they will not stand their ground, for the day of calamity is coming upon them—the time of their punishment.'),
('JER', 46, 22, 'JER.46.22', 'Egypt will hiss like a fleeing serpent, for the enemy will advance in force; with axes they will come against her like woodsmen cutting down trees.'),
('JER', 46, 23, 'JER.46.23', 'They will chop down her forest, declares the LORD, dense though it may be, for they are more numerous than locusts; they cannot be counted.'),
('JER', 46, 24, 'JER.46.24', 'The Daughter of Egypt will be put to shame; she will be delivered into the hands of the people of the north.”'),
('JER', 46, 25, 'JER.46.25', 'The LORD of Hosts, the God of Israel, says: “Behold, I am about to punish Amon god of Thebes, along with Pharaoh, Egypt with her gods and kings, and those who trust in Pharaoh.'),
('JER', 46, 26, 'JER.46.26', 'I will deliver them into the hands of those who seek their lives—of Nebuchadnezzar king of Babylon and his officers. But after this, Egypt will be inhabited as in days of old, declares the LORD.'),
('JER', 46, 27, 'JER.46.27', 'But you, O Jacob My servant, do not be afraid, and do not be dismayed, O Israel. For I will surely save you out of a distant place, your descendants from the land of their captivity! Jacob will return to quiet and ease, with no one to make him afraid.'),
('JER', 46, 28, 'JER.46.28', 'And you, My servant Jacob, do not be afraid, declares the LORD, for I am with you. Though I will completely destroy all the nations to which I have banished you, I will not completely destroy you. Yet I will discipline you justly, and will by no means leave you unpunished.”'),
('JER', 47, 1, 'JER.47.1', 'This is the word of the LORD that came to Jeremiah the prophet about the Philistines before Pharaoh struck down Gaza.'),
('JER', 47, 2, 'JER.47.2', 'This is what the LORD says: “See how the waters are rising from the north and becoming an overflowing torrent. They will overflow the land and its fullness, the cities and their inhabitants. The people will cry out, and all who dwell in the land will wail'),
('JER', 47, 3, 'JER.47.3', 'at the sound of the galloping hooves of stallions, the rumbling of chariots, and the clatter of their wheels. The fathers will not turn back for their sons; their hands will hang limp.'),
('JER', 47, 4, 'JER.47.4', 'For the day has come to destroy all the Philistines, to cut off from Tyre and Sidon every remaining ally. Indeed, the LORD is about to destroy the Philistines, the remnant from the coasts of Caphtor.'),
('JER', 47, 5, 'JER.47.5', 'The people of Gaza will shave their heads in mourning; Ashkelon will be silenced. O remnant of their valley, how long will you gash yourself?'),
('JER', 47, 6, 'JER.47.6', '‘Alas, O sword of the LORD, how long until you rest? Return to your sheath; cease and be still!’'),
('JER', 47, 7, 'JER.47.7', 'How can it rest when the LORD has commanded it? He has appointed it against Ashkelon and the shore of its coastland.”'),
('JER', 48, 1, 'JER.48.1', 'Concerning Moab, this is what the LORD of Hosts, the God of Israel, says: “Woe to Nebo, for it will be devastated. Kiriathaim will be captured and disgraced; the fortress will be shattered and dismantled.'),
('JER', 48, 2, 'JER.48.2', 'There is no longer praise for Moab; in Heshbon they devise evil against her: ‘Come, let us cut her off from nationhood.’ You too, O people of Madmen, will be silenced; the sword will pursue you.'),
('JER', 48, 3, 'JER.48.3', 'A voice cries out from Horonaim: ‘Devastation and great destruction!’'),
('JER', 48, 4, 'JER.48.4', 'Moab will be shattered; her little ones will cry out.'),
('JER', 48, 5, 'JER.48.5', 'For on the ascent to Luhith they weep bitterly as they go, and on the descent to Horonaim cries of distress resound over the destruction:'),
('JER', 48, 6, 'JER.48.6', '‘Flee! Run for your lives! Become like a juniper in the desert.’'),
('JER', 48, 7, 'JER.48.7', 'Because you trust in your works and treasures, you too will be captured, and Chemosh will go into exile with his priests and officials.'),
('JER', 48, 8, 'JER.48.8', 'The destroyer will move against every city, and not one town will escape. The valley will also be ruined, and the high plain will be destroyed, as the LORD has said.'),
('JER', 48, 9, 'JER.48.9', 'Put salt on Moab, for she will be laid waste; her cities will become desolate, with no one to dwell in them.'),
('JER', 48, 10, 'JER.48.10', 'Cursed is the one who is remiss in doing the work of the LORD, and cursed is he who withholds his sword from bloodshed.'),
('JER', 48, 11, 'JER.48.11', 'Moab has been at ease from youth, settled like wine on its dregs; he has not been poured from vessel to vessel or gone into exile. So his flavor has remained the same, and his aroma is unchanged.'),
('JER', 48, 12, 'JER.48.12', 'Therefore behold, the days are coming, declares the LORD, when I will send to him wanderers, who will pour him out. They will empty his vessels and shatter his jars.'),
('JER', 48, 13, 'JER.48.13', 'Then Moab will be ashamed of Chemosh, just as the house of Israel was ashamed when they trusted in Bethel.'),
('JER', 48, 14, 'JER.48.14', 'How can you say, ‘We are warriors, mighty men ready for battle’?'),
('JER', 48, 15, 'JER.48.15', 'Moab has been destroyed and its towns have been invaded; the best of its young men have gone down in the slaughter, declares the King, whose name is the LORD of Hosts.'),
('JER', 48, 16, 'JER.48.16', 'Moab’s calamity is at hand, and his affliction is rushing swiftly.'),
('JER', 48, 17, 'JER.48.17', 'Mourn for him, all you who surround him, everyone who knows his name; tell how the mighty scepter is shattered—the glorious staff!'),
('JER', 48, 18, 'JER.48.18', 'Come down from your glory; sit on parched ground, O daughter dwelling in Dibon, for the destroyer of Moab has come against you; he has destroyed your fortresses.'),
('JER', 48, 19, 'JER.48.19', 'Stand by the road and watch, O dweller of Aroer! Ask the man fleeing or the woman escaping, ‘What has happened?’'),
('JER', 48, 20, 'JER.48.20', 'Moab is put to shame, for it has been shattered. Wail and cry out! Declare by the Arnon that Moab is destroyed.'),
('JER', 48, 21, 'JER.48.21', 'Judgment has come upon the high plain—upon Holon, Jahzah, and Mephaath,'),
('JER', 48, 22, 'JER.48.22', 'upon Dibon, Nebo, and Beth-diblathaim,'),
('JER', 48, 23, 'JER.48.23', 'upon Kiriathaim, Beth-gamul, and Beth-meon,'),
('JER', 48, 24, 'JER.48.24', 'upon Kerioth, Bozrah, and all the towns of Moab, those far and near.'),
('JER', 48, 25, 'JER.48.25', 'The horn of Moab has been cut off, and his arm is broken,” declares the LORD.'),
('JER', 48, 26, 'JER.48.26', '“Make him drunk, because he has magnified himself against the LORD; so Moab will wallow in his own vomit, and he will also become a laughingstock.'),
('JER', 48, 27, 'JER.48.27', 'Was not Israel your object of ridicule? Was he ever found among thieves? For whenever you speak of him you shake your head.'),
('JER', 48, 28, 'JER.48.28', 'Abandon the towns and settle among the rocks, O dwellers of Moab! Be like a dove that nests at the mouth of a cave.'),
('JER', 48, 29, 'JER.48.29', 'We have heard of Moab’s pomposity, his exceeding pride and conceit, his proud arrogance and haughtiness of heart.'),
('JER', 48, 30, 'JER.48.30', 'I know his insolence,” declares the LORD, “but it is futile. His boasting is as empty as his deeds.'),
('JER', 48, 31, 'JER.48.31', 'Therefore I will wail for Moab; I will cry out for all of Moab; I will moan for the men of Kir-heres.'),
('JER', 48, 32, 'JER.48.32', 'I will weep for you, O vine of Sibmah, more than I weep for Jazer. Your tendrils have extended to the sea; they reach even to Jazer. The destroyer has descended on your summer fruit and grape harvest.'),
('JER', 48, 33, 'JER.48.33', 'Joy and gladness are removed from the orchard and from the fields of Moab. I have stopped the flow of wine from the presses; no one treads them with shouts of joy; their shouts are not for joy.'),
('JER', 48, 34, 'JER.48.34', 'There is a cry from Heshbon to Elealeh; they raise their voices to Jahaz, from Zoar to Horonaim and Eglath-shelishiyah; for even the waters of Nimrim have dried up.'),
('JER', 48, 35, 'JER.48.35', 'In Moab, declares the LORD, I will bring an end to those who make offerings on the high places and burn incense to their gods.'),
('JER', 48, 36, 'JER.48.36', 'Therefore My heart laments like a flute for Moab; it laments like a flute for the men of Kir-heres, because the wealth they acquired has perished.'),
('JER', 48, 37, 'JER.48.37', 'For every head is shaved and every beard is clipped; on every hand is a gash, and around every waist is sackcloth.'),
('JER', 48, 38, 'JER.48.38', 'On all the rooftops of Moab and in the public squares, everyone is mourning; for I have shattered Moab like an unwanted jar,” declares the LORD.'),
('JER', 48, 39, 'JER.48.39', '“How shattered it is! How they wail! How Moab has turned his back in shame! Moab has become an object of ridicule and horror to all those around him.”'),
('JER', 48, 40, 'JER.48.40', 'For this is what the LORD says: “Behold, an eagle swoops down and spreads his wings against Moab.'),
('JER', 48, 41, 'JER.48.41', 'Kirioth has been taken, and the strongholds seized. In that day the heart of Moab’s warriors will be like the heart of a woman in labor.'),
('JER', 48, 42, 'JER.48.42', 'Moab will be destroyed as a nation because he vaunted himself against the LORD.'),
('JER', 48, 43, 'JER.48.43', 'Terror and pit and snare await you, O dweller of Moab,” declares the LORD.'),
('JER', 48, 44, 'JER.48.44', '“Whoever flees the panic will fall into the pit, and whoever climbs from the pit will be caught in the snare. For I will bring upon Moab the year of their punishment,” declares the LORD.'),
('JER', 48, 45, 'JER.48.45', '“Those who flee will stand helpless in Heshbon’s shadow, because fire has gone forth from Heshbon and a flame from within Sihon. It devours the foreheads of Moab and the skulls of the sons of tumult.'),
('JER', 48, 46, 'JER.48.46', 'Woe to you, O Moab! The people of Chemosh have perished; for your sons have been taken into exile and your daughters have gone into captivity.'),
('JER', 48, 47, 'JER.48.47', 'Yet in the latter days I will restore Moab from captivity,” declares the LORD. Here ends the judgment on Moab.'),
('JER', 49, 1, 'JER.49.1', 'Concerning the Ammonites, this is what the LORD says: “Has Israel no sons? Is he without heir? Why then has Milcom taken possession of Gad? Why have his people settled in their cities?'),
('JER', 49, 2, 'JER.49.2', 'Therefore, behold, the days are coming, declares the LORD, when I will sound the battle cry against Rabbah of the Ammonites. It will become a heap of ruins, and its villages will be burned. Then Israel will drive out their dispossessors, says the LORD.'),
('JER', 49, 3, 'JER.49.3', 'Wail, O Heshbon, for Ai has been destroyed; cry out, O daughters of Rabbah! Put on sackcloth and mourn; run back and forth within your walls, for Milcom will go into exile together with his priests and officials.'),
('JER', 49, 4, 'JER.49.4', 'Why do you boast of your valleys—your valleys so fruitful, O faithless daughter? You trust in your riches and say, ‘Who can come against me?’'),
('JER', 49, 5, 'JER.49.5', 'Behold, I am about to bring terror upon you, declares the Lord GOD of Hosts, from all those around you. You will each be driven headlong, with no one to regather the fugitives.'),
('JER', 49, 6, 'JER.49.6', 'Yet afterward I will restore the Ammonites from captivity,” declares the LORD.'),
('JER', 49, 7, 'JER.49.7', 'Concerning Edom, this is what the LORD of Hosts says: “Is there no longer wisdom in Teman? Has counsel perished from the prudent? Has their wisdom decayed?'),
('JER', 49, 8, 'JER.49.8', 'Turn and run! Lie low, O dwellers of Dedan, for I will bring disaster on Esau at the time I punish him.'),
('JER', 49, 9, 'JER.49.9', 'If grape gatherers came to you, would they not leave some gleanings? Were thieves to come in the night, would they not steal only what they wanted?'),
('JER', 49, 10, 'JER.49.10', 'But I will strip Esau bare; I will uncover his hiding places, and he will be unable to conceal himself. His descendants will be destroyed along with his relatives and neighbors, and he will be no more.'),
('JER', 49, 11, 'JER.49.11', 'Abandon your orphans; I will preserve their lives. Let your widows trust in Me.”'),
('JER', 49, 12, 'JER.49.12', 'For this is what the LORD says: “If those who do not deserve to drink the cup must drink it, can you possibly remain unpunished? You will not go unpunished, for you must drink it too.'),
('JER', 49, 13, 'JER.49.13', 'For by Myself I have sworn, declares the LORD, that Bozrah will become a desolation, a disgrace, a ruin, and a curse, and all her cities will be in ruins forever.”'),
('JER', 49, 14, 'JER.49.14', 'I have heard a message from the LORD; an envoy has been sent to the nations: “Assemble yourselves to march against her! Rise up for battle!”'),
('JER', 49, 15, 'JER.49.15', '“For behold, I will make you small among nations, despised among men.'),
('JER', 49, 16, 'JER.49.16', 'The terror you cause and the pride of your heart have deceived you, O dwellers in the clefts of the rocks, O occupiers of the mountain summit. Though you elevate your nest like the eagle, even from there I will bring you down,” declares the LORD.'),
('JER', 49, 17, 'JER.49.17', '“Edom will become an object of horror. All who pass by will be appalled and will scoff at all her wounds.'),
('JER', 49, 18, 'JER.49.18', 'As Sodom and Gomorrah were overthrown along with their neighbors,” says the LORD, “no one will dwell there; no man will abide there.'),
('JER', 49, 19, 'JER.49.19', 'Behold, one will come up like a lion from the thickets of the Jordan to the watered pasture. For in an instant I will chase Edom from her land. Who is the chosen one I will appoint for this? For who is like Me, and who can challenge Me? What shepherd can stand against Me?”'),
('JER', 49, 20, 'JER.49.20', 'Therefore hear the plans that the LORD has drawn up against Edom and the strategies He has devised against the people of Teman: Surely the little ones of the flock will be dragged away; certainly their pasture will be made desolate because of them.'),
('JER', 49, 21, 'JER.49.21', 'At the sound of their fall the earth will quake; their cry will resound to the Red Sea.'),
('JER', 49, 22, 'JER.49.22', 'Look! An eagle will soar and swoop down, spreading its wings over Bozrah. In that day the hearts of Edom’s mighty men will be like the heart of a woman in labor.'),
('JER', 49, 23, 'JER.49.23', 'Concerning Damascus: “Hamath and Arpad are put to shame, for they have heard a bad report; they are agitated like the sea; their anxiety cannot be calmed.'),
('JER', 49, 24, 'JER.49.24', 'Damascus has become feeble; she has turned to flee. Panic has gripped her; anguish and pain have seized her like a woman in labor.'),
('JER', 49, 25, 'JER.49.25', 'How is the city of praise not forsaken, the town that brings Me joy?'),
('JER', 49, 26, 'JER.49.26', 'For her young men will fall in the streets, and all her warriors will be silenced in that day,” declares the LORD of Hosts.'),
('JER', 49, 27, 'JER.49.27', '“I will set fire to the walls of Damascus; it will consume the fortresses of Ben-hadad.”'),
('JER', 49, 28, 'JER.49.28', 'Concerning Kedar and the kingdoms of Hazor, which Nebuchadnezzar king of Babylon defeated, this is what the LORD says: “Rise up, advance against Kedar, and destroy the people of the east!'),
('JER', 49, 29, 'JER.49.29', 'They will take their tents and flocks, their tent curtains and all their goods. They will take their camels for themselves. They will shout to them: ‘Terror is on every side!’'),
('JER', 49, 30, 'JER.49.30', 'Run! Escape quickly! Lie low, O residents of Hazor,” declares the LORD, “for Nebuchadnezzar king of Babylon has drawn up a plan against you; he has devised a strategy against you.'),
('JER', 49, 31, 'JER.49.31', 'Rise up, advance against a nation at ease, one that dwells securely,” declares the LORD. “They have no gates or bars; they live alone.'),
('JER', 49, 32, 'JER.49.32', 'Their camels will become plunder, and their large herds will be spoil. I will scatter to the wind in every direction those who shave their temples; I will bring calamity on them from all sides,” declares the LORD.'),
('JER', 49, 33, 'JER.49.33', '“Hazor will become a haunt for jackals, a desolation forever. No one will dwell there; no man will abide there.”'),
('JER', 49, 34, 'JER.49.34', 'This is the word of the LORD that came to Jeremiah the prophet concerning Elam at the beginning of the reign of Zedekiah king of Judah.'),
('JER', 49, 35, 'JER.49.35', 'This is what the LORD of Hosts says: “Behold, I will shatter Elam’s bow, the mainstay of their might.'),
('JER', 49, 36, 'JER.49.36', 'I will bring the four winds against Elam from the four corners of the heavens, and I will scatter them to all these winds. There will not be a nation to which Elam’s exiles will not go.'),
('JER', 49, 37, 'JER.49.37', 'So I will shatter Elam before their foes, before those who seek their lives. I will bring disaster upon them, even My fierce anger,” declares the LORD. “I will send out the sword after them until I finish them off.'),
('JER', 49, 38, 'JER.49.38', 'I will set My throne in Elam, and destroy its king and officials,” declares the LORD.'),
('JER', 49, 39, 'JER.49.39', '“Yet in the last days, I will restore Elam from captivity,” declares the LORD.'),
('JER', 50, 1, 'JER.50.1', 'This is the word that the LORD spoke through Jeremiah the prophet concerning Babylon and the land of the Chaldeans:'),
('JER', 50, 2, 'JER.50.2', '“Announce and declare to the nations; lift up a banner and proclaim it; hold nothing back when you say, ‘Babylon is captured; Bel is put to shame; Marduk is shattered, her images are disgraced, her idols are broken in pieces.’'),
('JER', 50, 3, 'JER.50.3', 'For a nation from the north will come against her; it will make her land a desolation. No one will live in it; both man and beast will flee.”'),
('JER', 50, 4, 'JER.50.4', '“In those days and at that time, declares the LORD, the children of Israel and the children of Judah will come together, weeping as they come, and will seek the LORD their God.'),
('JER', 50, 5, 'JER.50.5', 'They will ask the way to Zion and turn their faces toward it. They will come and join themselves to the LORD in an everlasting covenant that will never be forgotten.'),
('JER', 50, 6, 'JER.50.6', 'My people are lost sheep; their shepherds have led them astray, causing them to roam the mountains. They have wandered from mountain to hill; they have forgotten their resting place.'),
('JER', 50, 7, 'JER.50.7', 'All who found them devoured them, and their enemies said, ‘We are not guilty, for they have sinned against the LORD, their true pasture, the LORD, the hope of their fathers.’'),
('JER', 50, 8, 'JER.50.8', 'Flee from the midst of Babylon; depart from the land of the Chaldeans; be like the he-goats that lead the flock.'),
('JER', 50, 9, 'JER.50.9', 'For behold, I stir up and bring against Babylon an assembly of great nations from the land of the north. They will line up against her; from the north she will be captured. Their arrows will be like skilled warriors who do not return empty-handed.'),
('JER', 50, 10, 'JER.50.10', 'Chaldea will be plundered; all who plunder her will have their fill,” declares the LORD.'),
('JER', 50, 11, 'JER.50.11', '“Because you rejoice, because you sing in triumph—you who plunder My inheritance—because you frolic like a heifer treading grain and neigh like stallions,'),
('JER', 50, 12, 'JER.50.12', 'your mother will be greatly ashamed; she who bore you will be disgraced. Behold, she will be the least of the nations, a wilderness, a dry land, and a desert.'),
('JER', 50, 13, 'JER.50.13', 'Because of the wrath of the LORD, she will not be inhabited; she will become completely desolate. All who pass through Babylon will be horrified and will hiss at all her wounds.'),
('JER', 50, 14, 'JER.50.14', 'Line up in formation around Babylon, all you who draw the bow! Shoot at her! Spare no arrows! For she has sinned against the LORD.'),
('JER', 50, 15, 'JER.50.15', 'Raise a war cry against her on every side! She has thrown up her hands in surrender; her towers have fallen; her walls are torn down. Since this is the vengeance of the LORD, take out your vengeance upon her; as she has done, do the same to her.'),
('JER', 50, 16, 'JER.50.16', 'Cut off the sower from Babylon, and the one who wields the sickle at harvest time. In the face of the oppressor’s sword, each will turn to his own people, each will flee to his own land.'),
('JER', 50, 17, 'JER.50.17', 'Israel is a scattered flock, chased away by lions. The first to devour him was the king of Assyria; the last to crush his bones was Nebuchadnezzar king of Babylon.”'),
('JER', 50, 18, 'JER.50.18', 'Therefore this is what the LORD of Hosts, the God of Israel, says: “I will punish the king of Babylon and his land as I punished the king of Assyria.'),
('JER', 50, 19, 'JER.50.19', 'I will return Israel to his pasture, and he will graze on Carmel and Bashan; his soul will be satisfied on the hills of Ephraim and Gilead.'),
('JER', 50, 20, 'JER.50.20', 'In those days and at that time, declares the LORD, a search will be made for Israel’s guilt, but there will be none, and for Judah’s sins, but they will not be found; for I will forgive the remnant I preserve.'),
('JER', 50, 21, 'JER.50.21', 'Go up against the land of Merathaim, and against the residents of Pekod. Kill them and devote them to destruction. Do all that I have commanded you,” declares the LORD.'),
('JER', 50, 22, 'JER.50.22', '“The noise of battle is in the land—the noise of great destruction.'),
('JER', 50, 23, 'JER.50.23', 'How the hammer of the whole earth lies broken and shattered! What a horror Babylon has become among the nations!'),
('JER', 50, 24, 'JER.50.24', 'I laid a snare for you, O Babylon, and you were caught before you knew it. You were found and captured because you challenged the LORD.'),
('JER', 50, 25, 'JER.50.25', 'The LORD has opened His armory and brought out His weapons of wrath, for this is the work of the Lord GOD of Hosts in the land of the Chaldeans.'),
('JER', 50, 26, 'JER.50.26', 'Come against her from the farthest border. Break open her granaries; pile her up like mounds of grain. Devote her to destruction; leave her no survivors.'),
('JER', 50, 27, 'JER.50.27', 'Kill all her young bulls; let them go down to the slaughter. Woe to them, for their day has come—the time of their punishment.'),
('JER', 50, 28, 'JER.50.28', 'Listen to the fugitives and refugees from the land of Babylon, declaring in Zion the vengeance of the LORD our God, the vengeance for His temple.'),
('JER', 50, 29, 'JER.50.29', 'Summon the archers against Babylon, all who string the bow. Encamp all around her; let no one escape. Repay her according to her deeds; do to her as she has done. For she has defied the LORD, the Holy One of Israel.'),
('JER', 50, 30, 'JER.50.30', 'Therefore, her young men will fall in the streets, and all her warriors will be silenced in that day,” declares the LORD.'),
('JER', 50, 31, 'JER.50.31', '“Behold, I am against you, O arrogant one,” declares the Lord GOD of Hosts, “for your day has come, the time when I will punish you.'),
('JER', 50, 32, 'JER.50.32', 'The arrogant one will stumble and fall with no one to pick him up. And I will kindle a fire in his cities to consume all those around him.”'),
('JER', 50, 33, 'JER.50.33', 'This is what the LORD of Hosts says: “The sons of Israel are oppressed, and the sons of Judah as well. All their captors hold them fast, refusing to release them.'),
('JER', 50, 34, 'JER.50.34', 'Their Redeemer is strong; the LORD of Hosts is His name. He will fervently plead their case so that He may bring rest to the earth, but turmoil to those who live in Babylon.'),
('JER', 50, 35, 'JER.50.35', 'A sword is against the Chaldeans, declares the LORD, against those who live in Babylon, and against her officials and wise men.'),
('JER', 50, 36, 'JER.50.36', 'A sword is against her false prophets, and they will become fools. A sword is against her warriors, and they will be filled with terror.'),
('JER', 50, 37, 'JER.50.37', 'A sword is against her horses and chariots and against all the foreigners in her midst, and they will become like women. A sword is against her treasuries, and they will be plundered.'),
('JER', 50, 38, 'JER.50.38', 'A drought is upon her waters, and they will be dried up. For it is a land of graven images, and the people go mad over idols.'),
('JER', 50, 39, 'JER.50.39', 'So the desert creatures and hyenas will live there and ostriches will dwell there. It will never again be inhabited or lived in from generation to generation.'),
('JER', 50, 40, 'JER.50.40', 'As God overthrew Sodom and Gomorrah along with their neighbors,” declares the LORD, “no one will dwell there; no man will abide there.'),
('JER', 50, 41, 'JER.50.41', 'Behold, an army is coming from the north; a great nation and many kings are stirred up from the ends of the earth.'),
('JER', 50, 42, 'JER.50.42', 'They grasp the bow and spear; they are cruel and merciless. Their voice roars like the sea, and they ride upon horses, lined up like men in formation against you, O Daughter of Babylon.'),
('JER', 50, 43, 'JER.50.43', 'The king of Babylon has heard the report, and his hands hang limp. Anguish has gripped him, pain like that of a woman in labor.'),
('JER', 50, 44, 'JER.50.44', 'Behold, one will come up like a lion from the thickets of the Jordan to the watered pasture. For in an instant I will chase Babylon from her land. Who is the chosen one I will appoint for this? For who is like Me, and who can challenge Me? What shepherd can stand against Me?”'),
('JER', 50, 45, 'JER.50.45', 'Therefore hear the plans that the LORD has drawn up against Babylon and the strategies He has devised against the land of the Chaldeans: Surely the little ones of the flock will be dragged away; certainly their pasture will be made desolate because of them.'),
('JER', 50, 46, 'JER.50.46', 'At the sound of Babylon’s capture the earth will quake; a cry will be heard among the nations.'),
('JER', 51, 1, 'JER.51.1', 'This is what the LORD says: “Behold, I will stir up against Babylon and against the people of Leb-kamai the spirit of a destroyer.'),
('JER', 51, 2, 'JER.51.2', 'I will send strangers to Babylon to winnow her and empty her land; for they will come against her from every side in her day of disaster.'),
('JER', 51, 3, 'JER.51.3', 'Do not let the archer bend his bow or put on his armor. Do not spare her young men; devote all her army to destruction!'),
('JER', 51, 4, 'JER.51.4', 'And they will fall slain in the land of the Chaldeans, and pierced through in her streets.'),
('JER', 51, 5, 'JER.51.5', 'For Israel and Judah have not been abandoned by their God, the LORD of Hosts, though their land is full of guilt before the Holy One of Israel.”'),
('JER', 51, 6, 'JER.51.6', 'Flee from Babylon! Escape with your lives! Do not be destroyed in her punishment. For this is the time of the LORD’s vengeance; He will pay her what she deserves.'),
('JER', 51, 7, 'JER.51.7', 'Babylon was a gold cup in the hand of the LORD, making the whole earth drunk. The nations drank her wine; therefore the nations have gone mad.'),
('JER', 51, 8, 'JER.51.8', 'Suddenly Babylon has fallen and been shattered. Wail for her; get her balm for her pain; perhaps she can be healed.'),
('JER', 51, 9, 'JER.51.9', '“We tried to heal Babylon, but she could not be healed. Abandon her! Let each of us go to his own land, for her judgment extends to the sky and reaches to the clouds.”'),
('JER', 51, 10, 'JER.51.10', '“The LORD has brought forth our vindication; come, let us tell in Zion what the LORD our God has accomplished.”'),
('JER', 51, 11, 'JER.51.11', 'Sharpen the arrows! Fill the quivers! The LORD has aroused the spirit of the kings of the Medes, because His plan is aimed at Babylon to destroy her, for it is the vengeance of the LORD—vengeance for His temple.'),
('JER', 51, 12, 'JER.51.12', 'Raise a banner against the walls of Babylon; post the guard; station the watchmen; prepare the ambush. For the LORD has both devised and accomplished what He spoke against the people of Babylon.'),
('JER', 51, 13, 'JER.51.13', 'You who dwell by many waters, rich in treasures, your end has come; the thread of your life is cut.'),
('JER', 51, 14, 'JER.51.14', 'The LORD of Hosts has sworn by Himself: “Surely I will fill you up with men as with locusts, and they will shout in triumph over you.”'),
('JER', 51, 15, 'JER.51.15', 'The LORD made the earth by His power; He established the world by His wisdom and stretched out the heavens by His understanding.'),
('JER', 51, 16, 'JER.51.16', 'When He thunders, the waters in the heavens roar; He causes the clouds to rise from the ends of the earth. He generates the lightning with the rain and brings forth the wind from His storehouses.'),
('JER', 51, 17, 'JER.51.17', 'Every man is senseless and devoid of knowledge; every goldsmith is put to shame by his idols. For his molten images are a fraud, and there is no breath in them.'),
('JER', 51, 18, 'JER.51.18', 'They are worthless, a work to be mocked. In the time of their punishment they will perish.'),
('JER', 51, 19, 'JER.51.19', 'The Portion of Jacob is not like these, for He is the Maker of all things, and of the tribe of His inheritance—the LORD of Hosts is His name.'),
('JER', 51, 20, 'JER.51.20', '“You are My war club, My weapon for battle. With you I shatter nations; with you I bring kingdoms to ruin.'),
('JER', 51, 21, 'JER.51.21', 'With you I shatter the horse and rider; with you I shatter the chariot and driver.'),
('JER', 51, 22, 'JER.51.22', 'With you I shatter man and woman; with you I shatter the old man and the youth; with you I shatter the young man and the maiden.'),
('JER', 51, 23, 'JER.51.23', 'With you I shatter the shepherd and his flock; with you I shatter the farmer and his oxen; with you I shatter the governors and officials.'),
('JER', 51, 24, 'JER.51.24', 'Before your very eyes I will repay Babylon and all the dwellers of Chaldea for all the evil they have done in Zion,” declares the LORD.'),
('JER', 51, 25, 'JER.51.25', '“Behold, I am against you, O destroying mountain, you who devastate the whole earth, declares the LORD. I will stretch out My hand against you; I will roll you over the cliffs and turn you into a charred mountain.'),
('JER', 51, 26, 'JER.51.26', 'No one shall retrieve from you a cornerstone or a foundation stone, because you will become desolate forever,” declares the LORD.'),
('JER', 51, 27, 'JER.51.27', '“Raise a banner in the land! Blow the ram’s horn among the nations! Prepare the nations against her. Summon the kingdoms against her—Ararat, Minni, and Ashkenaz. Appoint a captain against her; bring up horses like swarming locusts.'),
('JER', 51, 28, 'JER.51.28', 'Prepare the nations for battle against her—the kings of the Medes, their governors and all their officials, and all the lands they rule.'),
('JER', 51, 29, 'JER.51.29', 'The earth quakes and writhes because the LORD’s intentions against Babylon stand: to make the land of Babylon a desolation, without inhabitant.'),
('JER', 51, 30, 'JER.51.30', 'The warriors of Babylon have stopped fighting; they sit in their strongholds. Their strength is exhausted; they have become like women. Babylon’s homes have been set ablaze, the bars of her gates are broken.'),
('JER', 51, 31, 'JER.51.31', 'One courier races to meet another, and messenger follows messenger, to announce to the king of Babylon that his city has been captured from end to end.'),
('JER', 51, 32, 'JER.51.32', 'The fords have been seized, the marshes set on fire, and the soldiers are terrified.”'),
('JER', 51, 33, 'JER.51.33', 'For this is what the LORD of Hosts, the God of Israel, says: “The Daughter of Babylon is like a threshing floor at the time it is trampled. In just a little while her harvest time will come.”'),
('JER', 51, 34, 'JER.51.34', '“Nebuchadnezzar king of Babylon has devoured me; he has crushed me. He has set me aside like an empty vessel; he has swallowed me like a monster; he filled his belly with my delicacies and vomited me out.'),
('JER', 51, 35, 'JER.51.35', 'May the violence done to me and to my flesh be upon Babylon,” says the dweller of Zion. “May my blood be on the dwellers of Chaldea,” says Jerusalem.'),
('JER', 51, 36, 'JER.51.36', 'Therefore this is what the LORD says: “Behold, I will plead your case and take vengeance on your behalf; I will dry up her sea and make her springs run dry.'),
('JER', 51, 37, 'JER.51.37', 'Babylon will become a heap of rubble, a haunt for jackals, an object of horror and scorn, without inhabitant.'),
('JER', 51, 38, 'JER.51.38', 'They will roar together like young lions; they will growl like lion cubs.'),
('JER', 51, 39, 'JER.51.39', 'While they are flushed with heat, I will serve them a feast, and I will make them drunk so that they may revel; then they will fall asleep forever and never wake up, declares the LORD.'),
('JER', 51, 40, 'JER.51.40', 'I will bring them down like lambs to the slaughter, like rams with male goats.'),
('JER', 51, 41, 'JER.51.41', 'How Sheshach has been captured! The praise of all the earth has been seized. What a horror Babylon has become among the nations!'),
('JER', 51, 42, 'JER.51.42', 'The sea has come up over Babylon; she is covered in turbulent waves.'),
('JER', 51, 43, 'JER.51.43', 'Her cities have become a desolation, a dry and arid land, a land where no one lives, where no son of man passes through.'),
('JER', 51, 44, 'JER.51.44', 'I will punish Bel in Babylon. I will make him spew out what he swallowed. The nations will no longer stream to him; even the wall of Babylon will fall.'),
('JER', 51, 45, 'JER.51.45', 'Come out of her, My people! Save your lives, each of you, from the fierce anger of the LORD.'),
('JER', 51, 46, 'JER.51.46', 'Do not let your heart grow faint, and do not be afraid when the rumor is heard in the land; for a rumor will come one year—and then another the next year—of violence in the land and of ruler against ruler.'),
('JER', 51, 47, 'JER.51.47', 'Therefore, behold, the days are coming when I will punish the idols of Babylon. Her entire land will suffer shame, and all her slain will lie fallen within her.'),
('JER', 51, 48, 'JER.51.48', 'Then heaven and earth and all that is in them will shout for joy over Babylon because the destroyers from the north will come against her,” declares the LORD.'),
('JER', 51, 49, 'JER.51.49', '“Babylon must fall on account of the slain of Israel, just as the slain of all the earth have fallen because of Babylon.'),
('JER', 51, 50, 'JER.51.50', 'You who have escaped the sword, depart and do not linger! Remember the LORD from far away, and let Jerusalem come to mind.”'),
('JER', 51, 51, 'JER.51.51', '“We are ashamed because we have heard reproach; disgrace has covered our faces, because foreigners have entered the holy places of the LORD’s house.”'),
('JER', 51, 52, 'JER.51.52', '“Therefore, behold, the days are coming,” declares the LORD, “when I will punish her idols, and throughout her land the wounded will groan.'),
('JER', 51, 53, 'JER.51.53', 'Even if Babylon ascends to the heavens and fortifies her lofty stronghold, the destroyers I send will come against her,” declares the LORD.'),
('JER', 51, 54, 'JER.51.54', '“The sound of a cry comes from Babylon, the sound of great destruction from the land of the Chaldeans!'),
('JER', 51, 55, 'JER.51.55', 'For the LORD will destroy Babylon; He will silence her mighty voice. The waves will roar like great waters; the tumult of their voices will resound.'),
('JER', 51, 56, 'JER.51.56', 'For a destroyer is coming against her—against Babylon. Her warriors will be captured, and their bows will be broken, for the LORD is a God of retribution; He will repay in full.'),
('JER', 51, 57, 'JER.51.57', 'I will make her princes and wise men drunk, along with her governors, officials, and warriors. Then they will fall asleep forever and not wake up,” declares the King, whose name is the LORD of Hosts.'),
('JER', 51, 58, 'JER.51.58', 'This is what the LORD of Hosts says: “Babylon’s thick walls will be leveled, and her high gates consumed by fire. So the labor of the people will be for nothing; the nations will exhaust themselves to fuel the flames.”'),
('JER', 51, 59, 'JER.51.59', 'This is the message that Jeremiah the prophet gave to the quartermaster Seraiah son of Neriah, the son of Mahseiah, when he went to Babylon with King Zedekiah of Judah in the fourth year of Zedekiah’s reign.'),
('JER', 51, 60, 'JER.51.60', 'Jeremiah had written on a single scroll about all the disaster that would come upon Babylon—all these words that had been written concerning Babylon.'),
('JER', 51, 61, 'JER.51.61', 'And Jeremiah said to Seraiah, “When you get to Babylon, see that you read all these words aloud,'),
('JER', 51, 62, 'JER.51.62', 'and say, ‘O LORD, You have promised to cut off this place so that no one will remain—neither man nor beast. Indeed, it will be desolate forever.’'),
('JER', 51, 63, 'JER.51.63', 'When you finish reading this scroll, tie a stone to it and cast it into the Euphrates.'),
('JER', 51, 64, 'JER.51.64', 'Then you are to say, ‘In the same way Babylon will sink and never rise again, because of the disaster I will bring upon her. And her people will grow weary.’” Here end the words of Jeremiah.'),
('JER', 52, 1, 'JER.52.1', 'Zedekiah was twenty-one years old when he became king, and he reigned in Jerusalem eleven years. His mother’s name was Hamutal daughter of Jeremiah; she was from Libnah.'),
('JER', 52, 2, 'JER.52.2', 'And Zedekiah did evil in the sight of the LORD, just as Jehoiakim had done.'),
('JER', 52, 3, 'JER.52.3', 'For because of the anger of the LORD, all this happened in Jerusalem and Judah, until He finally banished them from His presence. And Zedekiah also rebelled against the king of Babylon.'),
('JER', 52, 4, 'JER.52.4', 'So in the ninth year of Zedekiah’s reign, on the tenth day of the tenth month, Nebuchadnezzar king of Babylon marched against Jerusalem with his entire army. They encamped outside the city and built a siege wall all around it.'),
('JER', 52, 5, 'JER.52.5', 'And the city was kept under siege until King Zedekiah’s eleventh year.'),
('JER', 52, 6, 'JER.52.6', 'By the ninth day of the fourth month, the famine in the city was so severe that the people of the land had no food.'),
('JER', 52, 7, 'JER.52.7', 'Then the city was breached; and though the Chaldeans had surrounded the city, all the men of war fled the city by night by way of the gate between the two walls near the king’s garden. They headed toward the Arabah,'),
('JER', 52, 8, 'JER.52.8', 'but the army of the Chaldeans pursued the king and overtook Zedekiah in the plains of Jericho, and his whole army deserted him.'),
('JER', 52, 9, 'JER.52.9', 'The Chaldeans seized the king and brought him up to the king of Babylon at Riblah in the land of Hamath, where he pronounced judgment on Zedekiah.'),
('JER', 52, 10, 'JER.52.10', 'There at Riblah the king of Babylon slaughtered the sons of Zedekiah before his eyes, and he also killed all the officials of Judah.'),
('JER', 52, 11, 'JER.52.11', 'Then he put out Zedekiah’s eyes, bound him with bronze shackles, and took him to Babylon, where he kept him in custody until his dying day.'),
('JER', 52, 12, 'JER.52.12', 'On the tenth day of the fifth month, in the nineteenth year of Nebuchadnezzar’s reign over Babylon, Nebuzaradan captain of the guard, a servant of the king of Babylon, entered Jerusalem.'),
('JER', 52, 13, 'JER.52.13', 'He burned down the house of the LORD, the royal palace, and all the houses of Jerusalem—every significant building.'),
('JER', 52, 14, 'JER.52.14', 'And the whole army of the Chaldeans under the captain of the guard broke down all the walls around Jerusalem.'),
('JER', 52, 15, 'JER.52.15', 'Then Nebuzaradan captain of the guard carried into exile some of the poorest people and those who remained in the city, along with the deserters who had defected to the king of Babylon and the rest of the craftsmen.'),
('JER', 52, 16, 'JER.52.16', 'But Nebuzaradan captain of the guard left behind some of the poorest of the land to tend the vineyards and fields.'),
('JER', 52, 17, 'JER.52.17', 'Moreover, the Chaldeans broke up the bronze pillars and stands and the bronze Sea in the house of the LORD, and they carried all the bronze to Babylon.'),
('JER', 52, 18, 'JER.52.18', 'They also took away the pots, shovels, wick trimmers, sprinkling bowls, dishes, and all the articles of bronze used in the temple service.'),
('JER', 52, 19, 'JER.52.19', 'The captain of the guard also took away the basins, censers, sprinkling bowls, pots, lampstands, pans, and drink offering bowls—anything made of pure gold or fine silver.'),
('JER', 52, 20, 'JER.52.20', 'As for the two pillars, the Sea, the twelve bronze bulls under it, and the movable stands that King Solomon had made for the house of the LORD, the weight of the bronze from all these articles was beyond measure.'),
('JER', 52, 21, 'JER.52.21', 'Each pillar was eighteen cubits tall and twelve cubits in circumference; each was hollow, four fingers thick.'),
('JER', 52, 22, 'JER.52.22', 'The bronze capital atop one pillar was five cubits high, with a network of bronze pomegranates all around. The second pillar, with its pomegranates, was similar.'),
('JER', 52, 23, 'JER.52.23', 'Each capital had ninety-six pomegranates on the sides, and a total of a hundred pomegranates were above the surrounding network.'),
('JER', 52, 24, 'JER.52.24', 'The captain of the guard also took away Seraiah the chief priest, Zephaniah the priest of second rank, and the three doorkeepers.'),
('JER', 52, 25, 'JER.52.25', 'Of those still in the city, he took a court official who had been appointed over the men of war, as well as seven trusted royal advisers. He also took the scribe of the captain of the army, who had enlisted the people of the land, and sixty men who were found in the city.'),
('JER', 52, 26, 'JER.52.26', 'Nebuzaradan captain of the guard took them and brought them to the king of Babylon at Riblah.'),
('JER', 52, 27, 'JER.52.27', 'There at Riblah in the land of Hamath, the king of Babylon struck them down and put them to death. So Judah was taken into exile, away from its own land.'),
('JER', 52, 28, 'JER.52.28', 'These are the people Nebuchadnezzar carried away: in the seventh year, 3,023 Jews;'),
('JER', 52, 29, 'JER.52.29', 'in Nebuchadnezzar’s eighteenth year, 832 people from Jerusalem;'),
('JER', 52, 30, 'JER.52.30', 'in Nebuchadnezzar’s twenty-third year, Nebuzaradan captain of the guard carried away 745 Jews. So in all, 4,600 people were taken away.'),
('JER', 52, 31, 'JER.52.31', 'On the twenty-fifth day of the twelfth month of the thirty-seventh year of the exile of Jehoiachin king of Judah, in the first year of the reign of Evil-merodach king of Babylon, he pardoned Jehoiachin king of Judah and released him from prison.'),
('JER', 52, 32, 'JER.52.32', 'And he spoke kindly to Jehoiachin and set his throne above the thrones of the other kings who were with him in Babylon.'),
('JER', 52, 33, 'JER.52.33', 'So Jehoiachin changed out of his prison clothes, and he dined regularly at the king’s table for the rest of his life.'),
('JER', 52, 34, 'JER.52.34', 'And the king of Babylon provided Jehoiachin a daily portion for the rest of his life, until the day of his death.'),
('LAM', 1, 1, 'LAM.1.1', 'How lonely lies the city, once so full of people! She who was great among the nations has become a widow. The princess of the provinces has become a slave.'),
('LAM', 1, 2, 'LAM.1.2', 'She weeps aloud in the night, with tears upon her cheeks. Among all her lovers there is no one to comfort her. All her friends have betrayed her; they have become her enemies.'),
('LAM', 1, 3, 'LAM.1.3', 'Judah has gone into exile under affliction and harsh slavery; she dwells among the nations but finds no place to rest. All her pursuers have overtaken her in the midst of her distress.'),
('LAM', 1, 4, 'LAM.1.4', 'The roads to Zion mourn, because no one comes to her appointed feasts. All her gates are deserted; her priests groan, her maidens grieve, and she herself is bitter with anguish.'),
('LAM', 1, 5, 'LAM.1.5', 'Her foes have become her masters; her enemies are at ease. For the LORD has brought her grief because of her many transgressions. Her children have gone away as captives before the enemy.'),
('LAM', 1, 6, 'LAM.1.6', 'All the splendor has departed from the Daughter of Zion. Her princes are like deer that find no pasture; they lack the strength to flee in the face of the hunter.'),
('LAM', 1, 7, 'LAM.1.7', 'In the days of her affliction and wandering Jerusalem remembers all the treasures that were hers in days of old. When her people fell into enemy hands she received no help. Her enemies looked upon her, laughing at her downfall.'),
('LAM', 1, 8, 'LAM.1.8', 'Jerusalem has sinned greatly; therefore she has become an object of scorn. All who honored her now despise her, for they have seen her nakedness; she herself groans and turns away.'),
('LAM', 1, 9, 'LAM.1.9', 'Her uncleanness stains her skirts; she did not consider her end. Her downfall was astounding; there was no one to comfort her. Look, O LORD, on my affliction, for the enemy has triumphed!'),
('LAM', 1, 10, 'LAM.1.10', 'The adversary has seized all her treasures. For she has seen the nations enter her sanctuary—those You had forbidden to enter Your assembly.'),
('LAM', 1, 11, 'LAM.1.11', 'All her people groan as they search for bread. They have traded their treasures for food to keep themselves alive. Look, O LORD, and consider, for I have become despised.'),
('LAM', 1, 12, 'LAM.1.12', 'Is this nothing to you, all you who pass by? Look around and see! Is there any sorrow like mine, which was inflicted on me, which the LORD made me suffer on the day of His fierce anger?'),
('LAM', 1, 13, 'LAM.1.13', 'He sent fire from on high, and it overpowered my bones. He spread a net for my feet and turned me back. He made me desolate, faint all the day long.'),
('LAM', 1, 14, 'LAM.1.14', 'My transgressions are bound into a yoke, knit together by His hand; they are draped over my neck, and the Lord has broken my strength. He has delivered me into the hands of those I cannot withstand.'),
('LAM', 1, 15, 'LAM.1.15', 'The Lord has rejected all the mighty men in my midst; He has summoned an army against me to crush my young warriors. Like grapes in a winepress, the Lord has trampled the Virgin Daughter of Judah.'),
('LAM', 1, 16, 'LAM.1.16', 'For these things I weep; my eyes flow with tears. For there is no one nearby to comfort me, no one to revive my soul. My children are destitute because the enemy has prevailed.'),
('LAM', 1, 17, 'LAM.1.17', 'Zion stretches out her hands, but there is no one to comfort her. The LORD has decreed against Jacob that his neighbors become his foes. Jerusalem has become an unclean thing among them.'),
('LAM', 1, 18, 'LAM.1.18', 'The LORD is righteous, yet I rebelled against His command. Listen, all you people; look upon my suffering. My young men and maidens have gone into captivity.'),
('LAM', 1, 19, 'LAM.1.19', 'I called out to my lovers, but they have betrayed me. My priests and elders perished in the city while they searched for food to keep themselves alive.'),
('LAM', 1, 20, 'LAM.1.20', 'See, O LORD, how distressed I am! I am churning within; my heart is pounding within me, for I have been most rebellious. Outside, the sword bereaves; inside, there is death.'),
('LAM', 1, 21, 'LAM.1.21', 'People have heard my groaning, but there is no one to comfort me. All my enemies have heard of my trouble; they are glad that You have caused it. May You bring the day You have announced, so that they may become like me.'),
('LAM', 1, 22, 'LAM.1.22', 'Let all their wickedness come before You, and deal with them as You have dealt with me because of all my transgressions. For my groans are many, and my heart is faint.'),
('LAM', 2, 1, 'LAM.2.1', 'How the Lord has covered the Daughter of Zion with the cloud of His anger! He has cast the glory of Israel from heaven to earth. He has abandoned His footstool in the day of His anger.'),
('LAM', 2, 2, 'LAM.2.2', 'Without pity the Lord has swallowed up all the dwellings of Jacob. In His wrath He has demolished the fortified cities of the Daughter of Judah. He brought to the ground and defiled her kingdom and its princes.'),
('LAM', 2, 3, 'LAM.2.3', 'In fierce anger He has cut off every horn of Israel and withdrawn His right hand at the approach of the enemy. He has burned in Jacob like a flaming fire that consumes everything around it.'),
('LAM', 2, 4, 'LAM.2.4', 'He has bent His bow like an enemy; His right hand is positioned. Like a foe He has killed all who were pleasing to the eye; He has poured out His wrath like fire on the tent of the Daughter of Zion.'),
('LAM', 2, 5, 'LAM.2.5', 'The Lord is like an enemy; He has swallowed up Israel. He has swallowed up all her palaces and destroyed her strongholds. He has multiplied mourning and lamentation for the Daughter of Judah.'),
('LAM', 2, 6, 'LAM.2.6', 'He has laid waste His tabernacle like a garden booth; He has destroyed His place of meeting. The LORD has made Zion forget her appointed feasts and Sabbaths. In His fierce anger He has despised both king and priest.'),
('LAM', 2, 7, 'LAM.2.7', 'The Lord has rejected His altar; He has abandoned His sanctuary; He has delivered the walls of her palaces into the hand of the enemy. They have raised a shout in the house of the LORD as on the day of an appointed feast.'),
('LAM', 2, 8, 'LAM.2.8', 'The LORD determined to destroy the wall of the Daughter of Zion. He stretched out a measuring line and did not withdraw His hand from destroying. He made the ramparts and walls lament; together they waste away.'),
('LAM', 2, 9, 'LAM.2.9', 'Her gates have sunk into the ground; He has destroyed and shattered their bars. Her king and her princes are exiled among the nations, the law is no more, and even her prophets find no vision from the LORD.'),
('LAM', 2, 10, 'LAM.2.10', 'The elders of the Daughter of Zion sit on the ground in silence. They have thrown dust on their heads and put on sackcloth. The young women of Jerusalem have bowed their heads to the ground.'),
('LAM', 2, 11, 'LAM.2.11', 'My eyes fail from weeping; I am churning within. My heart is poured out in grief over the destruction of the daughter of my people, because children and infants faint in the streets of the city.'),
('LAM', 2, 12, 'LAM.2.12', 'They cry out to their mothers: “Where is the grain and wine?” as they faint like the wounded in the streets of the city, as their lives fade away in the arms of their mothers.'),
('LAM', 2, 13, 'LAM.2.13', 'What can I say for you? To what can I compare you, O Daughter of Jerusalem? To what can I liken you, that I may console you, O Virgin Daughter of Zion? For your wound is as deep as the sea. Who can ever heal you?'),
('LAM', 2, 14, 'LAM.2.14', 'The visions of your prophets were empty and deceptive; they did not expose your guilt to ward off your captivity. The burdens they envisioned for you were empty and misleading.'),
('LAM', 2, 15, 'LAM.2.15', 'All who pass by clap their hands at you in scorn. They hiss and shake their heads at the Daughter of Jerusalem: “Is this the city that was called the perfection of beauty, the joy of all the earth?”'),
('LAM', 2, 16, 'LAM.2.16', 'All your enemies open their mouths against you. They hiss and gnash their teeth, saying, “We have swallowed her up. This is the day for which we have waited. We have lived to see it!”'),
('LAM', 2, 17, 'LAM.2.17', 'The LORD has done what He planned; He has accomplished His decree, which He ordained in days of old; He has overthrown you without pity. He has let the enemy gloat over you and exalted the horn of your foes.'),
('LAM', 2, 18, 'LAM.2.18', 'The hearts of the people cry out to the Lord. O wall of the Daughter of Zion, let your tears run down like a river day and night. Give yourself no relief, and your eyes no rest.'),
('LAM', 2, 19, 'LAM.2.19', 'Arise, cry out in the night from the first watch of the night. Pour out your heart like water in the presence of the Lord. Lift up your hands to Him for the lives of your children who are fainting from hunger on the corner of every street.'),
('LAM', 2, 20, 'LAM.2.20', 'Look, O LORD, and consider: Whom have You ever treated like this? Should women eat their offspring, the infants they have nurtured? Should priests and prophets be killed in the sanctuary of the Lord?'),
('LAM', 2, 21, 'LAM.2.21', 'Both young and old lie together in the dust of the streets. My young men and maidens have fallen by the sword. You have slain them in the day of Your anger; You have slaughtered them without compassion.'),
('LAM', 2, 22, 'LAM.2.22', 'You summoned my terrors on every side, as for the day of an appointed feast. In the day of the LORD’s anger no one escaped or survived; my enemy has destroyed those I nurtured and reared.'),
('LAM', 3, 1, 'LAM.3.1', 'I am the man who has seen affliction under the rod of God’s wrath.'),
('LAM', 3, 2, 'LAM.3.2', 'He has driven me away and made me walk in darkness instead of light.'),
('LAM', 3, 3, 'LAM.3.3', 'Indeed, He keeps turning His hand against me all day long.'),
('LAM', 3, 4, 'LAM.3.4', 'He has worn away my flesh and skin; He has shattered my bones.'),
('LAM', 3, 5, 'LAM.3.5', 'He has besieged me and surrounded me with bitterness and hardship.'),
('LAM', 3, 6, 'LAM.3.6', 'He has made me dwell in darkness like those dead for ages.'),
('LAM', 3, 7, 'LAM.3.7', 'He has walled me in so I cannot escape; He has weighed me down with chains.'),
('LAM', 3, 8, 'LAM.3.8', 'Even when I cry out and plead for help, He shuts out my prayer.'),
('LAM', 3, 9, 'LAM.3.9', 'He has barred my ways with cut stones; He has made my paths crooked.'),
('LAM', 3, 10, 'LAM.3.10', 'He is a bear lying in wait, a lion hiding in ambush.'),
('LAM', 3, 11, 'LAM.3.11', 'He forced me off my path and tore me to pieces; He left me without help.'),
('LAM', 3, 12, 'LAM.3.12', 'He bent His bow and set me as the target for His arrow.'),
('LAM', 3, 13, 'LAM.3.13', 'He pierced my kidneys with His arrows.'),
('LAM', 3, 14, 'LAM.3.14', 'I am a laughingstock to all my people; they mock me in song all day long.'),
('LAM', 3, 15, 'LAM.3.15', 'He has filled me with bitterness; He has intoxicated me with wormwood.'),
('LAM', 3, 16, 'LAM.3.16', 'He has ground my teeth with gravel and trampled me in the dust.'),
('LAM', 3, 17, 'LAM.3.17', 'My soul has been deprived of peace; I have forgotten what prosperity is.'),
('LAM', 3, 18, 'LAM.3.18', 'So I say, “My strength has perished, along with my hope from the LORD.”'),
('LAM', 3, 19, 'LAM.3.19', 'Remember my affliction and wandering, the wormwood and the gall.'),
('LAM', 3, 20, 'LAM.3.20', 'Surely my soul remembers and is humbled within me.'),
('LAM', 3, 21, 'LAM.3.21', 'Yet I call this to mind, and therefore I have hope:'),
('LAM', 3, 22, 'LAM.3.22', 'Because of the loving devotion of the LORD we are not consumed, for His mercies never fail.'),
('LAM', 3, 23, 'LAM.3.23', 'They are new every morning; great is Your faithfulness!'),
('LAM', 3, 24, 'LAM.3.24', '“The LORD is my portion,” says my soul, “therefore I will hope in Him.”'),
('LAM', 3, 25, 'LAM.3.25', 'The LORD is good to those who wait for Him, to the soul who seeks Him.'),
('LAM', 3, 26, 'LAM.3.26', 'It is good to wait quietly for the salvation of the LORD.'),
('LAM', 3, 27, 'LAM.3.27', 'It is good for a man to bear the yoke while he is still young.'),
('LAM', 3, 28, 'LAM.3.28', 'Let him sit alone in silence, for the LORD has laid it upon him.'),
('LAM', 3, 29, 'LAM.3.29', 'Let him bury his face in the dust—perhaps there is still hope.'),
('LAM', 3, 30, 'LAM.3.30', 'Let him offer his cheek to the one who would strike him; let him be filled with reproach.'),
('LAM', 3, 31, 'LAM.3.31', 'For the Lord will not cast us off forever.'),
('LAM', 3, 32, 'LAM.3.32', 'Even if He causes grief, He will show compassion according to His abundant loving devotion.'),
('LAM', 3, 33, 'LAM.3.33', 'For He does not willingly afflict or grieve the sons of men.'),
('LAM', 3, 34, 'LAM.3.34', 'To crush underfoot all the prisoners of the land,'),
('LAM', 3, 35, 'LAM.3.35', 'to deny a man justice before the Most High,'),
('LAM', 3, 36, 'LAM.3.36', 'to subvert a man in his lawsuit—of these the Lord does not approve.'),
('LAM', 3, 37, 'LAM.3.37', 'Who has spoken and it came to pass, unless the Lord has ordained it?'),
('LAM', 3, 38, 'LAM.3.38', 'Do not both adversity and good come from the mouth of the Most High?'),
('LAM', 3, 39, 'LAM.3.39', 'Why should any mortal man complain, in view of his sins?'),
('LAM', 3, 40, 'LAM.3.40', 'Let us examine and test our ways, and turn back to the LORD.'),
('LAM', 3, 41, 'LAM.3.41', 'Let us lift up our hearts and hands to God in heaven:'),
('LAM', 3, 42, 'LAM.3.42', '“We have sinned and rebelled; You have not forgiven.”'),
('LAM', 3, 43, 'LAM.3.43', 'You have covered Yourself in anger and pursued us; You have killed without pity.'),
('LAM', 3, 44, 'LAM.3.44', 'You have covered Yourself with a cloud that no prayer can pass through.'),
('LAM', 3, 45, 'LAM.3.45', 'You have made us scum and refuse among the nations.'),
('LAM', 3, 46, 'LAM.3.46', 'All our enemies open their mouths against us.'),
('LAM', 3, 47, 'LAM.3.47', 'Panic and pitfall have come upon us—devastation and destruction.'),
('LAM', 3, 48, 'LAM.3.48', 'Streams of tears flow from my eyes over the destruction of the daughter of my people.'),
('LAM', 3, 49, 'LAM.3.49', 'My eyes overflow unceasingly, without relief,'),
('LAM', 3, 50, 'LAM.3.50', 'until the LORD looks down from heaven and sees.'),
('LAM', 3, 51, 'LAM.3.51', 'My eyes bring grief to my soul because of all the daughters of my city.'),
('LAM', 3, 52, 'LAM.3.52', 'Without cause my enemies hunted me like a bird.'),
('LAM', 3, 53, 'LAM.3.53', 'They dropped me alive into a pit and cast stones upon me.'),
('LAM', 3, 54, 'LAM.3.54', 'The waters flowed over my head, and I thought I was going to die.'),
('LAM', 3, 55, 'LAM.3.55', 'I called on Your name, O LORD, out of the depths of the Pit.'),
('LAM', 3, 56, 'LAM.3.56', 'You heard my plea: “Do not ignore my cry for relief.”'),
('LAM', 3, 57, 'LAM.3.57', 'You drew near when I called on You; You said, “Do not be afraid.”'),
('LAM', 3, 58, 'LAM.3.58', 'You defend my cause, O Lord; You redeem my life.'),
('LAM', 3, 59, 'LAM.3.59', 'You have seen, O LORD, the wrong done to me; vindicate my cause!'),
('LAM', 3, 60, 'LAM.3.60', 'You have seen all their malice, all their plots against me.'),
('LAM', 3, 61, 'LAM.3.61', 'O LORD, You have heard their insults, all their plots against me—'),
('LAM', 3, 62, 'LAM.3.62', 'the slander and murmuring of my assailants against me all day long.'),
('LAM', 3, 63, 'LAM.3.63', 'When they sit and when they rise, see how they mock me in song.'),
('LAM', 3, 64, 'LAM.3.64', 'You will pay them back what they deserve, O LORD, according to the work of their hands.'),
('LAM', 3, 65, 'LAM.3.65', 'Put a veil of anguish over their hearts; may Your curse be upon them!'),
('LAM', 3, 66, 'LAM.3.66', 'You will pursue them in anger and exterminate them from under Your heavens, O LORD.'),
('LAM', 4, 1, 'LAM.4.1', 'How the gold has become tarnished, the pure gold has become dull! The gems of the temple lie scattered on every street corner.'),
('LAM', 4, 2, 'LAM.4.2', 'How the precious sons of Zion, once worth their weight in pure gold, are now esteemed as jars of clay, the work of a potter’s hands!'),
('LAM', 4, 3, 'LAM.4.3', 'Even jackals offer their breasts to nurse their young, but the daughter of my people has become cruel, like an ostrich in the wilderness.'),
('LAM', 4, 4, 'LAM.4.4', 'The nursing infant’s tongue clings in thirst to the roof of his mouth. Little children beg for bread, but no one gives them any.'),
('LAM', 4, 5, 'LAM.4.5', 'Those who once ate delicacies are destitute in the streets; those brought up in crimson huddle in ash heaps.'),
('LAM', 4, 6, 'LAM.4.6', 'The punishment of the daughter of my people is greater than that of Sodom, which was overthrown in an instant without a hand turned to help her.'),
('LAM', 4, 7, 'LAM.4.7', 'Her dignitaries were brighter than snow, whiter than milk; their bodies were more ruddy than rubies, their appearance like sapphires.'),
('LAM', 4, 8, 'LAM.4.8', 'But now their appearance is blacker than soot; they are not recognized in the streets. Their skin has shriveled on their bones; it has become as dry as a stick.'),
('LAM', 4, 9, 'LAM.4.9', 'Those slain by the sword are better off than those who die of hunger, who waste away, pierced with pain because the fields lack produce.'),
('LAM', 4, 10, 'LAM.4.10', 'The hands of compassionate women have cooked their own children, who became their food in the destruction of the daughter of my people.'),
('LAM', 4, 11, 'LAM.4.11', 'The LORD has exhausted His wrath; He has poured out His fierce anger; He has kindled a fire in Zion, and it has consumed her foundations.'),
('LAM', 4, 12, 'LAM.4.12', 'The kings of the earth did not believe, nor any people of the world, that an enemy or a foe could enter the gates of Jerusalem.'),
('LAM', 4, 13, 'LAM.4.13', 'But this was for the sins of her prophets and the guilt of her priests, who shed the blood of the righteous in her midst.'),
('LAM', 4, 14, 'LAM.4.14', 'They wandered blind in the streets, defiled by this blood, so that no one dared to touch their garments.'),
('LAM', 4, 15, 'LAM.4.15', '“Go away! Unclean!” men shouted at them. “Away, away! Do not touch us!” So they fled and wandered. Among the nations it was said, “They can stay here no longer.”'),
('LAM', 4, 16, 'LAM.4.16', 'The presence of the LORD has scattered them; He regards them no more. The priests are shown no honor; the elders find no favor.'),
('LAM', 4, 17, 'LAM.4.17', 'All the while our eyes were failing as we looked in vain for help. We watched from our towers for a nation that could not save us.'),
('LAM', 4, 18, 'LAM.4.18', 'They stalked our every step, so that we could not walk in our streets. Our end drew near, our time ran out, for our end had come!'),
('LAM', 4, 19, 'LAM.4.19', 'Those who chased us were swifter than the eagles in the sky; they pursued us over the mountains and ambushed us in the wilderness.'),
('LAM', 4, 20, 'LAM.4.20', 'The LORD’s anointed, the breath of our life, was captured in their pits. We had said of him, “Under his shadow we will live among the nations.”'),
('LAM', 4, 21, 'LAM.4.21', 'So rejoice and be glad, O Daughter of Edom, you who dwell in the land of Uz. Yet the cup will pass to you as well; you will get drunk and expose yourself.'),
('LAM', 4, 22, 'LAM.4.22', 'O Daughter of Zion, your punishment is complete; He will not prolong your exile. But He will punish your iniquity, O Daughter of Edom; He will expose your sins.'),
('LAM', 5, 1, 'LAM.5.1', 'Remember, O LORD, what has happened to us. Look and see our disgrace!'),
('LAM', 5, 2, 'LAM.5.2', 'Our inheritance has been turned over to strangers, our houses to foreigners.'),
('LAM', 5, 3, 'LAM.5.3', 'We have become fatherless orphans; our mothers are widows.'),
('LAM', 5, 4, 'LAM.5.4', 'We must buy the water we drink; our wood comes at a price.'),
('LAM', 5, 5, 'LAM.5.5', 'We are closely pursued; we are weary and find no rest.'),
('LAM', 5, 6, 'LAM.5.6', 'We submitted to Egypt and Assyria to get enough bread.'),
('LAM', 5, 7, 'LAM.5.7', 'Our fathers sinned and are no more, but we bear their punishment.'),
('LAM', 5, 8, 'LAM.5.8', 'Slaves rule over us; there is no one to deliver us from their hands.'),
('LAM', 5, 9, 'LAM.5.9', 'We get our bread at the risk of our lives because of the sword in the wilderness.'),
('LAM', 5, 10, 'LAM.5.10', 'Our skin is as hot as an oven with fever from our hunger.'),
('LAM', 5, 11, 'LAM.5.11', 'Women have been ravished in Zion, virgins in the cities of Judah.'),
('LAM', 5, 12, 'LAM.5.12', 'Princes have been hung up by their hands; elders receive no respect.'),
('LAM', 5, 13, 'LAM.5.13', 'Young men toil at millstones; boys stagger under loads of wood.'),
('LAM', 5, 14, 'LAM.5.14', 'The elders have left the city gate; the young men have stopped their music.'),
('LAM', 5, 15, 'LAM.5.15', 'Joy has left our hearts; our dancing has turned to mourning.'),
('LAM', 5, 16, 'LAM.5.16', 'The crown has fallen from our head. Woe to us, for we have sinned!'),
('LAM', 5, 17, 'LAM.5.17', 'Because of this, our hearts are faint; because of these, our eyes grow dim—'),
('LAM', 5, 18, 'LAM.5.18', 'because of Mount Zion, which lies desolate, patrolled by foxes.'),
('LAM', 5, 19, 'LAM.5.19', 'You, O LORD, reign forever; Your throne endures from generation to generation.'),
('LAM', 5, 20, 'LAM.5.20', 'Why have You forgotten us forever? Why have You forsaken us for so long?'),
('LAM', 5, 21, 'LAM.5.21', 'Restore us to Yourself, O LORD, so we may return; renew our days as of old,'),
('LAM', 5, 22, 'LAM.5.22', 'unless You have utterly rejected us and remain angry with us beyond measure.'),
('EZK', 1, 1, 'EZK.1.1', 'In the thirtieth year, on the fifth day of the fourth month, while I was among the exiles by the River Kebar, the heavens opened and I saw visions of God.'),
('EZK', 1, 2, 'EZK.1.2', 'On the fifth day of the month—it was the fifth year of the exile of King Jehoiachin—'),
('EZK', 1, 3, 'EZK.1.3', 'the word of the LORD came directly to Ezekiel the priest, the son of Buzi, in the land of the Chaldeans by the River Kebar. And there the LORD’s hand was upon him.'),
('EZK', 1, 4, 'EZK.1.4', 'I looked and saw a whirlwind coming from the north, a great cloud with fire flashing back and forth and brilliant light all around it. In the center of the fire was a gleam like amber,'),
('EZK', 1, 5, 'EZK.1.5', 'and within it was the form of four living creatures. And this was their appearance: They had a human form,'),
('EZK', 1, 6, 'EZK.1.6', 'but each had four faces and four wings.'),
('EZK', 1, 7, 'EZK.1.7', 'Their legs were straight, and the soles of their feet were like the hooves of a calf, gleaming like polished bronze.'),
('EZK', 1, 8, 'EZK.1.8', 'Under their wings on their four sides they had human hands. All four living creatures had faces and wings,'),
('EZK', 1, 9, 'EZK.1.9', 'and their wings were touching one another. They did not turn as they moved; each one went straight ahead.'),
('EZK', 1, 10, 'EZK.1.10', 'The form of their faces was that of a man, and each of the four had the face of a lion on the right side, the face of an ox on the left side, and also the face of an eagle.'),
('EZK', 1, 11, 'EZK.1.11', 'Such were their faces. Their wings were spread upward; each had two wings touching the wings of the creature on either side, and two wings covering its body.'),
('EZK', 1, 12, 'EZK.1.12', 'Each creature went straight ahead. Wherever the spirit would go, they would go, without turning as they moved.'),
('EZK', 1, 13, 'EZK.1.13', 'In the midst of the living creatures was the appearance of glowing coals of fire, or of torches. Fire moved back and forth between the living creatures; it was bright, and lightning flashed out of it.'),
('EZK', 1, 14, 'EZK.1.14', 'The creatures were darting back and forth as quickly as flashes of lightning.'),
('EZK', 1, 15, 'EZK.1.15', 'When I looked at the living creatures, I saw a wheel on the ground beside each creature with its four faces.'),
('EZK', 1, 16, 'EZK.1.16', 'The workmanship of the wheels looked like the gleam of beryl, and all four had the same likeness. Their workmanship looked like a wheel within a wheel.'),
('EZK', 1, 17, 'EZK.1.17', 'As they moved, they went in any of the four directions, without pivoting as they moved.'),
('EZK', 1, 18, 'EZK.1.18', 'Their rims were high and awesome, and all four rims were full of eyes all around.'),
('EZK', 1, 19, 'EZK.1.19', 'So as the living creatures moved, the wheels moved beside them, and when the creatures rose from the ground, the wheels also rose.'),
('EZK', 1, 20, 'EZK.1.20', 'Wherever the spirit would go, they would go, and the wheels would rise alongside them, because the spirit of the living creatures was in the wheels.'),
('EZK', 1, 21, 'EZK.1.21', 'When the creatures moved, the wheels moved; when the creatures stood still, the wheels stood still; and when the creatures rose from the ground, the wheels rose alongside them, because the spirit of the living creatures was in the wheels.'),
('EZK', 1, 22, 'EZK.1.22', 'Spread out above the heads of the living creatures was the likeness of an awesome expanse, gleaming like crystal.'),
('EZK', 1, 23, 'EZK.1.23', 'And under the expanse, their wings stretched out toward one another. Each one also had two wings covering its body.'),
('EZK', 1, 24, 'EZK.1.24', 'When the creatures moved, I heard the sound of their wings like the roar of many waters, like the voice of the Almighty, like the tumult of an army. When they stood still, they lowered their wings.'),
('EZK', 1, 25, 'EZK.1.25', 'And there came a voice from above the expanse over their heads as they stood still with their wings lowered.'),
('EZK', 1, 26, 'EZK.1.26', 'Above the expanse over their heads was the likeness of a throne with the appearance of sapphire, and on the throne high above was a figure like that of a man.'),
('EZK', 1, 27, 'EZK.1.27', 'From what seemed to be His waist up, I saw a gleam like amber, with what looked like fire within it all around. And from what seemed to be His waist down, I saw what looked like fire; and brilliant light surrounded Him.'),
('EZK', 1, 28, 'EZK.1.28', 'The appearance of the brilliant light all around Him was like that of a rainbow in a cloud on a rainy day. This was the appearance of the likeness of the glory of the LORD. And when I saw it, I fell facedown and heard a voice speaking.'),
('EZK', 2, 1, 'EZK.2.1', '“Son of man,” He said to me, “stand up on your feet and I will speak to you.”'),
('EZK', 2, 2, 'EZK.2.2', 'And as He spoke to me, the Spirit entered me and set me on my feet, and I heard Him speaking to me.'),
('EZK', 2, 3, 'EZK.2.3', '“Son of man,” He said to me, “I am sending you to the Israelites, to a rebellious nation that has rebelled against Me. To this very day they and their fathers have rebelled against Me.'),
('EZK', 2, 4, 'EZK.2.4', 'They are obstinate and stubborn children. I am sending you to them, and you are to say to them, ‘This is what the Lord GOD says.’'),
('EZK', 2, 5, 'EZK.2.5', 'And whether they listen or refuse to listen—for they are a rebellious house—they will know that a prophet has been among them.'),
('EZK', 2, 6, 'EZK.2.6', 'But you, son of man, do not be afraid of them or their words. Do not be afraid, though briers and thorns surround you, and you dwell among scorpions. Do not be afraid of their words or dismayed by their presence, though they are a rebellious house.'),
('EZK', 2, 7, 'EZK.2.7', 'But speak My words to them, whether they listen or refuse to listen, for they are rebellious.'),
('EZK', 2, 8, 'EZK.2.8', 'And you, son of man, listen to what I tell you. Do not be rebellious like that rebellious house. Open your mouth and eat what I give you.”'),
('EZK', 2, 9, 'EZK.2.9', 'Then I looked and saw a hand reaching out to me, and in it was a scroll,'),
('EZK', 2, 10, 'EZK.2.10', 'which He unrolled before me. And written on the front and back of it were words of lamentation, mourning, and woe.'),
('EZK', 3, 1, 'EZK.3.1', '“Son of man,” He said to me, “eat what you find here. Eat this scroll, then go and speak to the house of Israel.”'),
('EZK', 3, 2, 'EZK.3.2', 'So I opened my mouth, and He fed me the scroll.'),
('EZK', 3, 3, 'EZK.3.3', '“Son of man,” He said to me, “eat and fill your stomach with this scroll I am giving you.” So I ate, and it was as sweet as honey in my mouth.'),
('EZK', 3, 4, 'EZK.3.4', 'Then He said to me, “Son of man, go now to the house of Israel and speak My words to them.'),
('EZK', 3, 5, 'EZK.3.5', 'For you are not being sent to a people of unfamiliar speech or difficult language, but to the house of Israel—'),
('EZK', 3, 6, 'EZK.3.6', 'not to the many peoples of unfamiliar speech and difficult language whose words you cannot understand. Surely if I had sent you to them, they would have listened to you.'),
('EZK', 3, 7, 'EZK.3.7', 'But the house of Israel will be unwilling to listen to you, since they are unwilling to listen to Me. For the whole house of Israel is hard-headed and hard-hearted.'),
('EZK', 3, 8, 'EZK.3.8', 'Behold, I will make your face as hard as their faces, and your forehead as hard as their foreheads.'),
('EZK', 3, 9, 'EZK.3.9', 'I will make your forehead like a diamond, harder than flint. Do not be afraid of them or dismayed at their presence, even though they are a rebellious house.”'),
('EZK', 3, 10, 'EZK.3.10', '“Son of man,” He added, “listen carefully to all the words I speak to you, and take them to heart.'),
('EZK', 3, 11, 'EZK.3.11', 'Go to your people, the exiles; speak to them and tell them, ‘This is what the Lord GOD says,’ whether they listen or refuse to listen.”'),
('EZK', 3, 12, 'EZK.3.12', 'Then the Spirit lifted me up, and I heard a great rumbling sound behind me: “Blessed be the glory of the LORD in His dwelling place!”'),
('EZK', 3, 13, 'EZK.3.13', 'It was the sound of the wings of the living creatures brushing against one another and the sound of the wheels beside them, a great rumbling sound.'),
('EZK', 3, 14, 'EZK.3.14', 'So the Spirit lifted me up and took me away, and I went in bitterness and in the anger of my spirit, with the strong hand of the LORD upon me.'),
('EZK', 3, 15, 'EZK.3.15', 'I came to the exiles at Tel-abib who dwelt by the River Kebar. And for seven days I sat where they sat and remained there among them, overwhelmed.'),
('EZK', 3, 16, 'EZK.3.16', 'At the end of seven days the word of the LORD came to me, saying,'),
('EZK', 3, 17, 'EZK.3.17', '“Son of man, I have made you a watchman for the house of Israel. Whenever you hear a word from My mouth, give them a warning from Me.'),
('EZK', 3, 18, 'EZK.3.18', 'If I say to the wicked man, ‘You will surely die,’ but you do not warn him or speak out to warn him from his wicked way to save his life, that wicked man will die in his iniquity, and I will hold you responsible for his blood.'),
('EZK', 3, 19, 'EZK.3.19', 'But if you warn a wicked man and he does not turn from his wickedness and his wicked way, he will die in his iniquity, but you will have saved yourself.'),
('EZK', 3, 20, 'EZK.3.20', 'Now if a righteous man turns from his righteousness and commits iniquity, and I put a stumbling block before him, he will die. If you did not warn him, he will die in his sin, and the righteous acts he did will not be remembered. And I will hold you responsible for his blood.'),
('EZK', 3, 21, 'EZK.3.21', 'But if you warn the righteous man not to sin, and he does not sin, he will indeed live because he heeded your warning, and you will have saved yourself.”'),
('EZK', 3, 22, 'EZK.3.22', 'And there the hand of the LORD was upon me, and He said to me, “Get up, go out to the plain, and there I will speak with you.”'),
('EZK', 3, 23, 'EZK.3.23', 'So I got up and went out to the plain, and behold, the glory of the LORD was present there, like the glory I had seen by the River Kebar, and I fell facedown.'),
('EZK', 3, 24, 'EZK.3.24', 'Then the Spirit entered me and set me on my feet. He spoke with me and said, “Go, shut yourself inside your house.'),
('EZK', 3, 25, 'EZK.3.25', 'And you, son of man, they will tie with ropes, and you will be bound so that you cannot go out among the people.'),
('EZK', 3, 26, 'EZK.3.26', 'I will make your tongue stick to the roof of your mouth, and you will be silent and unable to rebuke them, though they are a rebellious house.'),
('EZK', 3, 27, 'EZK.3.27', 'But when I speak with you, I will open your mouth, and you are to tell them, ‘This is what the Lord GOD says.’ Whoever listens, let him listen; and whoever refuses, let him refuse, for they are a rebellious house.'),
('EZK', 4, 1, 'EZK.4.1', '“Now you, son of man, take a brick, place it before you, and draw on it the city of Jerusalem.'),
('EZK', 4, 2, 'EZK.4.2', 'Then lay siege against it: Construct a siege wall, build a ramp to it, set up camps against it, and place battering rams around it on all sides.'),
('EZK', 4, 3, 'EZK.4.3', 'Then take an iron plate and set it up as an iron wall between yourself and the city. Turn your face toward it so that it is under siege, and besiege it. This will be a sign to the house of Israel.'),
('EZK', 4, 4, 'EZK.4.4', 'Then lie down on your left side and place the iniquity of the house of Israel upon yourself. You are to bear their iniquity for the number of days you lie on your side.'),
('EZK', 4, 5, 'EZK.4.5', 'For I have assigned to you 390 days, according to the number of years of their iniquity. So you shall bear the iniquity of the house of Israel.'),
('EZK', 4, 6, 'EZK.4.6', 'When you have completed these days, lie down again, but on your right side, and bear the iniquity of the house of Judah. I have assigned to you 40 days, a day for each year.'),
('EZK', 4, 7, 'EZK.4.7', 'You must turn your face toward the siege of Jerusalem with your arm bared, and prophesy against it.'),
('EZK', 4, 8, 'EZK.4.8', 'Now behold, I will tie you up with ropes so you cannot turn from side to side until you have finished the days of your siege.'),
('EZK', 4, 9, 'EZK.4.9', 'But take wheat, barley, beans, lentils, millet, and spelt; put them in a single container and make them into bread for yourself. This is what you are to eat during the 390 days you lie on your side.'),
('EZK', 4, 10, 'EZK.4.10', 'You are to weigh out twenty shekels of food to eat each day, and you are to eat it at set times.'),
('EZK', 4, 11, 'EZK.4.11', 'You are also to measure out a sixth of a hin of water to drink, and you are to drink it at set times.'),
('EZK', 4, 12, 'EZK.4.12', 'And you shall eat the food as you would a barley cake, after you bake it over dried human excrement in the sight of the people.”'),
('EZK', 4, 13, 'EZK.4.13', 'Then the LORD said, “This is how the Israelites will eat their defiled bread among the nations to which I will banish them.”'),
('EZK', 4, 14, 'EZK.4.14', '“Ah, Lord GOD,” I said, “I have never defiled myself. From my youth until now I have not eaten anything found dead or mauled by wild beasts. No unclean meat has ever entered my mouth.”'),
('EZK', 4, 15, 'EZK.4.15', '“Look,” He replied, “I will let you use cow dung instead of human excrement, and you may bake your bread over that.”'),
('EZK', 4, 16, 'EZK.4.16', 'Then He told me, “Son of man, I am going to cut off the supply of food in Jerusalem. They will anxiously eat bread rationed by weight, and in despair they will drink water by measure.'),
('EZK', 4, 17, 'EZK.4.17', 'So they will lack food and water; they will be appalled at the sight of one another wasting away in their iniquity.'),
('EZK', 5, 1, 'EZK.5.1', '“As for you, son of man, take a sharp sword, use it as a barber’s razor, and shave your head and beard. Then take a set of scales and divide the hair.'),
('EZK', 5, 2, 'EZK.5.2', 'When the days of the siege have ended, you are to burn up a third of the hair inside the city; you are also to take a third and slash it with the sword all around the city; and you are to scatter a third to the wind. For I will unleash a sword behind them.'),
('EZK', 5, 3, 'EZK.5.3', 'But you are to take a few strands of hair and secure them in the folds of your garment.'),
('EZK', 5, 4, 'EZK.5.4', 'Again, take a few of these, throw them into the fire, and burn them. From there a fire will spread to the whole house of Israel.'),
('EZK', 5, 5, 'EZK.5.5', 'This is what the Lord GOD says: ‘This is Jerusalem, which I have set in the center of the nations, with countries all around her.'),
('EZK', 5, 6, 'EZK.5.6', 'But she has rebelled against My ordinances more wickedly than the nations, and against My statutes worse than the countries around her. For her people have rejected My ordinances and have not walked in My statutes.’'),
('EZK', 5, 7, 'EZK.5.7', 'Therefore this is what the Lord GOD says: ‘You have been more insubordinate than the nations around you; you have not walked in My statutes or kept My ordinances, nor have you even conformed to the ordinances of the nations around you.’'),
('EZK', 5, 8, 'EZK.5.8', 'Therefore this is what the Lord GOD says: ‘Behold, I Myself am against you, Jerusalem, and I will execute judgments among you in the sight of the nations.'),
('EZK', 5, 9, 'EZK.5.9', 'Because of all your abominations, I will do to you what I have never done before and will never do again.'),
('EZK', 5, 10, 'EZK.5.10', 'As a result, fathers among you will eat their sons, and sons will eat their fathers. I will execute judgments against you and scatter all your remnant to every wind.’'),
('EZK', 5, 11, 'EZK.5.11', 'Therefore as surely as I live, declares the Lord GOD, because you have defiled My sanctuary with all your detestable idols and abominations, I Myself will withdraw My favor; I will not look upon you with pity, nor will I spare you.'),
('EZK', 5, 12, 'EZK.5.12', 'A third of your people will die by plague or be consumed by famine within you, a third will fall by the sword outside your walls, and a third I will scatter to every wind and unleash a sword behind them.'),
('EZK', 5, 13, 'EZK.5.13', 'And when My anger is spent and I have vented My wrath against them, I will be appeased. And when I have spent My wrath on them, they will know that I, the LORD, in My zeal have spoken.'),
('EZK', 5, 14, 'EZK.5.14', 'I will make you a ruin and a disgrace among the nations around you, in the sight of all who pass by.'),
('EZK', 5, 15, 'EZK.5.15', 'So you will be a reproach and a taunt, a warning and a horror to the nations around you, when I execute judgments against you in anger, wrath, and raging fury. I, the LORD, have spoken.'),
('EZK', 5, 16, 'EZK.5.16', 'When I shower you with the deadly arrows of famine and destruction that I will send to destroy you, I will intensify the famine against you and cut off your supply of food.'),
('EZK', 5, 17, 'EZK.5.17', 'I will send famine and wild beasts against you, and they will leave you childless. Plague and bloodshed will sweep through you, and I will bring a sword against you. I, the LORD, have spoken.”'),
('EZK', 6, 1, 'EZK.6.1', 'And the word of the LORD came to me, saying,'),
('EZK', 6, 2, 'EZK.6.2', '“Son of man, set your face against the mountains of Israel and prophesy against them.'),
('EZK', 6, 3, 'EZK.6.3', 'You are to say: ‘O mountains of Israel, hear the word of the Lord GOD! This is what the Lord GOD says to the mountains and hills, to the ravines and valleys: I am about to bring a sword against you, and I will destroy your high places.'),
('EZK', 6, 4, 'EZK.6.4', 'Your altars will be demolished and your incense altars will be smashed; and I will cast down your slain before your idols.'),
('EZK', 6, 5, 'EZK.6.5', 'I will lay the corpses of the Israelites before their idols and scatter your bones around your altars.'),
('EZK', 6, 6, 'EZK.6.6', 'Wherever you live, the cities will be laid waste and the high places will be demolished, so that your altars will be laid waste and desecrated, your idols smashed and obliterated, your incense altars cut down, and your works blotted out.'),
('EZK', 6, 7, 'EZK.6.7', 'The slain will fall among you, and you will know that I am the LORD.'),
('EZK', 6, 8, 'EZK.6.8', 'Yet I will leave a remnant, for some of you will escape the sword when you are scattered among the nations and throughout the lands.'),
('EZK', 6, 9, 'EZK.6.9', 'Then in the nations to which they have been carried captive, your survivors will remember Me—how I have been grieved by their adulterous hearts that turned away from Me, and by their eyes that lusted after idols. So they will loathe themselves for the evil they have done and for all their abominations.'),
('EZK', 6, 10, 'EZK.6.10', 'And they will know that I am the LORD; I did not declare in vain that I would bring this calamity upon them.'),
('EZK', 6, 11, 'EZK.6.11', 'This is what the Lord GOD says: Clap your hands, stomp your feet, and cry out “Alas!” because of all the wicked abominations of the house of Israel, who will fall by sword and famine and plague.'),
('EZK', 6, 12, 'EZK.6.12', 'He who is far off will die by the plague, he who is near will fall by the sword, and he who remains will die by famine. So I will vent My fury upon them.'),
('EZK', 6, 13, 'EZK.6.13', 'Then you will know that I am the LORD, when their slain lie among their idols around their altars, on every high hill, on all the mountaintops, and under every green tree and leafy oak—the places where they offered fragrant incense to all their idols.'),
('EZK', 6, 14, 'EZK.6.14', 'I will stretch out My hand against them, and wherever they live I will make the land a desolate waste, from the wilderness to Diblah. Then they will know that I am the LORD.’”'),
('EZK', 7, 1, 'EZK.7.1', 'And the word of the LORD came to me, saying,'),
('EZK', 7, 2, 'EZK.7.2', '“O son of man, this is what the Lord GOD says to the land of Israel: ‘The end! The end has come upon the four corners of the land.'),
('EZK', 7, 3, 'EZK.7.3', 'The end is now upon you, and I will unleash My anger against you. I will judge you according to your ways and repay you for all your abominations.'),
('EZK', 7, 4, 'EZK.7.4', 'I will not look on you with pity, nor will I spare you, but I will punish you for your ways and for the abominations among you. Then you will know that I am the LORD.’'),
('EZK', 7, 5, 'EZK.7.5', 'This is what the Lord GOD says: ‘Disaster! An unprecedented disaster—behold, it is coming!'),
('EZK', 7, 6, 'EZK.7.6', 'The end has come! The end has come! It has roused itself against you. Behold, it has come!'),
('EZK', 7, 7, 'EZK.7.7', 'Doom has come to you, O inhabitants of the land. The time has come; the day is near; there is panic on the mountains instead of shouts of joy.'),
('EZK', 7, 8, 'EZK.7.8', 'Very soon I will pour out My wrath upon you and vent My anger against you; I will judge you according to your ways and repay you for all your abominations.'),
('EZK', 7, 9, 'EZK.7.9', 'I will not look on you with pity, nor will I spare you, but I will punish you for your ways and for the abominations among you. Then you will know that it is I, the LORD, who strikes the blow.'),
('EZK', 7, 10, 'EZK.7.10', 'Behold, the day is here! It has come! Doom has gone out, the rod has budded, arrogance has bloomed.'),
('EZK', 7, 11, 'EZK.7.11', 'Their violence has grown into a rod to punish their wickedness. None of them will remain: none of their multitude, none of their wealth, and nothing of value.'),
('EZK', 7, 12, 'EZK.7.12', 'The time has come; the day has arrived. Let the buyer not rejoice and the seller not mourn, for wrath is upon the whole multitude.'),
('EZK', 7, 13, 'EZK.7.13', 'The seller will surely not recover what he sold while both remain alive. For the vision concerning the whole multitude will not be revoked, and because of their iniquity, not one of them will preserve his life.'),
('EZK', 7, 14, 'EZK.7.14', 'They have blown the trumpet and made everything ready, but no one goes to war, for My wrath is upon the whole multitude.'),
('EZK', 7, 15, 'EZK.7.15', 'The sword is outside; plague and famine are within. Those in the country will die by the sword, and those in the city will be devoured by famine and plague.'),
('EZK', 7, 16, 'EZK.7.16', 'The survivors will escape and live in the mountains, moaning like doves of the valley, each for his own iniquity.'),
('EZK', 7, 17, 'EZK.7.17', 'Every hand will go limp, and every knee will turn to water.'),
('EZK', 7, 18, 'EZK.7.18', 'They will put on sackcloth, and terror will overwhelm them. Shame will cover all their faces, and all their heads will be shaved.'),
('EZK', 7, 19, 'EZK.7.19', 'They will throw their silver into the streets, and their gold will seem unclean. Their silver and gold cannot save them in the day of the wrath of the LORD. They cannot satisfy their appetites or fill their stomachs with wealth, for it became the stumbling block that brought their iniquity.'),
('EZK', 7, 20, 'EZK.7.20', 'His beautiful ornaments they transformed into pride and used them to fashion their vile images and detestable idols. Therefore I will make these into something unclean for them.'),
('EZK', 7, 21, 'EZK.7.21', 'And I will hand these things over as plunder to foreigners and loot to the wicked of the earth, who will defile them.'),
('EZK', 7, 22, 'EZK.7.22', 'I will turn My face away from them, and they will defile My treasured place. Violent men will enter it, and they will defile it.'),
('EZK', 7, 23, 'EZK.7.23', 'Forge the chain, for the land is full of crimes of bloodshed, and the city is full of violence.'),
('EZK', 7, 24, 'EZK.7.24', 'So I will bring the most wicked of nations to take possession of their houses. I will end the pride of the mighty, and their holy places will be profaned.'),
('EZK', 7, 25, 'EZK.7.25', 'Anguish is coming! They will seek peace, but find none.'),
('EZK', 7, 26, 'EZK.7.26', 'Disaster upon disaster will come, and rumor after rumor. Then they will seek a vision from a prophet, but instruction from the priests will perish, as will counsel from the elders.'),
('EZK', 7, 27, 'EZK.7.27', 'The king will mourn, the prince will be clothed with despair, and the hands of the people of the land will tremble. I will deal with them according to their conduct, and I will judge them by their own standards. Then they will know that I am the LORD.’”'),
('EZK', 8, 1, 'EZK.8.1', 'In the sixth year, on the fifth day of the sixth month, I was sitting in my house, and the elders of Judah were sitting before me; and there the hand of the Lord GOD fell upon me.'),
('EZK', 8, 2, 'EZK.8.2', 'Then I looked and saw a figure like that of a man. From His waist down His appearance was like fire, and from His waist up He was as bright as the gleam of amber.'),
('EZK', 8, 3, 'EZK.8.3', 'He stretched out what looked like a hand and took me by the hair of my head. Then the Spirit lifted me up between earth and heaven and carried me in visions of God to Jerusalem, to the entrance of the north gate of the inner court, where the idol that provokes jealousy was seated.'),
('EZK', 8, 4, 'EZK.8.4', 'And there I saw the glory of the God of Israel, like the vision I had seen in the plain.'),
('EZK', 8, 5, 'EZK.8.5', '“Son of man,” He said to me, “now lift up your eyes to the north.” So I lifted up my eyes to the north, and in the entrance north of the Altar Gate I saw this idol of jealousy.'),
('EZK', 8, 6, 'EZK.8.6', '“Son of man,” He said to me, “do you see what they are doing—the great abominations that the house of Israel is committing—to drive Me far from My sanctuary? Yet you will see even greater abominations.”'),
('EZK', 8, 7, 'EZK.8.7', 'Then He brought me to the entrance to the court, and I looked and saw a hole in the wall.'),
('EZK', 8, 8, 'EZK.8.8', '“Son of man,” He told me, “dig through the wall.” So I dug through the wall and discovered a doorway.'),
('EZK', 8, 9, 'EZK.8.9', 'Then He said to me, “Go in and see the wicked abominations they are committing here.”'),
('EZK', 8, 10, 'EZK.8.10', 'So I went in and looked, and engraved all around the wall was every kind of crawling creature and detestable beast, along with all the idols of the house of Israel.'),
('EZK', 8, 11, 'EZK.8.11', 'Before them stood seventy elders of the house of Israel, with Jaazaniah son of Shaphan standing among them. Each had a censer in his hand, and a fragrant cloud of incense was rising.'),
('EZK', 8, 12, 'EZK.8.12', '“Son of man,” He said to me, “do you see what the elders of the house of Israel are doing in the darkness, each at the shrine of his own idol? For they are saying, ‘The LORD does not see us; the LORD has forsaken the land.’”'),
('EZK', 8, 13, 'EZK.8.13', 'Again, He told me, “You will see them committing even greater abominations.”'),
('EZK', 8, 14, 'EZK.8.14', 'Then He brought me to the entrance of the north gate of the house of the LORD, and I saw women sitting there, weeping for Tammuz.'),
('EZK', 8, 15, 'EZK.8.15', '“Son of man,” He said to me, “do you see this? Yet you will see even greater abominations than these.”'),
('EZK', 8, 16, 'EZK.8.16', 'So He brought me to the inner court of the house of the LORD, and there at the entrance to the temple of the LORD, between the portico and the altar, were about twenty-five men with their backs to the temple of the LORD and their faces toward the east; and they were bowing to the east in worship of the sun.'),
('EZK', 8, 17, 'EZK.8.17', '“Son of man,” He said to me, “do you see this? Is it not enough for the house of Judah to commit the abominations they are practicing here, that they must also fill the land with violence and continually provoke Me to anger? Look, they are even putting the branch to their nose!'),
('EZK', 8, 18, 'EZK.8.18', 'Therefore I will respond with wrath. I will not look on them with pity, nor will I spare them. Although they shout loudly in My ears, I will not listen to them.”'),
('EZK', 9, 1, 'EZK.9.1', 'Then I heard Him call out in a loud voice, saying, “Draw near, O executioners of the city, each with a weapon of destruction in hand.”'),
('EZK', 9, 2, 'EZK.9.2', 'And I saw six men coming from the direction of the Upper Gate, which faces north, each with a weapon of slaughter in his hand. With them was another man clothed in linen who had a writing kit at his side. And they came in and stood beside the bronze altar.'),
('EZK', 9, 3, 'EZK.9.3', 'Then the glory of the God of Israel rose from above the cherubim, where it had been, and moved to the threshold of the temple. And He called to the man clothed in linen who had the writing kit at his side.'),
('EZK', 9, 4, 'EZK.9.4', '“Go throughout the city of Jerusalem,” said the LORD, “and put a mark on the foreheads of the men sighing and groaning over all the abominations committed there.”'),
('EZK', 9, 5, 'EZK.9.5', 'And as I listened, He said to the others, “Follow him through the city and start killing; do not show pity or spare anyone!'),
('EZK', 9, 6, 'EZK.9.6', 'Slaughter the old men, the young men and maidens, the women and children; but do not go near anyone who has the mark. Now begin at My sanctuary.” So they began with the elders who were before the temple.'),
('EZK', 9, 7, 'EZK.9.7', 'Then He told them, “Defile the temple and fill the courts with the slain. Go forth!” So they went out and began killing throughout the city.'),
('EZK', 9, 8, 'EZK.9.8', 'While they were killing, I was left alone. And I fell facedown and cried out, “Oh, Lord GOD, when You pour out Your wrath on Jerusalem, will You destroy the entire remnant of Israel?”'),
('EZK', 9, 9, 'EZK.9.9', 'He replied, “The iniquity of the house of Israel and Judah is exceedingly great. The land is full of bloodshed, and the city is full of perversity. For they say, ‘The LORD has forsaken the land; the LORD does not see.’'),
('EZK', 9, 10, 'EZK.9.10', 'But as for Me, I will not look on them with pity, nor will I spare them. I will bring their deeds down upon their own heads.”'),
('EZK', 9, 11, 'EZK.9.11', 'Then the man clothed in linen with the writing kit at his side reported back, “I have done as You commanded.”'),
('EZK', 10, 1, 'EZK.10.1', 'And I looked and saw above the expanse, above the heads of the cherubim, the likeness of a throne of sapphire.'),
('EZK', 10, 2, 'EZK.10.2', 'And the LORD said to the man clothed in linen, “Go inside the wheelwork beneath the cherubim. Fill your hands with burning coals from among the cherubim and scatter them over the city.” And as I watched, he went in.'),
('EZK', 10, 3, 'EZK.10.3', 'Now when the man went in, the cherubim were standing on the south side of the temple, and a cloud filled the inner court.'),
('EZK', 10, 4, 'EZK.10.4', 'Then the glory of the LORD rose from above the cherubim and stood over the threshold of the temple. The temple was filled with the cloud, and the court was filled with the brightness of the glory of the LORD.'),
('EZK', 10, 5, 'EZK.10.5', 'The sound of the wings of the cherubim could be heard as far as the outer court, like the voice of God Almighty when He speaks.'),
('EZK', 10, 6, 'EZK.10.6', 'When the LORD commanded the man clothed in linen, saying, “Take fire from within the wheelwork, from among the cherubim,” the man went in and stood beside a wheel.'),
('EZK', 10, 7, 'EZK.10.7', 'Then one of the cherubim reached out his hand and took some of the fire that was among them. And he put it into the hands of the man clothed in linen, who received it and went out.'),
('EZK', 10, 8, 'EZK.10.8', '(The cherubim appeared to have the form of human hands under their wings.)'),
('EZK', 10, 9, 'EZK.10.9', 'Then I looked and saw four wheels beside the cherubim, one wheel beside each cherub. And the wheels gleamed like a beryl stone.'),
('EZK', 10, 10, 'EZK.10.10', 'As for their appearance, all four had the same form, like a wheel within a wheel.'),
('EZK', 10, 11, 'EZK.10.11', 'When they moved, they would go in any of the four directions, without turning as they moved. For wherever the head faced, the cherubim would go in that direction, without turning as they moved.'),
('EZK', 10, 12, 'EZK.10.12', 'Their entire bodies, including their backs, hands, and wings, were full of eyes all around, as were their four wheels.'),
('EZK', 10, 13, 'EZK.10.13', 'I heard the wheels being called “the whirling wheels.”'),
('EZK', 10, 14, 'EZK.10.14', 'Each of the cherubim had four faces: the first face was that of a cherub, the second that of a man, the third that of a lion, and the fourth that of an eagle.'),
('EZK', 10, 15, 'EZK.10.15', 'Then the cherubim rose upward. These were the living creatures I had seen by the River Kebar.'),
('EZK', 10, 16, 'EZK.10.16', 'When the cherubim moved, the wheels moved beside them, and even when they spread their wings to rise from the ground, the wheels did not veer away from their side.'),
('EZK', 10, 17, 'EZK.10.17', 'When the cherubim stood still, the wheels also stood still, and when they ascended, the wheels ascended with them, for the spirit of the living creatures was in the wheels.'),
('EZK', 10, 18, 'EZK.10.18', 'Then the glory of the LORD moved away from the threshold of the temple and stood above the cherubim.'),
('EZK', 10, 19, 'EZK.10.19', 'As I watched, the cherubim lifted their wings and rose up from the ground, with the wheels beside them as they went. And they stopped at the entrance of the east gate of the house of the LORD, with the glory of the God of Israel above them.'),
('EZK', 10, 20, 'EZK.10.20', 'These were the living creatures I had seen beneath the God of Israel by the River Kebar, and I knew that they were cherubim.'),
('EZK', 10, 21, 'EZK.10.21', 'Each had four faces and four wings, with what looked like human hands under their wings.'),
('EZK', 10, 22, 'EZK.10.22', 'Their faces looked like the faces I had seen by the River Kebar. Each creature went straight ahead.'),
('EZK', 11, 1, 'EZK.11.1', 'Then the Spirit lifted me up and brought me to the gate of the house of the LORD that faces east. And there at the entrance of the gate were twenty-five men. Among them I saw Jaazaniah son of Azzur and Pelatiah son of Benaiah, who were leaders of the people.'),
('EZK', 11, 2, 'EZK.11.2', 'And the LORD said to me, “Son of man, these are the men who plot evil and give wicked counsel in this city.'),
('EZK', 11, 3, 'EZK.11.3', 'They are saying, ‘Is not the time near to build houses? The city is the cooking pot, and we are the meat.’'),
('EZK', 11, 4, 'EZK.11.4', 'Therefore prophesy against them; prophesy, O son of man!”'),
('EZK', 11, 5, 'EZK.11.5', 'And the Spirit of the LORD fell upon me and told me to declare that this is what the LORD says: “That is what you are thinking, O house of Israel; and I know the thoughts that arise in your minds.'),
('EZK', 11, 6, 'EZK.11.6', 'You have multiplied those you killed in this city and filled its streets with the dead.'),
('EZK', 11, 7, 'EZK.11.7', 'Therefore this is what the Lord GOD says: The slain you have laid within this city are the meat, and the city is the pot; but I will remove you from it.'),
('EZK', 11, 8, 'EZK.11.8', 'You fear the sword, so I will bring the sword against you, declares the Lord GOD.'),
('EZK', 11, 9, 'EZK.11.9', 'I will bring you out of the city and deliver you into the hands of foreigners, and I will execute judgments against you.'),
('EZK', 11, 10, 'EZK.11.10', 'You will fall by the sword, and I will judge you even to the borders of Israel. Then you will know that I am the LORD.'),
('EZK', 11, 11, 'EZK.11.11', 'The city will not be a pot for you, nor will you be the meat within it. I will judge you even to the borders of Israel.'),
('EZK', 11, 12, 'EZK.11.12', 'Then you will know that I am the LORD. For you have neither followed My statutes nor practiced My ordinances, but you have conformed to the ordinances of the nations around you.”'),
('EZK', 11, 13, 'EZK.11.13', 'Now as I was prophesying, Pelatiah son of Benaiah died. Then I fell facedown and cried out in a loud voice, “Oh, Lord GOD, will You bring the remnant of Israel to a complete end?”'),
('EZK', 11, 14, 'EZK.11.14', 'Then the word of the LORD came to me, saying,'),
('EZK', 11, 15, 'EZK.11.15', '“Son of man, your brothers—your relatives, your fellow exiles, and the whole house of Israel—are those of whom the people of Jerusalem have said, ‘They are far away from the LORD; this land has been given to us as a possession.’'),
('EZK', 11, 16, 'EZK.11.16', 'Therefore declare that this is what the Lord GOD says: ‘Although I sent them far away among the nations and scattered them among the countries, yet for a little while I have been a sanctuary for them in the countries to which they have gone.’'),
('EZK', 11, 17, 'EZK.11.17', 'Therefore declare that this is what the Lord GOD says: ‘I will gather you from the peoples and assemble you from the countries to which you have been scattered, and I will give back to you the land of Israel.’'),
('EZK', 11, 18, 'EZK.11.18', 'When they return to it, they will remove all its detestable things and all its abominations.'),
('EZK', 11, 19, 'EZK.11.19', 'And I will give them singleness of heart and put a new spirit within them; I will remove their heart of stone and give them a heart of flesh,'),
('EZK', 11, 20, 'EZK.11.20', 'so that they may follow My statutes, keep My ordinances, and practice them. Then they will be My people, and I will be their God.'),
('EZK', 11, 21, 'EZK.11.21', 'But as for those whose hearts pursue detestable things and abominations, I will bring their conduct down upon their own heads, declares the Lord GOD.”'),
('EZK', 11, 22, 'EZK.11.22', 'Then the cherubim, with the wheels beside them, spread their wings, and the glory of the God of Israel was above them.'),
('EZK', 11, 23, 'EZK.11.23', 'And the glory of the LORD rose up from within the city and stood over the mountain east of the city.'),
('EZK', 11, 24, 'EZK.11.24', 'And the Spirit lifted me up and carried me back to Chaldea, to the exiles in the vision given by the Spirit of God. After the vision had gone up from me,'),
('EZK', 11, 25, 'EZK.11.25', 'I told the exiles everything the LORD had shown me.'),
('EZK', 12, 1, 'EZK.12.1', 'Then the word of the LORD came to me, saying,'),
('EZK', 12, 2, 'EZK.12.2', '“Son of man, you are living in a rebellious house. They have eyes to see but do not see, and ears to hear but do not hear, for they are a rebellious house.'),
('EZK', 12, 3, 'EZK.12.3', 'Therefore, son of man, pack your bags for exile. In broad daylight, set out from your place and go to another as they watch. Perhaps they will understand, though they are a rebellious house.'),
('EZK', 12, 4, 'EZK.12.4', 'Bring out your baggage for exile by day, as they watch. Then in the evening, as they watch, go out like those who go into exile.'),
('EZK', 12, 5, 'EZK.12.5', 'As they watch, dig through the wall and carry your belongings out through it.'),
('EZK', 12, 6, 'EZK.12.6', 'And as they watch, lift your bags to your shoulder and take them out at dusk; cover your face so that you cannot see the land. For I have made you a sign to the house of Israel.”'),
('EZK', 12, 7, 'EZK.12.7', 'So I did as I was commanded. I brought out my bags for exile by day, and in the evening I dug through the wall by hand. I took my belongings out at dusk, carrying them on my shoulder as they watched.'),
('EZK', 12, 8, 'EZK.12.8', 'And in the morning the word of the LORD came to me, saying,'),
('EZK', 12, 9, 'EZK.12.9', '“Son of man, hasn’t the rebellious house of Israel asked you, ‘What are you doing?’'),
('EZK', 12, 10, 'EZK.12.10', 'Tell them that this is what the Lord GOD says: ‘This burden concerns the prince in Jerusalem and all the house of Israel who are there.’'),
('EZK', 12, 11, 'EZK.12.11', 'You are to say, ‘I am a sign to you.’ Just as it happened here, so will it be done to them; they will go into exile as captives.'),
('EZK', 12, 12, 'EZK.12.12', 'And at dusk the prince among them will lift his bags to his shoulder and go out. They will dig through the wall to bring him out. He will cover his face so he cannot see the land.'),
('EZK', 12, 13, 'EZK.12.13', 'But I will spread My net over him, and he will be caught in My snare. I will bring him to Babylon, the land of the Chaldeans; yet he will not see it, and there he will die.'),
('EZK', 12, 14, 'EZK.12.14', 'And I will scatter to every wind all the attendants around him and all his troops, and I will draw a sword to chase after them.'),
('EZK', 12, 15, 'EZK.12.15', 'And they will know that I am the LORD, when I disperse them among the nations and scatter them throughout the countries.'),
('EZK', 12, 16, 'EZK.12.16', 'But I will spare a few of them from sword and famine and plague, so that in the nations to which they go, they can recount all their abominations. Then they will know that I am the LORD.”'),
('EZK', 12, 17, 'EZK.12.17', 'Moreover, the word of the LORD came to me, saying,'),
('EZK', 12, 18, 'EZK.12.18', '“Son of man, eat your bread with trembling, and drink your water with quivering and anxiety.'),
('EZK', 12, 19, 'EZK.12.19', 'Then tell the people of the land that this is what the Lord GOD says about those living in Jerusalem and in the land of Israel: ‘They will eat their bread with anxiety and drink their water in dread, for their land will be stripped of everything in it because of the violence of all who dwell in it.'),
('EZK', 12, 20, 'EZK.12.20', 'The inhabited cities will be laid waste, and the land will become desolate. Then you will know that I am the LORD.’”'),
('EZK', 12, 21, 'EZK.12.21', 'Again the word of the LORD came to me, saying,'),
('EZK', 12, 22, 'EZK.12.22', '“Son of man, what is this proverb that you have in the land of Israel: ‘The days go by, and every vision fails’?'),
('EZK', 12, 23, 'EZK.12.23', 'Therefore tell them that this is what the Lord GOD says: ‘I will put an end to this proverb, and in Israel they will no longer recite it.’ But say to them: ‘The days are at hand when every vision will be fulfilled.'),
('EZK', 12, 24, 'EZK.12.24', 'For there will be no more false visions or flattering divinations within the house of Israel,'),
('EZK', 12, 25, 'EZK.12.25', 'because I, the LORD, will speak whatever word I speak, and it will be fulfilled without delay. For in your days, O rebellious house, I will speak a message and bring it to pass, declares the Lord GOD.’”'),
('EZK', 12, 26, 'EZK.12.26', 'Furthermore, the word of the LORD came to me, saying,'),
('EZK', 12, 27, 'EZK.12.27', '“Son of man, take note that the house of Israel is saying, ‘The vision that he sees is for many years from now; he prophesies about the distant future.’'),
('EZK', 12, 28, 'EZK.12.28', 'Therefore tell them that this is what the Lord GOD says: ‘None of My words will be delayed any longer. The message I speak will be fulfilled, declares the Lord GOD.’”'),
('EZK', 13, 1, 'EZK.13.1', 'Then the word of the LORD came to me, saying,'),
('EZK', 13, 2, 'EZK.13.2', '“Son of man, prophesy against the prophets of Israel who are now prophesying. Tell those who prophesy out of their own imagination: Hear the word of the LORD!'),
('EZK', 13, 3, 'EZK.13.3', 'This is what the Lord GOD says: Woe to the foolish prophets who follow their own spirit yet have seen nothing.'),
('EZK', 13, 4, 'EZK.13.4', 'Your prophets, O Israel, are like foxes among the ruins.'),
('EZK', 13, 5, 'EZK.13.5', 'You did not go up to the gaps or restore the wall around the house of Israel so that it would stand in the battle on the Day of the LORD.'),
('EZK', 13, 6, 'EZK.13.6', 'They see false visions and speak lying divinations. They claim, ‘Thus declares the LORD,’ when the LORD did not send them; yet they wait for the fulfillment of their message.'),
('EZK', 13, 7, 'EZK.13.7', 'Haven’t you seen a false vision and spoken a lying divination when you proclaim, ‘Thus declares the LORD,’ even though I have not spoken?'),
('EZK', 13, 8, 'EZK.13.8', 'Therefore this is what the Lord GOD says: Because you have uttered vain words and seen false visions, I am against you, declares the Lord GOD.'),
('EZK', 13, 9, 'EZK.13.9', 'My hand will be against the prophets who see false visions and speak lying divinations. They will not belong to the council of My people or be recorded in the register of the house of Israel, nor will they enter the land of Israel. Then you will know that I am the Lord GOD.'),
('EZK', 13, 10, 'EZK.13.10', 'Because they have led My people astray, saying, ‘Peace,’ when there is no peace, and whitewashing any flimsy wall that is built,'),
('EZK', 13, 11, 'EZK.13.11', 'tell those whitewashing the wall that it will fall. Rain will come in torrents, I will send hailstones plunging down, and a windstorm will burst forth.'),
('EZK', 13, 12, 'EZK.13.12', 'Surely when the wall has fallen, you will not be asked, ‘Where is the whitewash with which you covered it?’'),
('EZK', 13, 13, 'EZK.13.13', 'Therefore this is what the Lord GOD says: In My wrath I will release a windstorm, and in My anger torrents of rain and hail will fall with destructive fury.'),
('EZK', 13, 14, 'EZK.13.14', 'I will tear down the wall you whitewashed and level it to the ground, so that its foundation is exposed. The city will fall, and you will be destroyed within it. Then you will know that I am the LORD.'),
('EZK', 13, 15, 'EZK.13.15', 'And after I have vented My wrath against the wall and against those who whitewashed it, I will say to you: ‘The wall is gone, and so are those who whitewashed it—'),
('EZK', 13, 16, 'EZK.13.16', 'those prophets of Israel who prophesied to Jerusalem and saw a vision of peace for her when there was no peace, declares the Lord GOD.’'),
('EZK', 13, 17, 'EZK.13.17', 'Now, O son of man, set your face against the daughters of your people who prophesy out of their own imagination. Prophesy against them'),
('EZK', 13, 18, 'EZK.13.18', 'and tell them that this is what the Lord GOD says: Woe to the women who sew magic charms on their wrists and make veils for the heads of people of every height, in order to ensnare their souls. Will you ensnare the souls of My people but preserve your own?'),
('EZK', 13, 19, 'EZK.13.19', 'You have profaned Me among My people for handfuls of barley and scraps of bread. By lying to My people who would listen, you have killed those who should not have died and spared those who should not have lived.'),
('EZK', 13, 20, 'EZK.13.20', 'Therefore this is what the Lord GOD says: See, I am against the magic charms with which you ensnare souls like birds, and I will tear them from your arms. So I will free the souls you have ensnared like birds.'),
('EZK', 13, 21, 'EZK.13.21', 'I will also tear off your veils and deliver My people from your hands, so that they will no longer be prey in your hands. Then you will know that I am the LORD.'),
('EZK', 13, 22, 'EZK.13.22', 'Because you have disheartened the righteous with your lies, even though I have caused them no grief, and because you have encouraged the wicked not to turn from their evil ways to save their lives,'),
('EZK', 13, 23, 'EZK.13.23', 'therefore you will no longer see false visions or practice divination. I will deliver My people from your hands. Then you will know that I am the LORD.”'),
('EZK', 14, 1, 'EZK.14.1', 'Then some of the elders of Israel came and sat down before me.'),
('EZK', 14, 2, 'EZK.14.2', 'And the word of the LORD came to me, saying,'),
('EZK', 14, 3, 'EZK.14.3', '“Son of man, these men have set up idols in their hearts and put wicked stumbling blocks before their faces. Should I consult with them in any way?'),
('EZK', 14, 4, 'EZK.14.4', 'Therefore speak to them and tell them that this is what the Lord GOD says: ‘When any Israelite sets up idols in his heart and puts a wicked stumbling block before his face, and then comes to the prophet, I the LORD will answer him according to his great idolatry,'),
('EZK', 14, 5, 'EZK.14.5', 'so that I may take hold of the hearts of the people of Israel. For because of their idols, they are all estranged from Me.’'),
('EZK', 14, 6, 'EZK.14.6', 'Therefore tell the house of Israel that this is what the Lord GOD says: ‘Repent and turn away from your idols; turn your faces away from all your abominations.'),
('EZK', 14, 7, 'EZK.14.7', 'For when any Israelite or any foreigner dwelling in Israel separates himself from Me, sets up idols in his heart, and puts a wicked stumbling block before his face, and then comes to the prophet to inquire of Me, I the LORD will answer him Myself.'),
('EZK', 14, 8, 'EZK.14.8', 'I will set My face against that man and make him a sign and a proverb; I will cut him off from among My people. Then you will know that I am the LORD.'),
('EZK', 14, 9, 'EZK.14.9', 'But if the prophet is enticed to speak a message, then it was I the LORD who enticed him, and I will stretch out My hand against him and destroy him from among My people Israel.'),
('EZK', 14, 10, 'EZK.14.10', 'They will bear their punishment—the punishment of the inquirer will be the same as that of the prophet—'),
('EZK', 14, 11, 'EZK.14.11', 'in order that the house of Israel may no longer stray from Me and no longer defile themselves with all their transgressions. Then they will be My people and I will be their God, declares the Lord GOD.’”'),
('EZK', 14, 12, 'EZK.14.12', 'And the word of the LORD came to me, saying,'),
('EZK', 14, 13, 'EZK.14.13', '“Son of man, if a land sins against Me by acting unfaithfully, and I stretch out My hand against it to cut off its supply of food, to send famine upon it, and to cut off from it both man and beast,'),
('EZK', 14, 14, 'EZK.14.14', 'then even if these three men—Noah, Daniel, and Job—were in it, their righteousness could deliver only themselves, declares the Lord GOD.'),
('EZK', 14, 15, 'EZK.14.15', 'Or if I send wild beasts through the land to leave it childless and desolate, with no man passing through it for fear of the beasts,'),
('EZK', 14, 16, 'EZK.14.16', 'then as surely as I live, declares the Lord GOD, even if these three men were in it, they could not deliver their own sons or daughters. They alone would be delivered, but the land would be desolate.'),
('EZK', 14, 17, 'EZK.14.17', 'Or if I bring a sword against that land and say, ‘Let a sword pass through it,’ so that I cut off from it both man and beast,'),
('EZK', 14, 18, 'EZK.14.18', 'then as surely as I live, declares the Lord GOD, even if these three men were in it, they could not deliver their own sons or daughters. They alone would be delivered.'),
('EZK', 14, 19, 'EZK.14.19', 'Or if I send a plague into that land and pour out My wrath upon it through bloodshed, cutting off from it both man and beast,'),
('EZK', 14, 20, 'EZK.14.20', 'then as surely as I live, declares the Lord GOD, even if Noah, Daniel, and Job were in it, they could not deliver their own sons or daughters. Their righteousness could deliver only themselves.'),
('EZK', 14, 21, 'EZK.14.21', 'For this is what the Lord GOD says: ‘How much worse will it be when I send against Jerusalem My four dire judgments—sword, famine, wild beasts, and plague—in order to cut off from it both man and beast?'),
('EZK', 14, 22, 'EZK.14.22', 'Yet, behold, some survivors will be left in it—sons and daughters who will be brought out. They will come out to you, and when you see their conduct and actions, you will be comforted regarding the disaster I have brought upon Jerusalem—all that I have brought upon it.'),
('EZK', 14, 23, 'EZK.14.23', 'They will bring you consolation when you see their conduct and actions, and you will know that it was not without cause that I have done all these things within it,’ declares the Lord GOD.”'),
('EZK', 15, 1, 'EZK.15.1', 'Then the word of the LORD came to me, saying,'),
('EZK', 15, 2, 'EZK.15.2', '“Son of man, how does the wood of the vine surpass any other branch among the trees in the forest?'),
('EZK', 15, 3, 'EZK.15.3', 'Can wood be taken from it to make something useful? Or can one make from it a peg on which to hang utensils?'),
('EZK', 15, 4, 'EZK.15.4', 'No, it is cast into the fire for fuel. The fire devours both ends, and the middle is charred. Can it be useful for anything?'),
('EZK', 15, 5, 'EZK.15.5', 'Even when it was whole, it could not be made useful. How much less can it ever be useful when the fire has consumed it and charred it!'),
('EZK', 15, 6, 'EZK.15.6', 'Therefore this is what the Lord GOD says: ‘Like the wood of the vine among the trees of the forest, which I have given to the fire for fuel, so I will give up the people of Jerusalem.'),
('EZK', 15, 7, 'EZK.15.7', 'And I will set My face against them. Though they may have escaped the fire, yet another fire will consume them. And when I set My face against them, you will know that I am the LORD.'),
('EZK', 15, 8, 'EZK.15.8', 'Thus I will make the land desolate, because they have acted unfaithfully,’ declares the Lord GOD.”'),
('EZK', 16, 1, 'EZK.16.1', 'Again the word of the LORD came to me, saying,'),
('EZK', 16, 2, 'EZK.16.2', '“Son of man, confront Jerusalem with her abominations'),
('EZK', 16, 3, 'EZK.16.3', 'and tell her that this is what the Lord GOD says to Jerusalem: Your origin and your birth were in the land of the Canaanites. Your father was an Amorite and your mother a Hittite.'),
('EZK', 16, 4, 'EZK.16.4', 'On the day of your birth your cord was not cut, nor were you washed with water for cleansing. You were not rubbed with salt or wrapped in cloths.'),
('EZK', 16, 5, 'EZK.16.5', 'No one cared enough for you to do even one of these things out of compassion for you. Instead, you were thrown out into the open field, because you were despised on the day of your birth.'),
('EZK', 16, 6, 'EZK.16.6', 'Then I passed by and saw you wallowing in your blood, and as you lay there in your blood I said to you, ‘Live!’ There I said to you, ‘Live!’'),
('EZK', 16, 7, 'EZK.16.7', 'I made you thrive like a plant of the field. You grew up and matured and became very beautiful. Your breasts were formed and your hair grew, but you were naked and bare.'),
('EZK', 16, 8, 'EZK.16.8', 'Then I passed by and saw you, and you were indeed old enough for love. So I spread My cloak over you and covered your nakedness. I pledged Myself to you, entered into a covenant with you, and you became Mine, declares the Lord GOD.'),
('EZK', 16, 9, 'EZK.16.9', 'Then I bathed you with water, rinsed off your blood, and anointed you with oil.'),
('EZK', 16, 10, 'EZK.16.10', 'I clothed you in embroidered cloth and gave you sandals of fine leather. I wrapped you in fine linen and covered you with silk.'),
('EZK', 16, 11, 'EZK.16.11', 'I adorned you with jewelry, and I put bracelets on your wrists and a chain around your neck.'),
('EZK', 16, 12, 'EZK.16.12', 'I put a ring in your nose, earrings on your ears, and a beautiful crown upon your head.'),
('EZK', 16, 13, 'EZK.16.13', 'So you were adorned with gold and silver, and your clothing was made of fine linen, silk, and embroidered cloth. You ate fine flour, honey, and oil. You became very beautiful and rose to be queen.'),
('EZK', 16, 14, 'EZK.16.14', 'Your fame spread among the nations on account of your beauty, for it was perfect in the splendor I bestowed on you, declares the Lord GOD.'),
('EZK', 16, 15, 'EZK.16.15', 'But because of your fame, you trusted in your beauty and played the harlot. You lavished your favors on everyone who passed by, and your beauty was theirs for the asking.'),
('EZK', 16, 16, 'EZK.16.16', 'You took some of your garments and made colorful high places for yourself, and on them you prostituted yourself. Such things should not have happened; never should they have occurred!'),
('EZK', 16, 17, 'EZK.16.17', 'You also took the fine jewelry of gold and silver I had given you, and you made male idols with which to prostitute yourself.'),
('EZK', 16, 18, 'EZK.16.18', 'You took your embroidered garments to cover them, and you set My oil and incense before them.'),
('EZK', 16, 19, 'EZK.16.19', 'And you set before them as a pleasing aroma the food I had given you—the fine flour, oil, and honey that I had fed you. That is what happened, declares the Lord GOD.'),
('EZK', 16, 20, 'EZK.16.20', 'You even took the sons and daughters you bore to Me and sacrificed them as food to idols. Was your prostitution not enough?'),
('EZK', 16, 21, 'EZK.16.21', 'You slaughtered My children and delivered them up through the fire to idols.'),
('EZK', 16, 22, 'EZK.16.22', 'And in all your abominations and acts of prostitution, you did not remember the days of your youth when you were naked and bare, wallowing in your own blood.'),
('EZK', 16, 23, 'EZK.16.23', 'Woe! Woe to you, declares the Lord GOD. And in addition to all your other wickedness,'),
('EZK', 16, 24, 'EZK.16.24', 'you built yourself a mound and made yourself a lofty shrine in every public square.'),
('EZK', 16, 25, 'EZK.16.25', 'At the head of every street you built your lofty shrines and degraded your beauty. With increasing promiscuity, you spread your legs to all who passed by.'),
('EZK', 16, 26, 'EZK.16.26', 'You prostituted yourself with your lustful neighbors, the Egyptians, and increased your promiscuity to provoke Me to anger.'),
('EZK', 16, 27, 'EZK.16.27', 'Therefore I stretched out My hand against you and reduced your portion. I gave you over to the desire of those who hate you, the daughters of the Philistines, who were ashamed of your lewd conduct.'),
('EZK', 16, 28, 'EZK.16.28', 'Then you prostituted yourself with the Assyrians, because you were not yet satisfied. Even after that, you were still not satisfied.'),
('EZK', 16, 29, 'EZK.16.29', 'So you extended your promiscuity to Chaldea, the land of merchants—but even with this you were not satisfied!'),
('EZK', 16, 30, 'EZK.16.30', 'How weak-willed is your heart, declares the Lord GOD, while you do all these things, the acts of a shameless prostitute!'),
('EZK', 16, 31, 'EZK.16.31', 'But when you built your mounds at the head of every street and made your lofty shrines in every public square, you were not even like a prostitute, because you scorned payment.'),
('EZK', 16, 32, 'EZK.16.32', 'You adulterous wife! You receive strangers instead of your own husband!'),
('EZK', 16, 33, 'EZK.16.33', 'Men give gifts to all their prostitutes, but you gave gifts to all your lovers. You bribed them to come to you from everywhere for your illicit favors.'),
('EZK', 16, 34, 'EZK.16.34', 'So your prostitution is the opposite of that of other women: No one solicited your favors, and you paid a fee instead of receiving one; so you are the very opposite!'),
('EZK', 16, 35, 'EZK.16.35', 'Therefore, O prostitute, hear the word of the LORD!'),
('EZK', 16, 36, 'EZK.16.36', 'This is what the Lord GOD says: Because you poured out your wealth and exposed your nakedness in your promiscuity with your lovers and with all your detestable idols, and because of the blood of your children which you gave to them,'),
('EZK', 16, 37, 'EZK.16.37', 'therefore I will surely gather all the lovers with whom you found pleasure, all those you loved and all those you hated. I will gather them against you from all around and expose you before them, and they will see you completely naked.'),
('EZK', 16, 38, 'EZK.16.38', 'And I will sentence you to the punishment of women who commit adultery and those who shed blood; so I will bring upon you the wrath of your bloodshed and jealousy.'),
('EZK', 16, 39, 'EZK.16.39', 'Then I will deliver you into the hands of your lovers, and they will level your mounds and tear down your lofty shrines. They will strip off your clothes, take your fine jewelry, and leave you naked and bare.'),
('EZK', 16, 40, 'EZK.16.40', 'They will bring a mob against you, who will stone you and cut you to pieces with their swords.'),
('EZK', 16, 41, 'EZK.16.41', 'Then they will burn down your houses and execute judgment against you in the sight of many women. I will put an end to your prostitution, and you will never again pay your lovers.'),
('EZK', 16, 42, 'EZK.16.42', 'So I will lay to rest My wrath against you, and My jealousy will turn away from you. Then I will be calm and no longer angry.'),
('EZK', 16, 43, 'EZK.16.43', 'Because you did not remember the days of your youth, but enraged Me with all these things, I will surely bring your deeds down upon your own head, declares the Lord GOD. Have you not committed this lewdness on top of all your other abominations?'),
('EZK', 16, 44, 'EZK.16.44', 'Behold, all who speak in proverbs will quote this proverb about you: ‘Like mother, like daughter.’'),
('EZK', 16, 45, 'EZK.16.45', 'You are the daughter of your mother, who despised her husband and children. You are the sister of your sisters, who despised their husbands and children. Your mother was a Hittite and your father an Amorite.'),
('EZK', 16, 46, 'EZK.16.46', 'Your older sister was Samaria, who lived with her daughters to your north; and your younger sister was Sodom, who lived with her daughters to your south.'),
('EZK', 16, 47, 'EZK.16.47', 'And you not only walked in their ways and practiced their abominations, but soon you were more depraved than they were.'),
('EZK', 16, 48, 'EZK.16.48', 'As surely as I live, declares the Lord GOD, your sister Sodom and her daughters never did as you and your daughters have done.'),
('EZK', 16, 49, 'EZK.16.49', 'Now this was the iniquity of your sister Sodom: She and her daughters were arrogant, overfed, and complacent; they did not help the poor and needy.'),
('EZK', 16, 50, 'EZK.16.50', 'Thus they were haughty and committed abominations before Me. Therefore I removed them, as you have seen.'),
('EZK', 16, 51, 'EZK.16.51', 'Furthermore, Samaria did not commit half the sins you did. You have multiplied your abominations beyond theirs, and all the abominations you have committed have made your sisters appear righteous.'),
('EZK', 16, 52, 'EZK.16.52', 'So now you must bear your disgrace, since you have brought justification for your sisters. For they appear more righteous than you, because your sins were more vile than theirs. So you too must bear your shame and disgrace, since you have made your sisters appear righteous.'),
('EZK', 16, 53, 'EZK.16.53', 'But I will restore Sodom and her daughters from captivity, as well as Samaria and her daughters. And I will restore you along with them.'),
('EZK', 16, 54, 'EZK.16.54', 'So you will bear your disgrace and be ashamed of all you did to comfort them.'),
('EZK', 16, 55, 'EZK.16.55', 'And your sisters, Sodom with her daughters and Samaria with her daughters, will return to their former state. You and your daughters will also return to your former state.'),
('EZK', 16, 56, 'EZK.16.56', 'Did you not treat your sister Sodom as an object of scorn in the day of your pride,'),
('EZK', 16, 57, 'EZK.16.57', 'before your wickedness was uncovered? Even so, you are now scorned by the daughters of Edom and all those around her, and by the daughters of the Philistines—all those around you who despise you.'),
('EZK', 16, 58, 'EZK.16.58', 'You will bear the consequences of your lewdness and your abominations, declares the LORD.'),
('EZK', 16, 59, 'EZK.16.59', 'For this is what the Lord GOD says: I will deal with you according to your deeds, since you have despised the oath by breaking the covenant.'),
('EZK', 16, 60, 'EZK.16.60', 'But I will remember the covenant I made with you in the days of your youth, and I will establish an everlasting covenant with you.'),
('EZK', 16, 61, 'EZK.16.61', 'Then you will remember your ways and be ashamed when you receive your older and younger sisters. I will give them to you as daughters, but not because of My covenant with you.'),
('EZK', 16, 62, 'EZK.16.62', 'So I will establish My covenant with you, and you will know that I am the LORD,'),
('EZK', 16, 63, 'EZK.16.63', 'so that when I make atonement for all you have done, you will remember and be ashamed and never again open your mouth because of your disgrace, declares the Lord GOD.”'),
('EZK', 17, 1, 'EZK.17.1', 'Now the word of the LORD came to me, saying,'),
('EZK', 17, 2, 'EZK.17.2', '“Son of man, pose a riddle; speak a parable to the house of Israel'),
('EZK', 17, 3, 'EZK.17.3', 'and tell them that this is what the Lord GOD says: ‘A great eagle with great wings and long pinions, full of feathers of many colors, came to Lebanon and took away the top of the cedar.'),
('EZK', 17, 4, 'EZK.17.4', 'He plucked off its topmost shoot, carried it to the land of merchants, and planted it in a city of traders.'),
('EZK', 17, 5, 'EZK.17.5', 'He took some of the seed of the land and planted it in fertile soil; he placed it by abundant waters and set it out like a willow.'),
('EZK', 17, 6, 'EZK.17.6', 'It sprouted and became a spreading vine, low in height, with branches turned toward him; yet its roots remained where it stood. So it became a vine and yielded branches and sent out shoots.'),
('EZK', 17, 7, 'EZK.17.7', 'But there was another great eagle with great wings and many feathers. And behold, this vine bent its roots toward him. It stretched out its branches to him from its planting bed, so that he might water it.'),
('EZK', 17, 8, 'EZK.17.8', 'It had been planted in good soil by abundant waters in order to yield branches and bear fruit and become a splendid vine.’'),
('EZK', 17, 9, 'EZK.17.9', 'So you are to tell them that this is what the Lord GOD says: ‘Will it flourish? Will it not be uprooted and stripped of its fruit so that it shrivels? All its foliage will wither! It will not take a strong arm or many people to pull it up by its roots.'),
('EZK', 17, 10, 'EZK.17.10', 'Even if it is transplanted, will it flourish? Will it not completely wither when the east wind strikes? It will wither on the bed where it sprouted.’”'),
('EZK', 17, 11, 'EZK.17.11', 'Then the word of the LORD came to me, saying,'),
('EZK', 17, 12, 'EZK.17.12', '“Now say to this rebellious house: ‘Do you not know what these things mean?’ Tell them, ‘Behold, the king of Babylon came to Jerusalem, carried off its king and officials, and brought them back with him to Babylon.'),
('EZK', 17, 13, 'EZK.17.13', 'He took a member of the royal family and made a covenant with him, putting him under oath. Then he carried away the leading men of the land,'),
('EZK', 17, 14, 'EZK.17.14', 'so that the kingdom would be brought low, unable to lift itself up, surviving only by keeping his covenant.'),
('EZK', 17, 15, 'EZK.17.15', 'But this king rebelled against Babylon by sending his envoys to Egypt to ask for horses and a large army. Will he flourish? Will the one who does such things escape? Can he break a covenant and yet escape?’'),
('EZK', 17, 16, 'EZK.17.16', '‘As surely as I live,’ declares the Lord GOD, ‘he will die in Babylon, in the land of the king who enthroned him, whose oath he despised and whose covenant he broke.'),
('EZK', 17, 17, 'EZK.17.17', 'Pharaoh with his mighty army and vast horde will not help him in battle, when ramps are built and siege walls constructed to destroy many lives.'),
('EZK', 17, 18, 'EZK.17.18', 'He despised the oath by breaking the covenant. Seeing that he gave his hand in pledge yet did all these things, he will not escape!’'),
('EZK', 17, 19, 'EZK.17.19', 'Therefore this is what the Lord GOD says: ‘As surely as I live, I will bring down upon his head My oath that he despised and My covenant that he broke.'),
('EZK', 17, 20, 'EZK.17.20', 'I will spread My net over him and catch him in My snare. I will bring him to Babylon and execute judgment upon him there for the treason he committed against Me.'),
('EZK', 17, 21, 'EZK.17.21', 'All his choice troops will fall by the sword, and those who survive will be scattered to every wind. Then you will know that I, the LORD, have spoken.’'),
('EZK', 17, 22, 'EZK.17.22', 'This is what the Lord GOD says: ‘I will take a shoot from the lofty top of the cedar, and I will set it out. I will pluck a tender sprig from its topmost shoots, and I will plant it on a high and lofty mountain.'),
('EZK', 17, 23, 'EZK.17.23', 'I will plant it on the mountain heights of Israel so that it will bear branches; it will yield fruit and become a majestic cedar. Birds of every kind will nest under it, taking shelter in the shade of its branches.'),
('EZK', 17, 24, 'EZK.17.24', 'Then all the trees of the field will know that I am the LORD. I bring the tall tree down and make the low tree tall. I dry up the green tree and make the withered tree flourish. I, the LORD, have spoken, and I have done it.’”'),
('EZK', 18, 1, 'EZK.18.1', 'Then the word of the LORD came to me, saying,'),
('EZK', 18, 2, 'EZK.18.2', '“What do you people mean by quoting this proverb about the land of Israel: ‘The fathers have eaten sour grapes, and the teeth of the children are set on edge’?'),
('EZK', 18, 3, 'EZK.18.3', 'As surely as I live, declares the Lord GOD, you will no longer quote this proverb in Israel.'),
('EZK', 18, 4, 'EZK.18.4', 'Behold, every soul belongs to Me; both father and son are Mine. The soul who sins is the one who will die.'),
('EZK', 18, 5, 'EZK.18.5', 'Now suppose a man is righteous and does what is just and right:'),
('EZK', 18, 6, 'EZK.18.6', 'He does not eat at the mountain or look to the idols of the house of Israel. He does not defile his neighbor’s wife or approach a woman during her period.'),
('EZK', 18, 7, 'EZK.18.7', 'He does not oppress another, but restores the pledge to the debtor. He does not commit robbery, but gives his bread to the hungry and covers the naked with clothing.'),
('EZK', 18, 8, 'EZK.18.8', 'He does not engage in usury or take excess interest, but he withholds his hand from iniquity and executes true justice between men.'),
('EZK', 18, 9, 'EZK.18.9', 'He follows My statutes and faithfully keeps My ordinances. That man is righteous; surely he will live, declares the Lord GOD.'),
('EZK', 18, 10, 'EZK.18.10', 'Now suppose that man has a violent son, who sheds blood or does any of these things,'),
('EZK', 18, 11, 'EZK.18.11', 'though the father has done none of them: Indeed, the son eats at the mountain and defiles his neighbor’s wife.'),
('EZK', 18, 12, 'EZK.18.12', 'He oppresses the poor and needy; he commits robbery and does not restore a pledge. He lifts his eyes to idols; he commits abominations.'),
('EZK', 18, 13, 'EZK.18.13', 'He engages in usury and takes excess interest. Will this son live? He will not! Since he has committed all these abominations, he will surely die; his blood will be on his own head.'),
('EZK', 18, 14, 'EZK.18.14', 'Now suppose this son has a son who sees all the sins his father has committed, considers them, and does not do likewise:'),
('EZK', 18, 15, 'EZK.18.15', 'He does not eat at the mountain or look to the idols of the house of Israel. He does not defile his neighbor’s wife.'),
('EZK', 18, 16, 'EZK.18.16', 'He does not oppress another, or retain a pledge, or commit robbery. He gives his bread to the hungry and covers the naked with clothing.'),
('EZK', 18, 17, 'EZK.18.17', 'He withholds his hand from harming the poor and takes no interest or usury. He keeps My ordinances and follows My statutes. Such a man will not die for his father’s iniquity. He will surely live.'),
('EZK', 18, 18, 'EZK.18.18', 'As for his father, he will die for his own iniquity, because he practiced extortion, robbed his brother, and did what was wrong among his people.'),
('EZK', 18, 19, 'EZK.18.19', 'Yet you may ask, ‘Why shouldn’t the son bear the iniquity of his father?’ Since the son has done what is just and right, carefully observing all My statutes, he will surely live.'),
('EZK', 18, 20, 'EZK.18.20', 'The soul who sins is the one who will die. A son will not bear the iniquity of his father, and a father will not bear the iniquity of his son. The righteousness of the righteous man will fall upon him, and the wickedness of the wicked man will fall upon him.'),
('EZK', 18, 21, 'EZK.18.21', 'But if the wicked man turns from all the sins he has committed, keeps all My statutes, and does what is just and right, he will surely live; he will not die.'),
('EZK', 18, 22, 'EZK.18.22', 'None of the transgressions he has committed will be held against him. Because of the righteousness he has practiced, he will live.'),
('EZK', 18, 23, 'EZK.18.23', 'Do I take any pleasure in the death of the wicked? declares the Lord GOD. Wouldn’t I prefer that he turn from his ways and live?'),
('EZK', 18, 24, 'EZK.18.24', 'But if a righteous man turns from his righteousness and practices iniquity, committing the same abominations as the wicked, will he live? None of the righteous acts he did will be remembered. Because of the unfaithfulness and sin he has committed, he will die.'),
('EZK', 18, 25, 'EZK.18.25', 'Yet you say, ‘The way of the Lord is not just.’ Hear now, O house of Israel: Is it My way that is unjust? Is it not your ways that are unjust?'),
('EZK', 18, 26, 'EZK.18.26', 'If a righteous man turns from his righteousness and practices iniquity, he will die for this. He will die because of the iniquity he has committed.'),
('EZK', 18, 27, 'EZK.18.27', 'But if a wicked man turns from the wickedness he has committed and does what is just and right, he will save his life.'),
('EZK', 18, 28, 'EZK.18.28', 'Because he considered and turned from all the transgressions he had committed, he will surely live; he will not die.'),
('EZK', 18, 29, 'EZK.18.29', 'Yet the house of Israel says, ‘The way of the Lord is not just.’ Are My ways unjust, O house of Israel? Is it not your ways that are unjust?'),
('EZK', 18, 30, 'EZK.18.30', 'Therefore, O house of Israel, I will judge you, each according to his ways, declares the Lord GOD. Repent and turn from all your transgressions, so that your iniquity will not become your downfall.'),
('EZK', 18, 31, 'EZK.18.31', 'Cast away from yourselves all the transgressions you have committed, and fashion for yourselves a new heart and a new spirit. Why should you die, O house of Israel?'),
('EZK', 18, 32, 'EZK.18.32', 'For I take no pleasure in anyone’s death, declares the Lord GOD. So repent and live!'),
('EZK', 19, 1, 'EZK.19.1', '“As for you, take up a lament for the princes of Israel'),
('EZK', 19, 2, 'EZK.19.2', 'and say: ‘What was your mother? A lioness among the lions! She lay down among the young lions; she reared her cubs.'),
('EZK', 19, 3, 'EZK.19.3', 'She brought up one of her cubs, and he became a young lion. After learning to tear his prey, he devoured men.'),
('EZK', 19, 4, 'EZK.19.4', 'When the nations heard of him, he was trapped in their pit. With hooks they led him away to the land of Egypt.'),
('EZK', 19, 5, 'EZK.19.5', 'When she saw that she had waited in vain, that her hope was lost, she took another of her cubs and made him a young lion.'),
('EZK', 19, 6, 'EZK.19.6', 'He prowled among the lions, and became a young lion. After learning to tear his prey, he devoured men.'),
('EZK', 19, 7, 'EZK.19.7', 'He broke down their strongholds and devastated their cities. The land and everything in it shuddered at the sound of his roaring.'),
('EZK', 19, 8, 'EZK.19.8', 'Then the nations set out against him from the provinces on every side. They spread their net over him; he was trapped in their pit.'),
('EZK', 19, 9, 'EZK.19.9', 'With hooks they caged him and brought him to the king of Babylon. They brought him into captivity so that his roar was heard no longer on the mountains of Israel.'),
('EZK', 19, 10, 'EZK.19.10', 'Your mother was like a vine in your vineyard, planted by the water; it was fruitful and full of branches because of the abundant waters.'),
('EZK', 19, 11, 'EZK.19.11', 'It had strong branches, fit for a ruler’s scepter. It towered high above the thick branches, conspicuous for its height and for its dense foliage.'),
('EZK', 19, 12, 'EZK.19.12', 'But it was uprooted in fury, cast down to the ground, and the east wind dried up its fruit. Its strong branches were stripped off and they withered; the fire consumed them.'),
('EZK', 19, 13, 'EZK.19.13', 'Now it is planted in the wilderness, in a dry and thirsty land.'),
('EZK', 19, 14, 'EZK.19.14', 'Fire has gone out from its main branch and devoured its fruit; on it no strong branch remains fit for a ruler’s scepter.’ This is a lament and shall be used as a lament.”'),
('EZK', 20, 1, 'EZK.20.1', 'In the seventh year, on the tenth day of the fifth month, some of the elders of Israel came to inquire of the LORD, and they sat down before me.'),
('EZK', 20, 2, 'EZK.20.2', 'Then the word of the LORD came to me, saying,'),
('EZK', 20, 3, 'EZK.20.3', '“Son of man, speak to the elders of Israel and tell them that this is what the Lord GOD says: Have you come to inquire of Me? As surely as I live, I will not be consulted by you, declares the Lord GOD.'),
('EZK', 20, 4, 'EZK.20.4', 'Will you judge them, will you judge them, son of man? Confront them with the abominations of their fathers'),
('EZK', 20, 5, 'EZK.20.5', 'and tell them that this is what the Lord GOD says: On the day I chose Israel, I swore an oath to the descendants of the house of Jacob and made Myself known to them in the land of Egypt. With an uplifted hand I said to them, ‘I am the LORD your God.’'),
('EZK', 20, 6, 'EZK.20.6', 'On that day I swore to bring them out of the land of Egypt into a land that I had searched out for them, a land flowing with milk and honey, the glory of all lands.'),
('EZK', 20, 7, 'EZK.20.7', 'And I said to them: ‘Each of you must throw away the abominations before his eyes, and you must not defile yourselves with the idols of Egypt. I am the LORD your God.’'),
('EZK', 20, 8, 'EZK.20.8', 'But they rebelled against Me and refused to listen. None of them cast away the abominations before their eyes, and they did not forsake the idols of Egypt. So I resolved to pour out My wrath upon them and vent My anger against them in the land of Egypt.'),
('EZK', 20, 9, 'EZK.20.9', 'But I acted for the sake of My name, that it should not be profaned in the eyes of the nations among whom they were living, in whose sight I had revealed Myself to Israel by bringing them out of the land of Egypt.'),
('EZK', 20, 10, 'EZK.20.10', 'So I brought them out of the land of Egypt and led them into the wilderness.'),
('EZK', 20, 11, 'EZK.20.11', 'And I gave them My statutes and made known to them My ordinances—for the man who does these things will live by them.'),
('EZK', 20, 12, 'EZK.20.12', 'I also gave them My Sabbaths as a sign between us, so that they would know that I am the LORD who sanctifies them.'),
('EZK', 20, 13, 'EZK.20.13', 'Yet the house of Israel rebelled against Me in the wilderness. They did not follow My statutes and they rejected My ordinances—though the man who does these things will live by them—and they utterly profaned My Sabbaths. Then I resolved to pour out My wrath upon them and put an end to them in the wilderness.'),
('EZK', 20, 14, 'EZK.20.14', 'But I acted for the sake of My name, so that it would not be profaned in the eyes of the nations in whose sight I had brought them out.'),
('EZK', 20, 15, 'EZK.20.15', 'Moreover, with an uplifted hand I swore to them in the wilderness that I would not bring them into the land that I had given them—a land flowing with milk and honey, the glory of all lands—'),
('EZK', 20, 16, 'EZK.20.16', 'because they kept rejecting My ordinances, refusing to walk in My statutes, and profaning My Sabbaths; for their hearts continually went after their idols.'),
('EZK', 20, 17, 'EZK.20.17', 'Yet I looked on them with pity and did not destroy them or bring them to an end in the wilderness.'),
('EZK', 20, 18, 'EZK.20.18', 'In the wilderness I said to their children: ‘Do not walk in the statutes of your fathers or keep their ordinances or defile yourselves with their idols.'),
('EZK', 20, 19, 'EZK.20.19', 'I am the LORD your God; walk in My statutes, keep My ordinances, and practice them.'),
('EZK', 20, 20, 'EZK.20.20', 'Keep My Sabbaths holy, that they may be a sign between us, so that you may know that I am the LORD your God.’'),
('EZK', 20, 21, 'EZK.20.21', 'But the children rebelled against Me. They did not walk in My statutes or carefully observe My ordinances—though the man who does these things will live by them—and they profaned My Sabbaths. So I resolved to pour out My wrath upon them and vent My anger against them in the wilderness.'),
('EZK', 20, 22, 'EZK.20.22', 'But I withheld My hand and acted for the sake of My name, so that it would not be profaned in the eyes of the nations in whose sight I had brought them out.'),
('EZK', 20, 23, 'EZK.20.23', 'However, with an uplifted hand I swore to them in the wilderness that I would scatter them among the nations and disperse them throughout the lands.'),
('EZK', 20, 24, 'EZK.20.24', 'For they did not practice My ordinances, but they rejected My statutes and profaned My Sabbaths, fixing their eyes on the idols of their fathers.'),
('EZK', 20, 25, 'EZK.20.25', 'I also gave them over to statutes that were not good and ordinances by which they could not live.'),
('EZK', 20, 26, 'EZK.20.26', 'And I pronounced them unclean through their gifts—the sacrifice of every firstborn in the fire—so that I might devastate them, in order that they would know that I am the LORD.'),
('EZK', 20, 27, 'EZK.20.27', 'Therefore, son of man, speak to the house of Israel, and tell them that this is what the Lord GOD says: In this way also your fathers blasphemed Me by their unfaithfulness against Me.'),
('EZK', 20, 28, 'EZK.20.28', 'When I brought them into the land that I swore to give them and they saw any high hill or leafy tree, there they offered their sacrifices, presented offerings that provoked Me, sent up their fragrant incense, and poured out their drink offerings.'),
('EZK', 20, 29, 'EZK.20.29', 'So I asked them: ‘What is this high place to which you go?’ (And to this day it is called Bamah.)'),
('EZK', 20, 30, 'EZK.20.30', 'Therefore tell the house of Israel that this is what the Lord GOD says: Will you defile yourselves the way your fathers did, prostituting yourselves with their abominations?'),
('EZK', 20, 31, 'EZK.20.31', 'When you offer your gifts, sacrificing your sons in the fire, you continue to defile yourselves with all your idols to this day. So should I be consulted by you, O house of Israel? As surely as I live, declares the Lord GOD, I will not be consulted by you!'),
('EZK', 20, 32, 'EZK.20.32', 'When you say, ‘Let us be like the nations, like the peoples of the lands, serving wood and stone,’ what you have in mind will never come to pass.'),
('EZK', 20, 33, 'EZK.20.33', 'As surely as I live, declares the Lord GOD, with a strong hand, an outstretched arm, and outpoured wrath I will rule over you.'),
('EZK', 20, 34, 'EZK.20.34', 'With a strong hand, an outstretched arm, and outpoured wrath I will bring you out from the peoples and gather you from the lands to which you have been scattered.'),
('EZK', 20, 35, 'EZK.20.35', 'And I will bring you into the wilderness of the nations, where I will enter into judgment with you face to face.'),
('EZK', 20, 36, 'EZK.20.36', 'Just as I entered into judgment with your fathers in the wilderness of the land of Egypt, so I will enter into judgment with you, declares the Lord GOD.'),
('EZK', 20, 37, 'EZK.20.37', 'I will make you pass under the rod and will bring you into the bond of the covenant.'),
('EZK', 20, 38, 'EZK.20.38', 'And I will purge you of those who rebel and transgress against Me. I will bring them out of the land in which they dwell, but they will not enter the land of Israel. Then you will know that I am the LORD.'),
('EZK', 20, 39, 'EZK.20.39', 'And as for you, O house of Israel, this is what the Lord GOD says: Go and serve your idols, every one of you. But afterward, you will surely listen to Me, and you will no longer defile My holy name with your gifts and idols.'),
('EZK', 20, 40, 'EZK.20.40', 'For on My holy mountain, the high mountain of Israel, declares the Lord GOD, there the whole house of Israel, all of them, will serve Me in the land. There I will accept them and will require your offerings and choice gifts, along with all your holy sacrifices.'),
('EZK', 20, 41, 'EZK.20.41', 'When I bring you from the peoples and gather you from the lands to which you have been scattered, I will accept you as a pleasing aroma. And I will show My holiness through you in the sight of the nations.'),
('EZK', 20, 42, 'EZK.20.42', 'Then you will know that I am the LORD, when I bring you into the land of Israel, the land that I swore to give your fathers.'),
('EZK', 20, 43, 'EZK.20.43', 'There you will remember your ways and all the deeds with which you have defiled yourselves, and you will loathe yourselves for all the evils you have done.'),
('EZK', 20, 44, 'EZK.20.44', 'Then you will know, O house of Israel, that I am the LORD, when I have dealt with you for the sake of My name and not according to your wicked ways and corrupt acts, declares the Lord GOD.”'),
('EZK', 20, 45, 'EZK.20.45', 'Now the word of the LORD came to me, saying,'),
('EZK', 20, 46, 'EZK.20.46', '“Son of man, set your face toward the south, preach against it, and prophesy against the forest of the Negev.'),
('EZK', 20, 47, 'EZK.20.47', 'Say to the forest of the Negev: Hear the word of the LORD! This is what the Lord GOD says: I am about to ignite in you a fire, and it will devour all your trees, both green and dry. The blazing flame will not be quenched, and by it every face from south to north will be scorched.'),
('EZK', 20, 48, 'EZK.20.48', 'Then all people will see that I, the LORD, have kindled it; it will not be quenched.”'),
('EZK', 20, 49, 'EZK.20.49', 'Then I said, “Ah, Lord GOD, they are saying of me, ‘Is he not just telling parables?’”'),
('EZK', 21, 1, 'EZK.21.1', 'And the word of the LORD came to me, saying,'),
('EZK', 21, 2, 'EZK.21.2', '“Son of man, set your face against Jerusalem and preach against the sanctuaries. Prophesy against the land of Israel'),
('EZK', 21, 3, 'EZK.21.3', 'and tell her that this is what the LORD says: ‘I am against you, and I will draw My sword from its sheath and cut off from you both the righteous and the wicked.'),
('EZK', 21, 4, 'EZK.21.4', 'Because I will cut off both the righteous and the wicked, My sword will be unsheathed against everyone from south to north.'),
('EZK', 21, 5, 'EZK.21.5', 'Then all flesh will know that I, the LORD, have taken My sword from its sheath, not to return it again.’'),
('EZK', 21, 6, 'EZK.21.6', 'But you, son of man, groan! Groan before their eyes with a broken heart and bitter grief.'),
('EZK', 21, 7, 'EZK.21.7', 'And when they ask, ‘Why are you groaning?’ you are to say, ‘Because of the news that is coming. Every heart will melt, and every hand will go limp. Every spirit will faint, and every knee will turn to water.’ Yes, it is coming and it will surely happen, declares the Lord GOD.”'),
('EZK', 21, 8, 'EZK.21.8', 'Again the word of the LORD came to me, saying,'),
('EZK', 21, 9, 'EZK.21.9', '“Son of man, prophesy and tell them that this is what the Lord says: ‘A sword, a sword, sharpened and polished—'),
('EZK', 21, 10, 'EZK.21.10', 'it is sharpened for the slaughter, polished to flash like lightning! Should we rejoice in the scepter of My son? The sword despises every such stick.'),
('EZK', 21, 11, 'EZK.21.11', 'The sword is appointed to be polished, to be grasped in the hand. It is sharpened and polished, to be placed in the hand of the slayer.'),
('EZK', 21, 12, 'EZK.21.12', 'Cry out and wail, O son of man, for the sword is wielded against My people; it is against all the princes of Israel! They are tossed to the sword with My people; therefore strike your thigh.'),
('EZK', 21, 13, 'EZK.21.13', 'Surely testing will come! And what if even the scepter, which the sword despises, does not continue?’ declares the Lord GOD.'),
('EZK', 21, 14, 'EZK.21.14', '‘So then, son of man, prophesy and strike your hands together. Let the sword strike two times, even three. It is a sword that slays, a sword of great slaughter closing in on every side!'),
('EZK', 21, 15, 'EZK.21.15', 'So that their hearts may melt and many may stumble, I have appointed at all their gates a sword for slaughter. Yes, it is ready to flash like lightning; it is drawn for slaughter.'),
('EZK', 21, 16, 'EZK.21.16', 'Slash to the right; set your blade to the left—wherever your blade is directed.'),
('EZK', 21, 17, 'EZK.21.17', 'I too will strike My hands together, and I will satisfy My wrath.’ I, the LORD, have spoken.”'),
('EZK', 21, 18, 'EZK.21.18', 'Then the word of the LORD came to me, saying,'),
('EZK', 21, 19, 'EZK.21.19', '“Now you, son of man, mark out two roads for the sword of the king of Babylon to take, both starting from the same land. And make a signpost where the road branches off to each city.'),
('EZK', 21, 20, 'EZK.21.20', 'Mark out one road for the sword to come against Rabbah of the Ammonites, and another against Judah into fortified Jerusalem.'),
('EZK', 21, 21, 'EZK.21.21', 'For the king of Babylon stands at the fork in the road, at the junction of the two roads, to seek an omen: He shakes the arrows, he consults the idols, he examines the liver.'),
('EZK', 21, 22, 'EZK.21.22', 'In his right hand appears the portent for Jerusalem, where he is to set up battering rams, to call for the slaughter, to lift a battle cry, to direct the battering rams against the gates, to build a ramp, and to erect a siege wall.'),
('EZK', 21, 23, 'EZK.21.23', 'It will seem like a false omen to the eyes of those who have sworn allegiance to him, but it will draw attention to their guilt and take them captive.'),
('EZK', 21, 24, 'EZK.21.24', 'Therefore this is what the Lord GOD says: ‘Because you have drawn attention to your guilt, exposing your transgressions, so that your sins are revealed in all your deeds—because you have come to remembrance—you shall be taken in hand.'),
('EZK', 21, 25, 'EZK.21.25', 'And you, O profane and wicked prince of Israel, the day has come for your final punishment.’'),
('EZK', 21, 26, 'EZK.21.26', 'This is what the Lord GOD says: ‘Remove the turban, and take off the crown. Things will not remain as they are: Exalt the lowly and bring low the exalted.'),
('EZK', 21, 27, 'EZK.21.27', 'A ruin, a ruin, I will make it a ruin! And it will not be restored until the arrival of Him to whom it belongs, to whom I have assigned the right of judgment.’'),
('EZK', 21, 28, 'EZK.21.28', 'Now prophesy, son of man, and declare that this is what the Lord GOD says concerning the Ammonites and their contempt: ‘A sword! A sword is drawn for slaughter, polished to consume, to flash like lightning—'),
('EZK', 21, 29, 'EZK.21.29', 'while they offer false visions for you and lying divinations about you—to be placed on the necks of the wicked who are slain, whose day has come, the time of their final punishment.'),
('EZK', 21, 30, 'EZK.21.30', 'Return the sword to its sheath! In the place where you were created, in the land of your origin, I will judge you.'),
('EZK', 21, 31, 'EZK.21.31', 'I will pour out My anger upon you; I will breathe the fire of My fury against you; I will hand you over to brutal men, skilled in destruction.'),
('EZK', 21, 32, 'EZK.21.32', 'You will be fuel for the fire. Your blood will stain your own land. You will not be remembered, for I, the LORD, have spoken.’”'),
('EZK', 22, 1, 'EZK.22.1', 'Then the word of the LORD came to me, saying,'),
('EZK', 22, 2, 'EZK.22.2', '“As for you, son of man, will you judge her? Will you pass judgment on the city of bloodshed? Then confront her with all her abominations'),
('EZK', 22, 3, 'EZK.22.3', 'and tell her that this is what the Lord GOD says: ‘O city who brings her own doom by shedding blood within her walls and making idols to defile herself,'),
('EZK', 22, 4, 'EZK.22.4', 'you are guilty of the blood you have shed, and you are defiled by the idols you have made. You have brought your days to a close and have come to the end of your years. Therefore I have made you a reproach to the nations and a mockery to all the lands.'),
('EZK', 22, 5, 'EZK.22.5', 'Those near and far will mock you, O infamous city, full of turmoil.'),
('EZK', 22, 6, 'EZK.22.6', 'See how every prince of Israel within you has used his power to shed blood.'),
('EZK', 22, 7, 'EZK.22.7', 'Father and mother are treated with contempt. Within your walls the foreign resident is exploited, the fatherless and the widow are oppressed.'),
('EZK', 22, 8, 'EZK.22.8', 'You have despised My holy things and profaned My Sabbaths.'),
('EZK', 22, 9, 'EZK.22.9', 'Among you are slanderous men bent on bloodshed; within you are those who eat on the mountain shrines and commit acts of indecency.'),
('EZK', 22, 10, 'EZK.22.10', 'In you they have uncovered the nakedness of their fathers; in you they violate women during their menstrual impurity.'),
('EZK', 22, 11, 'EZK.22.11', 'One man commits an abomination with his neighbor’s wife; another wickedly defiles his daughter-in-law; and yet another violates his sister, his own father’s daughter.'),
('EZK', 22, 12, 'EZK.22.12', 'In you they take bribes to shed blood. You engage in usury, take excess interest, and extort your neighbors. But Me you have forgotten, declares the Lord GOD.'),
('EZK', 22, 13, 'EZK.22.13', 'Now look, I strike My hands together against your unjust gain and against the blood you have shed in your midst.'),
('EZK', 22, 14, 'EZK.22.14', 'Will your courage endure or your hands be strong in the day I deal with you? I, the LORD, have spoken, and I will act.'),
('EZK', 22, 15, 'EZK.22.15', 'I will disperse you among the nations and scatter you throughout the lands; I will purge your uncleanness.'),
('EZK', 22, 16, 'EZK.22.16', 'And when you have defiled yourself in the eyes of the nations, then you will know that I am the LORD.’”'),
('EZK', 22, 17, 'EZK.22.17', 'Then the word of the LORD came to me, saying,'),
('EZK', 22, 18, 'EZK.22.18', '“Son of man, the house of Israel has become dross to Me. All of them are copper, tin, iron, and lead inside the furnace; they are but the dross of silver.'),
('EZK', 22, 19, 'EZK.22.19', 'Therefore this is what the Lord GOD says: ‘Because all of you have become dross, behold, I will gather you into Jerusalem.'),
('EZK', 22, 20, 'EZK.22.20', 'Just as one gathers silver, copper, iron, lead, and tin into the furnace to melt with a fiery blast, so I will gather you in My anger and wrath, leave you there, and melt you.'),
('EZK', 22, 21, 'EZK.22.21', 'Yes, I will gather you together and blow on you with the fire of My wrath, and you will be melted within the city.'),
('EZK', 22, 22, 'EZK.22.22', 'As silver is melted in a furnace, so you will be melted within the city. Then you will know that I, the LORD, have poured out My wrath upon you.’”'),
('EZK', 22, 23, 'EZK.22.23', 'And the word of the LORD came to me, saying,'),
('EZK', 22, 24, 'EZK.22.24', '“Son of man, say to her, ‘In the day of indignation, you are a land that has not been cleansed, upon which no rain has fallen.’'),
('EZK', 22, 25, 'EZK.22.25', 'The conspiracy of the princes in her midst is like a roaring lion tearing its prey. They devour the people, seize the treasures and precious things, and multiply the widows within her.'),
('EZK', 22, 26, 'EZK.22.26', 'Her priests do violence to My law and profane My holy things. They make no distinction between the holy and the common, and they fail to distinguish between the clean and the unclean. They disregard My Sabbaths, so that I am profaned among them.'),
('EZK', 22, 27, 'EZK.22.27', 'Her officials within her are like wolves tearing their prey, shedding blood, and destroying lives for dishonest gain.'),
('EZK', 22, 28, 'EZK.22.28', 'Her prophets whitewash these deeds by false visions and lying divinations, saying, ‘This is what the Lord GOD says,’ when the LORD has not spoken.'),
('EZK', 22, 29, 'EZK.22.29', 'The people of the land have practiced extortion and committed robbery. They have oppressed the poor and needy and have exploited the foreign resident without justice.'),
('EZK', 22, 30, 'EZK.22.30', 'I searched for a man among them to repair the wall and stand in the gap before Me on behalf of the land, so that I should not destroy it. But I found no one.'),
('EZK', 22, 31, 'EZK.22.31', 'So I have poured out My indignation upon them and consumed them with the fire of My fury. I have brought their ways down upon their own heads, declares the Lord GOD.”'),
('EZK', 23, 1, 'EZK.23.1', 'Again the word of the LORD came to me, saying,'),
('EZK', 23, 2, 'EZK.23.2', '“Son of man, there were two women, daughters of the same mother,'),
('EZK', 23, 3, 'EZK.23.3', 'and they played in Egypt, prostituting themselves from their youth. Their breasts were fondled there, and their virgin bosoms caressed.'),
('EZK', 23, 4, 'EZK.23.4', 'The older was named Oholah, and her sister was named Oholibah. They became Mine and gave birth to sons and daughters. As for their identities, Oholah is Samaria, and Oholibah is Jerusalem.'),
('EZK', 23, 5, 'EZK.23.5', 'Oholah prostituted herself while she was still Mine. She lusted after her lovers, the Assyrians—warriors'),
('EZK', 23, 6, 'EZK.23.6', 'clothed in blue, governors and commanders, all desirable young men, horsemen mounted on steeds.'),
('EZK', 23, 7, 'EZK.23.7', 'She offered sexual favors to all the elite of Assyria. She defiled herself with all the idols of those for whom she lusted.'),
('EZK', 23, 8, 'EZK.23.8', 'She did not give up the prostitution she began in Egypt, when men slept with her in her youth, caressed her virgin bosom, and poured out their lust upon her.'),
('EZK', 23, 9, 'EZK.23.9', 'Therefore I delivered her into the hands of her lovers, the Assyrians for whom she lusted.'),
('EZK', 23, 10, 'EZK.23.10', 'They exposed her nakedness, seized her sons and daughters, and put her to the sword. Thus she became a byword among women, and they executed judgment against her.'),
('EZK', 23, 11, 'EZK.23.11', 'Her sister Oholibah saw this, yet in her lust and prostitution she was more depraved than her sister.'),
('EZK', 23, 12, 'EZK.23.12', 'She too lusted after the Assyrians—governors and commanders, warriors dressed in splendor, horsemen riding on steeds, all desirable young men.'),
('EZK', 23, 13, 'EZK.23.13', 'And I saw that she too had defiled herself; both of them had taken the same path.'),
('EZK', 23, 14, 'EZK.23.14', 'But Oholibah carried her prostitution even further. She saw the men portrayed on the wall, images of the Chaldeans, engraved in vermilion,'),
('EZK', 23, 15, 'EZK.23.15', 'wearing belts on their waists and flowing turbans on their heads; all of them looked like officers of the Babylonians in Chaldea, the land of their birth.'),
('EZK', 23, 16, 'EZK.23.16', 'At the sight of them, she lusted for them and sent messengers to them in Chaldea.'),
('EZK', 23, 17, 'EZK.23.17', 'Then the Babylonians came to her, to the bed of love, and in their lust they defiled her. But after she had been defiled by them, she turned away in disgust.'),
('EZK', 23, 18, 'EZK.23.18', 'When Oholibah openly prostituted herself and exposed her nakedness, I turned away from her in disgust, just as I had turned away from her sister.'),
('EZK', 23, 19, 'EZK.23.19', 'Yet she multiplied her promiscuity, remembering the days of her youth, when she had prostituted herself in the land of Egypt'),
('EZK', 23, 20, 'EZK.23.20', 'and lusted after their lovers, whose genitals were like those of donkeys and whose emission was like that of stallions.'),
('EZK', 23, 21, 'EZK.23.21', 'So you revisited the indecency of your youth, when the Egyptians caressed your bosom and pressed your young breasts.'),
('EZK', 23, 22, 'EZK.23.22', 'Therefore, Oholibah, this is what the Lord GOD says: ‘I will incite your lovers against you, those from whom you turned away in disgust. And I will bring them against you from every side—'),
('EZK', 23, 23, 'EZK.23.23', 'the Babylonians and all the Chaldeans, the men of Pekod, Shoa, and Koa, and all the Assyrians with them—all desirable young men, governors and commanders, officers and men of renown, mounted on horses.'),
('EZK', 23, 24, 'EZK.23.24', 'They will come against you with a host of peoples, with weapons, chariots, and wagons. They will array themselves against you on every side with buckler and shield and helmet. I will delegate judgment to them, and they will punish you according to their own standards.'),
('EZK', 23, 25, 'EZK.23.25', 'And I will set My jealous rage against you, and they will deal with you in fury. They will cut off your noses and ears, and your survivors will fall by the sword. They will seize your sons and daughters, and your remnant will be consumed by fire.'),
('EZK', 23, 26, 'EZK.23.26', 'They will strip off your clothes and take your fine jewelry.'),
('EZK', 23, 27, 'EZK.23.27', 'So I will put an end to your indecency and prostitution, which began in the land of Egypt, and you will not lift your eyes to them or remember Egypt anymore.’'),
('EZK', 23, 28, 'EZK.23.28', 'For this is what the Lord GOD says: ‘Surely I will deliver you into the hands of those you hate, from whom you turned away in disgust.'),
('EZK', 23, 29, 'EZK.23.29', 'They will treat you with hatred, take all for which you have worked, and leave you naked and bare, so that the shame of your prostitution will be exposed. Your indecency and promiscuity'),
('EZK', 23, 30, 'EZK.23.30', 'have brought these things upon you, because you have prostituted yourself with the nations and defiled yourself with their idols.'),
('EZK', 23, 31, 'EZK.23.31', 'Because you have followed the path of your sister, I will put her cup into your hand.’'),
('EZK', 23, 32, 'EZK.23.32', 'This is what the Lord GOD says: ‘You will drink your sister’s cup, a cup deep and wide. It will bring scorn and derision, for it holds so much.'),
('EZK', 23, 33, 'EZK.23.33', 'You will be filled with drunkenness and grief, with a cup of devastation and desolation, the cup of your sister Samaria.'),
('EZK', 23, 34, 'EZK.23.34', 'You will drink it and drain it; you will dash it to pieces, and tear your breasts. For I have spoken,’ declares the Lord GOD.'),
('EZK', 23, 35, 'EZK.23.35', 'Therefore this is what the Lord GOD says: ‘Because you have forgotten Me and have cast Me behind your back, you must bear the consequences of your indecency and prostitution.’”'),
('EZK', 23, 36, 'EZK.23.36', 'Then the LORD said to me: “Son of man, will you pass judgment against Oholah and Oholibah? Then declare to them their abominations.'),
('EZK', 23, 37, 'EZK.23.37', 'For they have committed adultery, and blood is on their hands. They have committed adultery with their idols. They have even sacrificed their children, whom they bore to Me, in the fire as food for their idols.'),
('EZK', 23, 38, 'EZK.23.38', 'They have also done this to Me: On that very same day, they defiled My sanctuary and profaned My Sabbaths.'),
('EZK', 23, 39, 'EZK.23.39', 'On the very day they slaughtered their children for their idols, they entered My sanctuary to profane it. Yes, they did this inside My house.'),
('EZK', 23, 40, 'EZK.23.40', 'Furthermore, you sisters sent messengers for men who came from afar; and behold, when they arrived, you bathed for them, painted your eyes, and adorned yourself with jewelry.'),
('EZK', 23, 41, 'EZK.23.41', 'You sat on a couch of luxury with a table spread before it, on which you had set My incense and My oil,'),
('EZK', 23, 42, 'EZK.23.42', 'accompanied by the sound of a carefree crowd. Drunkards were brought in from the desert along with men from the rabble, who put bracelets on your wrists and beautiful crowns on your head.'),
('EZK', 23, 43, 'EZK.23.43', 'Then I said of her who had grown old in adulteries: ‘Now let them use her as a prostitute, for that is all she is!’'),
('EZK', 23, 44, 'EZK.23.44', 'And they slept with her as with a prostitute; they slept with Oholah and Oholibah, those lewd women.'),
('EZK', 23, 45, 'EZK.23.45', 'But righteous men will sentence them to the punishment of those who commit adultery and bloodshed, because they are adulteresses with blood on their hands.'),
('EZK', 23, 46, 'EZK.23.46', 'This is what the Lord GOD says: ‘Bring a mob against them and consign them to terror and plunder.'),
('EZK', 23, 47, 'EZK.23.47', 'The mob will stone them and cut them down with their swords. They will kill their sons and daughters and burn down their houses.'),
('EZK', 23, 48, 'EZK.23.48', 'So I will put an end to indecency in the land, and all the women will be admonished not to imitate your behavior.'),
('EZK', 23, 49, 'EZK.23.49', 'They will repay you for your indecency, and you will bear the consequences of your sins of idolatry. Then you will know that I am the Lord GOD.’”'),
('EZK', 24, 1, 'EZK.24.1', 'In the ninth year, on the tenth day of the tenth month, the word of the LORD came to me, saying,'),
('EZK', 24, 2, 'EZK.24.2', '“Son of man, write down today’s date, for on this very day the king of Babylon has laid siege to Jerusalem.'),
('EZK', 24, 3, 'EZK.24.3', 'Now speak a parable to this rebellious house and tell them that this is what the Lord GOD says: ‘Put the pot on the fire; put it on and pour in the water.'),
('EZK', 24, 4, 'EZK.24.4', 'Put in the pieces of meat, every good piece—thigh and shoulder—fill it with choice bones.'),
('EZK', 24, 5, 'EZK.24.5', 'Take the choicest of the flock and pile the fuel beneath it. Bring it to a boil and cook the bones in it.’'),
('EZK', 24, 6, 'EZK.24.6', 'Therefore this is what the Lord GOD says: ‘Woe to the city of bloodshed, to the pot now rusted, whose rust will not come off! Empty it piece by piece; cast no lots for its contents.'),
('EZK', 24, 7, 'EZK.24.7', 'For the blood she shed is still within her; she poured it out on the bare rock; she did not pour it on the ground to cover it with dust.'),
('EZK', 24, 8, 'EZK.24.8', 'In order to stir up wrath and take vengeance, I have placed her blood on the bare rock, so that it would not be covered.’'),
('EZK', 24, 9, 'EZK.24.9', 'Yes, this is what the Lord GOD says: ‘Woe to the city of bloodshed! I, too, will pile the kindling high.'),
('EZK', 24, 10, 'EZK.24.10', 'Pile on the logs and kindle the fire; cook the meat well and mix in the spices; let the bones be burned.'),
('EZK', 24, 11, 'EZK.24.11', 'Set the empty pot on its coals until it becomes hot and its copper glows. Then its impurity will melt within; its rust will be consumed.'),
('EZK', 24, 12, 'EZK.24.12', 'It has frustrated every effort; its thick rust has not been removed, even by the fire.'),
('EZK', 24, 13, 'EZK.24.13', 'Because of the indecency of your uncleanness I tried to cleanse you, but you would not be purified from your filthiness. You will not be pure again until My wrath against you has subsided.'),
('EZK', 24, 14, 'EZK.24.14', 'I, the LORD, have spoken; the time is coming, and I will act. I will not refrain or show pity, nor will I relent. I will judge you according to your ways and deeds,’ declares the Lord GOD.”'),
('EZK', 24, 15, 'EZK.24.15', 'Then the word of the LORD came to me, saying,'),
('EZK', 24, 16, 'EZK.24.16', '“Son of man, behold, I am about to take away the desire of your eyes with a fatal blow. But you must not mourn or weep or let your tears flow.'),
('EZK', 24, 17, 'EZK.24.17', 'Groan quietly; do not mourn for the dead. Put on your turban and strap your sandals on your feet; do not cover your lips or eat the bread of mourners.”'),
('EZK', 24, 18, 'EZK.24.18', 'So I spoke to the people in the morning, and in the evening my wife died. And the next morning I did as I had been commanded.'),
('EZK', 24, 19, 'EZK.24.19', 'Then the people asked me, “Won’t you tell us what these things you are doing mean to us?”'),
('EZK', 24, 20, 'EZK.24.20', 'So I answered them, “The word of the LORD came to me, saying:'),
('EZK', 24, 21, 'EZK.24.21', 'Tell the house of Israel that this is what the Lord GOD says: ‘I am about to desecrate My sanctuary, the pride of your power, the desire of your eyes, and the delight of your soul. And the sons and daughters you left behind will fall by the sword.’'),
('EZK', 24, 22, 'EZK.24.22', 'Then you will do as I have done: You will not cover your lips or eat the bread of mourners.'),
('EZK', 24, 23, 'EZK.24.23', 'Your turbans will remain on your heads and your sandals on your feet. You will not mourn or weep, but you will waste away because of your sins, and you will groan among yourselves.'),
('EZK', 24, 24, 'EZK.24.24', '‘Thus Ezekiel will be a sign for you; you will do everything that he has done. When this happens, you will know that I am the Lord GOD.’'),
('EZK', 24, 25, 'EZK.24.25', 'And you, son of man, know that on the day I take away their stronghold, their pride and joy—the desire of their eyes which uplifted their souls—and their sons and daughters as well,'),
('EZK', 24, 26, 'EZK.24.26', 'on that day a fugitive will come and tell you the news.'),
('EZK', 24, 27, 'EZK.24.27', 'On that day your mouth will be opened to him who has escaped; you will speak and no longer be mute. So you will be a sign to them, and they will know that I am the LORD.”'),
('EZK', 25, 1, 'EZK.25.1', 'Then the word of the LORD came to me, saying,'),
('EZK', 25, 2, 'EZK.25.2', '“Son of man, set your face against the Ammonites and prophesy against them.'),
('EZK', 25, 3, 'EZK.25.3', 'Tell the Ammonites to hear the word of the Lord GOD, for this is what the Lord GOD says: ‘Because you exclaimed, “Aha!” when My sanctuary was profaned, when the land of Israel was laid waste, and when the house of Judah went into exile,'),
('EZK', 25, 4, 'EZK.25.4', 'therefore I will indeed give you as a possession to the people of the East. They will set up their camps and pitch their tents among you. They will eat your fruit and drink your milk.'),
('EZK', 25, 5, 'EZK.25.5', 'I will make Rabbah a pasture for camels, and Ammon a resting place for sheep. Then you will know that I am the LORD.’'),
('EZK', 25, 6, 'EZK.25.6', 'For this is what the Lord GOD says: ‘Because you clapped your hands and stomped your feet and rejoiced over the land of Israel with a heart full of contempt,'),
('EZK', 25, 7, 'EZK.25.7', 'therefore I will indeed stretch out My hand against you and give you as plunder to the nations. I will cut you off from the peoples and exterminate you from the countries. I will destroy you, and you will know that I am the LORD.’'),
('EZK', 25, 8, 'EZK.25.8', 'This is what the Lord GOD says: ‘Because Moab and Seir said, “Look, the house of Judah is like all the other nations,”'),
('EZK', 25, 9, 'EZK.25.9', 'therefore I will indeed expose the flank of Moab beginning with its frontier cities—Beth-jeshimoth, Baal-meon, and Kiriathaim—the glory of the land.'),
('EZK', 25, 10, 'EZK.25.10', 'I will give it along with the Ammonites as a possession to the people of the East, so that the Ammonites will no longer be remembered among the nations.'),
('EZK', 25, 11, 'EZK.25.11', 'So I will execute judgments on Moab, and they will know that I am the LORD.’'),
('EZK', 25, 12, 'EZK.25.12', 'This is what the Lord GOD says: ‘Because Edom acted vengefully against the house of Judah, and in so doing incurred grievous guilt,'),
('EZK', 25, 13, 'EZK.25.13', 'therefore this is what the Lord GOD says: I will stretch out My hand against Edom and cut off from it both man and beast. I will make it a wasteland, and from Teman to Dedan they will fall by the sword.'),
('EZK', 25, 14, 'EZK.25.14', 'I will take My vengeance on Edom by the hand of My people Israel, and they will deal with Edom according to My anger and wrath. Then they will know My vengeance, declares the Lord GOD.’'),
('EZK', 25, 15, 'EZK.25.15', 'This is what the Lord GOD says: ‘Because the Philistines acted in vengeance, taking vengeance with malice of soul to destroy Judah with ancient hostility,'),
('EZK', 25, 16, 'EZK.25.16', 'therefore this is what the Lord GOD says: Behold, I will stretch out My hand against the Philistines, and I will cut off the Cherethites and destroy the remnant along the coast.'),
('EZK', 25, 17, 'EZK.25.17', 'I will execute great vengeance against them with furious reproof. Then they will know that I am the LORD, when I lay My vengeance upon them.’”'),
('EZK', 26, 1, 'EZK.26.1', 'In the eleventh month of the twelfth year, on the first day of the month, the word of the LORD came to me, saying,'),
('EZK', 26, 2, 'EZK.26.2', '“Son of man, because Tyre has said of Jerusalem, ‘Aha! The gate to the nations is broken; it has swung open to me; now that she lies in ruins I will be filled,’'),
('EZK', 26, 3, 'EZK.26.3', 'therefore this is what the Lord GOD says: ‘Behold, O Tyre, I am against you, and I will raise up many nations against you, as the sea brings up its waves.'),
('EZK', 26, 4, 'EZK.26.4', 'They will destroy the walls of Tyre and demolish her towers. I will scrape the soil from her and make her a bare rock.'),
('EZK', 26, 5, 'EZK.26.5', 'She will become a place to spread nets in the sea, for I have spoken, declares the Lord GOD. She will become plunder for the nations,'),
('EZK', 26, 6, 'EZK.26.6', 'and the villages on her mainland will be slain by the sword. Then they will know that I am the LORD.’'),
('EZK', 26, 7, 'EZK.26.7', 'For this is what the Lord GOD says: ‘Behold, I will bring against Tyre from the north Nebuchadnezzar king of Babylon, king of kings, with horses and chariots, with cavalry and a great company of troops.'),
('EZK', 26, 8, 'EZK.26.8', 'He will slaughter the villages of your mainland with the sword; he will set up siege works against you, build a ramp to your walls, and raise his shields against you.'),
('EZK', 26, 9, 'EZK.26.9', 'He will direct the blows of his battering rams against your walls and tear down your towers with his axes.'),
('EZK', 26, 10, 'EZK.26.10', 'His multitude of horses will cover you in their dust. When he enters your gates as an army entering a breached city, your walls will shake from the noise of cavalry, wagons, and chariots.'),
('EZK', 26, 11, 'EZK.26.11', 'The hooves of his horses will trample all your streets. He will slaughter your people with the sword, and your mighty pillars will fall to the ground.'),
('EZK', 26, 12, 'EZK.26.12', 'They will plunder your wealth and pillage your merchandise. They will demolish your walls, tear down your beautiful homes, and throw your stones and timber and soil into the water.'),
('EZK', 26, 13, 'EZK.26.13', 'So I will silence the sound of your songs, and the music of your lyres will no longer be heard.'),
('EZK', 26, 14, 'EZK.26.14', 'I will make you a bare rock, and you will become a place to spread the fishing nets. You will never be rebuilt, for I, the LORD, have spoken, declares the Lord GOD.’'),
('EZK', 26, 15, 'EZK.26.15', 'This is what the Lord GOD says to Tyre: ‘Will not the coastlands quake at the sound of your downfall, when the wounded groan at the slaughter in your midst?'),
('EZK', 26, 16, 'EZK.26.16', 'All the princes of the sea will descend from their thrones, remove their robes, and strip off their embroidered garments. Clothed with terror, they will sit on the ground, trembling every moment, appalled over you.'),
('EZK', 26, 17, 'EZK.26.17', 'Then they will lament for you, saying, “How you have perished, O city of renown inhabited by seafaring men—she who was powerful on the sea, along with her people, who imposed terror on all peoples!'),
('EZK', 26, 18, 'EZK.26.18', 'Now the coastlands tremble on the day of your downfall; the islands in the sea are dismayed by your demise.”’'),
('EZK', 26, 19, 'EZK.26.19', 'For this is what the Lord GOD says: ‘When I make you a desolate city like other deserted cities, and when I raise up the deep against you so that the mighty waters cover you,'),
('EZK', 26, 20, 'EZK.26.20', 'then I will bring you down with those who descend to the Pit, to the people of antiquity. I will make you dwell in the earth below like the ancient ruins, with those who descend to the Pit, so that you will no longer be inhabited or set in splendor in the land of the living.'),
('EZK', 26, 21, 'EZK.26.21', 'I will make you an object of horror, and you will be no more. You will be sought, but will never be found,’ declares the Lord GOD.”'),
('EZK', 27, 1, 'EZK.27.1', 'Then the word of the LORD came to me, saying,'),
('EZK', 27, 2, 'EZK.27.2', '“Now you, son of man, take up a lament for Tyre.'),
('EZK', 27, 3, 'EZK.27.3', 'Tell Tyre, who dwells at the gateway to the sea, merchant of the peoples on many coasts, that this is what the Lord GOD says: You have said, O Tyre, ‘I am perfect in beauty.’'),
('EZK', 27, 4, 'EZK.27.4', 'Your borders are in the heart of the seas; your builders perfected your beauty.'),
('EZK', 27, 5, 'EZK.27.5', 'They constructed all your planking with cypress from Senir. They took a cedar from Lebanon to make a mast for you.'),
('EZK', 27, 6, 'EZK.27.6', 'Of oaks from Bashan they made your oars; of wood from the coasts of Cyprus they made your deck, inlaid with ivory.'),
('EZK', 27, 7, 'EZK.27.7', 'Of embroidered fine linen from Egypt they made your sail, which served as your banner. Of blue and purple from the coasts of Elishah they made your awning.'),
('EZK', 27, 8, 'EZK.27.8', 'The men of Sidon and Arvad were your oarsmen. Your men of skill, O Tyre, were there as your captains.'),
('EZK', 27, 9, 'EZK.27.9', 'The elders of Gebal were aboard as shipwrights, repairing your leaks. All the ships of the sea and their sailors came alongside to barter for your merchandise.'),
('EZK', 27, 10, 'EZK.27.10', 'Men of Persia, Lydia, and Put served as warriors in your army. They hung their shields and helmets on your walls; they gave you splendor.'),
('EZK', 27, 11, 'EZK.27.11', 'Men of Arvad and Helech manned your walls all around, and the men of Gammad were in your towers. They hung their shields around your walls; they perfected your beauty.'),
('EZK', 27, 12, 'EZK.27.12', 'Tarshish was your merchant because of your great wealth of goods; they exchanged silver, iron, tin, and lead for your wares.'),
('EZK', 27, 13, 'EZK.27.13', 'Javan, Tubal, and Meshech were your merchants. They exchanged slaves and bronze utensils for your merchandise.'),
('EZK', 27, 14, 'EZK.27.14', 'The men of Beth-togarmah exchanged horses, war horses, and mules for your wares.'),
('EZK', 27, 15, 'EZK.27.15', 'The men of Dedan were your clients; many coastlands were your market; they paid you with ivory tusks and ebony.'),
('EZK', 27, 16, 'EZK.27.16', 'Aram was your customer because of your many products; they exchanged turquoise, purple, embroidered work, fine linen, coral, and rubies for your wares.'),
('EZK', 27, 17, 'EZK.27.17', 'Judah and the land of Israel traded with you; they exchanged wheat from Minnith, cakes and honey, oil and balm for your merchandise.'),
('EZK', 27, 18, 'EZK.27.18', 'Because of your many products and your great wealth of goods, Damascus traded with you wine from Helbon, wool from Zahar,'),
('EZK', 27, 19, 'EZK.27.19', 'and casks of wine from Izal for your wares. Wrought iron, cassia, and sweet cane were exchanged for your merchandise.'),
('EZK', 27, 20, 'EZK.27.20', 'Dedan was your merchant in saddlecloths for riding.'),
('EZK', 27, 21, 'EZK.27.21', 'Arabia and all the princes of Kedar were your customers, trading in lambs, rams, and goats.'),
('EZK', 27, 22, 'EZK.27.22', 'The merchants of Sheba and Raamah traded with you; for your wares they exchanged gold, the finest of all spices, and precious stones.'),
('EZK', 27, 23, 'EZK.27.23', 'Haran, Canneh, and Eden traded with you, and so did the merchants of Sheba, Asshur, and Chilmad.'),
('EZK', 27, 24, 'EZK.27.24', 'In your marketplace they traded with you fine garments of blue, embroidered work, and multicolored rugs with cords tightly twisted and knotted.'),
('EZK', 27, 25, 'EZK.27.25', 'The ships of Tarshish carried your merchandise. And you were filled with heavy cargo in the heart of the sea.'),
('EZK', 27, 26, 'EZK.27.26', 'Your oarsmen have brought you onto the high seas, but the east wind will shatter you in the heart of the sea.'),
('EZK', 27, 27, 'EZK.27.27', 'Your wealth, wares, and merchandise, your sailors, captains, and shipwrights, your merchants and all the warriors within you, with all the other people on board, will sink into the heart of the sea on the day of your downfall.'),
('EZK', 27, 28, 'EZK.27.28', 'The countryside will shake when your sailors cry out.'),
('EZK', 27, 29, 'EZK.27.29', 'All who handle the oars will abandon their ships. The sailors and all the captains of the sea will stand on the shore.'),
('EZK', 27, 30, 'EZK.27.30', 'They will raise their voices for you and cry out bitterly. They will throw dust on their heads and roll in ashes.'),
('EZK', 27, 31, 'EZK.27.31', 'They will shave their heads for you and wrap themselves in sackcloth. They will weep over you with anguish of soul and bitter mourning.'),
('EZK', 27, 32, 'EZK.27.32', 'As they wail and mourn over you, they will take up a lament for you: ‘Who was ever like Tyre, silenced in the middle of the sea?'),
('EZK', 27, 33, 'EZK.27.33', 'When your wares went out to sea, you satisfied many nations. You enriched the kings of the earth with your abundant wealth and merchandise.'),
('EZK', 27, 34, 'EZK.27.34', 'Now you are shattered by the seas in the depths of the waters; your merchandise and the people among you have gone down with you.'),
('EZK', 27, 35, 'EZK.27.35', 'All the people of the coastlands are appalled over you. Their kings shudder with fear; their faces are contorted.'),
('EZK', 27, 36, 'EZK.27.36', 'Those who trade among the nations hiss at you; you have come to a horrible end and will be no more.’”'),
('EZK', 28, 1, 'EZK.28.1', 'And the word of the LORD came to me, saying,'),
('EZK', 28, 2, 'EZK.28.2', '“Son of man, tell the ruler of Tyre that this is what the Lord GOD says: Your heart is proud, and you have said, ‘I am a god; I sit in the seat of gods in the heart of the sea.’ Yet you are a man and not a god, though you have regarded your heart as that of a god.'),
('EZK', 28, 3, 'EZK.28.3', 'Behold, you are wiser than Daniel; no secret is hidden from you!'),
('EZK', 28, 4, 'EZK.28.4', 'By your wisdom and understanding you have gained your wealth and amassed gold and silver for your treasuries.'),
('EZK', 28, 5, 'EZK.28.5', 'By your great skill in trading you have increased your wealth, but your heart has grown proud because of it.'),
('EZK', 28, 6, 'EZK.28.6', 'Therefore this is what the Lord GOD says: Because you regard your heart as the heart of a god,'),
('EZK', 28, 7, 'EZK.28.7', 'behold, I will bring foreigners against you, the most ruthless of nations. They will draw their swords against the beauty of your wisdom and will defile your splendor.'),
('EZK', 28, 8, 'EZK.28.8', 'They will bring you down to the Pit, and you will die a violent death in the heart of the seas.'),
('EZK', 28, 9, 'EZK.28.9', 'Will you still say, ‘I am a god,’ in the presence of those who slay you? You will be only a man, not a god, in the hands of those who wound you.'),
('EZK', 28, 10, 'EZK.28.10', 'You will die the death of the uncircumcised at the hands of foreigners. For I have spoken, declares the Lord GOD.”'),
('EZK', 28, 11, 'EZK.28.11', 'Again the word of the LORD came to me, saying,'),
('EZK', 28, 12, 'EZK.28.12', '“Son of man, take up a lament for the king of Tyre and tell him that this is what the Lord GOD says: ‘You were the seal of perfection, full of wisdom and perfect in beauty.'),
('EZK', 28, 13, 'EZK.28.13', 'You were in Eden, the garden of God. Every kind of precious stone adorned you: ruby, topaz, and diamond, beryl, onyx, and jasper, sapphire, turquoise, and emerald. Your mountings and settings were crafted in gold, prepared on the day of your creation.'),
('EZK', 28, 14, 'EZK.28.14', 'You were anointed as a guardian cherub, for I had ordained you. You were on the holy mountain of God; you walked among the fiery stones.'),
('EZK', 28, 15, 'EZK.28.15', 'From the day you were created you were blameless in your ways—until wickedness was found in you.'),
('EZK', 28, 16, 'EZK.28.16', 'By the vastness of your trade, you were filled with violence, and you sinned. So I drove you in disgrace from the mountain of God, and I banished you, O guardian cherub, from among the fiery stones.'),
('EZK', 28, 17, 'EZK.28.17', 'Your heart grew proud of your beauty; you corrupted your wisdom because of your splendor; so I cast you to the earth; I made you a spectacle before kings.'),
('EZK', 28, 18, 'EZK.28.18', 'By the multitude of your iniquities and the dishonesty of your trading you have profaned your sanctuaries. So I made fire come from within you, and it consumed you. I reduced you to ashes on the ground in the eyes of all who saw you.'),
('EZK', 28, 19, 'EZK.28.19', 'All the nations who know you are appalled over you. You have come to a horrible end and will be no more.’”'),
('EZK', 28, 20, 'EZK.28.20', 'Then the word of the LORD came to me, saying,'),
('EZK', 28, 21, 'EZK.28.21', '“Son of man, set your face against Sidon and prophesy against her.'),
('EZK', 28, 22, 'EZK.28.22', 'And you are to declare that this is what the Lord GOD says: ‘Behold, I am against you, O Sidon, and I will be glorified within you. They will know that I am the LORD when I execute judgments against her and demonstrate My holiness through her.'),
('EZK', 28, 23, 'EZK.28.23', 'I will send a plague against her and shed blood in her streets; the slain will fall within her, while the sword is against her on every side. Then they will know that I am the LORD.'),
('EZK', 28, 24, 'EZK.28.24', 'For the people of Israel will no longer face a pricking brier or a painful thorn from all around them who treat them with contempt. Then they will know that I am the Lord GOD.’'),
('EZK', 28, 25, 'EZK.28.25', 'This is what the Lord GOD says: ‘When I gather the house of Israel from the peoples among whom they have been scattered, I will show Myself holy among them in the sight of the nations. Then they will dwell in their own land, which I have given to My servant Jacob.'),
('EZK', 28, 26, 'EZK.28.26', 'And there they will dwell securely, build houses, and plant vineyards. They will dwell securely when I execute judgments against all those around them who treat them with contempt. Then they will know that I am the LORD their God.’”'),
('EZK', 29, 1, 'EZK.29.1', 'In the tenth year, on the twelfth day of the tenth month, the word of the LORD came to me, saying,'),
('EZK', 29, 2, 'EZK.29.2', '“Son of man, set your face against Pharaoh king of Egypt and prophesy against him and against all Egypt.'),
('EZK', 29, 3, 'EZK.29.3', 'Speak to him and tell him that this is what the Lord GOD says: Behold, I am against you, O Pharaoh king of Egypt, O great monster who lies among his rivers, who says, ‘The Nile is mine; I made it myself.’'),
('EZK', 29, 4, 'EZK.29.4', 'But I will put hooks in your jaws and cause the fish of your streams to cling to your scales. I will haul you up out of your rivers, and all the fish of your streams will cling to your scales.'),
('EZK', 29, 5, 'EZK.29.5', 'I will leave you in the desert, you and all the fish of your streams. You will fall on the open field and will not be taken away or gathered for burial. I have given you as food to the beasts of the earth and the birds of the air.'),
('EZK', 29, 6, 'EZK.29.6', 'Then all the people of Egypt will know that I am the LORD. For you were only a staff of reeds to the house of Israel.'),
('EZK', 29, 7, 'EZK.29.7', 'When Israel took hold of you with their hands, you splintered, tearing all their shoulders; when they leaned on you, you broke, and their backs were wrenched.'),
('EZK', 29, 8, 'EZK.29.8', 'Therefore this is what the Lord GOD says: I will bring a sword against you and cut off from you man and beast.'),
('EZK', 29, 9, 'EZK.29.9', 'The land of Egypt will become a desolate wasteland. Then they will know that I am the LORD. Because you said, ‘The Nile is mine; I made it,’'),
('EZK', 29, 10, 'EZK.29.10', 'therefore I am against you and against your rivers. I will turn the land of Egypt into a ruin, a desolate wasteland from Migdol to Syene, and as far as the border of Cush.'),
('EZK', 29, 11, 'EZK.29.11', 'No foot of man or beast will pass through, and it will be uninhabited for forty years.'),
('EZK', 29, 12, 'EZK.29.12', 'I will make the land of Egypt a desolation among desolate lands, and her cities will lie desolate for forty years among the ruined cities. And I will disperse the Egyptians among the nations and scatter them throughout the countries.'),
('EZK', 29, 13, 'EZK.29.13', 'For this is what the Lord GOD says: At the end of forty years I will gather the Egyptians from the nations to which they were scattered.'),
('EZK', 29, 14, 'EZK.29.14', 'I will restore Egypt from captivity and bring them back to the land of Pathros, the land of their origin. There they will be a lowly kingdom.'),
('EZK', 29, 15, 'EZK.29.15', 'Egypt will be the lowliest of kingdoms and will never again exalt itself above the nations. For I will diminish Egypt so that it will never again rule over the nations.'),
('EZK', 29, 16, 'EZK.29.16', 'Egypt will never again be an object of trust for the house of Israel, but will remind them of their iniquity in turning to the Egyptians. Then they will know that I am the Lord GOD.”'),
('EZK', 29, 17, 'EZK.29.17', 'In the twenty-seventh year, on the first day of the first month, the word of the LORD came to me, saying,'),
('EZK', 29, 18, 'EZK.29.18', '“Son of man, Nebuchadnezzar king of Babylon caused his army to labor strenuously against Tyre. Every head was made bald and every shoulder made raw. But he and his army received no wages from Tyre for the labor they expended on it.'),
('EZK', 29, 19, 'EZK.29.19', 'Therefore this is what the Lord GOD says: I will give the land of Egypt to Nebuchadnezzar king of Babylon, who will carry off its wealth, seize its spoil, and remove its plunder. This will be the wages for his army.'),
('EZK', 29, 20, 'EZK.29.20', 'I have given him the land of Egypt as the reward for his labor, because it was done for Me, declares the Lord GOD.'),
('EZK', 29, 21, 'EZK.29.21', 'In that day I will cause a horn to sprout for the house of Israel, and I will open your mouth to speak among them. Then they will know that I am the LORD.”'),
('EZK', 30, 1, 'EZK.30.1', 'Again the word of the LORD came to me, saying,'),
('EZK', 30, 2, 'EZK.30.2', '“Son of man, prophesy and declare that this is what the Lord GOD says: Wail, ‘Alas for that day!’'),
('EZK', 30, 3, 'EZK.30.3', 'For the day is near, the Day of the LORD is near. It will be a day of clouds, a time of doom for the nations.'),
('EZK', 30, 4, 'EZK.30.4', 'A sword will come against Egypt, and there will be anguish in Cush when the slain fall in Egypt, its wealth is taken away, and its foundations are torn down.'),
('EZK', 30, 5, 'EZK.30.5', 'Cush, Put, and Lud, and all the various peoples, as well as Libya and the men of the covenant land, will fall with Egypt by the sword.'),
('EZK', 30, 6, 'EZK.30.6', 'For this is what the LORD says: The allies of Egypt will fall, and her proud strength will collapse. From Migdol to Syene they will fall by the sword within her, declares the Lord GOD.'),
('EZK', 30, 7, 'EZK.30.7', 'They will be desolate among desolate lands, and their cities will lie among ruined cities.'),
('EZK', 30, 8, 'EZK.30.8', 'Then they will know that I am the LORD when I set fire to Egypt and all her helpers are shattered.'),
('EZK', 30, 9, 'EZK.30.9', 'On that day messengers will go out from Me in ships to frighten Cush out of complacency. Anguish will come upon them on the day of Egypt’s doom. For it is indeed coming.'),
('EZK', 30, 10, 'EZK.30.10', 'This is what the Lord GOD says: I will put an end to the hordes of Egypt by the hand of Nebuchadnezzar king of Babylon.'),
('EZK', 30, 11, 'EZK.30.11', 'He and his people with him, the most ruthless of the nations, will be brought in to destroy the land. They will draw their swords against Egypt and fill the land with the slain.'),
('EZK', 30, 12, 'EZK.30.12', 'I will make the streams dry up and sell the land to the wicked. By the hands of foreigners I will bring desolation upon the land and everything in it. I, the LORD, have spoken.'),
('EZK', 30, 13, 'EZK.30.13', 'This is what the Lord GOD says: I will destroy the idols and put an end to the images in Memphis. There will no longer be a prince in Egypt, and I will instill fear in that land.'),
('EZK', 30, 14, 'EZK.30.14', 'I will lay waste Pathros, set fire to Zoan, and execute judgment on Thebes.'),
('EZK', 30, 15, 'EZK.30.15', 'I will pour out My wrath on Pelusium, the stronghold of Egypt, and cut off the crowds of Thebes.'),
('EZK', 30, 16, 'EZK.30.16', 'I will set fire to Egypt, Pelusium will writhe in anguish, Thebes will be split open, and Memphis will face daily distress.'),
('EZK', 30, 17, 'EZK.30.17', 'The young men of On and Pi-beseth will fall by the sword, and those cities will go into captivity.'),
('EZK', 30, 18, 'EZK.30.18', 'The day will be darkened in Tahpanhes when I break the yoke of Egypt and her proud strength comes to an end. A cloud will cover her, and her daughters will go into captivity.'),
('EZK', 30, 19, 'EZK.30.19', 'So I will execute judgment on Egypt, and they will know that I am the LORD.”'),
('EZK', 30, 20, 'EZK.30.20', 'In the eleventh year, on the seventh day of the first month, the word of the LORD came to me, saying,'),
('EZK', 30, 21, 'EZK.30.21', '“Son of man, I have broken the arm of Pharaoh king of Egypt. See, it has not been bound up for healing, or splinted for strength to hold the sword.'),
('EZK', 30, 22, 'EZK.30.22', 'Therefore this is what the Lord GOD says: Behold, I am against Pharaoh king of Egypt. I will break his arms, both the strong one and the one already broken, and will make the sword fall from his hand.'),
('EZK', 30, 23, 'EZK.30.23', 'I will disperse the Egyptians among the nations and scatter them throughout the lands.'),
('EZK', 30, 24, 'EZK.30.24', 'I will strengthen the arms of Babylon’s king and place My sword in his hand, but I will break the arms of Pharaoh, who will groan before him like a mortally wounded man.'),
('EZK', 30, 25, 'EZK.30.25', 'I will strengthen the arms of Babylon’s king, but Pharaoh’s arms will fall limp. Then they will know that I am the LORD, when I place My sword in the hand of Babylon’s king, and he wields it against the land of Egypt.'),
('EZK', 30, 26, 'EZK.30.26', 'I will disperse the Egyptians among the nations and scatter them throughout the lands. Then they will know that I am the LORD.”'),
('EZK', 31, 1, 'EZK.31.1', 'In the eleventh year, on the first day of the third month, the word of the LORD came to me, saying,'),
('EZK', 31, 2, 'EZK.31.2', '“Son of man, say to Pharaoh king of Egypt and to his multitude: ‘Who can be compared to your greatness?'),
('EZK', 31, 3, 'EZK.31.3', 'Look at Assyria, a cedar in Lebanon, with beautiful branches that shaded the forest. It towered on high; its top was among the clouds.'),
('EZK', 31, 4, 'EZK.31.4', 'The waters made it grow; the deep springs made it tall, directing their streams all around its base and sending their channels to all the trees of the field.'),
('EZK', 31, 5, 'EZK.31.5', 'Therefore it towered higher than all the trees of the field. Its branches multiplied, and its boughs grew long as it spread them out because of the abundant waters.'),
('EZK', 31, 6, 'EZK.31.6', 'All the birds of the air nested in its branches, and all the beasts of the field gave birth beneath its boughs; all the great nations lived in its shade.'),
('EZK', 31, 7, 'EZK.31.7', 'It was beautiful in its greatness, in the length of its limbs, for its roots extended to abundant waters.'),
('EZK', 31, 8, 'EZK.31.8', 'The cedars in the garden of God could not rival it; the cypresses could not compare with its branches, nor the plane trees match its boughs. No tree in the garden of God could compare with its beauty.'),
('EZK', 31, 9, 'EZK.31.9', 'I made it beautiful with its many branches, the envy of all the trees of Eden, which were in the garden of God.’'),
('EZK', 31, 10, 'EZK.31.10', 'Therefore this is what the Lord GOD says: ‘Since it became great in height and set its top among the clouds, and it grew proud on account of its height,'),
('EZK', 31, 11, 'EZK.31.11', 'I delivered it into the hand of the ruler of the nations, for him to deal with it according to its wickedness. I have banished it.'),
('EZK', 31, 12, 'EZK.31.12', 'Foreigners, the most ruthless of the nations, cut it down and left it. Its branches have fallen on the mountains and in every valley; its boughs lay broken in all the earth’s ravines. And all the peoples of the earth left its shade and abandoned it.'),
('EZK', 31, 13, 'EZK.31.13', 'All the birds of the air nested on its fallen trunk, and all the beasts of the field lived among its boughs.'),
('EZK', 31, 14, 'EZK.31.14', 'This happened so that no other trees by the waters would become great in height and set their tops among the clouds, and no other well-watered trees would reach them in height. For they have all been consigned to death, to the depths of the earth, among the mortals who descend to the Pit.’'),
('EZK', 31, 15, 'EZK.31.15', 'This is what the Lord GOD says: ‘On the day it was brought down to Sheol, I caused mourning. I covered the deep because of it; I held back its rivers; its abundant waters were restrained. I made Lebanon mourn for it, and all the trees of the field fainted because of it.'),
('EZK', 31, 16, 'EZK.31.16', 'I made the nations quake at the sound of its downfall, when I cast it down to Sheol with those who descend to the Pit. Then all the trees of Eden, the choicest and best of Lebanon, all the well-watered trees, were consoled in the earth below.'),
('EZK', 31, 17, 'EZK.31.17', 'They too descended with it to Sheol, to those slain by the sword. As its allies they had lived in its shade among the nations.'),
('EZK', 31, 18, 'EZK.31.18', 'Who then is like you in glory and greatness among the trees of Eden? You also will be brought down to the depths of the earth to be with the trees of Eden. You will lie among the uncircumcised, with those slain by the sword. This is Pharaoh and all his multitude, declares the Lord GOD.’”'),
('EZK', 32, 1, 'EZK.32.1', 'In the twelfth year, on the first day of the twelfth month, the word of the LORD came to me, saying,'),
('EZK', 32, 2, 'EZK.32.2', '“Son of man, take up a lament for Pharaoh king of Egypt and say to him: ‘You are like a lion among the nations; you are like a monster in the seas. You thrash about in your rivers, churning up the waters with your feet and muddying the streams.’'),
('EZK', 32, 3, 'EZK.32.3', 'This is what the Lord GOD says: ‘I will spread My net over you with a company of many peoples, and they will draw you up in My net.'),
('EZK', 32, 4, 'EZK.32.4', 'I will abandon you on the land and hurl you into the open field. I will cause all the birds of the air to settle upon you, and all the beasts of the earth to eat their fill of you.'),
('EZK', 32, 5, 'EZK.32.5', 'I will put your flesh on the mountains and fill the valleys with your remains.'),
('EZK', 32, 6, 'EZK.32.6', 'I will drench the land with the flow of your blood, all the way to the mountains—the ravines will be filled.'),
('EZK', 32, 7, 'EZK.32.7', 'When I extinguish you, I will cover the heavens and darken their stars. I will cover the sun with a cloud, and the moon will not give its light.'),
('EZK', 32, 8, 'EZK.32.8', 'All the shining lights in the heavens I will darken over you, and I will bring darkness upon your land,’ declares the Lord GOD.'),
('EZK', 32, 9, 'EZK.32.9', '‘I will trouble the hearts of many peoples, when I bring about your destruction among the nations, in countries you do not know.'),
('EZK', 32, 10, 'EZK.32.10', 'I will cause many peoples to be appalled over you, and their kings will shudder in horror because of you when I brandish My sword before them. On the day of your downfall each of them will tremble every moment for his life.’'),
('EZK', 32, 11, 'EZK.32.11', 'For this is what the Lord GOD says: ‘The sword of the king of Babylon will come against you!'),
('EZK', 32, 12, 'EZK.32.12', 'I will make your hordes fall by the swords of the mighty, the most ruthless of all nations. They will ravage the pride of Egypt and all her multitudes will be destroyed.'),
('EZK', 32, 13, 'EZK.32.13', 'I will slaughter all her cattle beside the abundant waters. No human foot will muddy them again, and no cattle hooves will disturb them.'),
('EZK', 32, 14, 'EZK.32.14', 'Then I will let her waters settle and will make her rivers flow like oil,’ declares the Lord GOD.'),
('EZK', 32, 15, 'EZK.32.15', '‘When I make the land of Egypt a desolation and empty it of all that filled it, when I strike down all who live there, then they will know that I am the LORD.’'),
('EZK', 32, 16, 'EZK.32.16', 'This is the lament they will chant for her; the daughters of the nations will chant it. Over Egypt and all her multitudes they will chant it, declares the Lord GOD.”'),
('EZK', 32, 17, 'EZK.32.17', 'In the twelfth year, on the fifteenth day of the month, the word of the LORD came to me, saying,'),
('EZK', 32, 18, 'EZK.32.18', '“Son of man, wail for the multitudes of Egypt, and consign her and the daughters of the mighty nations to the depths of the earth with those who descend to the Pit:'),
('EZK', 32, 19, 'EZK.32.19', 'Whom do you surpass in beauty? Go down and be placed with the uncircumcised!'),
('EZK', 32, 20, 'EZK.32.20', 'They will fall among those slain by the sword. The sword is appointed! Let them drag her away along with all her multitudes.'),
('EZK', 32, 21, 'EZK.32.21', 'Mighty chiefs will speak from the midst of Sheol about Egypt and her allies: ‘They have come down and lie with the uncircumcised, with those slain by the sword.’'),
('EZK', 32, 22, 'EZK.32.22', 'Assyria is there with her whole company; her graves are all around her. All of them are slain, fallen by the sword.'),
('EZK', 32, 23, 'EZK.32.23', 'Her graves are set in the depths of the Pit, and her company is all around her grave. All of them are slain, fallen by the sword—those who once spread terror in the land of the living.'),
('EZK', 32, 24, 'EZK.32.24', 'Elam is there with all her multitudes around her grave. All of them are slain, fallen by the sword—those who went down uncircumcised to the earth below, who once spread their terror in the land of the living. They bear their disgrace with those who descend to the Pit.'),
('EZK', 32, 25, 'EZK.32.25', 'Among the slain they prepare a resting place for Elam with all her hordes, with her graves all around her. All of them are uncircumcised, slain by the sword, although their terror was once spread in the land of the living. They bear their disgrace with those who descend to the Pit. They are placed among the slain.'),
('EZK', 32, 26, 'EZK.32.26', 'Meshech and Tubal are there with all their multitudes, with their graves all around them. All of them are uncircumcised, slain by the sword, because they spread their terror in the land of the living.'),
('EZK', 32, 27, 'EZK.32.27', 'They do not lie down with the fallen warriors of old, who went down to Sheol with their weapons of war, whose swords were placed under their heads, whose shields rested on their bones, although the terror of the mighty was once in the land of the living.'),
('EZK', 32, 28, 'EZK.32.28', 'But you too will be shattered and lie down among the uncircumcised, with those slain by the sword.'),
('EZK', 32, 29, 'EZK.32.29', 'Edom is there, and all her kings and princes, who despite their might are laid among those slain by the sword. They lie down with the uncircumcised, with those who descend to the Pit.'),
('EZK', 32, 30, 'EZK.32.30', 'All the leaders of the north and all the Sidonians are there; they went down in disgrace with the slain, despite the terror of their might. They lie uncircumcised with those slain by the sword and bear their shame with those who descend to the Pit.'),
('EZK', 32, 31, 'EZK.32.31', 'Pharaoh will see them and be comforted over all his multitude—Pharaoh and all his army, slain by the sword, declares the Lord GOD.'),
('EZK', 32, 32, 'EZK.32.32', 'For I will spread My terror in the land of the living, so that Pharaoh and all his multitude will be laid to rest among the uncircumcised, with those slain by the sword, declares the Lord GOD.”'),
('EZK', 33, 1, 'EZK.33.1', 'Again the word of the LORD came to me, saying,'),
('EZK', 33, 2, 'EZK.33.2', '“Son of man, speak to your people and tell them: ‘Suppose I bring the sword against a land, and the people of that land choose a man from among them, appointing him as their watchman,'),
('EZK', 33, 3, 'EZK.33.3', 'and he sees the sword coming against that land and blows the ram’s horn to warn the people.'),
('EZK', 33, 4, 'EZK.33.4', 'Then if anyone hears the sound of the horn but fails to heed the warning, and the sword comes and takes him away, his blood will be on his own head.'),
('EZK', 33, 5, 'EZK.33.5', 'Since he heard the sound of the horn but failed to heed the warning, his blood will be on his own head. If he had heeded the warning, he would have saved his life.'),
('EZK', 33, 6, 'EZK.33.6', 'But if the watchman sees the sword coming and fails to blow the horn to warn the people, and the sword comes and takes away a life, then that one will be taken away in his iniquity, but I will hold the watchman accountable for his blood.’'),
('EZK', 33, 7, 'EZK.33.7', 'As for you, O son of man, I have made you a watchman for the house of Israel; so hear the word from My mouth and give them the warning from Me.'),
('EZK', 33, 8, 'EZK.33.8', 'If I say to the wicked, ‘O wicked man, you will surely die,’ but you do not speak out to dissuade him from his way, then that wicked man will die in his iniquity, yet I will hold you accountable for his blood.'),
('EZK', 33, 9, 'EZK.33.9', 'But if you warn the wicked man to turn from his way, and he does not turn from it, he will die in his iniquity, but you will have saved your life.'),
('EZK', 33, 10, 'EZK.33.10', 'Now as for you, son of man, tell the house of Israel that this is what they have said: ‘Our transgressions and our sins are heavy upon us, and we are wasting away because of them! How can we live?’'),
('EZK', 33, 11, 'EZK.33.11', 'Say to them: ‘As surely as I live, declares the Lord GOD, I take no pleasure in the death of the wicked, but rather that the wicked should turn from their ways and live. Turn! Turn from your evil ways! For why should you die, O house of Israel?’'),
('EZK', 33, 12, 'EZK.33.12', 'Therefore, son of man, say to your people: ‘The righteousness of the righteous man will not deliver him in the day of his transgression; neither will the wickedness of the wicked man cause him to stumble on the day he turns from his wickedness. Nor will the righteous man be able to survive by his righteousness on the day he sins.’'),
('EZK', 33, 13, 'EZK.33.13', 'If I tell the righteous man that he will surely live, but he then trusts in his righteousness and commits iniquity, then none of his righteous works will be remembered; he will die because of the iniquity he has committed.'),
('EZK', 33, 14, 'EZK.33.14', 'But if I tell the wicked man, ‘You will surely die,’ and he turns from his sin and does what is just and right—'),
('EZK', 33, 15, 'EZK.33.15', 'if he restores a pledge, makes restitution for what he has stolen, and walks in the statutes of life without practicing iniquity—then he will surely live; he will not die.'),
('EZK', 33, 16, 'EZK.33.16', 'None of the sins he has committed will be held against him. He has done what is just and right; he will surely live.'),
('EZK', 33, 17, 'EZK.33.17', 'Yet your people say, ‘The way of the Lord is not just.’ But it is their way that is not just.'),
('EZK', 33, 18, 'EZK.33.18', 'If a righteous man turns from his righteousness and commits iniquity, he will die for it.'),
('EZK', 33, 19, 'EZK.33.19', 'But if a wicked man turns from his wickedness and does what is just and right, he will live because of this.'),
('EZK', 33, 20, 'EZK.33.20', 'Yet you say, ‘The way of the Lord is not just.’ But I will judge each of you according to his ways, O house of Israel.”'),
('EZK', 33, 21, 'EZK.33.21', 'In the twelfth year of our exile, on the fifth day of the tenth month, a fugitive from Jerusalem came to me and reported, “The city has been taken!”'),
('EZK', 33, 22, 'EZK.33.22', 'Now the evening before the fugitive arrived, the hand of the LORD was upon me, and He opened my mouth before the man came to me in the morning. So my mouth was opened and I was no longer mute.'),
('EZK', 33, 23, 'EZK.33.23', 'Then the word of the LORD came to me, saying,'),
('EZK', 33, 24, 'EZK.33.24', '“Son of man, those living in the ruins in the land of Israel are saying, ‘Abraham was only one man, yet he possessed the land. But we are many; surely the land has been given to us as a possession.’'),
('EZK', 33, 25, 'EZK.33.25', 'Therefore tell them that this is what the Lord GOD says: ‘You eat meat with the blood in it, lift up your eyes to your idols, and shed blood. Should you then possess the land?'),
('EZK', 33, 26, 'EZK.33.26', 'You have relied on your swords, you have committed detestable acts, and each of you has defiled his neighbor’s wife. Should you then possess the land?’'),
('EZK', 33, 27, 'EZK.33.27', 'Tell them that this is what the Lord GOD says: ‘As surely as I live, those in the ruins will fall by the sword, those in the open field I will give to be devoured by wild animals, and those in the strongholds and caves will die by plague.'),
('EZK', 33, 28, 'EZK.33.28', 'I will make the land a desolate waste, and the pride of her strength will come to an end. The mountains of Israel will become desolate, so that no one will pass through.'),
('EZK', 33, 29, 'EZK.33.29', 'Then they will know that I am the LORD, when I have made the land a desolate waste because of all the abominations they have committed.’'),
('EZK', 33, 30, 'EZK.33.30', 'As for you, son of man, your people are talking about you near the city walls and in the doorways of their houses. One speaks to another, each saying to his brother, ‘Come and hear the message that has come from the LORD!’'),
('EZK', 33, 31, 'EZK.33.31', 'So My people come to you as usual, sit before you, and hear your words; but they do not put them into practice. Although they express love with their mouths, their hearts pursue dishonest gain.'),
('EZK', 33, 32, 'EZK.33.32', 'Indeed, you are to them like a singer of love songs with a beautiful voice, who skillfully plays an instrument. They hear your words but do not put them into practice.'),
('EZK', 33, 33, 'EZK.33.33', 'So when it comes to pass—and surely it will come—then they will know that a prophet has been among them.”'),
('EZK', 34, 1, 'EZK.34.1', 'Then the word of the LORD came to me, saying,'),
('EZK', 34, 2, 'EZK.34.2', '“Son of man, prophesy against the shepherds of Israel. Prophesy and tell them that this is what the Lord GOD says: ‘Woe to the shepherds of Israel, who only feed themselves! Should not the shepherds feed their flock?'),
('EZK', 34, 3, 'EZK.34.3', 'You eat the fat, wear the wool, and butcher the fattened sheep, but you do not feed the flock.'),
('EZK', 34, 4, 'EZK.34.4', 'You have not strengthened the weak, healed the sick, bound up the injured, brought back the strays, or searched for the lost. Instead, you have ruled them with violence and cruelty.'),
('EZK', 34, 5, 'EZK.34.5', 'They were scattered for lack of a shepherd, and when they were scattered they became food for all the wild beasts.'),
('EZK', 34, 6, 'EZK.34.6', 'My flock went astray on all the mountains and every high hill. They were scattered over the face of all the earth, with no one to search for them or seek them out.’'),
('EZK', 34, 7, 'EZK.34.7', 'Therefore, you shepherds, hear the word of the LORD:'),
('EZK', 34, 8, 'EZK.34.8', '‘As surely as I live, declares the Lord GOD, because My flock lacks a shepherd and has become prey and food for every wild beast, and because My shepherds did not search for My flock but fed themselves instead,'),
('EZK', 34, 9, 'EZK.34.9', 'therefore, you shepherds, hear the word of the LORD!’'),
('EZK', 34, 10, 'EZK.34.10', 'This is what the Lord GOD says: ‘Behold, I am against the shepherds, and I will demand from them My flock and remove them from tending the flock, so that they can no longer feed themselves. For I will deliver My flock from their mouths, and it will no longer be food for them.’'),
('EZK', 34, 11, 'EZK.34.11', 'For this is what the Lord GOD says: ‘Behold, I Myself will search for My flock and seek them out.'),
('EZK', 34, 12, 'EZK.34.12', 'As a shepherd looks for his scattered sheep when he is among the flock, so I will look for My flock. I will rescue them from all the places to which they were scattered on a day of clouds and darkness.'),
('EZK', 34, 13, 'EZK.34.13', 'I will bring them out from the peoples, gather them from the countries, and bring them into their own land. I will feed them on the mountains of Israel, in the ravines, and in all the settlements of the land.'),
('EZK', 34, 14, 'EZK.34.14', 'I will feed them in good pasture, and the lofty mountains of Israel will be their grazing land. There they will lie down in a good grazing land; they will feed in rich pasture on the mountains of Israel.'),
('EZK', 34, 15, 'EZK.34.15', 'I will tend My flock and make them lie down, declares the Lord GOD.'),
('EZK', 34, 16, 'EZK.34.16', 'I will seek the lost, bring back the strays, bind up the broken, and strengthen the weak; but the sleek and strong I will destroy. I will shepherd them with justice.’'),
('EZK', 34, 17, 'EZK.34.17', 'This is what the Lord GOD says to you, My flock: ‘I will judge between one sheep and another, between the rams and the goats.'),
('EZK', 34, 18, 'EZK.34.18', 'Is it not enough for you to feed on the good pasture? Must you also trample the rest of the pasture with your feet? Is it not enough for you to drink the clear waters? Must you also muddy the rest with your feet?'),
('EZK', 34, 19, 'EZK.34.19', 'Why must My flock feed on what your feet have trampled, and drink what your feet have muddied?’'),
('EZK', 34, 20, 'EZK.34.20', 'Therefore this is what the Lord GOD says to them: ‘Behold, I Myself will judge between the fat sheep and the lean sheep.'),
('EZK', 34, 21, 'EZK.34.21', 'Since you shove with flank and shoulder, butting all the weak ones with your horns until you have scattered them abroad,'),
('EZK', 34, 22, 'EZK.34.22', 'I will save My flock, and they will no longer be prey. I will judge between one sheep and another.'),
('EZK', 34, 23, 'EZK.34.23', 'I will appoint over them one shepherd, My servant David, and he will feed them. He will feed them and be their shepherd.'),
('EZK', 34, 24, 'EZK.34.24', 'I, the LORD, will be their God, and My servant David will be a prince among them. I, the LORD, have spoken.'),
('EZK', 34, 25, 'EZK.34.25', 'I will make with them a covenant of peace and rid the land of wild animals, so that they may dwell securely in the wilderness and sleep in the forest.'),
('EZK', 34, 26, 'EZK.34.26', 'I will make them and the places around My hill a blessing. I will send down showers in season—showers of blessing.'),
('EZK', 34, 27, 'EZK.34.27', 'The trees of the field will give their fruit, and the land will yield its produce; My flock will be secure in their land. Then they will know that I am the LORD, when I have broken the bars of their yoke and delivered them from the hands that enslaved them.'),
('EZK', 34, 28, 'EZK.34.28', 'They will no longer be prey for the nations, and the beasts of the earth will not consume them. They will dwell securely, and no one will frighten them.'),
('EZK', 34, 29, 'EZK.34.29', 'And I will raise up for them a garden of renown, and they will no longer be victims of famine in the land or bear the scorn of the nations.'),
('EZK', 34, 30, 'EZK.34.30', 'Then they will know that I, the LORD their God, am with them, and that they, the house of Israel, are My people,’ declares the Lord GOD.'),
('EZK', 34, 31, 'EZK.34.31', '‘You are My flock, the sheep of My pasture, My people, and I am your God,’ declares the Lord GOD.”'),
('EZK', 35, 1, 'EZK.35.1', 'Moreover, the word of the LORD came to me, saying,'),
('EZK', 35, 2, 'EZK.35.2', '“Son of man, set your face against Mount Seir and prophesy against it,'),
('EZK', 35, 3, 'EZK.35.3', 'and declare that this is what the Lord GOD says: Behold, I am against you, O Mount Seir. I will stretch out My hand against you and make you a desolate waste.'),
('EZK', 35, 4, 'EZK.35.4', 'I will turn your cities into ruins, and you will become a desolation. Then you will know that I am the LORD.'),
('EZK', 35, 5, 'EZK.35.5', 'Because you harbored an ancient hatred and delivered the Israelites over to the sword in the time of their disaster at the final stage of their punishment,'),
('EZK', 35, 6, 'EZK.35.6', 'therefore as surely as I live, declares the Lord GOD, I will give you over to bloodshed and it will pursue you. Since you did not hate bloodshed, it will pursue you.'),
('EZK', 35, 7, 'EZK.35.7', 'I will make Mount Seir a desolate waste and will cut off from it those who come and go.'),
('EZK', 35, 8, 'EZK.35.8', 'I will fill its mountains with the slain; those killed by the sword will fall on your hills, in your valleys, and in all your ravines.'),
('EZK', 35, 9, 'EZK.35.9', 'I will make you a perpetual desolation, and your cities will not be inhabited. Then you will know that I am the LORD.'),
('EZK', 35, 10, 'EZK.35.10', 'Because you have said, ‘These two nations and countries will be ours, and we will possess them,’ even though the LORD was there,'),
('EZK', 35, 11, 'EZK.35.11', 'therefore as surely as I live, declares the Lord GOD, I will treat you according to the anger and jealousy you showed in your hatred against them, and I will make Myself known among them when I judge you.'),
('EZK', 35, 12, 'EZK.35.12', 'Then you will know that I, the LORD, have heard every contemptuous word you uttered against the mountains of Israel when you said, ‘They are desolate; they are given to us to devour!’'),
('EZK', 35, 13, 'EZK.35.13', 'You boasted against Me with your mouth and multiplied your words against Me. I heard it Myself!'),
('EZK', 35, 14, 'EZK.35.14', 'This is what the Lord GOD says: While the whole earth rejoices, I will make you desolate.'),
('EZK', 35, 15, 'EZK.35.15', 'As you rejoiced when the inheritance of the house of Israel became desolate, so will I do to you. You will become a desolation, O Mount Seir, and so will all of Edom. Then they will know that I am the LORD.'),
('EZK', 36, 1, 'EZK.36.1', '“And you, son of man, prophesy to the mountains of Israel and say: O mountains of Israel, hear the word of the LORD.'),
('EZK', 36, 2, 'EZK.36.2', 'This is what the Lord GOD says: Because the enemy has said of you, ‘Aha! The ancient heights have become our possession,’'),
('EZK', 36, 3, 'EZK.36.3', 'therefore prophesy and declare that this is what the Lord GOD says: Because they have made you desolate and have trampled you on every side, so that you became a possession of the rest of the nations and were taken up in slander by the lips of their talkers,'),
('EZK', 36, 4, 'EZK.36.4', 'therefore, O mountains of Israel, hear the word of the Lord GOD. This is what the Lord GOD says to the mountains and hills, to the ravines and valleys, to the desolate ruins and abandoned cities, which have become a spoil and a mockery to the rest of the nations around you.'),
('EZK', 36, 5, 'EZK.36.5', 'Therefore this is what the Lord GOD says: Surely in My burning zeal I have spoken against the rest of the nations, and against all Edom, who took My land as their own possession with wholehearted joy and utter contempt, so that its pastureland became plunder.'),
('EZK', 36, 6, 'EZK.36.6', 'Therefore, prophesy concerning the land of Israel and tell the mountains and hills, the ravines and valleys, that this is what the Lord GOD says: Behold, I have spoken in My burning zeal because you have endured the reproach of the nations.'),
('EZK', 36, 7, 'EZK.36.7', 'Therefore this is what the Lord GOD says: I have sworn with an uplifted hand that surely the nations around you will endure reproach of their own.'),
('EZK', 36, 8, 'EZK.36.8', 'But you, O mountains of Israel, will produce branches and bear fruit for My people Israel, for they will soon come home.'),
('EZK', 36, 9, 'EZK.36.9', 'For behold, I am on your side; I will turn toward you, and you will be tilled and sown.'),
('EZK', 36, 10, 'EZK.36.10', 'I will multiply the people upon you—the house of Israel in its entirety. The cities will be inhabited and the ruins rebuilt.'),
('EZK', 36, 11, 'EZK.36.11', 'I will fill you with people and animals, and they will multiply and be fruitful. I will make you as inhabited as you once were, and I will make you prosper more than before. Then you will know that I am the LORD.'),
('EZK', 36, 12, 'EZK.36.12', 'Yes, I will cause My people Israel to walk upon you; they will possess you, and you will be their inheritance, and you will no longer deprive them of their children.'),
('EZK', 36, 13, 'EZK.36.13', 'For this is what the Lord GOD says: Because people say to you, ‘You devour men and deprive your nation of its children,’'),
('EZK', 36, 14, 'EZK.36.14', 'therefore you will no longer devour men or deprive your nation of its children, declares the Lord GOD.'),
('EZK', 36, 15, 'EZK.36.15', 'I will no longer allow the taunts of the nations to be heard against you, and you will no longer endure the reproach of the peoples or cause your nation to stumble, declares the Lord GOD.”'),
('EZK', 36, 16, 'EZK.36.16', 'Again the word of the LORD came to me, saying,'),
('EZK', 36, 17, 'EZK.36.17', '“Son of man, when the people of Israel lived in their land, they defiled it by their own ways and deeds. Their behavior before Me was like the uncleanness of a woman’s impurity.'),
('EZK', 36, 18, 'EZK.36.18', 'So I poured out My wrath upon them because of the blood they had shed on the land, and because they had defiled it with their idols.'),
('EZK', 36, 19, 'EZK.36.19', 'I dispersed them among the nations, and they were scattered throughout the lands. I judged them according to their ways and deeds.'),
('EZK', 36, 20, 'EZK.36.20', 'And wherever they went among the nations, they profaned My holy name, because it was said of them, ‘These are the people of the LORD, yet they had to leave His land.’'),
('EZK', 36, 21, 'EZK.36.21', 'But I had concern for My holy name, which the house of Israel had profaned among the nations to which they had gone.'),
('EZK', 36, 22, 'EZK.36.22', 'Therefore tell the house of Israel that this is what the Lord GOD says: It is not for your sake that I will act, O house of Israel, but for My holy name, which you profaned among the nations to which you went.'),
('EZK', 36, 23, 'EZK.36.23', 'I will show the holiness of My great name, which has been profaned among the nations—the name you have profaned among them. Then the nations will know that I am the LORD, declares the Lord GOD, when I show My holiness in you before their eyes.'),
('EZK', 36, 24, 'EZK.36.24', 'For I will take you from among the nations and gather you out of all the countries, and I will bring you back into your own land.'),
('EZK', 36, 25, 'EZK.36.25', 'I will also sprinkle clean water on you, and you will be clean. I will cleanse you from all your impurities and all your idols.'),
('EZK', 36, 26, 'EZK.36.26', 'I will give you a new heart and put a new spirit within you; I will remove your heart of stone and give you a heart of flesh.'),
('EZK', 36, 27, 'EZK.36.27', 'And I will put My Spirit within you and cause you to walk in My statutes and to carefully observe My ordinances.'),
('EZK', 36, 28, 'EZK.36.28', 'Then you will live in the land that I gave your forefathers; you will be My people, and I will be your God.'),
('EZK', 36, 29, 'EZK.36.29', 'I will save you from all your uncleanness. I will summon the grain and make it plentiful, and I will not bring famine upon you.'),
('EZK', 36, 30, 'EZK.36.30', 'I will also make the fruit of the trees and the crops of the field plentiful, so that you will no longer bear reproach among the nations on account of famine.'),
('EZK', 36, 31, 'EZK.36.31', 'Then you will remember your evil ways and wicked deeds, and you will loathe yourselves for your iniquities and abominations.'),
('EZK', 36, 32, 'EZK.36.32', 'It is not for your sake that I will act, declares the Lord GOD—let it be known to you. Be ashamed and disgraced for your ways, O house of Israel!'),
('EZK', 36, 33, 'EZK.36.33', 'This is what the Lord GOD says: On the day I cleanse you from all your iniquities, I will cause the cities to be resettled and the ruins to be rebuilt.'),
('EZK', 36, 34, 'EZK.36.34', 'The desolate land will be cultivated instead of lying desolate in the sight of all who pass through.'),
('EZK', 36, 35, 'EZK.36.35', 'Then they will say, ‘This land that was desolate has become like the garden of Eden. The cities that were once ruined, desolate, and destroyed are now fortified and inhabited.’'),
('EZK', 36, 36, 'EZK.36.36', 'Then the nations around you that remain will know that I, the LORD, have rebuilt what was destroyed, and I have replanted what was desolate. I, the LORD, have spoken, and I will do it.'),
('EZK', 36, 37, 'EZK.36.37', 'This is what the Lord GOD says: Once again I will hear the plea of the house of Israel and do for them this: I will multiply their people like a flock.'),
('EZK', 36, 38, 'EZK.36.38', 'Like the numerous flocks for sacrifices at Jerusalem during her appointed feasts, so the ruined cities will be filled with flocks of people. Then they will know that I am the LORD.”'),
('EZK', 37, 1, 'EZK.37.1', 'The hand of the LORD was upon me, and He brought me out by His Spirit and set me down in the middle of the valley, and it was full of bones.'),
('EZK', 37, 2, 'EZK.37.2', 'He led me all around among them, and I saw a great many bones on the floor of the valley, and indeed, they were very dry.'),
('EZK', 37, 3, 'EZK.37.3', 'Then He asked me, “Son of man, can these bones come to life?” “O Lord GOD,” I replied, “only You know.”'),
('EZK', 37, 4, 'EZK.37.4', 'And He said to me, “Prophesy concerning these bones and tell them, ‘Dry bones, hear the word of the LORD!'),
('EZK', 37, 5, 'EZK.37.5', 'This is what the Lord GOD says to these bones: I will cause breath to enter you, and you will come to life.'),
('EZK', 37, 6, 'EZK.37.6', 'I will attach tendons to you and make flesh grow upon you and cover you with skin. I will put breath within you so that you will come to life. Then you will know that I am the LORD.’”'),
('EZK', 37, 7, 'EZK.37.7', 'So I prophesied as I had been commanded. And as I prophesied, there was suddenly a noise, a rattling, and the bones came together, bone to bone.'),
('EZK', 37, 8, 'EZK.37.8', 'As I looked on, tendons appeared on them, flesh grew, and skin covered them; but there was no breath in them.'),
('EZK', 37, 9, 'EZK.37.9', 'Then He said to me, “Prophesy to the breath; prophesy, son of man, and tell the breath that this is what the Lord GOD says: Come from the four winds, O breath, and breathe into these slain, so that they may live!”'),
('EZK', 37, 10, 'EZK.37.10', 'So I prophesied as He had commanded me, and the breath entered them, and they came to life and stood on their feet—a vast army.'),
('EZK', 37, 11, 'EZK.37.11', 'Then He said to me, “Son of man, these bones are the whole house of Israel. Look, they are saying, ‘Our bones are dried up, and our hope has perished; we are cut off.’'),
('EZK', 37, 12, 'EZK.37.12', 'Therefore prophesy and tell them that this is what the Lord GOD says: ‘O My people, I will open your graves and bring you up from them, and I will bring you back to the land of Israel.'),
('EZK', 37, 13, 'EZK.37.13', 'Then you, My people, will know that I am the LORD, when I open your graves and bring you up from them.'),
('EZK', 37, 14, 'EZK.37.14', 'I will put My Spirit in you and you will live, and I will settle you in your own land. Then you will know that I, the LORD, have spoken, and I will do it, declares the LORD.’”'),
('EZK', 37, 15, 'EZK.37.15', 'Again the word of the LORD came to me, saying,'),
('EZK', 37, 16, 'EZK.37.16', '“And you, son of man, take a single stick and write on it: ‘Belonging to Judah and to the Israelites associated with him.’ Then take another stick and write on it: ‘Belonging to Joseph—the stick of Ephraim—and to all the house of Israel associated with him.’'),
('EZK', 37, 17, 'EZK.37.17', 'Then join them together into one stick, so that they become one in your hand.'),
('EZK', 37, 18, 'EZK.37.18', 'When your people ask you, ‘Won’t you explain to us what you mean by these?’'),
('EZK', 37, 19, 'EZK.37.19', 'you are to tell them that this is what the Lord GOD says: ‘I will take the stick of Joseph, which is in the hand of Ephraim, and the tribes of Israel associated with him, and I will put them together with the stick of Judah. I will make them into a single stick, and they will become one in My hand.’'),
('EZK', 37, 20, 'EZK.37.20', 'When the sticks on which you write are in your hand and in full view of the people,'),
('EZK', 37, 21, 'EZK.37.21', 'you are to tell them that this is what the Lord GOD says: ‘I will take the Israelites out of the nations to which they have gone, and I will gather them from all around and bring them into their own land.'),
('EZK', 37, 22, 'EZK.37.22', 'I will make them one nation in the land, on the mountains of Israel, and one king will rule over all of them. Then they will no longer be two nations and will never again be divided into two kingdoms.'),
('EZK', 37, 23, 'EZK.37.23', 'They will no longer defile themselves with their idols or detestable images, or with any of their transgressions. I will save them from all their apostasies by which they sinned, and I will cleanse them. Then they will be My people, and I will be their God.'),
('EZK', 37, 24, 'EZK.37.24', 'My servant David will be king over them, and there will be one shepherd for all of them. They will follow My ordinances and keep and observe My statutes.'),
('EZK', 37, 25, 'EZK.37.25', 'They will live in the land that I gave to My servant Jacob, where your fathers lived. They will live there forever with their children and grandchildren, and My servant David will be their prince forever.'),
('EZK', 37, 26, 'EZK.37.26', 'And I will make a covenant of peace with them; it will be an everlasting covenant. I will establish them and multiply them, and I will set My sanctuary among them forever.'),
('EZK', 37, 27, 'EZK.37.27', 'My dwelling place will be with them; I will be their God, and they will be My people.'),
('EZK', 37, 28, 'EZK.37.28', 'Then the nations will know that I the LORD sanctify Israel, when My sanctuary is among them forever.’”'),
('EZK', 38, 1, 'EZK.38.1', 'And the word of the LORD came to me, saying,'),
('EZK', 38, 2, 'EZK.38.2', '“Son of man, set your face against Gog of the land of Magog, the chief prince of Meshech and Tubal. Prophesy against him'),
('EZK', 38, 3, 'EZK.38.3', 'and declare that this is what the Lord GOD says: Behold, I am against you, O Gog, chief prince of Meshech and Tubal.'),
('EZK', 38, 4, 'EZK.38.4', 'I will turn you around, put hooks in your jaws, and bring you out with all your army—your horses, your horsemen in full armor, and a great company armed with shields and bucklers, all brandishing their swords.'),
('EZK', 38, 5, 'EZK.38.5', 'Persia, Cush, and Put will accompany them, all with shields and helmets,'),
('EZK', 38, 6, 'EZK.38.6', 'as well as Gomer with all its troops, and Beth-togarmah from the far north with all its troops—the many nations with you.'),
('EZK', 38, 7, 'EZK.38.7', 'Get ready; prepare yourself, you and all your company gathered around you; you will be their guard.'),
('EZK', 38, 8, 'EZK.38.8', 'After a long time you will be summoned. In the latter years you will enter a land that has recovered from war, whose people were gathered from many nations to the mountains of Israel, which had long been desolate. They had been brought out from the nations, and all now dwell securely.'),
('EZK', 38, 9, 'EZK.38.9', 'You and all your troops, and many peoples with you will go up, advancing like a thunderstorm; you will be like a cloud covering the land.'),
('EZK', 38, 10, 'EZK.38.10', 'This is what the Lord GOD says: On that day, thoughts will arise in your mind, and you will devise an evil plan.'),
('EZK', 38, 11, 'EZK.38.11', 'You will say, ‘I will go up against a land of unwalled villages; I will come against a quiet people who dwell securely, all of them living without walls or bars or gates—'),
('EZK', 38, 12, 'EZK.38.12', 'in order to seize the spoil and carry off the plunder, to turn a hand against the desolate places now inhabited and against a people gathered from the nations, who have acquired livestock and possessions and who live at the center of the land.’'),
('EZK', 38, 13, 'EZK.38.13', 'Sheba and Dedan and the merchants of Tarshish with all its villages will ask, ‘Have you come to capture the plunder? Have you assembled your hordes to carry away loot, to make off with silver and gold, to take cattle and goods, to seize great spoil?’'),
('EZK', 38, 14, 'EZK.38.14', 'Therefore prophesy, son of man, and tell Gog that this is what the Lord GOD says: On that day when My people Israel are dwelling securely, will you not take notice of this?'),
('EZK', 38, 15, 'EZK.38.15', 'And you will come from your place out of the far north—you and many peoples with you, all riding horses—a mighty horde, a huge army.'),
('EZK', 38, 16, 'EZK.38.16', 'You will advance against My people Israel like a cloud covering the land. It will happen in the latter days, O Gog, that I will bring you against My land, so that the nations may know Me when I show Myself holy in you before their eyes.'),
('EZK', 38, 17, 'EZK.38.17', 'This is what the Lord GOD says: Are you the one of whom I have spoken in former days through My servants, the prophets of Israel, who in those times prophesied for years that I would bring you against them?'),
('EZK', 38, 18, 'EZK.38.18', 'Now on that day when Gog comes against the land of Israel, declares the Lord GOD, My wrath will flare up.'),
('EZK', 38, 19, 'EZK.38.19', 'In My zeal and fiery rage I proclaim that on that day there will be a great earthquake in the land of Israel.'),
('EZK', 38, 20, 'EZK.38.20', 'The fish of the sea, the birds of the air, the beasts of the field, every creature that crawls upon the ground, and all mankind on the face of the earth will tremble at My presence. The mountains will be thrown down, the cliffs will collapse, and every wall will fall to the ground.'),
('EZK', 38, 21, 'EZK.38.21', 'And I will summon a sword against Gog on all My mountains, declares the Lord GOD, and every man’s sword will be against his brother.'),
('EZK', 38, 22, 'EZK.38.22', 'I will execute judgment upon him with plague and bloodshed. I will pour out torrents of rain, hailstones, fire, and sulfur on him and on his troops and on the many nations with him.'),
('EZK', 38, 23, 'EZK.38.23', 'I will magnify and sanctify Myself, and I will reveal Myself in the sight of many nations. Then they will know that I am the LORD.'),
('EZK', 39, 1, 'EZK.39.1', '“As for you, O son of man, prophesy against Gog and declare that this is what the Lord GOD says: Behold, I am against you, O Gog, chief prince of Meshech and Tubal.'),
('EZK', 39, 2, 'EZK.39.2', 'I will turn you around, drive you along, bring you up from the far north, and send you against the mountains of Israel.'),
('EZK', 39, 3, 'EZK.39.3', 'Then I will strike the bow from your left hand and dash down the arrows from your right hand.'),
('EZK', 39, 4, 'EZK.39.4', 'On the mountains of Israel you will fall—you and all your troops and the nations with you. I will give you as food to every kind of ravenous bird and wild beast.'),
('EZK', 39, 5, 'EZK.39.5', 'You will fall in the open field, for I have spoken, declares the Lord GOD.'),
('EZK', 39, 6, 'EZK.39.6', 'I will send fire on Magog and on those who dwell securely in the coastlands, and they will know that I am the LORD.'),
('EZK', 39, 7, 'EZK.39.7', 'So I will make My holy name known among My people Israel and will no longer allow it to be profaned. Then the nations will know that I am the LORD, the Holy One in Israel.'),
('EZK', 39, 8, 'EZK.39.8', 'Yes, it is coming, and it will surely happen, declares the Lord GOD. This is the day of which I have spoken.'),
('EZK', 39, 9, 'EZK.39.9', 'Then those who dwell in the cities of Israel will go out, kindle fires, and burn up the weapons—the bucklers and shields, the bows and arrows, the clubs and spears. For seven years they will use them for fuel.'),
('EZK', 39, 10, 'EZK.39.10', 'They will not gather wood from the countryside or cut it from the forests, for they will use the weapons for fuel. They will loot those who looted them and plunder those who plundered them, declares the Lord GOD.'),
('EZK', 39, 11, 'EZK.39.11', 'And on that day I will give Gog a burial place in Israel, the Valley of the Travelers, east of the Sea. It will block those who travel through, because Gog and all his hordes will be buried there. So it will be called the Valley of Hamon-gog.'),
('EZK', 39, 12, 'EZK.39.12', 'For seven months the house of Israel will be burying them in order to cleanse the land.'),
('EZK', 39, 13, 'EZK.39.13', 'All the people of the land will bury them, and it will bring them renown on the day I display My glory, declares the Lord GOD.'),
('EZK', 39, 14, 'EZK.39.14', 'And men will be employed to continually pass through the land to cleanse it by burying the invaders who remain on the ground. At the end of the seven months they will begin their search.'),
('EZK', 39, 15, 'EZK.39.15', 'As they pass through the land, anyone who sees a human bone will set up a pillar next to it, until the gravediggers have buried it in the Valley of Hamon-gog.'),
('EZK', 39, 16, 'EZK.39.16', '(Even the city will be named Hamonah.) And so they will cleanse the land.'),
('EZK', 39, 17, 'EZK.39.17', 'And as for you, son of man, this is what the Lord GOD says: Call out to every kind of bird and to every beast of the field: ‘Assemble and come together from all around to the sacrificial feast that I am preparing for you, a great feast on the mountains of Israel. There you will eat flesh and drink blood.'),
('EZK', 39, 18, 'EZK.39.18', 'You will eat the flesh of the mighty and drink the blood of the princes of the earth as though they were rams, lambs, goats, and bulls—all the fattened animals of Bashan.'),
('EZK', 39, 19, 'EZK.39.19', 'At the sacrifice I am preparing, you will eat fat until you are gorged and drink blood until you are drunk.'),
('EZK', 39, 20, 'EZK.39.20', 'And at My table you will eat your fill of horses and riders, of mighty men and warriors of every kind,’ declares the Lord GOD.'),
('EZK', 39, 21, 'EZK.39.21', 'I will display My glory among the nations, and all the nations will see the judgment that I execute and the hand that I lay upon them.'),
('EZK', 39, 22, 'EZK.39.22', 'From that day forward the house of Israel will know that I am the LORD their God.'),
('EZK', 39, 23, 'EZK.39.23', 'And the nations will know that the house of Israel went into exile for their iniquity, because they were unfaithful to Me. So I hid My face from them and delivered them into the hands of their enemies, so that they all fell by the sword.'),
('EZK', 39, 24, 'EZK.39.24', 'I dealt with them according to their uncleanness and transgressions, and I hid My face from them.'),
('EZK', 39, 25, 'EZK.39.25', 'Therefore this is what the Lord GOD says: Now I will restore Jacob from captivity and will have compassion on the whole house of Israel, and I will be jealous for My holy name.'),
('EZK', 39, 26, 'EZK.39.26', 'They will forget their disgrace and all the treachery they committed against Me, when they dwell securely in their land, with no one to frighten them.'),
('EZK', 39, 27, 'EZK.39.27', 'When I bring them back from the peoples and gather them out of the lands of their enemies, I will show My holiness in them in the sight of many nations.'),
('EZK', 39, 28, 'EZK.39.28', 'Then they will know that I am the LORD their God, when I regather them to their own land, not leaving any of them behind after their exile among the nations.'),
('EZK', 39, 29, 'EZK.39.29', 'And I will no longer hide My face from them, for I will pour out My Spirit on the house of Israel, declares the Lord GOD.”'),
('EZK', 40, 1, 'EZK.40.1', 'In the twenty-fifth year of our exile, at the beginning of the year, on the tenth day of the month—in the fourteenth year after Jerusalem had been struck down—on that very day the hand of the LORD was upon me, and He took me there.'),
('EZK', 40, 2, 'EZK.40.2', 'In visions of God He took me to the land of Israel and set me on a very high mountain, on whose southern slope was a structure that resembled a city.'),
('EZK', 40, 3, 'EZK.40.3', 'So He took me there, and I saw a man whose appearance was like bronze. He was standing in the gateway with a linen cord and a measuring rod in his hand.'),
('EZK', 40, 4, 'EZK.40.4', '“Son of man,” he said to me, “look with your eyes, hear with your ears, and pay attention to everything I am going to show you, for that is why you have been brought here. Report to the house of Israel everything you see.”'),
('EZK', 40, 5, 'EZK.40.5', 'And I saw a wall surrounding the temple area. Now the length of the measuring rod in the man’s hand was six long cubits (each measuring a cubit and a handbreadth), and he measured the wall to be one rod thick and one rod high.'),
('EZK', 40, 6, 'EZK.40.6', 'Then he came to the gate facing east and climbed its steps. He measured the threshold of the gate to be one rod deep.'),
('EZK', 40, 7, 'EZK.40.7', 'Each gate chamber was one rod long and one rod wide, and there were five cubits between the gate chambers. The inner threshold of the gate by the portico facing inward was one rod deep.'),
('EZK', 40, 8, 'EZK.40.8', 'Then he measured the portico of the gateway inside;'),
('EZK', 40, 9, 'EZK.40.9', 'it was eight cubits deep, and its jambs were two cubits thick. And the portico of the gateway faced the temple.'),
('EZK', 40, 10, 'EZK.40.10', 'There were three gate chambers on each side of the east gate, each with the same measurements, and the gateposts on either side also had the same measurements.'),
('EZK', 40, 11, 'EZK.40.11', 'And he measured the width of the gateway entrance to be ten cubits, and its length was thirteen cubits.'),
('EZK', 40, 12, 'EZK.40.12', 'In front of each gate chamber was a wall one cubit high, and the gate chambers were six cubits square.'),
('EZK', 40, 13, 'EZK.40.13', 'Then he measured the gateway from the roof of one gate chamber to the roof of the opposite one; the distance was twenty-five cubits from doorway to doorway.'),
('EZK', 40, 14, 'EZK.40.14', 'Next he measured the gateposts to be sixty cubits high. The gateway extended around to the gatepost of the courtyard.'),
('EZK', 40, 15, 'EZK.40.15', 'And the distance from the entrance of the gateway to the far end of its inner portico was fifty cubits.'),
('EZK', 40, 16, 'EZK.40.16', 'The gate chambers and their side pillars had beveled windows all around the inside of the gateway. The porticos also had windows all around on the inside. Each side pillar was decorated with palm trees.'),
('EZK', 40, 17, 'EZK.40.17', 'Then he brought me into the outer court, and there were chambers and a pavement laid out all around the court. Thirty chambers faced the pavement,'),
('EZK', 40, 18, 'EZK.40.18', 'which flanked the gateways and corresponded to the length of the gates; this was the lower pavement.'),
('EZK', 40, 19, 'EZK.40.19', 'Then he measured the distance from the front of the lower gateway to the outside of the inner court; it was a hundred cubits on the east side as well as on the north.'),
('EZK', 40, 20, 'EZK.40.20', 'He also measured the length and width of the gateway of the outer court facing north.'),
('EZK', 40, 21, 'EZK.40.21', 'Its three gate chambers on each side, its side pillars, and its portico all had the same measurements as the first gate: fifty cubits long and twenty-five cubits wide.'),
('EZK', 40, 22, 'EZK.40.22', 'Its windows, portico, and palm trees had the same measurements as those of the gate facing east. Seven steps led up to it, with its portico opposite them.'),
('EZK', 40, 23, 'EZK.40.23', 'There was a gate to the inner court facing the north gate, just as there was on the east. He measured the distance from gateway to gateway to be a hundred cubits.'),
('EZK', 40, 24, 'EZK.40.24', 'Then he led me to the south side, and I saw a gateway facing south. He measured its side pillars and portico, and they had the same measurements as the others.'),
('EZK', 40, 25, 'EZK.40.25', 'Both the gateway and its portico had windows all around, like the other windows. It was fifty cubits long and twenty-five cubits wide.'),
('EZK', 40, 26, 'EZK.40.26', 'Seven steps led up to it, and its portico was opposite them; it had palm trees on its side pillars, one on each side.'),
('EZK', 40, 27, 'EZK.40.27', 'The inner court also had a gate facing south, and he measured the distance from gateway to gateway toward the south to be a hundred cubits.'),
('EZK', 40, 28, 'EZK.40.28', 'Next he brought me into the inner court through the south gate, and he measured the south gate; it had the same measurements as the others.'),
('EZK', 40, 29, 'EZK.40.29', 'Its gate chambers, side pillars, and portico had the same measurements as the others. Both the gateway and its portico had windows all around; it was fifty cubits long and twenty-five cubits wide.'),
('EZK', 40, 30, 'EZK.40.30', '(The porticoes around the inner court were twenty-five cubits long and five cubits deep.)'),
('EZK', 40, 31, 'EZK.40.31', 'Its portico faced the outer court, and its side pillars were decorated with palm trees. Eight steps led up to it.'),
('EZK', 40, 32, 'EZK.40.32', 'And he brought me to the inner court on the east side, and he measured the gateway; it had the same measurements as the others.'),
('EZK', 40, 33, 'EZK.40.33', 'Its gate chambers, side pillars, and portico had the same measurements as the others. Both the gateway and its portico had windows all around. It was fifty cubits long and twenty-five cubits wide.'),
('EZK', 40, 34, 'EZK.40.34', 'Its portico faced the outer court, and its side pillars were decorated with palm trees on each side. Eight steps led up to it.'),
('EZK', 40, 35, 'EZK.40.35', 'Then he brought me to the north gate and measured it. It had the same measurements as the others,'),
('EZK', 40, 36, 'EZK.40.36', 'as did its gate chambers, side pillars, and portico. It also had windows all around. It was fifty cubits long and twenty-five cubits wide.'),
('EZK', 40, 37, 'EZK.40.37', 'Its portico faced the outer court, and its side pillars were decorated with palm trees on each side. Eight steps led up to it.'),
('EZK', 40, 38, 'EZK.40.38', 'There was a chamber with a doorway by the portico in each of the inner gateways. There the burnt offering was to be washed.'),
('EZK', 40, 39, 'EZK.40.39', 'Inside the portico of the gateway were two tables on each side, on which the burnt offerings, sin offerings, and guilt offerings were to be slaughtered.'),
('EZK', 40, 40, 'EZK.40.40', 'Outside, as one goes up to the entrance of the north gateway, there were two tables on one side and two more tables on the other side of the gate’s portico.'),
('EZK', 40, 41, 'EZK.40.41', 'So there were four tables inside the gateway and four outside—eight tables in all—on which the sacrifices were to be slaughtered.'),
('EZK', 40, 42, 'EZK.40.42', 'There were also four tables of dressed stone for the burnt offering, each a cubit and a half long, a cubit and a half wide, and a cubit high. On these were placed the utensils used to slaughter the burnt offerings and the other sacrifices.'),
('EZK', 40, 43, 'EZK.40.43', 'The double-pronged hooks, each a handbreadth long, were fastened all around the inside of the room, and the flesh of the offering was to be placed on the tables.'),
('EZK', 40, 44, 'EZK.40.44', 'Outside the inner gate, within the inner court, were two chambers, one beside the north gate and facing south, and another beside the south gate and facing north.'),
('EZK', 40, 45, 'EZK.40.45', 'Then the man said to me: “The chamber that faces south is for the priests who keep charge of the temple,'),
('EZK', 40, 46, 'EZK.40.46', 'and the chamber that faces north is for the priests who keep charge of the altar. These are the sons of Zadok, the only Levites who may approach the LORD to minister before Him.”'),
('EZK', 40, 47, 'EZK.40.47', 'Next he measured the court. It was square, a hundred cubits long and a hundred cubits wide. And the altar was in front of the temple.'),
('EZK', 40, 48, 'EZK.40.48', 'Then he brought me to the portico of the temple and measured the side pillars of the portico to be five cubits on each side. The width of the gateway was fourteen cubits and its sidewalls were three cubits on either side.'),
('EZK', 40, 49, 'EZK.40.49', 'The portico was twenty cubits wide and twelve cubits deep, and ten steps led up to it. There were columns by the side pillars, one on each side.'),
('EZK', 41, 1, 'EZK.41.1', 'Then the man brought me into the outer sanctuary and measured the side pillars to be six cubits wide on each side.'),
('EZK', 41, 2, 'EZK.41.2', 'The width of the entrance was ten cubits, and the sides of the entrance were five cubits on each side. He also measured the length of the outer sanctuary to be forty cubits, and the width to be twenty cubits.'),
('EZK', 41, 3, 'EZK.41.3', 'And he went into the inner sanctuary and measured the side pillars at the entrance to be two cubits wide. The entrance was six cubits wide, and the walls on each side were seven cubits wide.'),
('EZK', 41, 4, 'EZK.41.4', 'Then he measured the room adjacent to the inner sanctuary to be twenty cubits long and twenty cubits wide. And he said to me, “This is the Most Holy Place.”'),
('EZK', 41, 5, 'EZK.41.5', 'Next he measured the wall of the temple to be six cubits thick, and the width of each side room around the temple was four cubits.'),
('EZK', 41, 6, 'EZK.41.6', 'The side rooms were arranged one above another in three levels of thirty rooms each. There were ledges all around the wall of the temple to serve as supports for the side rooms, so that the supports would not be fastened into the wall of the temple itself.'),
('EZK', 41, 7, 'EZK.41.7', 'The side rooms surrounding the temple widened at each successive level, because the structure surrounding the temple ascended by stages corresponding to the narrowing of the temple wall as it rose upward. And so a stairway went up from the lowest story to the highest, through the middle one.'),
('EZK', 41, 8, 'EZK.41.8', 'I saw that the temple had a raised base all around it, forming the foundation of the side rooms. It was the full length of a rod, six long cubits.'),
('EZK', 41, 9, 'EZK.41.9', 'The outer wall of the side rooms was five cubits thick, and the open area between the side rooms of the temple'),
('EZK', 41, 10, 'EZK.41.10', 'and the outer chambers was twenty cubits wide all around the temple.'),
('EZK', 41, 11, 'EZK.41.11', 'The side rooms opened into this area, with one entrance on the north and another on the south. The open area was five cubits wide all around.'),
('EZK', 41, 12, 'EZK.41.12', 'Now the building that faced the temple courtyard on the west was seventy cubits wide, and the wall of the building was five cubits thick all around, with a length of ninety cubits.'),
('EZK', 41, 13, 'EZK.41.13', 'Then he measured the temple to be a hundred cubits long, and the temple courtyard and the building with its walls were also a hundred cubits long.'),
('EZK', 41, 14, 'EZK.41.14', 'The width of the temple courtyard on the east, including the front of the temple, was a hundred cubits.'),
('EZK', 41, 15, 'EZK.41.15', 'Next he measured the length of the building facing the temple courtyard at the rear of the temple, including its galleries on each side; it was a hundred cubits. The outer sanctuary, the inner sanctuary, and the porticoes facing the court,'),
('EZK', 41, 16, 'EZK.41.16', 'as well as the thresholds and the beveled windows and the galleries all around with their three levels opposite the threshold, were overlaid with wood on all sides. They were paneled from the ground to the windows, and the windows were covered.'),
('EZK', 41, 17, 'EZK.41.17', 'In the space above the outside of the entrance to the inner sanctuary on all the walls, spaced evenly around the inner and outer sanctuary,'),
('EZK', 41, 18, 'EZK.41.18', 'were alternating carved cherubim and palm trees. Each cherub had two faces:'),
('EZK', 41, 19, 'EZK.41.19', 'the face of a man was toward the palm tree on one side, and the face of a young lion was toward the palm tree on the other side. They were carved all the way around the temple.'),
('EZK', 41, 20, 'EZK.41.20', 'Cherubim and palm trees were carved on the wall of the outer sanctuary from the floor to the space above the entrance.'),
('EZK', 41, 21, 'EZK.41.21', 'The outer sanctuary had a rectangular doorframe, and the doorframe of the sanctuary was similar.'),
('EZK', 41, 22, 'EZK.41.22', 'There was an altar of wood three cubits high and two cubits square. Its corners, base, and sides were of wood. And the man told me, “This is the table that is before the LORD.”'),
('EZK', 41, 23, 'EZK.41.23', 'Both the outer sanctuary and the inner sanctuary had double doors,'),
('EZK', 41, 24, 'EZK.41.24', 'and each door had two swinging panels. There were two panels for one door and two for the other.'),
('EZK', 41, 25, 'EZK.41.25', 'Cherubim and palm trees like those on the walls were carved on the doors of the outer sanctuary, and there was a wooden canopy outside, on the front of the portico.'),
('EZK', 41, 26, 'EZK.41.26', 'There were beveled windows and palm trees on the sidewalls of the portico. The side rooms of the temple also had canopies.'),
('EZK', 42, 1, 'EZK.42.1', 'Then the man led me out northward into the outer court, and he brought me to the group of chambers opposite the temple courtyard and the outer wall on the north side.'),
('EZK', 42, 2, 'EZK.42.2', 'The building with the door facing north was a hundred cubits long and fifty cubits wide.'),
('EZK', 42, 3, 'EZK.42.3', 'Gallery faced gallery in three levels opposite the twenty cubits that belonged to the inner court and opposite the pavement that belonged to the outer court.'),
('EZK', 42, 4, 'EZK.42.4', 'In front of the chambers was an inner walkway ten cubits wide and a hundred cubits long. Their doors were on the north.'),
('EZK', 42, 5, 'EZK.42.5', 'Now the upper chambers were smaller because the galleries took more space from the chambers on the lower and middle floors of the building.'),
('EZK', 42, 6, 'EZK.42.6', 'For they were arranged in three stories, and unlike the courts, they had no pillars. So the upper chambers were set back further than the lower and middle floors.'),
('EZK', 42, 7, 'EZK.42.7', 'An outer wall in front of the chambers was fifty cubits long and ran parallel to the chambers and the outer court.'),
('EZK', 42, 8, 'EZK.42.8', 'For the chambers on the outer court were fifty cubits long, while those facing the temple were a hundred cubits long.'),
('EZK', 42, 9, 'EZK.42.9', 'And below these chambers was the entrance on the east side as one enters them from the outer court.'),
('EZK', 42, 10, 'EZK.42.10', 'On the south side along the length of the wall of the outer court were chambers adjoining the courtyard and opposite the building,'),
('EZK', 42, 11, 'EZK.42.11', 'with a passageway in front of them, just like the chambers that were on the north. They had the same length and width, with similar exits and dimensions.'),
('EZK', 42, 12, 'EZK.42.12', 'And corresponding to the doors of the chambers that were facing south, there was a door in front of the walkway that was parallel to the wall extending eastward.'),
('EZK', 42, 13, 'EZK.42.13', 'Then the man said to me, “The north and south chambers facing the temple courtyard are the holy chambers where the priests who approach the LORD will eat the most holy offerings. There they will place the most holy offerings—the grain offerings, the sin offerings, and the guilt offerings—for the place is holy.'),
('EZK', 42, 14, 'EZK.42.14', 'Once the priests have entered the holy area, they must not go out into the outer court until they have left behind the garments in which they minister, for these are holy. They are to put on other clothes before they approach the places that are for the people.”'),
('EZK', 42, 15, 'EZK.42.15', 'Now when the man had finished measuring the interior of the temple area, he led me out by the gate that faced east, and he measured the area all around:'),
('EZK', 42, 16, 'EZK.42.16', 'With a measuring rod he measured the east side to be five hundred cubits long.'),
('EZK', 42, 17, 'EZK.42.17', 'He measured the north side to be five hundred cubits long.'),
('EZK', 42, 18, 'EZK.42.18', 'He measured the south side to be five hundred cubits long.'),
('EZK', 42, 19, 'EZK.42.19', 'And he came around and measured the west side to be five hundred cubits long.'),
('EZK', 42, 20, 'EZK.42.20', 'So he measured the area on all four sides. It had a wall all around, five hundred cubits long and five hundred cubits wide, to separate the holy from the common.'),
('EZK', 43, 1, 'EZK.43.1', 'Then the man brought me back to the gate that faces east,'),
('EZK', 43, 2, 'EZK.43.2', 'and I saw the glory of the God of Israel coming from the east. His voice was like the roar of many waters, and the earth shone with His glory.'),
('EZK', 43, 3, 'EZK.43.3', 'The vision I saw was like the vision I had seen when He came to destroy the city and like the visions I had seen by the River Kebar. I fell facedown,'),
('EZK', 43, 4, 'EZK.43.4', 'and the glory of the LORD entered the temple through the gate facing east.'),
('EZK', 43, 5, 'EZK.43.5', 'Then the Spirit lifted me up and brought me into the inner court, and the glory of the LORD filled the temple.'),
('EZK', 43, 6, 'EZK.43.6', 'While the man was standing beside me, I heard someone speaking to me from inside the temple,'),
('EZK', 43, 7, 'EZK.43.7', 'and He said to me, “Son of man, this is the place of My throne and the place for the soles of My feet, where I will dwell among the Israelites forever. The house of Israel will never again defile My holy name—neither they nor their kings—by their prostitution and by the funeral offerings for their kings at their deaths.'),
('EZK', 43, 8, 'EZK.43.8', 'When they placed their threshold next to My threshold and their doorposts beside My doorposts, with only a wall between Me and them, they defiled My holy name by the abominations they committed. Therefore I have consumed them in My anger.'),
('EZK', 43, 9, 'EZK.43.9', 'Now let them remove far from Me their prostitution and the funeral offerings for their kings, and I will dwell among them forever.'),
('EZK', 43, 10, 'EZK.43.10', 'As for you, son of man, describe the temple to the people of Israel, so that they may be ashamed of their iniquities. Let them measure the plan,'),
('EZK', 43, 11, 'EZK.43.11', 'and if they are ashamed of all they have done, then make known to them the design of the temple—its arrangement and its exits and entrances—its whole design along with all its statutes, forms, and laws. Write it down in their sight, so that they may keep its complete design and all its statutes and may carry them out.'),
('EZK', 43, 12, 'EZK.43.12', 'This is the law of the temple: All its surrounding territory on top of the mountain will be most holy. Yes, this is the law of the temple.'),
('EZK', 43, 13, 'EZK.43.13', 'These are the measurements of the altar in long cubits (a cubit and a handbreadth): Its gutter shall be a cubit deep and a cubit wide, with a rim of one span around its edge. And this is the height of the altar:'),
('EZK', 43, 14, 'EZK.43.14', 'The space from the gutter on the ground to the lower ledge shall be two cubits, and the ledge one cubit wide. The space from the smaller ledge to the larger ledge shall be four cubits, and the ledge one cubit wide.'),
('EZK', 43, 15, 'EZK.43.15', 'The altar hearth shall be four cubits high, and four horns shall project upward from the hearth.'),
('EZK', 43, 16, 'EZK.43.16', 'The altar hearth shall be square at its four corners, twelve cubits long and twelve cubits wide.'),
('EZK', 43, 17, 'EZK.43.17', 'The ledge shall also be square, fourteen cubits long and fourteen cubits wide, with a rim of half a cubit and a gutter of a cubit all around it. The steps of the altar shall face east.”'),
('EZK', 43, 18, 'EZK.43.18', 'Then He said to me: “Son of man, this is what the Lord GOD says: ‘These are the statutes for the altar on the day it is constructed, so that burnt offerings may be sacrificed on it and blood may be splattered on it:'),
('EZK', 43, 19, 'EZK.43.19', 'You are to give a young bull from the herd as a sin offering to the Levitical priests who are of the family of Zadok, who approach Me to minister before Me, declares the Lord GOD.'),
('EZK', 43, 20, 'EZK.43.20', 'You are to take some of its blood and put it on the four horns of the altar, on the four corners of the ledge, and all around the rim; thus you will cleanse the altar and make atonement for it.'),
('EZK', 43, 21, 'EZK.43.21', 'Then you are to take away the bull for the sin offering and burn it in the appointed part of the temple area outside the sanctuary.'),
('EZK', 43, 22, 'EZK.43.22', 'On the second day you are to present an unblemished male goat as a sin offering, and the altar is to be cleansed as it was with the bull.'),
('EZK', 43, 23, 'EZK.43.23', 'When you have finished the purification, you are to present a young, unblemished bull and an unblemished ram from the flock.'),
('EZK', 43, 24, 'EZK.43.24', 'You must present them before the LORD; the priests are to sprinkle salt on them and sacrifice them as a burnt offering to the LORD.'),
('EZK', 43, 25, 'EZK.43.25', 'For seven days you are to provide a male goat daily for a sin offering; you are also to provide a young bull and a ram from the flock, both unblemished.'),
('EZK', 43, 26, 'EZK.43.26', 'For seven days the priests are to make atonement for the altar and cleanse it; so they shall consecrate it.'),
('EZK', 43, 27, 'EZK.43.27', 'At the end of these days, from the eighth day on, the priests are to present your burnt offerings and peace offerings on the altar. Then I will accept you, declares the Lord GOD.’”'),
('EZK', 44, 1, 'EZK.44.1', 'The man then brought me back to the outer gate of the sanctuary that faced east, but it was shut.'),
('EZK', 44, 2, 'EZK.44.2', 'And the LORD said to me, “This gate is to remain shut. It shall not be opened, and no man shall enter through it, because the LORD, the God of Israel, has entered through it. Therefore it will remain shut.'),
('EZK', 44, 3, 'EZK.44.3', 'Only the prince himself may sit inside the gateway to eat in the presence of the LORD. He must enter by way of the portico of the gateway and go out the same way.”'),
('EZK', 44, 4, 'EZK.44.4', 'Then the man brought me to the front of the temple by way of the north gate. I looked and saw the glory of the LORD filling His temple, and I fell facedown.'),
('EZK', 44, 5, 'EZK.44.5', 'The LORD said to me: “Son of man, pay attention; look carefully with your eyes and listen closely with your ears to everything I tell you concerning all the statutes and laws of the house of the LORD. Take careful note of the entrance to the temple, along with all the exits of the sanctuary.'),
('EZK', 44, 6, 'EZK.44.6', 'Tell the rebellious house of Israel that this is what the Lord GOD says: ‘I have had enough of all your abominations, O house of Israel.'),
('EZK', 44, 7, 'EZK.44.7', 'In addition to all your other abominations, you brought in foreigners uncircumcised in both heart and flesh to occupy My sanctuary; you defiled My temple when you offered My food—the fat and the blood; you broke My covenant.'),
('EZK', 44, 8, 'EZK.44.8', 'And you have not kept charge of My holy things, but have appointed others to keep charge of My sanctuary for you.’'),
('EZK', 44, 9, 'EZK.44.9', 'This is what the Lord GOD says: No foreigner uncircumcised in heart and flesh may enter My sanctuary—not even a foreigner who lives among the Israelites.'),
('EZK', 44, 10, 'EZK.44.10', 'Surely the Levites who wandered away from Me when Israel went astray, and who wandered away from Me after their idols, will bear the consequences of their iniquity.'),
('EZK', 44, 11, 'EZK.44.11', 'Yet they shall be ministers in My sanctuary, having charge of the gates of the temple and ministering there. They shall slaughter the burnt offerings and other sacrifices for the people and stand before them to minister to them.'),
('EZK', 44, 12, 'EZK.44.12', 'Because they ministered before their idols and became a stumbling block of iniquity to the house of Israel, therefore I swore with an uplifted hand concerning them that they would bear the consequences of their iniquity, declares the Lord GOD.'),
('EZK', 44, 13, 'EZK.44.13', 'They must not approach Me to serve Me as priests or come near any of My holy things or the most holy things. They will bear the shame of the abominations they have committed.'),
('EZK', 44, 14, 'EZK.44.14', 'Yet I will appoint them to keep charge of all the work for the temple and everything to be done in it.'),
('EZK', 44, 15, 'EZK.44.15', 'But the Levitical priests, who are descended from Zadok and who kept charge of My sanctuary when the Israelites went astray from Me, are to approach Me to minister before Me. They will stand before Me to offer Me fat and blood, declares the Lord GOD.'),
('EZK', 44, 16, 'EZK.44.16', 'They alone shall enter My sanctuary and draw near to My table to minister before Me. They will keep My charge.'),
('EZK', 44, 17, 'EZK.44.17', 'When they enter the gates of the inner court, they are to wear linen garments; they must not wear anything made of wool when they minister at the gates of the inner court or inside the temple.'),
('EZK', 44, 18, 'EZK.44.18', 'They are to wear linen turbans on their heads and linen undergarments around their waists. They must not wear anything that makes them perspire.'),
('EZK', 44, 19, 'EZK.44.19', 'When they go out to the outer court, to the people, they are to take off the garments in which they have ministered, leave them in the holy chambers, and dress in other clothes so that they do not transmit holiness to the people with their garments.'),
('EZK', 44, 20, 'EZK.44.20', 'They must not shave their heads or let their hair grow long, but must carefully trim their hair.'),
('EZK', 44, 21, 'EZK.44.21', 'No priest may drink wine before he enters the inner court.'),
('EZK', 44, 22, 'EZK.44.22', 'And they shall not marry a widow or a divorced woman, but must marry a virgin of the descendants of the house of Israel, or a widow of a priest.'),
('EZK', 44, 23, 'EZK.44.23', 'They are to teach My people the difference between the holy and the common and show them how to discern between the clean and the unclean.'),
('EZK', 44, 24, 'EZK.44.24', 'In any dispute, they shall officiate as judges and judge according to My ordinances. They must keep My laws and statutes regarding all My appointed feasts, and they must keep My Sabbaths holy.'),
('EZK', 44, 25, 'EZK.44.25', 'A priest must not defile himself by going near a dead person. However, for a father, a mother, a son, a daughter, a brother, or an unmarried sister, he may do so,'),
('EZK', 44, 26, 'EZK.44.26', 'and after he is cleansed, he must count off seven days for himself.'),
('EZK', 44, 27, 'EZK.44.27', 'And on the day he goes into the sanctuary, into the inner court, to minister in the sanctuary, he must present his sin offering, declares the Lord GOD.'),
('EZK', 44, 28, 'EZK.44.28', 'In regard to their inheritance, I am their inheritance. You are to give them no possession in Israel, for I am their possession.'),
('EZK', 44, 29, 'EZK.44.29', 'They shall eat the grain offerings, the sin offerings, and the guilt offerings. Everything in Israel devoted to the LORD will belong to them.'),
('EZK', 44, 30, 'EZK.44.30', 'The best of all the firstfruits and of every contribution from all your offerings will belong to the priests. You are to give your first batch of dough to the priest, so that a blessing may rest upon your homes.'),
('EZK', 44, 31, 'EZK.44.31', 'The priests may not eat any bird or animal found dead or torn by wild beasts.'),
('EZK', 45, 1, 'EZK.45.1', '“When you divide the land by lot as an inheritance, you are to set aside a portion for the LORD, a holy portion of the land 25,000 cubits long and 20,000 cubits wide. This entire tract of land will be holy.'),
('EZK', 45, 2, 'EZK.45.2', 'Within this area there is to be a section for the sanctuary 500 cubits square, with 50 cubits around it for open land.'),
('EZK', 45, 3, 'EZK.45.3', 'From this holy portion, you are to measure off a length of 25,000 cubits and a width of 10,000 cubits, and in it will be the sanctuary, the Most Holy Place.'),
('EZK', 45, 4, 'EZK.45.4', 'It will be a holy portion of the land to be used by the priests who minister in the sanctuary, who draw near to minister before the LORD. It will be a place for their houses, as well as a holy area for the sanctuary.'),
('EZK', 45, 5, 'EZK.45.5', 'An adjacent area 25,000 cubits long and 10,000 cubits wide shall belong to the Levites who minister in the temple; it will be their possession for towns in which to live.'),
('EZK', 45, 6, 'EZK.45.6', 'As the property of the city, you are to set aside an area 5,000 cubits wide and 25,000 cubits long, adjacent to the holy district. It will belong to the whole house of Israel.'),
('EZK', 45, 7, 'EZK.45.7', 'Now the prince will have the area bordering each side of the area formed by the holy district and the property of the city, extending westward from the western side and eastward from the eastern side, running lengthwise from the western boundary to the eastern boundary and parallel to one of the tribal portions.'),
('EZK', 45, 8, 'EZK.45.8', 'This land will be his possession in Israel. And My princes will no longer oppress My people, but will give the rest of the land to the house of Israel according to their tribes.'),
('EZK', 45, 9, 'EZK.45.9', 'For this is what the Lord GOD says: ‘Enough, O princes of Israel! Cease your violence and oppression, and do what is just and right. Stop dispossessing My people, declares the Lord GOD.’'),
('EZK', 45, 10, 'EZK.45.10', 'You must use honest scales, a just ephah, and a just bath.'),
('EZK', 45, 11, 'EZK.45.11', 'The ephah and the bath shall be the same quantity so that the bath will contain a tenth of a homer, and the ephah a tenth of a homer; the homer will be the standard measure for both.'),
('EZK', 45, 12, 'EZK.45.12', 'The shekel will consist of twenty gerahs. Twenty shekels plus twenty-five shekels plus fifteen shekels will equal one mina.'),
('EZK', 45, 13, 'EZK.45.13', 'This is the contribution you are to offer: a sixth of an ephah from each homer of wheat, and a sixth of an ephah from each homer of barley.'),
('EZK', 45, 14, 'EZK.45.14', 'The prescribed portion of oil, measured by the bath, is a tenth of a bath from each cor (a cor consists of ten baths or one homer, since ten baths are equivalent to a homer).'),
('EZK', 45, 15, 'EZK.45.15', 'And one sheep shall be given from each flock of two hundred from the well-watered pastures of Israel. These are for the grain offerings, burnt offerings, and peace offerings, to make atonement for the people, declares the Lord GOD.'),
('EZK', 45, 16, 'EZK.45.16', 'All the people of the land must participate in this contribution for the prince in Israel.'),
('EZK', 45, 17, 'EZK.45.17', 'And it shall be the prince’s part to provide the burnt offerings, grain offerings, and drink offerings for the feasts, New Moons, and Sabbaths—for all the appointed feasts of the house of Israel. He will provide the sin offerings, grain offerings, burnt offerings, and peace offerings to make atonement for the house of Israel.'),
('EZK', 45, 18, 'EZK.45.18', 'This is what the Lord GOD says: ‘On the first day of the first month you are to take a young bull without blemish and purify the sanctuary.'),
('EZK', 45, 19, 'EZK.45.19', 'And the priest is to take some of the blood from the sin offering and put it on the doorposts of the temple, on the four corners of the ledge of the altar, and on the gateposts of the inner court.'),
('EZK', 45, 20, 'EZK.45.20', 'You must do the same thing on the seventh day of the month for anyone who strays unintentionally or in ignorance. In this way you will make atonement for the temple.'),
('EZK', 45, 21, 'EZK.45.21', 'On the fourteenth day of the first month you are to observe the Passover, a feast of seven days, during which unleavened bread shall be eaten.'),
('EZK', 45, 22, 'EZK.45.22', 'On that day the prince shall provide a bull as a sin offering for himself and for all the people of the land.'),
('EZK', 45, 23, 'EZK.45.23', 'Each day during the seven days of the feast, he shall provide seven bulls and seven rams without blemish as a burnt offering to the LORD, along with a male goat for a sin offering.'),
('EZK', 45, 24, 'EZK.45.24', 'He shall also provide as a grain offering an ephah for each bull and an ephah for each ram, along with a hin of olive oil for each ephah of grain.'),
('EZK', 45, 25, 'EZK.45.25', 'During the seven days of the feast that begins on the fifteenth day of the seventh month, he is to make the same provision for sin offerings, burnt offerings, grain offerings, and oil.’'),
('EZK', 46, 1, 'EZK.46.1', '“This is what the Lord GOD says: ‘The gate of the inner court that faces east must be kept shut during the six days of work, but on the Sabbath day and on the day of the New Moon it shall be opened.'),
('EZK', 46, 2, 'EZK.46.2', 'The prince is to enter from the outside through the portico of the gateway and stand by the gatepost, while the priests sacrifice his burnt offerings and peace offerings. He is to bow in worship at the threshold of the gate and then depart, but the gate must not be shut until evening.'),
('EZK', 46, 3, 'EZK.46.3', 'On the Sabbaths and New Moons the people of the land are also to bow in worship before the LORD at the entrance to that gateway.'),
('EZK', 46, 4, 'EZK.46.4', 'The burnt offering that the prince presents to the LORD on the Sabbath day shall be six unblemished male lambs and an unblemished ram.'),
('EZK', 46, 5, 'EZK.46.5', 'The grain offering with the ram shall be one ephah, and the grain offering with the lambs shall be as much as he is able, along with a hin of oil per ephah.'),
('EZK', 46, 6, 'EZK.46.6', 'On the day of the New Moon he shall offer a young, unblemished bull, six lambs, and a ram without blemish.'),
('EZK', 46, 7, 'EZK.46.7', 'He is to provide a grain offering of an ephah with the bull, an ephah with the ram, and as much as he is able with the lambs, along with a hin of oil per ephah.'),
('EZK', 46, 8, 'EZK.46.8', 'When the prince enters, he shall go in through the portico of the gateway, and he shall go out the same way.'),
('EZK', 46, 9, 'EZK.46.9', 'When the people of the land come before the LORD at the appointed feasts, whoever enters by the north gate to worship must go out by the south gate, and whoever enters by the south gate must go out by the north gate. No one is to return through the gate by which he entered, but each must go out by the opposite gate.'),
('EZK', 46, 10, 'EZK.46.10', 'When the people enter, the prince shall go in with them, and when they leave, he shall leave.'),
('EZK', 46, 11, 'EZK.46.11', 'At the festivals and appointed feasts, the grain offering shall be an ephah with a bull, an ephah with a ram, and as much as one is able to give with the lambs, along with a hin of oil per ephah.'),
('EZK', 46, 12, 'EZK.46.12', 'When the prince makes a freewill offering to the LORD, whether a burnt offering or a peace offering, the gate facing east must be opened for him. He is to offer his burnt offering or peace offering just as he does on the Sabbath day. Then he shall go out, and the gate must be closed after he goes out.'),
('EZK', 46, 13, 'EZK.46.13', 'And you shall provide an unblemished year-old lamb as a daily burnt offering to the LORD; you are to offer it every morning.'),
('EZK', 46, 14, 'EZK.46.14', 'You are also to provide with it every morning a grain offering of a sixth of an ephah with a third of a hin of oil to moisten the fine flour—a grain offering to the LORD. This is a permanent statute.'),
('EZK', 46, 15, 'EZK.46.15', 'Thus they shall provide the lamb, the grain offering, and the oil every morning as a regular burnt offering.’'),
('EZK', 46, 16, 'EZK.46.16', 'This is what the Lord GOD says: ‘If the prince gives a gift to any of his sons as an inheritance, it will belong to his descendants. It will become their property by inheritance.'),
('EZK', 46, 17, 'EZK.46.17', 'But if he gives a gift from his inheritance to one of his servants, it will belong to that servant until the year of freedom; then it will revert to the prince. His inheritance belongs only to his sons; it shall be theirs.'),
('EZK', 46, 18, 'EZK.46.18', 'The prince must not take any of the inheritance of the people by evicting them from their property. He is to provide an inheritance for his sons from his own property, so that none of My people will be displaced from his property.’”'),
('EZK', 46, 19, 'EZK.46.19', 'Then the man brought me through the entrance at the side of the gate into the holy chambers facing north, which belonged to the priests, and he showed me a place there at the far western end'),
('EZK', 46, 20, 'EZK.46.20', 'and said to me, “This is the place where the priests shall boil the guilt offering and the sin offering, and where they shall bake the grain offering, so that they do not bring them into the outer court and transmit holiness to the people.”'),
('EZK', 46, 21, 'EZK.46.21', 'Then he brought me into the outer court and led me around to its four corners, and I saw a separate court in each of its corners.'),
('EZK', 46, 22, 'EZK.46.22', 'In the four corners of the outer court there were enclosed courts, each forty cubits long and thirty cubits wide. Each of the four corner areas had the same dimensions.'),
('EZK', 46, 23, 'EZK.46.23', 'Around the inside of each of the four courts was a row of masonry with ovens built at the base of the walls on all sides.'),
('EZK', 46, 24, 'EZK.46.24', 'And he said to me, “These are the kitchens where those who minister at the temple will cook the sacrifices offered by the people.”'),
('EZK', 47, 1, 'EZK.47.1', 'Then the man brought me back to the entrance of the temple, and I saw water flowing from under the threshold of the temple toward the east (for the temple faced east). The water was coming down from under the south side of the temple, south of the altar.'),
('EZK', 47, 2, 'EZK.47.2', 'Next he brought me out through the north gate and led me around the outside to the outer gate facing east, and there I saw the water trickling out from the south side.'),
('EZK', 47, 3, 'EZK.47.3', 'As the man went eastward with a measuring line in his hand, he measured off a thousand cubits and led me through ankle-deep water.'),
('EZK', 47, 4, 'EZK.47.4', 'Then he measured off a thousand cubits and led me through knee-deep water. Again he measured a thousand cubits and led me through waist-deep water.'),
('EZK', 47, 5, 'EZK.47.5', 'Once again he measured off a thousand cubits, but now it was a river that I could not cross, because the water had risen and was deep enough for swimming—a river that could not be crossed on foot.'),
('EZK', 47, 6, 'EZK.47.6', '“Son of man, do you see this?” he asked. Then he led me back to the bank of the river.'),
('EZK', 47, 7, 'EZK.47.7', 'When I arrived, I saw a great number of trees along both banks of the river.'),
('EZK', 47, 8, 'EZK.47.8', 'And he said to me, “This water flows out to the eastern region and goes down into the Arabah. When it empties into the Dead Sea, the water there becomes fresh.'),
('EZK', 47, 9, 'EZK.47.9', 'Wherever the river flows, there will be swarms of living creatures and a great number of fish, because it flows there and makes the waters fresh; so wherever the river flows, everything will flourish.'),
('EZK', 47, 10, 'EZK.47.10', 'Fishermen will stand by the shore; from En-gedi to En-eglaim they will spread their nets to catch fish of many kinds, like the fish of the Great Sea.'),
('EZK', 47, 11, 'EZK.47.11', 'But the swamps and marshes will not become fresh; they will be left for salt.'),
('EZK', 47, 12, 'EZK.47.12', 'Along both banks of the river, fruit trees of all kinds will grow. Their leaves will not wither, and their fruit will not fail. Each month they will bear fruit, because the water from the sanctuary flows to them. Their fruit will be used for food and their leaves for healing.”'),
('EZK', 47, 13, 'EZK.47.13', 'This is what the Lord GOD says: “These are the boundaries by which you are to divide the land as an inheritance among the twelve tribes of Israel; Joseph shall receive two portions.'),
('EZK', 47, 14, 'EZK.47.14', 'You are to divide it equally among them. Because I swore with an uplifted hand to give it to your forefathers, this land will fall to you as an inheritance.'),
('EZK', 47, 15, 'EZK.47.15', 'This shall be the boundary of the land: On the north side it will extend from the Great Sea by way of Hethlon through Lebo-hamath to Zedad,'),
('EZK', 47, 16, 'EZK.47.16', 'Berothah, and Sibraim (which is on the border between Damascus and Hamath), as far as Hazer-hatticon, which is on the border of Hauran.'),
('EZK', 47, 17, 'EZK.47.17', 'So the border will run from the Sea to Hazar-enan, along the northern border of Damascus, with the territory of Hamath to the north. This will be the northern boundary.'),
('EZK', 47, 18, 'EZK.47.18', 'On the east side the border will run between Hauran and Damascus, along the Jordan between Gilead and the land of Israel, to the Eastern Sea and as far as Tamar. This will be the eastern boundary.'),
('EZK', 47, 19, 'EZK.47.19', 'On the south side it will run from Tamar to the waters of Meribath-kadesh, and along the Brook of Egypt to the Great Sea. This will be the southern boundary.'),
('EZK', 47, 20, 'EZK.47.20', 'And on the west side, the Great Sea will be the boundary up to a point opposite Lebo-hamath. This will be the western boundary.'),
('EZK', 47, 21, 'EZK.47.21', 'You are to divide this land among yourselves according to the tribes of Israel.'),
('EZK', 47, 22, 'EZK.47.22', 'You shall allot it as an inheritance for yourselves and for the foreigners who dwell among you and who have children. You are to treat them as native-born Israelites; along with you, they shall be allotted an inheritance among the tribes of Israel.'),
('EZK', 47, 23, 'EZK.47.23', 'In whatever tribe a foreigner dwells, you are to assign his inheritance there,” declares the Lord GOD.'),
('EZK', 48, 1, 'EZK.48.1', '“Now these are the names of the tribes: At the northern frontier, Dan will have one portion bordering the road of Hethlon to Lebo-hamath and running on to Hazar-enan on the border of Damascus with Hamath to the north, and extending from the east side to the west side.'),
('EZK', 48, 2, 'EZK.48.2', 'Asher will have one portion bordering the territory of Dan from east to west.'),
('EZK', 48, 3, 'EZK.48.3', 'Naphtali will have one portion bordering the territory of Asher from east to west.'),
('EZK', 48, 4, 'EZK.48.4', 'Manasseh will have one portion bordering the territory of Naphtali from east to west.'),
('EZK', 48, 5, 'EZK.48.5', 'Ephraim will have one portion bordering the territory of Manasseh from east to west.'),
('EZK', 48, 6, 'EZK.48.6', 'Reuben will have one portion bordering the territory of Ephraim from east to west.'),
('EZK', 48, 7, 'EZK.48.7', 'Judah will have one portion bordering the territory of Reuben from east to west.'),
('EZK', 48, 8, 'EZK.48.8', 'Bordering the territory of Judah, from east to west, will be the portion you are to set apart. It will be 25,000 cubits wide, and the length of a tribal portion from east to west. In the center will be the sanctuary.'),
('EZK', 48, 9, 'EZK.48.9', 'The special portion you set apart to the LORD shall be 25,000 cubits long and 10,000 cubits wide.'),
('EZK', 48, 10, 'EZK.48.10', 'This will be the holy portion for the priests. It will be 25,000 cubits long on the north side, 10,000 cubits wide on the west side, 10,000 cubits wide on the east side, and 25,000 cubits long on the south side. In the center will be the sanctuary of the LORD.'),
('EZK', 48, 11, 'EZK.48.11', 'It will be for the consecrated priests, the descendants of Zadok, who kept My charge and did not go astray as the Levites did when the Israelites went astray.'),
('EZK', 48, 12, 'EZK.48.12', 'It will be a special portion for them set apart from the land, a most holy portion adjacent to the territory of the Levites.'),
('EZK', 48, 13, 'EZK.48.13', 'Bordering the territory of the priests, the Levites shall have an area 25,000 cubits long and 10,000 cubits wide. The whole length will be 25,000 cubits, and the width 10,000 cubits.'),
('EZK', 48, 14, 'EZK.48.14', 'They must not sell or exchange any of it, and they must not transfer this best part of the land, for it is holy to the LORD.'),
('EZK', 48, 15, 'EZK.48.15', 'The remaining area, 5,000 cubits wide and 25,000 cubits long, will be for common use by the city, for houses, and for pastureland. The city will be in the center of it'),
('EZK', 48, 16, 'EZK.48.16', 'and will have these measurements: 4,500 cubits on the north side, 4,500 cubits on the south side, 4,500 cubits on the east side, and 4,500 cubits on the west side.'),
('EZK', 48, 17, 'EZK.48.17', 'The pastureland of the city will extend 250 cubits to the north, 250 cubits to the south, 250 cubits to the east, and 250 cubits to the west.'),
('EZK', 48, 18, 'EZK.48.18', 'The remainder of the length bordering the holy portion and running adjacent to it will be 10,000 cubits on the east side and 10,000 cubits on the west side. Its produce will supply food for the workers of the city.'),
('EZK', 48, 19, 'EZK.48.19', 'The workers of the city who cultivate it will come from all the tribes of Israel.'),
('EZK', 48, 20, 'EZK.48.20', 'The entire portion will be a square, 25,000 cubits by 25,000 cubits. You are to set apart the holy portion, along with the city property.'),
('EZK', 48, 21, 'EZK.48.21', 'The remaining area on both sides of the holy portion and of the property of the city will belong to the prince. He will own the land adjacent to the tribal portions, extending eastward from the 25,000 cubits of the holy district toward the eastern border, and westward from the 25,000 cubits to the western border. And in the center of them will be the holy portion and the sanctuary of the temple.'),
('EZK', 48, 22, 'EZK.48.22', 'So the Levitical property and the city property will lie in the center of the area belonging to the prince—the area between the borders of Judah and Benjamin.'),
('EZK', 48, 23, 'EZK.48.23', 'As for the rest of the tribes: Benjamin will have one portion extending from the east side to the west side.'),
('EZK', 48, 24, 'EZK.48.24', 'Simeon will have one portion bordering the territory of Benjamin from east to west.'),
('EZK', 48, 25, 'EZK.48.25', 'Issachar will have one portion bordering the territory of Simeon from east to west.'),
('EZK', 48, 26, 'EZK.48.26', 'Zebulun will have one portion bordering the territory of Issachar from east to west.'),
('EZK', 48, 27, 'EZK.48.27', 'And Gad will have one portion bordering the territory of Zebulun from east to west.'),
('EZK', 48, 28, 'EZK.48.28', 'The southern border of Gad will run from Tamar to the waters of Meribath-kadesh, then along the Brook of Egypt and out to the Great Sea.'),
('EZK', 48, 29, 'EZK.48.29', 'This is the land you are to allot as an inheritance to the tribes of Israel, and these will be their portions,” declares the Lord GOD.'),
('EZK', 48, 30, 'EZK.48.30', '“These will be the exits of the city: Beginning on the north side, which will be 4,500 cubits long,'),
('EZK', 48, 31, 'EZK.48.31', 'the gates of the city will be named after the tribes of Israel. On the north side there will be three gates: the gate of Reuben, the gate of Judah, and the gate of Levi.'),
('EZK', 48, 32, 'EZK.48.32', 'On the east side, which will be 4,500 cubits long, there will be three gates: the gate of Joseph, the gate of Benjamin, and the gate of Dan.'),
('EZK', 48, 33, 'EZK.48.33', 'On the south side, which will be 4,500 cubits long, there will be three gates: the gate of Simeon, the gate of Issachar, and the gate of Zebulun.'),
('EZK', 48, 34, 'EZK.48.34', 'And on the west side, which will be 4,500 cubits long, there will be three gates: the gate of Gad, the gate of Asher, and the gate of Naphtali.'),
('EZK', 48, 35, 'EZK.48.35', 'The perimeter of the city will be 18,000 cubits, and from that day on the name of the city will be: THE LORD IS THERE.”'),
('DAN', 1, 1, 'DAN.1.1', 'In the third year of the reign of Jehoiakim king of Judah, Nebuchadnezzar king of Babylon came to Jerusalem and besieged it.'),
('DAN', 1, 2, 'DAN.1.2', 'And the Lord delivered into his hand Jehoiakim king of Judah, along with some of the articles from the house of God. He carried these off to the land of Shinar, to the house of his god, where he put them in the treasury of his god.'),
('DAN', 1, 3, 'DAN.1.3', 'Then the king ordered Ashpenaz, the chief of his court officials, to bring in some Israelites from the royal family and the nobility—'),
('DAN', 1, 4, 'DAN.1.4', 'young men without blemish, handsome, gifted in all wisdom, knowledgeable, quick to understand, and qualified to serve in the king’s palace—and to teach them the language and literature of the Chaldeans.'),
('DAN', 1, 5, 'DAN.1.5', 'The king assigned them daily provisions of the royal food and wine. They were to be trained for three years, after which they were to enter the king’s service.'),
('DAN', 1, 6, 'DAN.1.6', 'Among these young men were some from Judah: Daniel, Hananiah, Mishael, and Azariah.'),
('DAN', 1, 7, 'DAN.1.7', 'The chief official gave them new names: To Daniel he gave the name Belteshazzar; to Hananiah, Shadrach; to Mishael, Meshach; and to Azariah, Abednego.'),
('DAN', 1, 8, 'DAN.1.8', 'But Daniel made up his mind that he would not defile himself with the king’s food or wine. So he asked the chief official for permission not to defile himself.'),
('DAN', 1, 9, 'DAN.1.9', 'Now God had granted Daniel favor and compassion from the chief official,'),
('DAN', 1, 10, 'DAN.1.10', 'but he said to Daniel, “I fear my lord the king, who has assigned your food and drink. For why should he see your faces looking thinner than those of the other young men your age? You would endanger my head before the king!”'),
('DAN', 1, 11, 'DAN.1.11', 'Then Daniel said to the steward whom the chief official had appointed over Daniel, Hananiah, Mishael, and Azariah,'),
('DAN', 1, 12, 'DAN.1.12', '“Please test your servants for ten days. Let us be given only vegetables to eat and water to drink.'),
('DAN', 1, 13, 'DAN.1.13', 'Then compare our appearances with those of the young men who are eating the royal food, and deal with your servants according to what you see.”'),
('DAN', 1, 14, 'DAN.1.14', 'So he consented to this and tested them for ten days.'),
('DAN', 1, 15, 'DAN.1.15', 'And at the end of ten days, they looked healthier and better nourished than all the young men who were eating the king’s food.'),
('DAN', 1, 16, 'DAN.1.16', 'So the steward continued to withhold their choice food and the wine they were to drink, and he gave them vegetables instead.'),
('DAN', 1, 17, 'DAN.1.17', 'To these four young men God gave knowledge and understanding in every kind of literature and wisdom. And Daniel had insight into all kinds of visions and dreams.'),
('DAN', 1, 18, 'DAN.1.18', 'Now at the end of the time specified by the king, the chief official presented them to Nebuchadnezzar.'),
('DAN', 1, 19, 'DAN.1.19', 'And the king spoke with them, and among all the young men he found no one equal to Daniel, Hananiah, Mishael, and Azariah. So they entered the king’s service.'),
('DAN', 1, 20, 'DAN.1.20', 'In every matter of wisdom and understanding about which the king consulted them, he found them ten times better than all the magicians and enchanters in his entire kingdom.'),
('DAN', 1, 21, 'DAN.1.21', 'And Daniel remained there until the first year of King Cyrus.'),
('DAN', 2, 1, 'DAN.2.1', 'In the second year of his reign, Nebuchadnezzar had dreams that troubled his spirit, and sleep escaped him.'),
('DAN', 2, 2, 'DAN.2.2', 'So the king gave orders to summon the magicians, enchanters, sorcerers, and astrologers to explain his dreams. When they came and stood before the king,'),
('DAN', 2, 3, 'DAN.2.3', 'he said to them, “I have had a dream, and my spirit is anxious to understand it.”'),
('DAN', 2, 4, 'DAN.2.4', 'Then the astrologers answered the king in Aramaic, “O king, may you live forever! Tell your servants the dream, and we will give the interpretation.”'),
('DAN', 2, 5, 'DAN.2.5', 'The king replied to the astrologers, “My word is final: If you do not tell me the dream and its interpretation, you will be cut into pieces and your houses will be reduced to rubble.'),
('DAN', 2, 6, 'DAN.2.6', 'But if you tell me the dream and its interpretation, you will receive from me gifts and rewards and great honor. So tell me the dream and its interpretation.”'),
('DAN', 2, 7, 'DAN.2.7', 'They answered a second time, “Let the king tell the dream to his servants, and we will give the interpretation.”'),
('DAN', 2, 8, 'DAN.2.8', 'The king replied, “I know for sure that you are stalling for time because you see that my word is final.'),
('DAN', 2, 9, 'DAN.2.9', 'If you do not tell me the dream, there is only one decree for you. You have conspired to speak before me false and fraudulent words, hoping the situation will change. Therefore tell me the dream, and I will know that you can give me its interpretation.”'),
('DAN', 2, 10, 'DAN.2.10', 'The astrologers answered the king, “No one on earth can do what the king requests! No king, however great and powerful, has ever asked anything like this of any magician, enchanter, or astrologer.'),
('DAN', 2, 11, 'DAN.2.11', 'What the king requests is so difficult that no one can tell it to him except the gods, whose dwelling is not with mortals.”'),
('DAN', 2, 12, 'DAN.2.12', 'This response made the king so angry and furious that he gave orders to destroy all the wise men of Babylon.'),
('DAN', 2, 13, 'DAN.2.13', 'So the decree went out that the wise men were to be executed, and men went to look for Daniel and his friends to execute them.'),
('DAN', 2, 14, 'DAN.2.14', 'When Arioch, the commander of the king’s guard, went out to execute the wise men of Babylon, Daniel responded with discretion and tact.'),
('DAN', 2, 15, 'DAN.2.15', '“Why is the decree from the king so harsh?” he asked. Then Arioch explained the situation to Daniel.'),
('DAN', 2, 16, 'DAN.2.16', 'So Daniel went in and asked the king to give him some time, so that he could give him the interpretation.'),
('DAN', 2, 17, 'DAN.2.17', 'Then Daniel returned to his house and explained the matter to his friends Hananiah, Mishael, and Azariah,'),
('DAN', 2, 18, 'DAN.2.18', 'urging them to plead for mercy from the God of heaven concerning this mystery, so that Daniel and his friends would not be killed with the rest of the wise men of Babylon.'),
('DAN', 2, 19, 'DAN.2.19', 'During the night, the mystery was revealed to Daniel in a vision, and he blessed the God of heaven'),
('DAN', 2, 20, 'DAN.2.20', 'and declared: “Blessed be the name of God forever and ever, for wisdom and power belong to Him.'),
('DAN', 2, 21, 'DAN.2.21', 'He changes the times and seasons; He removes kings and establishes them. He gives wisdom to the wise and knowledge to the discerning.'),
('DAN', 2, 22, 'DAN.2.22', 'He reveals the deep and hidden things; He knows what lies in darkness, and light dwells with Him.'),
('DAN', 2, 23, 'DAN.2.23', 'To You, O God of my fathers, I give thanks and praise, because You have given me wisdom and power. And now You have made known to me what we have requested, for You have made known to us the dream of the king.”'),
('DAN', 2, 24, 'DAN.2.24', 'Therefore Daniel went to Arioch, whom the king had appointed to destroy the wise men of Babylon, and said to him, “Do not execute the wise men of Babylon! Bring me before the king, and I will give him the interpretation.”'),
('DAN', 2, 25, 'DAN.2.25', 'Arioch hastily brought Daniel before the king and said to him, “I have found a man among the exiles from Judah who will tell the king the interpretation.”'),
('DAN', 2, 26, 'DAN.2.26', 'The king responded to Daniel, whose name was Belteshazzar, “Are you able to tell me what I saw in the dream, as well as its interpretation?”'),
('DAN', 2, 27, 'DAN.2.27', 'Daniel answered the king, “No wise man, enchanter, medium, or magician can explain to the king the mystery of which he inquires.'),
('DAN', 2, 28, 'DAN.2.28', 'But there is a God in heaven who reveals mysteries, and He has made known to King Nebuchadnezzar what will happen in the latter days. Your dream and the visions that came into your mind as you lay on your bed were these:'),
('DAN', 2, 29, 'DAN.2.29', 'As you lay on your bed, O king, your thoughts turned to the future, and the Revealer of Mysteries made known to you what will happen.'),
('DAN', 2, 30, 'DAN.2.30', 'And to me this mystery has been revealed, not because I have more wisdom than any man alive, but in order that the interpretation might be made known to the king, and that you may understand the thoughts of your mind.'),
('DAN', 2, 31, 'DAN.2.31', 'As you, O king, were watching, a great statue appeared. A great and dazzling statue stood before you, and its form was awesome.'),
('DAN', 2, 32, 'DAN.2.32', 'The head of the statue was pure gold, its chest and arms were silver, its belly and thighs were bronze,'),
('DAN', 2, 33, 'DAN.2.33', 'its legs were iron, and its feet were part iron and part clay.'),
('DAN', 2, 34, 'DAN.2.34', 'As you watched, a stone was cut out, but not by human hands. It struck the statue on its feet of iron and clay, and crushed them.'),
('DAN', 2, 35, 'DAN.2.35', 'Then the iron, clay, bronze, silver, and gold were shattered and became like chaff on the threshing floor in summer. The wind carried them away, and not a trace of them could be found. But the stone that had struck the statue became a great mountain and filled the whole earth.'),
('DAN', 2, 36, 'DAN.2.36', 'This was the dream; now we will tell the king its interpretation.'),
('DAN', 2, 37, 'DAN.2.37', 'You, O king, are the king of kings, to whom the God of heaven has given sovereignty, power, strength, and glory.'),
('DAN', 2, 38, 'DAN.2.38', 'Wherever the sons of men or beasts of the field or birds of the air dwell, He has given them into your hand and has made you ruler over them all. You are that head of gold.'),
('DAN', 2, 39, 'DAN.2.39', 'But after you, there will arise another kingdom, inferior to yours. Next, a third kingdom, one of bronze, will rule the whole earth.'),
('DAN', 2, 40, 'DAN.2.40', 'Finally, there will be a fourth kingdom as strong as iron; for iron shatters and crushes all things, and like iron that crushes all things, it will shatter and crush all the others.'),
('DAN', 2, 41, 'DAN.2.41', 'And just as you saw that the feet and toes were made partly of fired clay and partly of iron, so this will be a divided kingdom, yet some of the strength of iron will be in it—just as you saw the iron mixed with clay.'),
('DAN', 2, 42, 'DAN.2.42', 'And as the toes of the feet were partly iron and partly clay, so this kingdom will be partly strong and partly brittle.'),
('DAN', 2, 43, 'DAN.2.43', 'As you saw the iron mixed with clay, so the peoples will mix with one another but will not hold together any more than iron mixes with clay.'),
('DAN', 2, 44, 'DAN.2.44', 'In the days of those kings, the God of heaven will set up a kingdom that will never be destroyed, nor will it be left to another people. It will shatter all these kingdoms and bring them to an end, but will itself stand forever.'),
('DAN', 2, 45, 'DAN.2.45', 'And just as you saw a stone being cut out of the mountain without human hands, and it shattered the iron, bronze, clay, silver, and gold, so the great God has told the king what will happen in the future. The dream is true, and its interpretation is trustworthy.”'),
('DAN', 2, 46, 'DAN.2.46', 'At this, King Nebuchadnezzar fell on his face, paid homage to Daniel, and ordered that an offering and incense be presented to him.'),
('DAN', 2, 47, 'DAN.2.47', 'The king said to Daniel, “Your God is truly the God of gods and Lord of kings, the Revealer of Mysteries, since you were able to reveal this mystery.”'),
('DAN', 2, 48, 'DAN.2.48', 'Then the king promoted Daniel and gave him many generous gifts. He made him ruler over the entire province of Babylon and chief administrator over all the wise men of Babylon.'),
('DAN', 2, 49, 'DAN.2.49', 'And at Daniel’s request, the king appointed Shadrach, Meshach, and Abednego to manage the province of Babylon, while Daniel remained in the king’s court.'),
('DAN', 3, 1, 'DAN.3.1', 'King Nebuchadnezzar made a golden statue sixty cubits high and six cubits wide, and he set it up on the plain of Dura in the province of Babylon.'),
('DAN', 3, 2, 'DAN.3.2', 'Then King Nebuchadnezzar sent word to assemble the satraps, prefects, governors, advisers, treasurers, judges, magistrates, and all the other officials of the provinces to attend the dedication of the statue he had set up.'),
('DAN', 3, 3, 'DAN.3.3', 'So the satraps, prefects, governors, advisers, treasurers, judges, magistrates, and all the rulers of the provinces assembled for the dedication of the statue that King Nebuchadnezzar had set up, and they stood before it.'),
('DAN', 3, 4, 'DAN.3.4', 'Then the herald loudly proclaimed, “O people of every nation and language, this is what you are commanded:'),
('DAN', 3, 5, 'DAN.3.5', 'As soon as you hear the sound of the horn, flute, zither, lyre, harp, pipes, and all kinds of music, you must fall down and worship the golden statue that King Nebuchadnezzar has set up.'),
('DAN', 3, 6, 'DAN.3.6', 'And whoever does not fall down and worship will immediately be thrown into the blazing fiery furnace.”'),
('DAN', 3, 7, 'DAN.3.7', 'Therefore, as soon as all the people heard the sound of the horn, flute, zither, lyre, harp, and all kinds of music, the people of every nation and language would fall down and worship the golden statue that King Nebuchadnezzar had set up.'),
('DAN', 3, 8, 'DAN.3.8', 'At this time some astrologers came forward and maliciously accused the Jews,'),
('DAN', 3, 9, 'DAN.3.9', 'saying to King Nebuchadnezzar, “O king, may you live forever!'),
('DAN', 3, 10, 'DAN.3.10', 'You, O king, have issued a decree that everyone who hears the sound of the horn, flute, zither, lyre, harp, pipes, and all kinds of music must fall down and worship the golden statue,'),
('DAN', 3, 11, 'DAN.3.11', 'and that whoever does not fall down and worship will be thrown into the blazing fiery furnace.'),
('DAN', 3, 12, 'DAN.3.12', 'But there are some Jews you have appointed to manage the province of Babylon—Shadrach, Meshach, and Abednego—who have ignored you, O king, and have refused to serve your gods or worship the golden statue you have set up.”'),
('DAN', 3, 13, 'DAN.3.13', 'Then Nebuchadnezzar, furious with rage, summoned Shadrach, Meshach, and Abednego. So these men were brought before the king,'),
('DAN', 3, 14, 'DAN.3.14', 'and Nebuchadnezzar said to them, “Shadrach, Meshach, and Abednego, is it true that you do not serve my gods or worship the golden statue I have set up?'),
('DAN', 3, 15, 'DAN.3.15', 'Now when you hear the sound of the horn, flute, zither, lyre, harp, pipes, and all kinds of music, if you are ready to fall down and worship the statue I have made, very good. But if you refuse to worship, you will be thrown at once into the blazing fiery furnace. Then what god will be able to deliver you from my hands?”'),
('DAN', 3, 16, 'DAN.3.16', 'Shadrach, Meshach, and Abednego replied to the king, “O Nebuchadnezzar, we have no need to answer you in this matter.'),
('DAN', 3, 17, 'DAN.3.17', 'If the God whom we serve exists, then He is able to deliver us from the blazing fiery furnace and from your hand, O king.'),
('DAN', 3, 18, 'DAN.3.18', 'But even if He does not, let it be known to you, O king, that we will not serve your gods or worship the golden statue you have set up.”'),
('DAN', 3, 19, 'DAN.3.19', 'At this, Nebuchadnezzar was filled with rage, and the expression on his face changed toward Shadrach, Meshach, and Abednego. He gave orders to heat the furnace seven times hotter than usual,'),
('DAN', 3, 20, 'DAN.3.20', 'and he commanded some mighty men of valor in his army to tie up Shadrach, Meshach, and Abednego and throw them into the blazing fiery furnace.'),
('DAN', 3, 21, 'DAN.3.21', 'So they were tied up, wearing robes, trousers, turbans, and other clothes, and they were thrown into the blazing fiery furnace.'),
('DAN', 3, 22, 'DAN.3.22', 'The king’s command was so urgent and the furnace so hot that the fiery flames killed the men who carried up Shadrach, Meshach, and Abednego.'),
('DAN', 3, 23, 'DAN.3.23', 'And these three men, Shadrach, Meshach, and Abednego, firmly bound, fell into the blazing fiery furnace.'),
('DAN', 3, 24, 'DAN.3.24', 'Suddenly King Nebuchadnezzar jumped up in amazement and asked his advisers, “Did we not throw three men, firmly bound, into the fire?” “Certainly, O king,” they replied.'),
('DAN', 3, 25, 'DAN.3.25', '“Look!” he exclaimed. “I see four men, unbound and unharmed, walking around in the fire—and the fourth looks like a son of the gods!”'),
('DAN', 3, 26, 'DAN.3.26', 'Then Nebuchadnezzar approached the door of the blazing fiery furnace and called out, “Shadrach, Meshach, and Abednego, servants of the Most High God, come out!” So Shadrach, Meshach, and Abednego came out of the fire,'),
('DAN', 3, 27, 'DAN.3.27', 'and when the satraps, prefects, governors, and royal advisers had gathered around, they saw that the fire had no effect on the bodies of these men. Not a hair of their heads was singed, their robes were unaffected, and there was no smell of fire on them.'),
('DAN', 3, 28, 'DAN.3.28', 'Nebuchadnezzar declared, “Blessed be the God of Shadrach, Meshach, and Abednego, who has sent His angel and delivered His servants who trusted in Him. They violated the king’s command and risked their lives rather than serve or worship any god except their own God.'),
('DAN', 3, 29, 'DAN.3.29', 'Therefore I decree that the people of any nation or language who say anything offensive against the God of Shadrach, Meshach, and Abednego will be cut into pieces and their houses reduced to rubble. For there is no other god who can deliver in this way.”'),
('DAN', 3, 30, 'DAN.3.30', 'Then the king promoted Shadrach, Meshach, and Abednego in the province of Babylon.'),
('DAN', 4, 1, 'DAN.4.1', 'King Nebuchadnezzar, To the people of every nation and language who dwell in all the earth: May your prosperity be multiplied.'),
('DAN', 4, 2, 'DAN.4.2', 'I am pleased to declare the signs and wonders that the Most High God has performed for me.'),
('DAN', 4, 3, 'DAN.4.3', 'How great are His signs, how mighty His wonders! His kingdom is an eternal kingdom; His dominion endures from generation to generation.'),
('DAN', 4, 4, 'DAN.4.4', 'I, Nebuchadnezzar, was at ease in my house and flourishing in my palace.'),
('DAN', 4, 5, 'DAN.4.5', 'I had a dream, and it frightened me; while I was in my bed, the images and visions in my mind alarmed me.'),
('DAN', 4, 6, 'DAN.4.6', 'So I issued a decree that all the wise men of Babylon be brought before me to interpret the dream for me.'),
('DAN', 4, 7, 'DAN.4.7', 'When the magicians, enchanters, astrologers, and diviners came in, I told them the dream, but they could not interpret it for me.'),
('DAN', 4, 8, 'DAN.4.8', 'But at last, into my presence came Daniel (whose name is Belteshazzar after the name of my god, and in whom is the spirit of the holy gods). And I told him the dream:'),
('DAN', 4, 9, 'DAN.4.9', '“O Belteshazzar, chief of the magicians, I know that the spirit of the holy gods is in you and that no mystery baffles you. So explain to me the visions I saw in my dream, and their interpretation.'),
('DAN', 4, 10, 'DAN.4.10', 'In these visions of my mind as I was lying in bed, I saw this come to pass: There was a tree in the midst of the land, and its height was great.'),
('DAN', 4, 11, 'DAN.4.11', 'The tree grew large and strong; its top reached the sky, and it was visible to the ends of the earth.'),
('DAN', 4, 12, 'DAN.4.12', 'Its leaves were beautiful, its fruit was abundant, and upon it was food for all. Under it the beasts of the field found shelter, in its branches the birds of the air nested, and from it every creature was fed.'),
('DAN', 4, 13, 'DAN.4.13', 'As I lay on my bed, I also saw in the visions of my mind a watcher, a holy one, coming down from heaven.'),
('DAN', 4, 14, 'DAN.4.14', 'He called out in a loud voice: ‘Cut down the tree and chop off its branches; strip off its leaves and scatter its fruit. Let the beasts flee from under it, and the birds from its branches.'),
('DAN', 4, 15, 'DAN.4.15', 'But leave the stump with its roots in the ground, with a band of iron and bronze around it, in the tender grass of the field. Let him be drenched with the dew of heaven and graze with the beasts on the grass of the earth.'),
('DAN', 4, 16, 'DAN.4.16', 'Let his mind be changed from that of a man, and let him be given the mind of a beast till seven times pass him by.'),
('DAN', 4, 17, 'DAN.4.17', 'This decision is the decree of the watchers, the verdict declared by the holy ones, so that the living will know that the Most High rules over the kingdom of mankind and gives it to whom He wishes, setting over it the lowliest of men.’'),
('DAN', 4, 18, 'DAN.4.18', 'This is the dream that I, King Nebuchadnezzar, saw. Now, Belteshazzar, tell me the interpretation, because none of the wise men of my kingdom can interpret it for me. But you are able, because the spirit of the holy gods is in you.”'),
('DAN', 4, 19, 'DAN.4.19', 'For a time, Daniel, who was also known as Belteshazzar, was perplexed, and his thoughts alarmed him. So the king said, “Belteshazzar, do not let the dream or its interpretation alarm you.” “My lord,” replied Belteshazzar, “may the dream apply to those who hate you, and its interpretation to your enemies!'),
('DAN', 4, 20, 'DAN.4.20', 'The tree you saw that grew large and strong, whose top reached the sky and was visible to all the earth,'),
('DAN', 4, 21, 'DAN.4.21', 'whose foliage was beautiful and whose fruit was abundant, providing food for all, under which the beasts of the field lived, and in whose branches the birds of the air nested—'),
('DAN', 4, 22, 'DAN.4.22', 'you, O king, are that tree! For you have become great and strong; your greatness has grown to reach the sky, and your dominion extends to the ends of the earth.'),
('DAN', 4, 23, 'DAN.4.23', 'And you, O king, saw a watcher, a holy one, coming down from heaven and saying: ‘Cut down the tree and destroy it, but leave the stump with its roots in the ground, with a band of iron and bronze around it, in the tender grass of the field. Let him be drenched with the dew of heaven, and graze with the beasts of the field till seven times pass him by.’'),
('DAN', 4, 24, 'DAN.4.24', 'This is the interpretation, O king, and this is the decree that the Most High has issued against my lord the king:'),
('DAN', 4, 25, 'DAN.4.25', 'You will be driven away from mankind, and your dwelling will be with the beasts of the field. You will feed on grass like an ox and be drenched with the dew of heaven, and seven times shall pass you by, until you acknowledge that the Most High rules over the kingdom of mankind and gives it to whom He wishes.'),
('DAN', 4, 26, 'DAN.4.26', 'As for the command to leave the stump of the tree with its roots, your kingdom will be restored to you as soon as you acknowledge that Heaven rules.'),
('DAN', 4, 27, 'DAN.4.27', 'Therefore, may my advice be pleasing to you, O king. Break away from your sins by doing what is right, and from your iniquities by showing mercy to the oppressed. Perhaps there will be an extension of your prosperity.”'),
('DAN', 4, 28, 'DAN.4.28', 'All this happened to King Nebuchadnezzar.'),
('DAN', 4, 29, 'DAN.4.29', 'Twelve months later, as he was walking on the roof of the royal palace of Babylon,'),
('DAN', 4, 30, 'DAN.4.30', 'the king exclaimed, “Is this not Babylon the Great, which I myself have built as a royal residence by the might of my power and for the glory of my majesty?”'),
('DAN', 4, 31, 'DAN.4.31', 'While the words were still in the king’s mouth, a voice came from heaven: “It is decreed to you, King Nebuchadnezzar, that the kingdom has departed from you.'),
('DAN', 4, 32, 'DAN.4.32', 'You will be driven away from mankind to live with the beasts of the field, and you will feed on grass like an ox. And seven times will pass you by, until you acknowledge that the Most High rules over the kingdom of mankind and gives it to whom He wishes.”'),
('DAN', 4, 33, 'DAN.4.33', 'At that moment the sentence against Nebuchadnezzar was fulfilled. He was driven away from mankind. He ate grass like an ox, and his body was drenched with the dew of heaven, until his hair grew like the feathers of an eagle and his nails like the claws of a bird.'),
('DAN', 4, 34, 'DAN.4.34', 'But at the end of those days I, Nebuchadnezzar, looked up to heaven, and my sanity was restored to me. Then I praised the Most High, and I honored and glorified Him who lives forever: “For His dominion is an everlasting dominion, and His kingdom endures from generation to generation.'),
('DAN', 4, 35, 'DAN.4.35', 'All the peoples of the earth are counted as nothing, and He does as He pleases with the army of heaven and the peoples of the earth. There is no one who can restrain His hand or say to Him, ‘What have You done?’”'),
('DAN', 4, 36, 'DAN.4.36', 'At the same time my sanity was restored, my honor and splendor returned to me for the glory of my kingdom. My advisers and nobles sought me out, and I was restored to my throne, and surpassing greatness was added to me.'),
('DAN', 4, 37, 'DAN.4.37', 'Now I, Nebuchadnezzar, praise and exalt and glorify the King of heaven, for all His works are true and all His ways are just. And He is able to humble those who walk in pride.'),
('DAN', 5, 1, 'DAN.5.1', 'Later, King Belshazzar held a great feast for a thousand of his nobles, and he drank wine with them.'),
('DAN', 5, 2, 'DAN.5.2', 'Under the influence of the wine, Belshazzar gave orders to bring in the gold and silver vessels that Nebuchadnezzar his father had taken from the temple in Jerusalem, so that the king could drink from them, along with his nobles, his wives, and his concubines.'),
('DAN', 5, 3, 'DAN.5.3', 'Thus they brought in the gold vessels that had been taken from the temple, the house of God in Jerusalem, and the king drank from them, along with his nobles, his wives, and his concubines.'),
('DAN', 5, 4, 'DAN.5.4', 'As they drank the wine, they praised their gods of gold and silver, bronze and iron, wood and stone.'),
('DAN', 5, 5, 'DAN.5.5', 'At that moment the fingers of a human hand appeared and wrote on the plaster of the wall, near the lampstand in the royal palace. As the king watched the hand that was writing,'),
('DAN', 5, 6, 'DAN.5.6', 'his face grew pale and his thoughts so alarmed him that his hips gave way and his knees knocked together.'),
('DAN', 5, 7, 'DAN.5.7', 'The king called out for the enchanters, astrologers, and diviners to be brought in, and he said to these wise men of Babylon, “Whoever reads this inscription and tells me its interpretation will be clothed in purple and have a gold chain placed around his neck, and he will be made the third highest ruler in the kingdom.”'),
('DAN', 5, 8, 'DAN.5.8', 'So all the king’s wise men came in, but they could not read the inscription or interpret it for him.'),
('DAN', 5, 9, 'DAN.5.9', 'Then King Belshazzar became even more terrified, his face grew even more pale, and his nobles were bewildered.'),
('DAN', 5, 10, 'DAN.5.10', 'Hearing the outcry of the king and his nobles, the queen entered the banquet hall. “O king, may you live forever!” she said. “Do not let your thoughts terrify you, or your face grow pale.'),
('DAN', 5, 11, 'DAN.5.11', 'There is a man in your kingdom who has the spirit of the holy gods in him. In the days of your father he was found to have insight, intelligence, and wisdom like that of the gods. Your father, King Nebuchadnezzar, appointed him chief of the magicians, enchanters, astrologers, and diviners. Your own father, the king,'),
('DAN', 5, 12, 'DAN.5.12', 'did this because Daniel, the one he named Belteshazzar, was found to have an extraordinary spirit, as well as knowledge, understanding, and the ability to interpret dreams, explain riddles, and solve difficult problems. Summon Daniel, therefore, and he will give you the interpretation.”'),
('DAN', 5, 13, 'DAN.5.13', 'So Daniel was brought before the king, who asked him, “Are you Daniel, one of the exiles my father the king brought from Judah?'),
('DAN', 5, 14, 'DAN.5.14', 'I have heard that the spirit of the gods is in you, and that you have insight, intelligence, and extraordinary wisdom.'),
('DAN', 5, 15, 'DAN.5.15', 'Now the wise men and enchanters were brought before me to read this inscription and interpret it for me, but they could not give its interpretation.'),
('DAN', 5, 16, 'DAN.5.16', 'But I have heard about you, that you are able to give interpretations and solve difficult problems. Therefore, if you can read this inscription and give me its interpretation, you will be clothed in purple and have a gold chain placed around your neck, and you will be made the third highest ruler in the kingdom.”'),
('DAN', 5, 17, 'DAN.5.17', 'In response, Daniel said to the king, “You may keep your gifts for yourself and give your rewards to someone else. Nevertheless, I will read the inscription for the king and interpret it for him.'),
('DAN', 5, 18, 'DAN.5.18', 'As for you, O king, the Most High God gave your father Nebuchadnezzar sovereignty and greatness, glory and honor.'),
('DAN', 5, 19, 'DAN.5.19', 'Because of the greatness that He bestowed on him, the people of every nation and language trembled in fear before him. He killed whom he wished and kept alive whom he wished; he exalted whom he wished and humbled whom he wished.'),
('DAN', 5, 20, 'DAN.5.20', 'But when his heart became arrogant and his spirit was hardened with pride, he was deposed from his royal throne, and his glory was taken from him.'),
('DAN', 5, 21, 'DAN.5.21', 'He was driven away from mankind, and his mind was like that of a beast. He lived with the wild donkeys and ate grass like an ox, and his body was drenched with the dew of heaven until he acknowledged that the Most High God rules over the kingdom of mankind, setting over it whom He wishes.'),
('DAN', 5, 22, 'DAN.5.22', 'But you his son, O Belshazzar, have not humbled your heart, even though you knew all this.'),
('DAN', 5, 23, 'DAN.5.23', 'Instead, you have exalted yourself against the Lord of heaven. The vessels from His house were brought to you, and as you drank wine from them with your nobles, wives, and concubines, you praised your gods of silver and gold, bronze and iron, wood and stone, which cannot see or hear or understand. But you have failed to glorify the God who holds in His hand your very breath and all your ways.'),
('DAN', 5, 24, 'DAN.5.24', 'Therefore He sent the hand that wrote the inscription.'),
('DAN', 5, 25, 'DAN.5.25', 'Now this is the inscription that was written: MENE, MENE, TEKEL, PARSIN.'),
('DAN', 5, 26, 'DAN.5.26', 'And this is the interpretation of the message: MENE means that God has numbered the days of your reign and brought it to an end.'),
('DAN', 5, 27, 'DAN.5.27', 'TEKEL means that you have been weighed on the scales and found deficient.'),
('DAN', 5, 28, 'DAN.5.28', 'PERES means that your kingdom has been divided and given over to the Medes and Persians.”'),
('DAN', 5, 29, 'DAN.5.29', 'Then Belshazzar gave the command, and they clothed Daniel in purple, placed a gold chain around his neck, and proclaimed him the third highest ruler in the kingdom.'),
('DAN', 5, 30, 'DAN.5.30', 'That very night Belshazzar king of the Chaldeans was slain,'),
('DAN', 5, 31, 'DAN.5.31', 'and Darius the Mede received the kingdom at the age of sixty-two.'),
('DAN', 6, 1, 'DAN.6.1', 'Now it pleased Darius to appoint 120 satraps to rule throughout the kingdom,'),
('DAN', 6, 2, 'DAN.6.2', 'and over them three administrators, including Daniel, to whom these satraps were accountable so that the king would not suffer loss.'),
('DAN', 6, 3, 'DAN.6.3', 'Soon, by his extraordinary spirit, Daniel distinguished himself among the administrators and satraps. So the king planned to set him over the whole kingdom.'),
('DAN', 6, 4, 'DAN.6.4', 'Thus the administrators and satraps sought a charge against Daniel concerning the kingdom, but they could find no charge or corruption, because he was trustworthy, and no negligence or corruption was found in him.'),
('DAN', 6, 5, 'DAN.6.5', 'Finally these men said, “We will never find any charge against this Daniel unless we find something against him concerning the law of his God.”'),
('DAN', 6, 6, 'DAN.6.6', 'So the administrators and satraps went together to the king and said, “O King Darius, may you live forever!'),
('DAN', 6, 7, 'DAN.6.7', 'All the royal administrators, prefects, satraps, advisers, and governors have agreed that the king should establish an ordinance and enforce a decree that for thirty days anyone who petitions any god or man except you, O king, will be thrown into the den of lions.'),
('DAN', 6, 8, 'DAN.6.8', 'Therefore, O king, establish the decree and sign the document so that it cannot be changed—in accordance with the law of the Medes and Persians, which cannot be repealed.”'),
('DAN', 6, 9, 'DAN.6.9', 'Therefore King Darius signed the written decree.'),
('DAN', 6, 10, 'DAN.6.10', 'Now when Daniel learned that the document had been signed, he went into his house, where the windows of his upper room opened toward Jerusalem, and three times a day he got down on his knees, prayed, and gave thanks to his God, just as he had done before.'),
('DAN', 6, 11, 'DAN.6.11', 'Then these men went as a group and found Daniel petitioning and imploring his God.'),
('DAN', 6, 12, 'DAN.6.12', 'So they approached the king and asked about his royal decree: “Did you not sign a decree that for thirty days any man who petitions any god or man except you, O king, will be thrown into the den of lions?” The king replied, “According to the law of the Medes and Persians the order stands, and it cannot be repealed.”'),
('DAN', 6, 13, 'DAN.6.13', 'Then they told the king, “Daniel, one of the exiles from Judah, shows no regard for you, O king, or for the decree that you have signed. He still makes his petition three times a day.”'),
('DAN', 6, 14, 'DAN.6.14', 'As soon as the king heard this, he was deeply distressed and set his mind on delivering Daniel, and he labored until sundown to rescue him.'),
('DAN', 6, 15, 'DAN.6.15', 'Then the men approached the king together and said to him, “Remember, O king, that by the law of the Medes and Persians no decree or ordinance established by the king can be changed.”'),
('DAN', 6, 16, 'DAN.6.16', 'So the king gave the order, and they brought Daniel and threw him into the den of lions. The king said to Daniel, “May your God, whom you serve continually, deliver you!”'),
('DAN', 6, 17, 'DAN.6.17', 'A stone was brought and placed over the mouth of the den, and the king sealed it with his own signet ring and with the rings of his nobles, so that nothing concerning Daniel could be changed.'),
('DAN', 6, 18, 'DAN.6.18', 'Then the king went to his palace and spent the night fasting. No entertainment was brought before him, and sleep fled from him.'),
('DAN', 6, 19, 'DAN.6.19', 'At the first light of dawn, the king got up and hurried to the den of lions.'),
('DAN', 6, 20, 'DAN.6.20', 'When he reached the den, he cried out in a voice of anguish, “O Daniel, servant of the living God, has your God, whom you serve continually, been able to deliver you from the lions?”'),
('DAN', 6, 21, 'DAN.6.21', 'Then Daniel replied, “O king, may you live forever!'),
('DAN', 6, 22, 'DAN.6.22', 'My God sent His angel and shut the mouths of the lions. They have not hurt me, for I was found innocent in His sight, and I have done no wrong against you, O king.”'),
('DAN', 6, 23, 'DAN.6.23', 'The king was overjoyed and gave orders to lift Daniel out of the den, and when Daniel was lifted out of the den, no wounds whatsoever were found on him, because he had trusted in his God.'),
('DAN', 6, 24, 'DAN.6.24', 'At the command of the king, the men who had falsely accused Daniel were brought and thrown into the den of lions—they and their children and wives. And before they had reached the bottom of the den, the lions overpowered them and crushed all their bones.'),
('DAN', 6, 25, 'DAN.6.25', 'Then King Darius wrote to the people of every nation and language throughout the land: “May your prosperity abound.'),
('DAN', 6, 26, 'DAN.6.26', 'I hereby decree that in every part of my kingdom, men are to tremble in fear before the God of Daniel: For He is the living God, and He endures forever; His kingdom will never be destroyed, and His dominion will never end.'),
('DAN', 6, 27, 'DAN.6.27', 'He delivers and rescues; He performs signs and wonders in the heavens and on the earth, for He has rescued Daniel from the power of the lions.”'),
('DAN', 6, 28, 'DAN.6.28', 'So Daniel prospered during the reign of Darius and the reign of Cyrus the Persian.'),
('DAN', 7, 1, 'DAN.7.1', 'In the first year of the reign of Belshazzar over Babylon, Daniel had a dream, and visions passed through his mind as he lay on his bed. He wrote down the dream, and this is the summary of his account.'),
('DAN', 7, 2, 'DAN.7.2', 'Daniel declared: “In my vision in the night I looked, and suddenly the four winds of heaven were churning up the great sea.'),
('DAN', 7, 3, 'DAN.7.3', 'Then four great beasts came up out of the sea, each one different from the others:'),
('DAN', 7, 4, 'DAN.7.4', 'The first beast was like a lion, and it had the wings of an eagle. I watched until its wings were torn off and it was lifted up from the ground and made to stand on two feet like a man and given the mind of a man.'),
('DAN', 7, 5, 'DAN.7.5', 'Suddenly another beast appeared, which looked like a bear. It was raised up on one of its sides, and it had three ribs in its mouth between its teeth. So it was told, ‘Get up and gorge yourself on flesh!’'),
('DAN', 7, 6, 'DAN.7.6', 'Next, as I watched, suddenly another beast appeared. It was like a leopard, and on its back it had four wings like those of a bird. The beast also had four heads, and it was given authority to rule.'),
('DAN', 7, 7, 'DAN.7.7', 'After this, as I watched in my vision in the night, suddenly a fourth beast appeared, and it was terrifying—dreadful and extremely strong—with large iron teeth. It devoured and crushed; then it trampled underfoot whatever was left. It was different from all the beasts before it, and it had ten horns.'),
('DAN', 7, 8, 'DAN.7.8', 'While I was contemplating the horns, suddenly another horn, a little one, came up among them, and three of the first horns were uprooted before it. This horn had eyes like those of a man and a mouth that spoke words of arrogance.'),
('DAN', 7, 9, 'DAN.7.9', 'As I continued to watch, thrones were set in place, and the Ancient of Days took His seat. His clothing was white as snow, and the hair of His head was like pure wool. His throne was flaming with fire, and its wheels were all ablaze.'),
('DAN', 7, 10, 'DAN.7.10', 'A river of fire was flowing, coming out from His presence. Thousands upon thousands attended Him, and myriads upon myriads stood before Him. The court was convened, and the books were opened.'),
('DAN', 7, 11, 'DAN.7.11', 'Then I kept watching because of the arrogant words the horn was speaking. As I continued to watch, the beast was slain, and its body was destroyed and thrown into the blazing fire.'),
('DAN', 7, 12, 'DAN.7.12', 'As for the rest of the beasts, their dominion was removed, but they were granted an extension of life for a season and a time.'),
('DAN', 7, 13, 'DAN.7.13', 'In my vision in the night I continued to watch, and I saw One like the Son of Man coming with the clouds of heaven. He approached the Ancient of Days and was led into His presence.'),
('DAN', 7, 14, 'DAN.7.14', 'And He was given dominion, glory, and kingship, that the people of every nation and language should serve Him. His dominion is an everlasting dominion that will not pass away, and His kingdom is one that will never be destroyed.'),
('DAN', 7, 15, 'DAN.7.15', 'I, Daniel, was grieved in my spirit, and the visions in my mind alarmed me.'),
('DAN', 7, 16, 'DAN.7.16', 'I approached one of those who were standing there, and I asked him the true meaning of all this. So he told me the interpretation of these things:'),
('DAN', 7, 17, 'DAN.7.17', '‘These four great beasts are four kings who will arise from the earth.'),
('DAN', 7, 18, 'DAN.7.18', 'But the saints of the Most High will receive the kingdom and possess it forever—yes, forever and ever.’'),
('DAN', 7, 19, 'DAN.7.19', 'Then I wanted to know the true meaning of the fourth beast, which was different from all the others—extremely terrifying—devouring and crushing with iron teeth and bronze claws, then trampling underfoot whatever was left.'),
('DAN', 7, 20, 'DAN.7.20', 'I also wanted to know about the ten horns on its head and the other horn that came up, before which three of them fell—the horn whose appearance was more imposing than the others, with eyes and with a mouth that spoke words of arrogance.'),
('DAN', 7, 21, 'DAN.7.21', 'As I watched, this horn was waging war against the saints and prevailing against them,'),
('DAN', 7, 22, 'DAN.7.22', 'until the Ancient of Days arrived and pronounced judgment in favor of the saints of the Most High, and the time came for them to possess the kingdom.'),
('DAN', 7, 23, 'DAN.7.23', 'This is what he said: ‘The fourth beast is a fourth kingdom that will appear on the earth, different from all the other kingdoms, and it will devour the whole earth, trample it down, and crush it.'),
('DAN', 7, 24, 'DAN.7.24', 'And the ten horns are ten kings who will rise from this kingdom. After them another king, different from the earlier ones, will rise and subdue three kings.'),
('DAN', 7, 25, 'DAN.7.25', 'He will speak out against the Most High and oppress the saints of the Most High, intending to change the appointed times and laws; and the saints will be given into his hand for a time, and times, and half a time.'),
('DAN', 7, 26, 'DAN.7.26', 'But the court will convene, and his dominion will be taken away and completely destroyed forever.'),
('DAN', 7, 27, 'DAN.7.27', 'Then the sovereignty, dominion, and greatness of the kingdoms under all of heaven will be given to the people, the saints of the Most High. His kingdom will be an everlasting kingdom, and all rulers will serve and obey Him.’'),
('DAN', 7, 28, 'DAN.7.28', 'Thus ends the matter. As for me, Daniel, my thoughts troubled me greatly, and my face turned pale. But I kept the matter to myself.”'),
('DAN', 8, 1, 'DAN.8.1', 'In the third year of the reign of King Belshazzar, a vision appeared to me, Daniel, subsequent to the one that had appeared to me earlier.'),
('DAN', 8, 2, 'DAN.8.2', 'And in the vision I saw myself in the citadel of Susa, in the province of Elam. I saw in the vision that I was beside the Ulai Canal.'),
('DAN', 8, 3, 'DAN.8.3', 'Then I lifted up my eyes and saw a ram with two horns standing beside the canal. The horns were long, but one was longer than the other, and the longer one grew up later.'),
('DAN', 8, 4, 'DAN.8.4', 'I saw the ram charging toward the west and the north and the south. No animal could stand against him, and there was no deliverance from his power. He did as he pleased and became great.'),
('DAN', 8, 5, 'DAN.8.5', 'As I was contemplating all this, suddenly a goat with a prominent horn between his eyes came out of the west, crossing the surface of the entire earth without touching the ground.'),
('DAN', 8, 6, 'DAN.8.6', 'He came toward the two-horned ram I had seen standing beside the canal and rushed at him with furious power.'),
('DAN', 8, 7, 'DAN.8.7', 'I saw him approach the ram in a rage against him, and he struck the ram and shattered his two horns. The ram was powerless to stand against him, and the goat threw him to the ground and trampled him, and no one could deliver the ram from his power.'),
('DAN', 8, 8, 'DAN.8.8', 'Thus the goat became very great, but at the height of his power, his large horn was broken off, and four prominent horns came up in its place, pointing toward the four winds of heaven.'),
('DAN', 8, 9, 'DAN.8.9', 'From one of these horns a little horn emerged and grew extensively toward the south and the east and toward the Beautiful Land.'),
('DAN', 8, 10, 'DAN.8.10', 'It grew as high as the host of heaven, and it cast down some of the host and some of the stars to the earth and trampled them.'),
('DAN', 8, 11, 'DAN.8.11', 'It magnified itself, even to the Prince of the host; it removed His daily sacrifice and overthrew the place of His sanctuary.'),
('DAN', 8, 12, 'DAN.8.12', 'And in the rebellion, the host and the daily sacrifice were given over to the horn, and it flung truth to the ground and prospered in whatever it did.'),
('DAN', 8, 13, 'DAN.8.13', 'Then I heard a holy one speaking, and another holy one said to him, “How long until the fulfillment of the vision of the daily sacrifice, the rebellion that causes desolation, and the surrender of the sanctuary and of the host to be trampled?”'),
('DAN', 8, 14, 'DAN.8.14', 'He said to me, “It will take 2,300 evenings and mornings; then the sanctuary will be properly restored.”'),
('DAN', 8, 15, 'DAN.8.15', 'While I, Daniel, was watching the vision and trying to understand it, there stood before me one having the appearance of a man.'),
('DAN', 8, 16, 'DAN.8.16', 'And I heard the voice of a man calling from between the banks of the Ulai: “Gabriel, explain the vision to this man.”'),
('DAN', 8, 17, 'DAN.8.17', 'As he came near to where I stood, I was terrified and fell facedown. “Son of man,” he said to me, “understand that the vision concerns the time of the end.”'),
('DAN', 8, 18, 'DAN.8.18', 'While he was speaking with me, I fell into a deep sleep, with my face to the ground. Then he touched me, helped me to my feet,'),
('DAN', 8, 19, 'DAN.8.19', 'and said, “Behold, I will make known to you what will happen in the latter time of wrath, because it concerns the appointed time of the end.'),
('DAN', 8, 20, 'DAN.8.20', 'The two-horned ram that you saw represents the kings of Media and Persia.'),
('DAN', 8, 21, 'DAN.8.21', 'The shaggy goat represents the king of Greece, and the large horn between his eyes is the first king.'),
('DAN', 8, 22, 'DAN.8.22', 'The four horns that replaced the broken one represent four kingdoms that will rise from that nation but will not have the same power.'),
('DAN', 8, 23, 'DAN.8.23', 'In the latter part of their reign, when the rebellion has reached its full measure, an insolent king, skilled in intrigue, will come to the throne.'),
('DAN', 8, 24, 'DAN.8.24', 'His power will be great, but it will not be his own. He will cause terrible destruction and succeed in whatever he does. He will destroy the mighty men along with the holy people.'),
('DAN', 8, 25, 'DAN.8.25', 'Through his craft and by his hand, he will cause deceit to prosper, and in his own mind he will make himself great. In a time of peace he will destroy many, and he will even stand against the Prince of princes. Yet he will be broken off, but not by human hands.'),
('DAN', 8, 26, 'DAN.8.26', 'The vision of the evenings and the mornings that has been spoken is true. Now you must seal up the vision, for it concerns the distant future.”'),
('DAN', 8, 27, 'DAN.8.27', 'I, Daniel, was exhausted and lay ill for days. Then I got up and went about the king’s business. I was confounded by the vision; it was beyond understanding.'),
('DAN', 9, 1, 'DAN.9.1', 'In the first year of Darius son of Xerxes, a Mede by descent, who was made ruler over the kingdom of the Chaldeans—'),
('DAN', 9, 2, 'DAN.9.2', 'in the first year of his reign, I, Daniel, understood from the sacred books, according to the word of the LORD to Jeremiah the prophet, that the desolation of Jerusalem would last seventy years.'),
('DAN', 9, 3, 'DAN.9.3', 'So I turned my attention to the Lord God to seek Him by prayer and petition, with fasting, sackcloth, and ashes.'),
('DAN', 9, 4, 'DAN.9.4', 'And I prayed to the LORD my God and confessed, “O, Lord, the great and awesome God, who keeps His covenant of loving devotion to those who love Him and keep His commandments,'),
('DAN', 9, 5, 'DAN.9.5', 'we have sinned and done wrong. We have acted wickedly and rebelled. We have turned away from Your commandments and ordinances.'),
('DAN', 9, 6, 'DAN.9.6', 'We have not listened to Your servants the prophets, who spoke in Your name to our kings, leaders, fathers, and all the people of the land.'),
('DAN', 9, 7, 'DAN.9.7', 'To You, O Lord, belongs righteousness, but this day we are covered with shame—the men of Judah, the people of Jerusalem, and all Israel near and far, in all the countries to which You have driven us because of our unfaithfulness to You.'),
('DAN', 9, 8, 'DAN.9.8', 'O LORD, we are covered with shame—our kings, our leaders, and our fathers—because we have sinned against You.'),
('DAN', 9, 9, 'DAN.9.9', 'To the Lord our God belong compassion and forgiveness, even though we have rebelled against Him'),
('DAN', 9, 10, 'DAN.9.10', 'and have not obeyed the voice of the LORD our God to walk in His laws, which He set before us through His servants the prophets.'),
('DAN', 9, 11, 'DAN.9.11', 'All Israel has transgressed Your law and turned away, refusing to obey Your voice; so the oath and the curse written in the Law of Moses the servant of God has been poured out on us, because we have sinned against You.'),
('DAN', 9, 12, 'DAN.9.12', 'You have carried out the words spoken against us and against our rulers by bringing upon us a great disaster. For under all of heaven, nothing has ever been done like what has been done to Jerusalem.'),
('DAN', 9, 13, 'DAN.9.13', 'Just as it is written in the Law of Moses, all this disaster has come upon us, yet we have not sought the favor of the LORD our God by turning from our iniquities and giving attention to Your truth.'),
('DAN', 9, 14, 'DAN.9.14', 'Therefore the LORD has kept the calamity in store and brought it upon us. For the LORD our God is righteous in all He does; yet we have not obeyed His voice.'),
('DAN', 9, 15, 'DAN.9.15', 'Now, O Lord our God, who brought Your people out of the land of Egypt with a mighty hand, and who made for Yourself a name renowned to this day, we have sinned; we have acted wickedly.'),
('DAN', 9, 16, 'DAN.9.16', 'O Lord, in keeping with all Your righteous acts, I pray that Your anger and wrath may turn away from Your city Jerusalem, Your holy mountain; for because of our sins and the iniquities of our fathers, Jerusalem and Your people are a reproach to all around us.'),
('DAN', 9, 17, 'DAN.9.17', 'So now, our God, hear the prayers and petitions of Your servant. For Your sake, O Lord, cause Your face to shine upon Your desolate sanctuary.'),
('DAN', 9, 18, 'DAN.9.18', 'Incline Your ear, O my God, and hear; open Your eyes and see the desolation of the city that bears Your name. For we are not presenting our petitions before You because of our righteous acts, but because of Your great compassion.'),
('DAN', 9, 19, 'DAN.9.19', 'O Lord, listen! O Lord, forgive! O Lord, hear and act! For Your sake, O my God, do not delay, because Your city and Your people bear Your name.”'),
('DAN', 9, 20, 'DAN.9.20', 'While I was speaking, praying, confessing my sin and that of my people Israel, and presenting my petition before the LORD my God concerning His holy mountain—'),
('DAN', 9, 21, 'DAN.9.21', 'while I was still praying, Gabriel, the man I had seen in the earlier vision, came to me in swift flight about the time of the evening sacrifice.'),
('DAN', 9, 22, 'DAN.9.22', 'He instructed me and spoke with me, saying: “O Daniel, I have come now to give you insight and understanding.'),
('DAN', 9, 23, 'DAN.9.23', 'At the beginning of your petitions, an answer went out, and I have come to tell you, for you are highly precious. So consider the message and understand the vision:'),
('DAN', 9, 24, 'DAN.9.24', 'Seventy weeks are decreed for your people and your holy city to stop their transgression, to put an end to sin, to make atonement for iniquity, to bring in everlasting righteousness, to seal up vision and prophecy, and to anoint the Most Holy Place.'),
('DAN', 9, 25, 'DAN.9.25', 'Know and understand this: From the issuance of the decree to restore and rebuild Jerusalem until the Messiah, the Prince, there will be seven weeks and sixty-two weeks. It will be rebuilt with streets and a trench, but in times of distress.'),
('DAN', 9, 26, 'DAN.9.26', 'Then after the sixty-two weeks the Messiah will be cut off and will have nothing. Then the people of the prince who is to come will destroy the city and the sanctuary. The end will come like a flood, and until the end there will be war; desolations have been decreed.'),
('DAN', 9, 27, 'DAN.9.27', 'And he will confirm a covenant with many for one week, but in the middle of the week he will put an end to sacrifice and offering. And on the wing of the temple will come the abomination that causes desolation, until the decreed destruction is poured out upon him.”'),
('DAN', 10, 1, 'DAN.10.1', 'In the third year of Cyrus king of Persia, a message was revealed to Daniel, who was called Belteshazzar. The message was true, and it concerned a great conflict. And the understanding of the message was given to him in a vision.'),
('DAN', 10, 2, 'DAN.10.2', 'In those days I, Daniel, was mourning for three full weeks.'),
('DAN', 10, 3, 'DAN.10.3', 'I ate no rich food, no meat or wine entered my mouth, and I did not anoint myself with oil until the three weeks were completed.'),
('DAN', 10, 4, 'DAN.10.4', 'On the twenty-fourth day of the first month, as I was standing on the bank of the great river, the Tigris,'),
('DAN', 10, 5, 'DAN.10.5', 'I lifted up my eyes, and behold, there was a certain man dressed in linen, with a belt of fine gold from Uphaz around his waist.'),
('DAN', 10, 6, 'DAN.10.6', 'His body was like beryl, his face like the brilliance of lightning, his eyes like flaming torches, his arms and legs like the gleam of polished bronze, and his voice like the sound of a multitude.'),
('DAN', 10, 7, 'DAN.10.7', 'Only I, Daniel, saw the vision; the men with me did not see it, but a great terror fell upon them, and they ran and hid themselves.'),
('DAN', 10, 8, 'DAN.10.8', 'So I was left alone, gazing at this great vision. No strength remained in me; my face grew deathly pale, and I was powerless.'),
('DAN', 10, 9, 'DAN.10.9', 'I heard the sound of his words, and as I listened, I fell into a deep sleep, with my face to the ground.'),
('DAN', 10, 10, 'DAN.10.10', 'Suddenly, a hand touched me and set me trembling on my hands and knees.'),
('DAN', 10, 11, 'DAN.10.11', 'He said to me, “Daniel, you are a man who is highly precious. Consider carefully the words that I am about to say to you. Stand up, for I have now been sent to you.” And when he had said this to me, I stood up trembling.'),
('DAN', 10, 12, 'DAN.10.12', '“Do not be afraid, Daniel,” he said, “for from the first day that you purposed to understand and to humble yourself before your God, your words were heard, and I have come in response to them.'),
('DAN', 10, 13, 'DAN.10.13', 'However, the prince of the kingdom of Persia opposed me for twenty-one days. Then Michael, one of the chief princes, came to help me, for I had been left there with the kings of Persia.'),
('DAN', 10, 14, 'DAN.10.14', 'Now I have come to explain to you what will happen to your people in the latter days, for the vision concerns those days.”'),
('DAN', 10, 15, 'DAN.10.15', 'While he was speaking these words to me, I set my face toward the ground and became speechless.'),
('DAN', 10, 16, 'DAN.10.16', 'And suddenly one with the likeness of a man touched my lips, and I opened my mouth and said to the one standing before me, “My lord, because of the vision, I am overcome with anguish, and I have no strength.'),
('DAN', 10, 17, 'DAN.10.17', 'How can I, your servant, speak with you, my lord? Now I have no strength, nor is any breath left in me.”'),
('DAN', 10, 18, 'DAN.10.18', 'Again the one with the likeness of a man touched me and strengthened me.'),
('DAN', 10, 19, 'DAN.10.19', '“Do not be afraid, you who are highly precious,” he said. “Peace be with you! Be strong now; be very strong!” As he spoke with me, I was strengthened and said, “Speak, my lord, for you have strengthened me.”'),
('DAN', 10, 20, 'DAN.10.20', '“Do you know why I have come to you?” he said. “I must return at once to fight against the prince of Persia, and when I have gone forth, behold, the prince of Greece will come.'),
('DAN', 10, 21, 'DAN.10.21', 'But first I will tell you what is inscribed in the Book of Truth. Yet no one has the courage to support me against these, except Michael your prince.'),
('DAN', 11, 1, 'DAN.11.1', '“And I, in the first year of Darius the Mede, stood up to strengthen and protect him.'),
('DAN', 11, 2, 'DAN.11.2', 'Now then, I will tell you the truth: Three more kings will arise in Persia, and then a fourth, who will be far richer than all the others. By the power of his wealth, he will stir up everyone against the kingdom of Greece.'),
('DAN', 11, 3, 'DAN.11.3', 'Then a mighty king will arise, who will rule with great authority and do as he pleases.'),
('DAN', 11, 4, 'DAN.11.4', 'But as soon as he is established, his kingdom will be broken up and parceled out toward the four winds of heaven. It will not go to his descendants, nor will it have the authority with which he ruled, because his kingdom will be uprooted and given to others.'),
('DAN', 11, 5, 'DAN.11.5', 'The king of the South will grow strong, but one of his commanders will grow even stronger and will rule his own kingdom with great authority.'),
('DAN', 11, 6, 'DAN.11.6', 'After some years they will form an alliance, and the daughter of the king of the South will go to the king of the North to seal the agreement. But his daughter will not retain her position of power, nor will his strength endure. At that time she will be given up, along with her royal escort and her father and the one who supported her.'),
('DAN', 11, 7, 'DAN.11.7', 'But one from her family line will rise up in his place, come against the army of the king of the North, and enter his fortress, fighting and prevailing.'),
('DAN', 11, 8, 'DAN.11.8', 'He will take even their gods captive to Egypt, with their metal images and their precious vessels of silver and gold. For some years he will stay away from the king of the North,'),
('DAN', 11, 9, 'DAN.11.9', 'who will invade the realm of the king of the South and then return to his own land.'),
('DAN', 11, 10, 'DAN.11.10', 'But his sons will stir up strife and assemble a great army, which will advance forcefully, sweeping through like a flood, and will again carry the battle as far as his fortress.'),
('DAN', 11, 11, 'DAN.11.11', 'In a rage, the king of the South will march out to fight the king of the North, who will raise a large army, but it will be delivered into the hand of his enemy.'),
('DAN', 11, 12, 'DAN.11.12', 'When the army is carried off, the king of the South will be proud in heart and will cast down tens of thousands, but he will not triumph.'),
('DAN', 11, 13, 'DAN.11.13', 'For the king of the North will raise another army, larger than the first, and after some years he will advance with a great army and many supplies.'),
('DAN', 11, 14, 'DAN.11.14', 'In those times many will rise up against the king of the South. Violent ones among your own people will exalt themselves in fulfillment of the vision, but they will fail.'),
('DAN', 11, 15, 'DAN.11.15', 'Then the king of the North will come, build up a siege ramp, and capture a fortified city. The forces of the South will not stand; even their best troops will not be able to resist.'),
('DAN', 11, 16, 'DAN.11.16', 'The invader will do as he pleases, and no one will stand against him. He will establish himself in the Beautiful Land, with destruction in his hand.'),
('DAN', 11, 17, 'DAN.11.17', 'He will resolve to come with the strength of his whole kingdom, and will reach an agreement with the king of the South. He will give him a daughter in marriage in order to overthrow the kingdom, but his plan will not succeed or help him.'),
('DAN', 11, 18, 'DAN.11.18', 'Then he will turn his face to the coastlands and capture many of them. But a commander will put an end to his reproach and will turn it back upon him.'),
('DAN', 11, 19, 'DAN.11.19', 'After this, he will turn back toward the fortresses of his own land, but he will stumble and fall and be no more.'),
('DAN', 11, 20, 'DAN.11.20', 'In his place one will arise who will send out a tax collector for the glory of the kingdom; but within a few days he will be destroyed, though not in anger or in battle.'),
('DAN', 11, 21, 'DAN.11.21', 'In his place a despicable person will arise; royal honors will not be given to him, but he will come in a time of peace and seize the kingdom by intrigue.'),
('DAN', 11, 22, 'DAN.11.22', 'Then a flood of forces will be swept away before him and destroyed, along with a prince of the covenant.'),
('DAN', 11, 23, 'DAN.11.23', 'After an alliance is made with him, he will act deceitfully; for he will rise to power with only a few people.'),
('DAN', 11, 24, 'DAN.11.24', 'In a time of peace, he will invade the richest provinces and do what his fathers and forefathers never did. He will lavish plunder, loot, and wealth on his followers, and he will plot against the strongholds—but only for a time.'),
('DAN', 11, 25, 'DAN.11.25', 'And with a large army he will stir up his power and his courage against the king of the South, who will mobilize a very large and powerful army but will not withstand the plots devised against him.'),
('DAN', 11, 26, 'DAN.11.26', 'Those who eat from his provisions will seek to destroy him; his army will be swept away, and many will fall slain.'),
('DAN', 11, 27, 'DAN.11.27', 'And the two kings, with their hearts bent on evil, will speak lies at the same table, but to no avail, for still the end will come at the appointed time.'),
('DAN', 11, 28, 'DAN.11.28', 'The king of the North will return to his land with great wealth, but his heart will be set against the holy covenant; so he will do damage and return to his own land.'),
('DAN', 11, 29, 'DAN.11.29', 'At the appointed time he will invade the South again, but this time will not be like the first.'),
('DAN', 11, 30, 'DAN.11.30', 'Ships of Kittim will come against him, and he will lose heart. Then he will turn back and rage against the holy covenant and do damage. So he will return and show favor to those who forsake the holy covenant.'),
('DAN', 11, 31, 'DAN.11.31', 'His forces will rise up and desecrate the temple fortress. They will abolish the daily sacrifice and set up the abomination of desolation.'),
('DAN', 11, 32, 'DAN.11.32', 'With flattery he will corrupt those who violate the covenant, but the people who know their God will firmly resist him.'),
('DAN', 11, 33, 'DAN.11.33', 'Those with insight will instruct many, though for a time they will fall by sword or flame, or be captured or plundered.'),
('DAN', 11, 34, 'DAN.11.34', 'Now when they fall, they will be granted a little help, but many will join them insincerely.'),
('DAN', 11, 35, 'DAN.11.35', 'Some of the wise will fall so that they may be refined, purified, and made spotless until the time of the end, for it will still come at the appointed time.'),
('DAN', 11, 36, 'DAN.11.36', 'Then the king will do as he pleases and will exalt and magnify himself above every god, and he will speak monstrous things against the God of gods. He will be successful until the time of wrath is completed, for what has been decreed must be accomplished.'),
('DAN', 11, 37, 'DAN.11.37', 'He will show no regard for the gods of his fathers, nor for the one desired by women, nor for any other god, because he will magnify himself above them all.'),
('DAN', 11, 38, 'DAN.11.38', 'And in their place, he will honor a god of fortresses—a god his fathers did not know—with gold, silver, precious stones, and riches.'),
('DAN', 11, 39, 'DAN.11.39', 'He will attack the strongest fortresses with the help of a foreign god and will greatly honor those who acknowledge him, making them rulers over many and distributing the land for a price.'),
('DAN', 11, 40, 'DAN.11.40', 'At the time of the end, the king of the South will engage him in battle, but the king of the North will storm out against him with chariots, horsemen, and many ships, invading many countries and sweeping through them like a flood.'),
('DAN', 11, 41, 'DAN.11.41', 'He will also invade the Beautiful Land, and many countries will fall. But these will be delivered from his hand: Edom, Moab, and the leaders of the Ammonites.'),
('DAN', 11, 42, 'DAN.11.42', 'He will extend his power over many countries, and not even the land of Egypt will escape.'),
('DAN', 11, 43, 'DAN.11.43', 'He will gain control of the treasures of gold and silver and over all the riches of Egypt, and the Libyans and Cushites will also submit to him.'),
('DAN', 11, 44, 'DAN.11.44', 'But news from the east and the north will alarm him, and he will go out with great fury to destroy many and devote them to destruction.'),
('DAN', 11, 45, 'DAN.11.45', 'He will pitch his royal tents between the sea and the beautiful holy mountain, but he will meet his end with no one to help him.'),
('DAN', 12, 1, 'DAN.12.1', '“At that time Michael, the great prince who stands watch over your people, will rise up. There will be a time of distress, the likes of which will not have occurred from the beginning of nations until that time. But at that time your people—everyone whose name is found written in the book—will be delivered.'),
('DAN', 12, 2, 'DAN.12.2', 'And many who sleep in the dust of the earth will awake, some to everlasting life, but others to shame and everlasting contempt.'),
('DAN', 12, 3, 'DAN.12.3', 'Then the wise will shine like the brightness of the heavens, and those who lead many to righteousness will shine like the stars forever and ever.'),
('DAN', 12, 4, 'DAN.12.4', 'But you, Daniel, shut up these words and seal the book until the time of the end. Many will roam to and fro, and knowledge will increase.”'),
('DAN', 12, 5, 'DAN.12.5', 'Then I, Daniel, looked and saw two others standing there, one on this bank of the river and one on the opposite bank.'),
('DAN', 12, 6, 'DAN.12.6', 'One of them said to the man dressed in linen, who was above the waters of the river, “How long until the fulfillment of these wonders?”'),
('DAN', 12, 7, 'DAN.12.7', 'And the man dressed in linen, who was above the waters of the river, raised his right hand and his left hand toward heaven, and I heard him swear by Him who lives forever, saying, “It will be for a time, and times, and half a time. When the power of the holy people has finally been shattered, all these things will be completed.”'),
('DAN', 12, 8, 'DAN.12.8', 'I heard, but I did not understand. So I asked, “My lord, what will be the outcome of these things?”'),
('DAN', 12, 9, 'DAN.12.9', '“Go on your way, Daniel,” he replied, “for the words are closed up and sealed until the time of the end.'),
('DAN', 12, 10, 'DAN.12.10', 'Many will be purified, made spotless, and refined, but the wicked will continue to act wickedly. None of the wicked will understand, but the wise will understand.'),
('DAN', 12, 11, 'DAN.12.11', 'And from the time the daily sacrifice is abolished and the abomination of desolation set up, there will be 1,290 days.'),
('DAN', 12, 12, 'DAN.12.12', 'Blessed is he who waits and reaches the end of the 1,335 days.'),
('DAN', 12, 13, 'DAN.12.13', 'But as for you, go on your way until the end. You will rest, and then you will arise to your inheritance at the end of the days.”'),
('HOS', 1, 1, 'HOS.1.1', 'This is the word of the LORD that came to Hosea son of Beeri in the days of Uzziah, Jotham, Ahaz, and Hezekiah, kings of Judah, and of Jeroboam son of Jehoash, king of Israel.'),
('HOS', 1, 2, 'HOS.1.2', 'When the LORD first spoke through Hosea, He told him, “Go, take a prostitute as your wife and have children of adultery, because this land is flagrantly prostituting itself by departing from the LORD.”'),
('HOS', 1, 3, 'HOS.1.3', 'So Hosea went and married Gomer daughter of Diblaim, and she conceived and bore him a son.'),
('HOS', 1, 4, 'HOS.1.4', 'Then the LORD said to Hosea, “Name him Jezreel, for soon I will bring the bloodshed of Jezreel upon the house of Jehu, and I will put an end to the kingdom of Israel.'),
('HOS', 1, 5, 'HOS.1.5', 'And on that day I will break the bow of Israel in the Valley of Jezreel.”'),
('HOS', 1, 6, 'HOS.1.6', 'Gomer again conceived and gave birth to a daughter, and the LORD said to Hosea, “Name her Lo-ruhamah, for I will no longer have compassion on the house of Israel, that I should ever forgive them.'),
('HOS', 1, 7, 'HOS.1.7', 'Yet I will have compassion on the house of Judah, and I will save them—not by bow or sword or war, not by horses and cavalry, but by the LORD their God.”'),
('HOS', 1, 8, 'HOS.1.8', 'After she had weaned Lo-ruhamah, Gomer conceived and gave birth to a son.'),
('HOS', 1, 9, 'HOS.1.9', 'And the LORD said, “Name him Lo-ammi, for you are not My people, and I am not your God.'),
('HOS', 1, 10, 'HOS.1.10', 'Yet the number of the Israelites will be like the sand of the sea, which cannot be measured or counted. And it will happen that in the very place where it was said to them, ‘You are not My people,’ they will be called ‘sons of the living God.’'),
('HOS', 1, 11, 'HOS.1.11', 'Then the people of Judah and of Israel will be gathered together, and they will appoint for themselves one leader, and will go up out of the land. For great will be the day of Jezreel.'),
('HOS', 2, 1, 'HOS.2.1', '“Say of your brothers, ‘My people,’ and of your sisters, ‘My loved one.’'),
('HOS', 2, 2, 'HOS.2.2', 'Rebuke your mother, rebuke her, for she is not My wife, and I am not her husband. Let her remove the adultery from her face and the unfaithfulness from between her breasts.'),
('HOS', 2, 3, 'HOS.2.3', 'Otherwise, I will strip her naked and expose her like the day of her birth. I will make her like a desert and turn her into a parched land, and I will let her die of thirst.'),
('HOS', 2, 4, 'HOS.2.4', 'I will have no compassion on her children, because they are the children of adultery.'),
('HOS', 2, 5, 'HOS.2.5', 'For their mother has played the harlot and has conceived them in disgrace. For she thought, ‘I will go after my lovers, who give me bread and water, wool and linen, oil and drink.’'),
('HOS', 2, 6, 'HOS.2.6', 'Therefore, behold, I will hedge up her path with thorns; I will enclose her with a wall, so she cannot find her way.'),
('HOS', 2, 7, 'HOS.2.7', 'She will pursue her lovers but not catch them; she will seek them but not find them. Then she will say, ‘I will return to my first husband, for then I was better off than now.’'),
('HOS', 2, 8, 'HOS.2.8', 'For she does not acknowledge that it was I who gave her grain, new wine, and oil, who lavished on her silver and gold—which they crafted for Baal.'),
('HOS', 2, 9, 'HOS.2.9', 'Therefore I will take back My grain in its time and My new wine in its season; I will take away My wool and linen, which were given to cover her nakedness.'),
('HOS', 2, 10, 'HOS.2.10', 'And then I will expose her lewdness in the sight of her lovers, and no one will deliver her out of My hands.'),
('HOS', 2, 11, 'HOS.2.11', 'I will put an end to all her exultation: her feasts, New Moons, and Sabbaths—all her appointed feasts.'),
('HOS', 2, 12, 'HOS.2.12', 'I will destroy her vines and fig trees, which she thinks are the wages paid by her lovers. So I will make them into a thicket, and the beasts of the field will devour them.'),
('HOS', 2, 13, 'HOS.2.13', 'I will punish her for the days of the Baals when she burned incense to them, when she adorned herself with rings and jewelry, and went after her lovers. But Me she forgot,” declares the LORD.'),
('HOS', 2, 14, 'HOS.2.14', '“Therefore, behold, I will allure her and lead her to the wilderness, and speak to her tenderly.'),
('HOS', 2, 15, 'HOS.2.15', 'There I will give back her vineyards and make the Valley of Achor into a gateway of hope. There she will respond as she did in the days of her youth, as in the day she came up out of Egypt.'),
('HOS', 2, 16, 'HOS.2.16', 'In that day,” declares the LORD, “you will call Me ‘my Husband,’ and no longer call Me ‘my Master.’'),
('HOS', 2, 17, 'HOS.2.17', 'For I will remove from her lips the names of the Baals; no longer will their names be invoked.'),
('HOS', 2, 18, 'HOS.2.18', 'On that day I will make a covenant for them with the beasts of the field and the birds of the air and the creatures that crawl on the ground. And I will abolish bow and sword and battle in the land, and will make them lie down in safety.'),
('HOS', 2, 19, 'HOS.2.19', 'So I will betroth you to Me forever; I will betroth you in righteousness and justice, in loving devotion and compassion.'),
('HOS', 2, 20, 'HOS.2.20', 'And I will betroth you in faithfulness, and you will know the LORD.”'),
('HOS', 2, 21, 'HOS.2.21', '“On that day I will respond—” declares the LORD—“I will respond to the heavens, and they will respond to the earth.'),
('HOS', 2, 22, 'HOS.2.22', 'And the earth will respond to the grain, to the new wine and oil, and they will respond to Jezreel.'),
('HOS', 2, 23, 'HOS.2.23', 'And I will sow her as My own in the land, and I will have compassion on ‘No Compassion.’ I will say to those called ‘Not My People,’ ‘You are My people,’ and they will say, ‘You are my God.’”'),
('HOS', 3, 1, 'HOS.3.1', 'Then the LORD said to me, “Go show love to your wife again, though she is loved by another and is an adulteress. Love her as the LORD loves the Israelites, though they turn to other gods and love to offer raisin cakes to idols.”'),
('HOS', 3, 2, 'HOS.3.2', 'So I bought her for fifteen shekels of silver and a homer and a lethech of barley.'),
('HOS', 3, 3, 'HOS.3.3', 'Then I said to her, “You must live with me for many days; you must not be promiscuous or belong to another, and I will do the same for you.”'),
('HOS', 3, 4, 'HOS.3.4', 'For the Israelites must live many days without king or prince, without sacrifice or sacred pillar, and without ephod or idol.'),
('HOS', 3, 5, 'HOS.3.5', 'Afterward, the people of Israel will return and seek the LORD their God and David their king. They will come trembling to the LORD and to His goodness in the last days.'),
('HOS', 4, 1, 'HOS.4.1', 'Hear the word of the LORD, O children of Israel, for the LORD has a case against the people of the land: “There is no truth, no loving devotion, and no knowledge of God in the land!'),
('HOS', 4, 2, 'HOS.4.2', 'Cursing and lying, murder and stealing, and adultery are rampant; one act of bloodshed follows another.'),
('HOS', 4, 3, 'HOS.4.3', 'Therefore the land mourns, and all who dwell in it will waste away with the beasts of the field and the birds of the air; even the fish of the sea disappear.'),
('HOS', 4, 4, 'HOS.4.4', 'But let no man contend; let no man offer reproof; for your people are like those who contend with a priest.'),
('HOS', 4, 5, 'HOS.4.5', 'You will stumble by day, and the prophet will stumble with you by night; so I will destroy your mother—'),
('HOS', 4, 6, 'HOS.4.6', 'My people are destroyed for lack of knowledge. Because you have rejected knowledge, I will also reject you as My priests. Since you have forgotten the law of your God, I will also forget your children.'),
('HOS', 4, 7, 'HOS.4.7', 'The more they multiplied, the more they sinned against Me; they exchanged their Glory for a thing of disgrace.'),
('HOS', 4, 8, 'HOS.4.8', 'They feed on the sins of My people and set their hearts on iniquity.'),
('HOS', 4, 9, 'HOS.4.9', 'And it shall be like people, like priest. I will punish both of them for their ways and repay them for their deeds.'),
('HOS', 4, 10, 'HOS.4.10', 'They will eat but not be satisfied; they will be promiscuous but not multiply. For they have abandoned the LORD to give themselves'),
('HOS', 4, 11, 'HOS.4.11', 'to promiscuity, wine, and new wine, which take away understanding.'),
('HOS', 4, 12, 'HOS.4.12', 'My people consult their wooden idols, and their divining rods inform them. For a spirit of prostitution leads them astray and they have played the harlot against their God.'),
('HOS', 4, 13, 'HOS.4.13', 'They sacrifice on the mountaintops and burn offerings on the hills, under oak, poplar, and terebinth, because their shade is pleasant. And so your daughters turn to prostitution and your daughters-in-law to adultery.'),
('HOS', 4, 14, 'HOS.4.14', 'I will not punish your daughters when they prostitute themselves, nor your daughters-in-law when they commit adultery. For the men themselves go off with prostitutes and offer sacrifices with shrine prostitutes. So a people without understanding will come to ruin.'),
('HOS', 4, 15, 'HOS.4.15', 'Though you prostitute yourself, O Israel, may Judah avoid such guilt! Do not journey to Gilgal, do not go up to Beth-aven, and do not swear on oath, ‘As surely as the LORD lives!’'),
('HOS', 4, 16, 'HOS.4.16', 'For Israel is as obstinate as a stubborn heifer. Can the LORD now shepherd them like lambs in an open meadow?'),
('HOS', 4, 17, 'HOS.4.17', 'Ephraim is joined to idols; leave him alone!'),
('HOS', 4, 18, 'HOS.4.18', 'When their liquor is gone, they turn to prostitution; their rulers dearly love disgrace.'),
('HOS', 4, 19, 'HOS.4.19', 'The whirlwind has wrapped them in its wings, and their sacrifices will bring them shame.'),
('HOS', 5, 1, 'HOS.5.1', '“Hear this, O priests! Take heed, O house of Israel! Give ear, O royal house! For this judgment is against you because you have been a snare at Mizpah, a net spread out on Tabor.'),
('HOS', 5, 2, 'HOS.5.2', 'The rebels are deep in slaughter; but I will chastise them all.'),
('HOS', 5, 3, 'HOS.5.3', 'I know all about Ephraim, and Israel is not hidden from Me. For now, O Ephraim, you have turned to prostitution; Israel is defiled.'),
('HOS', 5, 4, 'HOS.5.4', 'Their deeds do not permit them to return to their God, for a spirit of prostitution is within them, and they do not know the LORD.'),
('HOS', 5, 5, 'HOS.5.5', 'Israel’s arrogance testifies against them; Israel and Ephraim stumble in their iniquity; even Judah stumbles with them.'),
('HOS', 5, 6, 'HOS.5.6', 'They go with their flocks and herds to seek the LORD, but they do not find Him; He has withdrawn Himself from them.'),
('HOS', 5, 7, 'HOS.5.7', 'They have been unfaithful to the LORD; for they have borne illegitimate children. Now the New Moon will devour them along with their land.'),
('HOS', 5, 8, 'HOS.5.8', 'Blow the ram’s horn in Gibeah, the trumpet in Ramah; raise the battle cry in Beth-aven: Lead on, O Benjamin!'),
('HOS', 5, 9, 'HOS.5.9', 'Ephraim will be laid waste on the day of rebuke. Among the tribes of Israel I proclaim what is certain.'),
('HOS', 5, 10, 'HOS.5.10', 'The princes of Judah are like those who move boundary stones; I will pour out My fury upon them like water.'),
('HOS', 5, 11, 'HOS.5.11', 'Ephraim is oppressed, crushed in judgment, for he is determined to follow worthless idols.'),
('HOS', 5, 12, 'HOS.5.12', 'So I am like a moth to Ephraim, and like decay to the house of Judah.'),
('HOS', 5, 13, 'HOS.5.13', 'When Ephraim saw his sickness and Judah his wound, then Ephraim turned to Assyria and sent to the great king. But he cannot cure you or heal your wound.'),
('HOS', 5, 14, 'HOS.5.14', 'For I am like a lion to Ephraim and like a young lion to the house of Judah. I, even I, will tear them to pieces and then go away. I will carry them off where no one can rescue them.'),
('HOS', 5, 15, 'HOS.5.15', 'Then I will return to My place until they admit their guilt and seek My face; in their affliction they will earnestly seek Me.”'),
('HOS', 6, 1, 'HOS.6.1', 'Come, let us return to the LORD. For He has torn us to pieces, but He will heal us; He has wounded us, but He will bind up our wounds.'),
('HOS', 6, 2, 'HOS.6.2', 'After two days He will revive us; on the third day He will raise us up, that we may live in His presence.'),
('HOS', 6, 3, 'HOS.6.3', 'So let us know—let us press on to know the LORD. As surely as the sun rises, He will appear; He will come to us like the rain, like the spring showers that water the earth.'),
('HOS', 6, 4, 'HOS.6.4', 'What shall I do with you, O Ephraim? What shall I do with you, O Judah? For your loyalty is like a morning mist, like the early dew that vanishes.'),
('HOS', 6, 5, 'HOS.6.5', 'Therefore I have hewn them by the prophets; I have slain them by the words of My mouth, and My judgments go forth like lightning.'),
('HOS', 6, 6, 'HOS.6.6', 'For I desire mercy, not sacrifice, and the knowledge of God rather than burnt offerings.'),
('HOS', 6, 7, 'HOS.6.7', 'But they, like Adam, have transgressed the covenant; there they were unfaithful to Me.'),
('HOS', 6, 8, 'HOS.6.8', 'Gilead is a city of evildoers, tracked with footprints of blood.'),
('HOS', 6, 9, 'HOS.6.9', 'Like raiders who lie in ambush, so does a band of priests; they murder on the way to Shechem; surely they have committed atrocities.'),
('HOS', 6, 10, 'HOS.6.10', 'In the house of Israel I have seen a horrible thing: Ephraim practices prostitution there, and Israel is defiled.'),
('HOS', 6, 11, 'HOS.6.11', 'Also for you, O Judah, a harvest is appointed, when I restore My people from captivity.'),
('HOS', 7, 1, 'HOS.7.1', 'When I heal Israel, the iniquity of Ephraim will be exposed, as well as the crimes of Samaria. For they practice deceit and thieves break in; bandits raid in the streets.'),
('HOS', 7, 2, 'HOS.7.2', 'But they fail to consider in their hearts that I remember all their evil. Now their deeds are all around them; they are before My face.'),
('HOS', 7, 3, 'HOS.7.3', 'They delight the king with their evil, and the princes with their lies.'),
('HOS', 7, 4, 'HOS.7.4', 'They are all adulterers, like an oven heated by a baker who needs not stoke the fire from the kneading to the rising of the dough.'),
('HOS', 7, 5, 'HOS.7.5', 'The princes are inflamed with wine on the day of our king; so he joins hands with those who mock him.'),
('HOS', 7, 6, 'HOS.7.6', 'For they prepare their heart like an oven while they lie in wait; all night their anger smolders; in the morning it blazes like a flaming fire.'),
('HOS', 7, 7, 'HOS.7.7', 'All of them are hot as an oven, and they devour their rulers. All their kings fall; not one of them calls upon Me.'),
('HOS', 7, 8, 'HOS.7.8', 'Ephraim mixes with the nations; Ephraim is an unturned cake.'),
('HOS', 7, 9, 'HOS.7.9', 'Foreigners consume his strength, but he does not notice. Even his hair is streaked with gray, but he does not know.'),
('HOS', 7, 10, 'HOS.7.10', 'Israel’s arrogance testifies against them, yet they do not return to the LORD their God; despite all this, they do not seek Him.'),
('HOS', 7, 11, 'HOS.7.11', 'So Ephraim has become like a silly, senseless dove—calling out to Egypt, then turning to Assyria.'),
('HOS', 7, 12, 'HOS.7.12', 'As they go, I will spread My net over them; I will bring them down like birds of the air. I will chastise them when I hear them flocking together.'),
('HOS', 7, 13, 'HOS.7.13', 'Woe to them, for they have strayed from Me! Destruction to them, for they have rebelled against Me! Though I would redeem them, they speak lies against Me.'),
('HOS', 7, 14, 'HOS.7.14', 'They do not cry out to Me from their hearts when they wail upon their beds. They slash themselves for grain and new wine, but turn away from Me.'),
('HOS', 7, 15, 'HOS.7.15', 'Although I trained and strengthened their arms, they plot evil against Me.'),
('HOS', 7, 16, 'HOS.7.16', 'They turn, but not to the Most High; they are like a faulty bow. Their leaders will fall by the sword for the cursing of their tongue; for this they will be ridiculed in the land of Egypt.'),
('HOS', 8, 1, 'HOS.8.1', 'Put the ram’s horn to your lips! An eagle looms over the house of the LORD, because the people have transgressed My covenant and rebelled against My law.'),
('HOS', 8, 2, 'HOS.8.2', 'Israel cries out to Me, “O our God, we know You!”'),
('HOS', 8, 3, 'HOS.8.3', 'But Israel has rejected good; an enemy will pursue him.'),
('HOS', 8, 4, 'HOS.8.4', 'They set up kings, but not by Me. They make princes, but without My approval. With their silver and gold they make themselves idols, to their own destruction.'),
('HOS', 8, 5, 'HOS.8.5', 'He has rejected your calf, O Samaria. My anger burns against them. How long will they be incapable of innocence?'),
('HOS', 8, 6, 'HOS.8.6', 'For this thing is from Israel—a craftsman made it, and it is not God. It will be broken to pieces, that calf of Samaria.'),
('HOS', 8, 7, 'HOS.8.7', 'For they sow the wind, and they shall reap the whirlwind. There is no standing grain; what sprouts fails to yield flour. Even if it should produce, the foreigners would swallow it up.'),
('HOS', 8, 8, 'HOS.8.8', 'Israel is swallowed up! Now they are among the nations like a worthless vessel.'),
('HOS', 8, 9, 'HOS.8.9', 'For they have gone up to Assyria like a wild donkey on its own. Ephraim has hired lovers.'),
('HOS', 8, 10, 'HOS.8.10', 'Though they hire allies among the nations, I will now round them up, and they will begin to diminish under the oppression of the king of princes.'),
('HOS', 8, 11, 'HOS.8.11', 'Though Ephraim multiplied the altars for sin, they became his altars for sinning.'),
('HOS', 8, 12, 'HOS.8.12', 'Though I wrote for them the great things of My law, they regarded them as something strange.'),
('HOS', 8, 13, 'HOS.8.13', 'Though they offer sacrifices as gifts to Me, and though they eat the meat, the LORD does not accept them. Now He will remember their iniquity and punish their sins: They will return to Egypt.'),
('HOS', 8, 14, 'HOS.8.14', 'Israel has forgotten his Maker and built palaces; Judah has multiplied its fortified cities. But I will send fire upon their cities, and it will consume their citadels.'),
('HOS', 9, 1, 'HOS.9.1', 'Do not rejoice, O Israel, with exultation like the nations, for you have played the harlot against your God; you have made love for hire on every threshing floor.'),
('HOS', 9, 2, 'HOS.9.2', 'The threshing floor and winepress will not feed them, and the new wine will fail them.'),
('HOS', 9, 3, 'HOS.9.3', 'They will not remain in the land of the LORD; Ephraim will return to Egypt and eat unclean food in Assyria.'),
('HOS', 9, 4, 'HOS.9.4', 'They will not pour out wine offerings to the LORD, and their sacrifices will not please Him, but will be to them like the bread of mourners; all who eat will be defiled. For their bread will be for themselves; it will not enter the house of the LORD.'),
('HOS', 9, 5, 'HOS.9.5', 'What will you do on the appointed day, on the day of the LORD’s feast?'),
('HOS', 9, 6, 'HOS.9.6', 'For even if they flee destruction, Egypt will gather them and Memphis will bury them. Their precious silver will be taken over by thistles, and thorns will overrun their tents.'),
('HOS', 9, 7, 'HOS.9.7', 'The days of punishment have come; the days of retribution have arrived—let Israel know it. The prophet is called a fool, and the inspired man insane, because of the greatness of your iniquity and hostility.'),
('HOS', 9, 8, 'HOS.9.8', 'The prophet is Ephraim’s watchman, along with my God, yet the snare of the fowler lies on all his paths. Hostility is in the house of his God!'),
('HOS', 9, 9, 'HOS.9.9', 'They have deeply corrupted themselves as in the days of Gibeah; He will remember their guilt; He will punish their sins.'),
('HOS', 9, 10, 'HOS.9.10', 'I found Israel like grapes in the wilderness. I saw your fathers as the firstfruits of the fig tree in its first season. But they went to Baal-peor, and consecrated themselves to Shame; so they became as detestable as the thing they loved.'),
('HOS', 9, 11, 'HOS.9.11', 'Ephraim’s glory will fly away like a bird, with no birth, no pregnancy, and no conception.'),
('HOS', 9, 12, 'HOS.9.12', 'Even if they raise their children, I will bereave them of each one. Yes, woe be to them when I turn away from them!'),
('HOS', 9, 13, 'HOS.9.13', 'I have seen Ephraim, like Tyre, planted in a meadow. But Ephraim will bring out his children for slaughter.'),
('HOS', 9, 14, 'HOS.9.14', 'Give them, O LORD—what will You give? Give them wombs that miscarry and breasts that dry up!'),
('HOS', 9, 15, 'HOS.9.15', 'All their evil appears at Gilgal, for there I hated them. I will drive them from My house for the wickedness of their deeds. I will no longer love them; all their leaders are rebellious.'),
('HOS', 9, 16, 'HOS.9.16', 'Ephraim is struck down; their root is withered; they cannot bear fruit. Even if they bear children, I will slay the darlings of their wombs.'),
('HOS', 9, 17, 'HOS.9.17', 'My God will reject them because they have not obeyed Him; and they shall be wanderers among the nations.'),
('HOS', 10, 1, 'HOS.10.1', 'Israel was a luxuriant vine, yielding fruit for himself. The more his fruit increased, the more he increased the altars. The better his land produced, the better he made the sacred pillars.'),
('HOS', 10, 2, 'HOS.10.2', 'Their hearts are devious; now they must bear their guilt. The LORD will break down their altars and demolish their sacred pillars.'),
('HOS', 10, 3, 'HOS.10.3', 'Surely now they will say, “We have no king, for we do not revere the LORD. What can a king do for us?”'),
('HOS', 10, 4, 'HOS.10.4', 'They speak mere words; with false oaths they make covenants. So judgment springs up like poisonous weeds in the furrows of a field.'),
('HOS', 10, 5, 'HOS.10.5', 'The people of Samaria will fear for the calf of Beth-aven. Indeed, its people will mourn over it with its idolatrous priests—those who rejoiced in its glory—for it has been taken from them into exile.'),
('HOS', 10, 6, 'HOS.10.6', 'Yes, it will be carried to Assyria as tribute to the great king. Ephraim will be seized with shame; Israel will be ashamed of its wooden idols.'),
('HOS', 10, 7, 'HOS.10.7', 'Samaria will be carried off with her king like a twig on the surface of the water.'),
('HOS', 10, 8, 'HOS.10.8', 'The high places of Aven will be destroyed—it is the sin of Israel; thorns and thistles will overgrow their altars. Then they will say to the mountains, “Cover us!” and to the hills, “Fall on us!”'),
('HOS', 10, 9, 'HOS.10.9', 'Since the days of Gibeah you have sinned, O Israel, and there you have remained. Did not the battle in Gibeah overtake the sons of iniquity?'),
('HOS', 10, 10, 'HOS.10.10', 'I will chasten them when I please; nations will be gathered against them to put them in bondage for their double transgression.'),
('HOS', 10, 11, 'HOS.10.11', 'Ephraim is a well-trained heifer that loves to thresh; but I will place a yoke on her fair neck. I will harness Ephraim, Judah will plow, and Jacob will break the hard ground.'),
('HOS', 10, 12, 'HOS.10.12', 'Sow for yourselves righteousness and reap the fruit of loving devotion; break up your unplowed ground. For it is time to seek the LORD until He comes and sends righteousness upon you like rain.'),
('HOS', 10, 13, 'HOS.10.13', 'You have plowed wickedness and reaped injustice; you have eaten the fruit of lies. Because you have trusted in your own way and in the multitude of your mighty men,'),
('HOS', 10, 14, 'HOS.10.14', 'the roar of battle will rise against your people, so that all your fortresses will be demolished as Shalman devastated Beth-arbel in the day of battle, when mothers were dashed to pieces along with their children.'),
('HOS', 10, 15, 'HOS.10.15', 'Thus it will be done to you, O Bethel, because of your great wickedness. When the day dawns, the king of Israel will be utterly cut off.'),
('HOS', 11, 1, 'HOS.11.1', 'When Israel was a child, I loved him, and out of Egypt I called My son.'),
('HOS', 11, 2, 'HOS.11.2', 'But the more I called Israel, the farther they departed from Me. They sacrificed to the Baals and burned incense to carved images.'),
('HOS', 11, 3, 'HOS.11.3', 'It was I who taught Ephraim to walk, taking them by the arms, but they never realized that it was I who healed them.'),
('HOS', 11, 4, 'HOS.11.4', 'I led them with cords of kindness, with ropes of love; I lifted the yoke from their necks and bent down to feed them.'),
('HOS', 11, 5, 'HOS.11.5', 'Will they not return to the land of Egypt and be ruled by Assyria because they refused to repent?'),
('HOS', 11, 6, 'HOS.11.6', 'A sword will flash through their cities; it will destroy the bars of their gates and consume them in their own plans.'),
('HOS', 11, 7, 'HOS.11.7', 'My people are bent on turning from Me. Though they call to the Most High, He will by no means exalt them.'),
('HOS', 11, 8, 'HOS.11.8', 'How could I give you up, O Ephraim? How could I surrender you, O Israel? How could I make you like Admah? How could I treat you like Zeboiim? My heart is turned within Me; My compassion is stirred!'),
('HOS', 11, 9, 'HOS.11.9', 'I will not execute the full fury of My anger; I will not destroy Ephraim again. For I am God and not man—the Holy One among you—and I will not come in wrath.'),
('HOS', 11, 10, 'HOS.11.10', 'They will walk after the LORD; He will roar like a lion. When He roars, His children will come trembling from the west.'),
('HOS', 11, 11, 'HOS.11.11', 'They will come trembling like birds from Egypt and like doves from the land of Assyria. Then I will settle them in their homes, declares the LORD.'),
('HOS', 11, 12, 'HOS.11.12', 'Ephraim surrounds Me with lies, the house of Israel with deceit; but Judah still walks with God and is faithful to the Holy One.'),
('HOS', 12, 1, 'HOS.12.1', 'Ephraim feeds on the wind and pursues the east wind all day long; he multiplies lies and violence; he makes a covenant with Assyria and sends olive oil to Egypt.'),
('HOS', 12, 2, 'HOS.12.2', 'The LORD has a charge to bring against Judah. He will punish Jacob according to his ways and repay him according to his deeds.'),
('HOS', 12, 3, 'HOS.12.3', 'In the womb he grasped his brother’s heel, and in his vigor he wrestled with God.'),
('HOS', 12, 4, 'HOS.12.4', 'Yes, he struggled with the angel and prevailed; he wept and sought His favor; he found Him at Bethel and spoke with Him there—'),
('HOS', 12, 5, 'HOS.12.5', 'the LORD God of Hosts, the LORD is His name of renown.'),
('HOS', 12, 6, 'HOS.12.6', 'But you must return to your God; maintain love and justice, and always wait on your God.'),
('HOS', 12, 7, 'HOS.12.7', 'A merchant loves to defraud with dishonest scales in his hands.'),
('HOS', 12, 8, 'HOS.12.8', 'And Ephraim boasts: “How rich I have become! I have found wealth for myself. In all my labors, they can find in me no iniquity that is sinful.”'),
('HOS', 12, 9, 'HOS.12.9', 'But I am the LORD your God ever since the land of Egypt. I will again make you dwell in tents, as in the days of the appointed feast.'),
('HOS', 12, 10, 'HOS.12.10', 'I spoke through the prophets and multiplied their visions; I gave parables through the prophets.'),
('HOS', 12, 11, 'HOS.12.11', 'Is there iniquity in Gilead? They will surely come to nothing. Do they sacrifice bulls in Gilgal? Indeed, their altars will be heaps of stones in the furrows of the field.'),
('HOS', 12, 12, 'HOS.12.12', 'Jacob fled to the land of Aram and Israel worked for a wife—for a wife he tended sheep.'),
('HOS', 12, 13, 'HOS.12.13', 'But by a prophet the LORD brought Israel out of Egypt, and by a prophet he was preserved.'),
('HOS', 12, 14, 'HOS.12.14', 'Ephraim has provoked bitter anger, so his Lord will leave his bloodguilt upon him and repay him for his contempt.'),
('HOS', 13, 1, 'HOS.13.1', 'When Ephraim spoke, there was trembling; he was exalted in Israel. But he incurred guilt through Baal, and he died.'),
('HOS', 13, 2, 'HOS.13.2', 'Now they sin more and more and make for themselves cast images, idols skillfully made from their silver, all of them the work of craftsmen. People say of them, “They offer human sacrifice and kiss the calves!”'),
('HOS', 13, 3, 'HOS.13.3', 'Therefore they will be like the morning mist, like the early dew that vanishes, like chaff blown from a threshing floor, like smoke through an open window.'),
('HOS', 13, 4, 'HOS.13.4', 'Yet I am the LORD your God ever since the land of Egypt; you know no God but Me, for there is no Savior besides Me.'),
('HOS', 13, 5, 'HOS.13.5', 'I knew you in the wilderness, in the land of drought.'),
('HOS', 13, 6, 'HOS.13.6', 'When they had pasture, they became satisfied; when they were satisfied, their hearts became proud, and as a result they forgot Me.'),
('HOS', 13, 7, 'HOS.13.7', 'So like a lion I will pounce on them; like a leopard I will lurk by the path.'),
('HOS', 13, 8, 'HOS.13.8', 'Like a bear robbed of her cubs I will attack them, and I will tear open their chests. There I will devour them like a lion, like a wild beast tearing them apart.'),
('HOS', 13, 9, 'HOS.13.9', 'You are destroyed, O Israel, because you are against Me—against your helper.'),
('HOS', 13, 10, 'HOS.13.10', 'Where is your king now to save you in all your cities, and the rulers to whom you said, “Give me a king and princes”?'),
('HOS', 13, 11, 'HOS.13.11', 'So in My anger I gave you a king, and in My wrath I took him away.'),
('HOS', 13, 12, 'HOS.13.12', 'The iniquity of Ephraim is bound up; his sin is stored up.'),
('HOS', 13, 13, 'HOS.13.13', 'Labor pains come upon him, but he is an unwise son. When the time arrives, he fails to present himself at the opening of the womb.'),
('HOS', 13, 14, 'HOS.13.14', 'I will ransom them from the power of Sheol; I will redeem them from Death. Where, O Death, are your plagues? Where, O Sheol, is your sting? Compassion is hidden from My eyes.'),
('HOS', 13, 15, 'HOS.13.15', 'Although he flourishes among his brothers, an east wind will come—a wind from the LORD rising up from the desert. His fountain will fail, and his spring will run dry. The wind will plunder his treasury of every precious article.'),
('HOS', 13, 16, 'HOS.13.16', 'Samaria will bear her guilt because she has rebelled against her God. They will fall by the sword; their little ones will be dashed to pieces, and their pregnant women ripped open.'),
('HOS', 14, 1, 'HOS.14.1', 'Return, O Israel, to the LORD your God, for you have stumbled by your iniquity.'),
('HOS', 14, 2, 'HOS.14.2', 'Bring your confessions and return to the LORD. Say to Him: “Take away all our iniquity and receive us graciously, that we may present the fruit of our lips.'),
('HOS', 14, 3, 'HOS.14.3', 'Assyria will not save us, nor will we ride on horses. We will never again say, ‘Our gods!’ to the work of our own hands. For in You the fatherless find compassion.”'),
('HOS', 14, 4, 'HOS.14.4', 'I will heal their apostasy; I will freely love them, for My anger has turned away from them.'),
('HOS', 14, 5, 'HOS.14.5', 'I will be like the dew to Israel; he will blossom like the lily and take root like the cedars of Lebanon.'),
('HOS', 14, 6, 'HOS.14.6', 'His shoots will sprout, and his splendor will be like the olive tree, his fragrance like the cedars of Lebanon.'),
('HOS', 14, 7, 'HOS.14.7', 'They will return and dwell in his shade; they will grow grain and blossom like the vine. His renown will be like the wine of Lebanon.'),
('HOS', 14, 8, 'HOS.14.8', 'O Ephraim, what have I to do anymore with idols? It is I who answer and watch over him. I am like a flourishing cypress; your fruit comes from Me.'),
('HOS', 14, 9, 'HOS.14.9', 'Whoever is wise, let him understand these things; whoever is discerning, let him know them. For the ways of the LORD are right, and the righteous walk in them but the rebellious stumble in them.'),
('JOL', 1, 1, 'JOL.1.1', 'This is the word of the LORD that came to Joel son of Pethuel:'),
('JOL', 1, 2, 'JOL.1.2', 'Hear this, O elders; and give ear, all who dwell in the land. Has anything like this ever happened in your days or in the days of your fathers?'),
('JOL', 1, 3, 'JOL.1.3', 'Tell it to your children; let your children tell it to their children, and their children to the next generation.'),
('JOL', 1, 4, 'JOL.1.4', 'What the devouring locust has left, the swarming locust has eaten; what the swarming locust has left, the young locust has eaten; and what the young locust has left, the destroying locust has eaten.'),
('JOL', 1, 5, 'JOL.1.5', 'Wake up, you drunkards, and weep; wail, all you drinkers of wine, because of the sweet wine, for it has been cut off from your mouth.'),
('JOL', 1, 6, 'JOL.1.6', 'For a nation has invaded My land, powerful and without number; its teeth are the teeth of a lion, and its fangs are the fangs of a lioness.'),
('JOL', 1, 7, 'JOL.1.7', 'It has laid waste My grapevine and splintered My fig tree. It has stripped off the bark and thrown it away; the branches have turned white.'),
('JOL', 1, 8, 'JOL.1.8', 'Wail like a virgin dressed in sackcloth, grieving for the husband of her youth.'),
('JOL', 1, 9, 'JOL.1.9', 'Grain and drink offerings have been cut off from the house of the LORD; the priests are in mourning, those who minister before the LORD.'),
('JOL', 1, 10, 'JOL.1.10', 'The field is ruined; the land mourns. For the grain is destroyed, the new wine is dried up, and the oil fails.'),
('JOL', 1, 11, 'JOL.1.11', 'Be dismayed, O farmers, wail, O vinedressers, over the wheat and barley, because the harvest of the field has perished.'),
('JOL', 1, 12, 'JOL.1.12', 'The grapevine is dried up, and the fig tree is withered; the pomegranate, palm, and apple—all the trees of the orchard—are withered. Surely the joy of mankind has dried up.'),
('JOL', 1, 13, 'JOL.1.13', 'Put on sackcloth and lament, O priests; wail, O ministers of the altar. Come, spend the night in sackcloth, O ministers of my God, because the grain and drink offerings are withheld from the house of your God.'),
('JOL', 1, 14, 'JOL.1.14', 'Consecrate a fast; proclaim a solemn assembly! Gather the elders and all the residents of the land to the house of the LORD your God, and cry out to the LORD.'),
('JOL', 1, 15, 'JOL.1.15', 'Alas for the day! For the Day of the LORD is near, and it will come as destruction from the Almighty.'),
('JOL', 1, 16, 'JOL.1.16', 'Has not the food been cut off before our very eyes—joy and gladness from the house of our God?'),
('JOL', 1, 17, 'JOL.1.17', 'The seeds lie shriveled beneath the clods; the storehouses are in ruins; the granaries are broken down, for the grain has withered away.'),
('JOL', 1, 18, 'JOL.1.18', 'How the cattle groan! The herds wander in confusion because they have no pasture. Even the flocks of sheep are suffering.'),
('JOL', 1, 19, 'JOL.1.19', 'To You, O LORD, I call, for fire has consumed the open pastures and flames have scorched all the trees of the field.'),
('JOL', 1, 20, 'JOL.1.20', 'Even the beasts of the field pant for You, for the streams of water have dried up, and fire has consumed the open pastures.'),
('JOL', 2, 1, 'JOL.2.1', 'Blow the ram’s horn in Zion; sound the alarm on My holy mountain! Let all who dwell in the land tremble, for the Day of the LORD is coming; indeed, it is near—'),
('JOL', 2, 2, 'JOL.2.2', 'a day of darkness and gloom, a day of clouds and blackness. Like the dawn overspreading the mountains a great and strong army appears, such as never was of old, nor will ever be in ages to come.'),
('JOL', 2, 3, 'JOL.2.3', 'Before them a fire devours, and behind them a flame scorches. The land before them is like the Garden of Eden, but behind them, it is like a desert wasteland—surely nothing will escape them.'),
('JOL', 2, 4, 'JOL.2.4', 'Their appearance is like that of horses, and they gallop like swift steeds.'),
('JOL', 2, 5, 'JOL.2.5', 'With a sound like that of chariots they bound over the mountaintops, like the crackling of fire consuming stubble, like a mighty army deployed for battle.'),
('JOL', 2, 6, 'JOL.2.6', 'Nations writhe in horror before them; every face turns pale.'),
('JOL', 2, 7, 'JOL.2.7', 'They charge like mighty men; they scale the walls like men of war. Each one marches in formation, not swerving from the course.'),
('JOL', 2, 8, 'JOL.2.8', 'They do not jostle one another; each proceeds in his path. They burst through the defenses, never breaking ranks.'),
('JOL', 2, 9, 'JOL.2.9', 'They storm the city; they run along the wall; they climb into houses, entering through windows like thieves.'),
('JOL', 2, 10, 'JOL.2.10', 'Before them the earth quakes; the heavens tremble. The sun and moon grow dark, and the stars lose their brightness.'),
('JOL', 2, 11, 'JOL.2.11', 'The LORD raises His voice in the presence of His army. Indeed, His camp is very large, for mighty are those who obey His command. For the Day of the LORD is great and very dreadful. Who can endure it?'),
('JOL', 2, 12, 'JOL.2.12', '“Yet even now,” declares the LORD, “return to Me with all your heart, with fasting, weeping, and mourning.”'),
('JOL', 2, 13, 'JOL.2.13', 'So rend your hearts and not your garments, and return to the LORD your God. For He is gracious and compassionate, slow to anger, abounding in loving devotion. And He relents from sending disaster.'),
('JOL', 2, 14, 'JOL.2.14', 'Who knows? He may turn and relent and leave a blessing behind Him—grain and drink offerings for the LORD your God.'),
('JOL', 2, 15, 'JOL.2.15', 'Blow the ram’s horn in Zion, consecrate a fast, proclaim a sacred assembly.'),
('JOL', 2, 16, 'JOL.2.16', 'Gather the people, sanctify the congregation, assemble the aged, gather the children, even those nursing at the breast. Let the bridegroom leave his room, and the bride her chamber.'),
('JOL', 2, 17, 'JOL.2.17', 'Let the priests who minister before the LORD weep between the portico and the altar, saying, “Spare Your people, O LORD, and do not make Your heritage a reproach, an object of scorn among the nations. Why should they say among the peoples, ‘Where is their God?’”'),
('JOL', 2, 18, 'JOL.2.18', 'Then the LORD became jealous for His land, and He spared His people.'),
('JOL', 2, 19, 'JOL.2.19', 'And the LORD answered His people: “Behold, I will send you grain, new wine, and oil, and by them you will be satisfied. I will never again make you a reproach among the nations.'),
('JOL', 2, 20, 'JOL.2.20', 'The northern army I will drive away from you, banishing it to a barren and desolate land, its front ranks into the Eastern Sea, and its rear guard into the Western Sea. And its stench will rise; its foul odor will ascend. For He has done great things.'),
('JOL', 2, 21, 'JOL.2.21', 'Do not be afraid, O land; rejoice and be glad, for the LORD has done great things.'),
('JOL', 2, 22, 'JOL.2.22', 'Do not be afraid, O beasts of the field, for the open pastures have turned green, the trees bear their fruit, and the fig tree and vine yield their best.'),
('JOL', 2, 23, 'JOL.2.23', 'Be glad, O children of Zion, and rejoice in the LORD your God, for He has given you the autumn rains for your vindication. He sends you showers, both autumn and spring rains, as before.'),
('JOL', 2, 24, 'JOL.2.24', 'The threshing floors will be full of grain, and the vats will overflow with new wine and oil.'),
('JOL', 2, 25, 'JOL.2.25', 'I will repay you for the years eaten by locusts—the swarming locust, the young locust, the destroying locust, and the devouring locust—My great army that I sent against you.'),
('JOL', 2, 26, 'JOL.2.26', 'You will have plenty to eat, until you are satisfied. You will praise the name of the LORD your God, who has worked wonders for you. My people will never again be put to shame.'),
('JOL', 2, 27, 'JOL.2.27', 'Then you will know that I am present in Israel and that I am the LORD your God, and there is no other. My people will never again be put to shame.'),
('JOL', 2, 28, 'JOL.2.28', 'And afterward, I will pour out My Spirit on all people. Your sons and daughters will prophesy, your old men will dream dreams, your young men will see visions.'),
('JOL', 2, 29, 'JOL.2.29', 'Even on My menservants and maidservants, I will pour out My Spirit in those days.'),
('JOL', 2, 30, 'JOL.2.30', 'I will show wonders in the heavens and on the earth, blood and fire and columns of smoke.'),
('JOL', 2, 31, 'JOL.2.31', 'The sun will be turned to darkness and the moon to blood before the coming of the great and awesome Day of the LORD.'),
('JOL', 2, 32, 'JOL.2.32', 'And everyone who calls on the name of the LORD will be saved; for on Mount Zion and in Jerusalem there will be deliverance, as the LORD has promised, among the remnant called by the LORD.'),
('JOL', 3, 1, 'JOL.3.1', '“Yes, in those days and at that time, when I restore Judah and Jerusalem from captivity,'),
('JOL', 3, 2, 'JOL.3.2', 'I will gather all the nations and bring them down to the Valley of Jehoshaphat. There I will enter into judgment against them concerning My people, My inheritance, Israel, whom they have scattered among the nations as they divided up My land.'),
('JOL', 3, 3, 'JOL.3.3', 'They cast lots for My people; they bartered a boy for a prostitute and sold a girl for wine to drink.'),
('JOL', 3, 4, 'JOL.3.4', 'Now what do you have against Me, O Tyre, Sidon, and all the regions of Philistia? Are you rendering against Me a recompense? If you retaliate against Me, I will swiftly and speedily return your recompense upon your heads.'),
('JOL', 3, 5, 'JOL.3.5', 'For you took My silver and gold and carried off My finest treasures to your temples.'),
('JOL', 3, 6, 'JOL.3.6', 'You sold the people of Judah and Jerusalem to the Greeks, to send them far from their homeland.'),
('JOL', 3, 7, 'JOL.3.7', 'Behold, I will rouse them from the places to which you sold them; I will return your recompense upon your heads.'),
('JOL', 3, 8, 'JOL.3.8', 'I will sell your sons and daughters into the hands of the people of Judah, and they will sell them to the Sabeans—to a distant nation.” Indeed, the LORD has spoken.'),
('JOL', 3, 9, 'JOL.3.9', 'Proclaim this among the nations: “Prepare for war; rouse the mighty men; let all the men of war advance and attack!'),
('JOL', 3, 10, 'JOL.3.10', 'Beat your plowshares into swords and your pruning hooks into spears. Let the weak say, ‘I am strong!’'),
('JOL', 3, 11, 'JOL.3.11', 'Come quickly, all you surrounding nations, and gather yourselves. Bring down Your mighty ones, O LORD.'),
('JOL', 3, 12, 'JOL.3.12', 'Let the nations be roused and advance to the Valley of Jehoshaphat, for there I will sit down to judge all the nations on every side.'),
('JOL', 3, 13, 'JOL.3.13', 'Swing the sickle, for the harvest is ripe. Come, trample the grapes, for the winepress is full; the wine vats overflow because their wickedness is great.'),
('JOL', 3, 14, 'JOL.3.14', 'Multitudes, multitudes in the valley of decision! For the Day of the LORD is near in the valley of decision.'),
('JOL', 3, 15, 'JOL.3.15', 'The sun and moon will grow dark, and the stars will no longer shine.'),
('JOL', 3, 16, 'JOL.3.16', 'The LORD will roar from Zion and raise His voice from Jerusalem; heaven and earth will tremble. But the LORD will be a refuge for His people, a stronghold for the people of Israel.'),
('JOL', 3, 17, 'JOL.3.17', 'Then you will know that I am the LORD your God, who dwells in Zion, My holy mountain. Jerusalem will be holy, never again to be overrun by foreigners.'),
('JOL', 3, 18, 'JOL.3.18', 'And in that day the mountains will drip with sweet wine, and the hills will flow with milk. All the streams of Judah will run with water, and a spring will flow from the house of the LORD to water the Valley of Acacias.'),
('JOL', 3, 19, 'JOL.3.19', 'Egypt will become desolate, and Edom a desert wasteland, because of the violence done to the people of Judah, in whose land they shed innocent blood.'),
('JOL', 3, 20, 'JOL.3.20', 'But Judah will be inhabited forever, and Jerusalem from generation to generation.'),
('JOL', 3, 21, 'JOL.3.21', 'For I will avenge their blood, which I have not yet avenged.” For the LORD dwells in Zion.'),
('AMO', 1, 1, 'AMO.1.1', 'These are the words of Amos, who was among the sheepherders of Tekoa—what he saw concerning Israel two years before the earthquake, in the days when Uzziah was king of Judah and Jeroboam son of Jehoash was king of Israel.'),
('AMO', 1, 2, 'AMO.1.2', 'He said: “The LORD roars from Zion and raises His voice from Jerusalem; the pastures of the shepherds mourn, and the summit of Carmel withers.”'),
('AMO', 1, 3, 'AMO.1.3', 'This is what the LORD says: “For three transgressions of Damascus, even four, I will not revoke My judgment, because they threshed Gilead with sledges of iron.'),
('AMO', 1, 4, 'AMO.1.4', 'So I will send fire upon the house of Hazael to consume the citadels of Ben-hadad.'),
('AMO', 1, 5, 'AMO.1.5', 'I will break down the gates of Damascus; I will cut off the ruler from the Valley of Aven and the one who wields the scepter in Beth-eden. The people of Aram will be exiled to Kir,” says the LORD.'),
('AMO', 1, 6, 'AMO.1.6', 'This is what the LORD says: “For three transgressions of Gaza, even four, I will not revoke My judgment, because they exiled a whole population, delivering them up to Edom.'),
('AMO', 1, 7, 'AMO.1.7', 'So I will send fire upon the walls of Gaza, to consume its citadels.'),
('AMO', 1, 8, 'AMO.1.8', 'I will cut off the ruler of Ashdod and the one who wields the scepter in Ashkelon. I will turn My hand against Ekron, and the remnant of the Philistines will perish,” says the Lord GOD.'),
('AMO', 1, 9, 'AMO.1.9', 'This is what the LORD says: “For three transgressions of Tyre, even four, I will not revoke My judgment, because they delivered up a whole congregation of exiles to Edom and broke a covenant of brotherhood.'),
('AMO', 1, 10, 'AMO.1.10', 'So I will send fire upon the walls of Tyre to consume its citadels.”'),
('AMO', 1, 11, 'AMO.1.11', 'This is what the LORD says: “For three transgressions of Edom, even four, I will not revoke My judgment, because he pursued his brother with the sword and stifled all compassion; his anger raged continually, and his fury flamed incessantly.'),
('AMO', 1, 12, 'AMO.1.12', 'So I will send fire upon Teman to consume the citadels of Bozrah.”'),
('AMO', 1, 13, 'AMO.1.13', 'This is what the LORD says: “For three transgressions of the Ammonites, even four, I will not revoke My judgment, because they ripped open the pregnant women of Gilead in order to enlarge their territory.'),
('AMO', 1, 14, 'AMO.1.14', 'So I will kindle a fire in the walls of Rabbah to consume its citadels amid war cries on the day of battle and a violent wind on the day of tempest.'),
('AMO', 1, 15, 'AMO.1.15', 'Their king will go into exile—he and his princes together,” says the LORD.'),
('AMO', 2, 1, 'AMO.2.1', 'This is what the LORD says: “For three transgressions of Moab, even four, I will not revoke My judgment, because he burned to lime the bones of Edom’s king.'),
('AMO', 2, 2, 'AMO.2.2', 'So I will send fire against Moab to consume the citadels of Kerioth. Moab will die in tumult, amid war cries and the sound of the ram’s horn.'),
('AMO', 2, 3, 'AMO.2.3', 'I will cut off the ruler of Moab and kill all the officials with him,” says the LORD.'),
('AMO', 2, 4, 'AMO.2.4', 'This is what the LORD says: “For three transgressions of Judah, even four, I will not revoke My judgment, because they reject the Law of the LORD and fail to keep His statutes; they are led astray by the lies in which their fathers walked.'),
('AMO', 2, 5, 'AMO.2.5', 'So I will send fire upon Judah to consume the citadels of Jerusalem.”'),
('AMO', 2, 6, 'AMO.2.6', 'This is what the LORD says: “For three transgressions of Israel, even four, I will not revoke My judgment, because they sell the righteous for silver and the needy for a pair of sandals.'),
('AMO', 2, 7, 'AMO.2.7', 'They trample on the heads of the poor as on the dust of the earth; they push the needy out of their way. A man and his father have relations with the same girl and so profane My holy name.'),
('AMO', 2, 8, 'AMO.2.8', 'They lie down beside every altar on garments taken in pledge. And in the house of their God, they drink wine obtained through fines.'),
('AMO', 2, 9, 'AMO.2.9', 'Yet it was I who destroyed the Amorite before them, though his height was like that of the cedars, and he was as strong as the oaks. Yet I destroyed his fruit above and his roots below.'),
('AMO', 2, 10, 'AMO.2.10', 'And I brought you up from the land of Egypt and led you forty years in the wilderness, that you might take possession of the land of the Amorite.'),
('AMO', 2, 11, 'AMO.2.11', 'I raised up prophets from your sons and Nazirites from your young men. Is this not true, O children of Israel?” declares the LORD.'),
('AMO', 2, 12, 'AMO.2.12', '“But you made the Nazirites drink wine and commanded the prophets not to prophesy.'),
('AMO', 2, 13, 'AMO.2.13', 'Behold, I am about to crush you in your place as with a cart full of grain.'),
('AMO', 2, 14, 'AMO.2.14', 'Escape will fail the swift, the strong will not prevail by his strength, and the mighty will not save his life.'),
('AMO', 2, 15, 'AMO.2.15', 'The archer will not stand his ground, the fleet of foot will not escape, and the horseman will not save his life.'),
('AMO', 2, 16, 'AMO.2.16', 'Even the bravest of mighty men will flee naked on that day,” declares the LORD.'),
('AMO', 3, 1, 'AMO.3.1', 'Hear this word that the LORD has spoken against you, O children of Israel, against the whole family that I brought up out of the land of Egypt:'),
('AMO', 3, 2, 'AMO.3.2', '“Only you have I known from all the families of the earth; therefore I will punish you for all your iniquities.”'),
('AMO', 3, 3, 'AMO.3.3', 'Can two walk together without agreeing where to go?'),
('AMO', 3, 4, 'AMO.3.4', 'Does a lion roar in the forest when he has no prey? Does a young lion growl in his den if he has caught nothing?'),
('AMO', 3, 5, 'AMO.3.5', 'Does a bird land in a snare where no bait has been set? Does a trap spring from the ground when it has nothing to catch?'),
('AMO', 3, 6, 'AMO.3.6', 'If a ram’s horn sounds in a city, do the people not tremble? If calamity comes to a city, has not the LORD caused it?'),
('AMO', 3, 7, 'AMO.3.7', 'Surely the Lord GOD does nothing without revealing His plan to His servants the prophets.'),
('AMO', 3, 8, 'AMO.3.8', 'The lion has roared—who will not fear? The Lord GOD has spoken—who will not prophesy?'),
('AMO', 3, 9, 'AMO.3.9', 'Proclaim to the citadels of Ashdod and to the citadels of Egypt: “Assemble on the mountains of Samaria; see the great unrest in the city and the acts of oppression in her midst.”'),
('AMO', 3, 10, 'AMO.3.10', '“For they know not how to do right,” declares the LORD. “They store up violence and destruction in their citadels.”'),
('AMO', 3, 11, 'AMO.3.11', 'Therefore this is what the Lord GOD says: “An enemy will surround the land; he will pull down your strongholds and plunder your citadels.”'),
('AMO', 3, 12, 'AMO.3.12', 'This is what the LORD says: “As the shepherd snatches from the mouth of the lion two legs or a piece of an ear, so the Israelites dwelling in Samaria will be rescued having just the corner of a bed or the cushion of a couch.'),
('AMO', 3, 13, 'AMO.3.13', 'Hear and testify against the house of Jacob, declares the Lord GOD, the God of Hosts.'),
('AMO', 3, 14, 'AMO.3.14', 'On the day I punish Israel for their transgressions, I will visit destruction on the altars of Bethel; the horns of the altar will be cut off, and they will fall to the ground.'),
('AMO', 3, 15, 'AMO.3.15', 'I will tear down the winter house along with the summer house; the houses of ivory will also perish, and the great houses will come to an end,” declares the LORD.'),
('AMO', 4, 1, 'AMO.4.1', 'Hear this word, you cows of Bashan on Mount Samaria, you women who oppress the poor and crush the needy, who say to your husbands, “Bring us more to drink.”'),
('AMO', 4, 2, 'AMO.4.2', 'The Lord GOD has sworn by His holiness: “Behold, the days are coming when you will be taken away with hooks, and your posterity with fishhooks.'),
('AMO', 4, 3, 'AMO.4.3', 'You will go out through broken walls, each one straight ahead of her, and you will be cast out toward Harmon,” declares the LORD.'),
('AMO', 4, 4, 'AMO.4.4', '“Go to Bethel and transgress; rebel even more at Gilgal! Bring your sacrifices every morning, your tithes every three days.'),
('AMO', 4, 5, 'AMO.4.5', 'Offer leavened bread as a thank offering, and loudly proclaim your freewill offerings. For that is what you children of Israel love to do,” declares the Lord GOD.'),
('AMO', 4, 6, 'AMO.4.6', '“I afflicted all your cities with cleanness of teeth and all your towns with lack of bread, yet you did not return to Me,” declares the LORD.'),
('AMO', 4, 7, 'AMO.4.7', '“I also withheld the rain from you when the harvest was three months away. I sent rain on one city but withheld it from another. One field received rain; another without rain withered.'),
('AMO', 4, 8, 'AMO.4.8', 'People staggered from city to city for water to drink, but they were not satisfied; yet you did not return to Me,” declares the LORD.'),
('AMO', 4, 9, 'AMO.4.9', '“I struck you with blight and mildew in your growing gardens and vineyards; the locust devoured your fig and olive trees, yet you did not return to Me,” declares the LORD.'),
('AMO', 4, 10, 'AMO.4.10', '“I sent plagues among you like those of Egypt; I killed your young men with the sword, along with your captured horses. I filled your nostrils with the stench of your camp, yet you did not return to Me,” declares the LORD.'),
('AMO', 4, 11, 'AMO.4.11', '“Some of you I overthrew as I overthrew Sodom and Gomorrah, and you were like a firebrand snatched from a blaze, yet you did not return to Me,” declares the LORD.'),
('AMO', 4, 12, 'AMO.4.12', '“Therefore, that is what I will do to you, O Israel, and since I will do this to you, prepare to meet your God, O Israel!'),
('AMO', 4, 13, 'AMO.4.13', 'For behold, He who forms the mountains, who creates the wind and reveals His thoughts to man, who turns the dawn to darkness and strides on the heights of the earth—the LORD, the God of Hosts, is His name.”'),
('AMO', 5, 1, 'AMO.5.1', 'Hear this word, O house of Israel, this lamentation I take up against you:'),
('AMO', 5, 2, 'AMO.5.2', '“Fallen is Virgin Israel, never to rise again. She lies abandoned on her land, with no one to raise her up.”'),
('AMO', 5, 3, 'AMO.5.3', 'This is what the Lord GOD says: “The city that marches out a thousand strong will have but a hundred left, and the one that marches out a hundred strong will have but ten left in the house of Israel.”'),
('AMO', 5, 4, 'AMO.5.4', 'For this is what the LORD says to the house of Israel: “Seek Me and live!'),
('AMO', 5, 5, 'AMO.5.5', 'Do not seek Bethel or go to Gilgal; do not journey to Beersheba, for Gilgal will surely go into exile, and Bethel will come to nothing.'),
('AMO', 5, 6, 'AMO.5.6', 'Seek the LORD and live, or He will sweep like fire through the house of Joseph; it will devour everything, with no one at Bethel to extinguish it.'),
('AMO', 5, 7, 'AMO.5.7', 'There are those who turn justice into wormwood and cast righteousness to the ground.'),
('AMO', 5, 8, 'AMO.5.8', 'He who made the Pleiades and Orion, who turns darkness into dawn and darkens day into night, who summons the waters of the sea and pours them over the face of the earth—the LORD is His name—'),
('AMO', 5, 9, 'AMO.5.9', 'He flashes destruction on the strong, so that fury comes upon the stronghold.'),
('AMO', 5, 10, 'AMO.5.10', 'There are those who hate the one who reproves in the gate and despise him who speaks with integrity.'),
('AMO', 5, 11, 'AMO.5.11', 'Therefore, because you trample on the poor and exact from him a tax of grain, you will never live in the stone houses you have built; you will never drink the wine from the lush vineyards you have planted.'),
('AMO', 5, 12, 'AMO.5.12', 'For I know that your transgressions are many and your sins are numerous. You oppress the righteous by taking bribes; you deprive the poor of justice in the gate.'),
('AMO', 5, 13, 'AMO.5.13', 'Therefore, the prudent keep silent in such times, for the days are evil.'),
('AMO', 5, 14, 'AMO.5.14', 'Seek good, not evil, so that you may live. And the LORD, the God of Hosts, will be with you, as you have claimed.'),
('AMO', 5, 15, 'AMO.5.15', 'Hate evil and love good; establish justice in the gate. Perhaps the LORD, the God of Hosts, will be gracious to the remnant of Joseph.”'),
('AMO', 5, 16, 'AMO.5.16', 'Therefore this is what the LORD, the God of Hosts, the Lord, says: “There will be wailing in all the public squares and cries of ‘Alas! Alas!’ in all the streets. The farmer will be summoned to mourn, and the mourners to wail.'),
('AMO', 5, 17, 'AMO.5.17', 'There will be wailing in all the vineyards, for I will pass through your midst,” says the LORD.'),
('AMO', 5, 18, 'AMO.5.18', 'Woe to you who long for the Day of the LORD! What will the Day of the LORD be for you? It will be darkness and not light.'),
('AMO', 5, 19, 'AMO.5.19', 'It will be like a man who flees from a lion, only to encounter a bear, or who enters his house and rests his hand against the wall, only to be bitten by a snake.'),
('AMO', 5, 20, 'AMO.5.20', 'Will not the Day of the LORD be darkness and not light, even gloom with no brightness in it?'),
('AMO', 5, 21, 'AMO.5.21', '“I hate, I despise your feasts! I cannot stand the stench of your solemn assemblies.'),
('AMO', 5, 22, 'AMO.5.22', 'Even though you offer Me burnt offerings and grain offerings, I will not accept them; for your peace offerings of fattened cattle I will have no regard.'),
('AMO', 5, 23, 'AMO.5.23', 'Take away from Me the noise of your songs! I will not listen to the music of your harps.'),
('AMO', 5, 24, 'AMO.5.24', 'But let justice roll on like a river, and righteousness like an ever-flowing stream.'),
('AMO', 5, 25, 'AMO.5.25', 'Did you bring Me sacrifices and offerings forty years in the wilderness, O house of Israel?'),
('AMO', 5, 26, 'AMO.5.26', 'You have taken along Sakkuth your king and Kaiwan your star god, the idols you made for yourselves.'),
('AMO', 5, 27, 'AMO.5.27', 'Therefore I will send you into exile beyond Damascus,” says the LORD, whose name is the God of Hosts.'),
('AMO', 6, 1, 'AMO.6.1', 'Woe to those at ease in Zion and those secure on Mount Samaria, the distinguished ones of the foremost nation, to whom the house of Israel comes.'),
('AMO', 6, 2, 'AMO.6.2', 'Cross over to Calneh and see; go from there to the great Hamath; then go down to Gath of the Philistines. Are you better than these kingdoms? Is their territory larger than yours?'),
('AMO', 6, 3, 'AMO.6.3', 'You dismiss the day of calamity and bring near a reign of violence.'),
('AMO', 6, 4, 'AMO.6.4', 'You lie on beds inlaid with ivory, and lounge upon your couches. You dine on lambs from the flock and calves from the stall.'),
('AMO', 6, 5, 'AMO.6.5', 'You improvise songs on the harp like David and invent your own musical instruments.'),
('AMO', 6, 6, 'AMO.6.6', 'You drink wine by the bowlful and anoint yourselves with the finest oils, but you fail to grieve over the ruin of Joseph.'),
('AMO', 6, 7, 'AMO.6.7', 'Therefore, you will now go into exile as the first of the captives, and your feasting and lounging will come to an end.'),
('AMO', 6, 8, 'AMO.6.8', 'The Lord GOD has sworn by Himself—the LORD, the God of Hosts, has declared: “I abhor Jacob’s pride and detest his citadels, so I will deliver up the city and everything in it.”'),
('AMO', 6, 9, 'AMO.6.9', 'And if there are ten men left in one house, they too will die.'),
('AMO', 6, 10, 'AMO.6.10', 'And when the relative who is to burn the bodies picks them up to remove them from the house, he will call to one inside, “Is anyone else with you?” “None,” that person will answer. “Silence,” the relative will retort, “for the name of the LORD must not be invoked.”'),
('AMO', 6, 11, 'AMO.6.11', 'For the LORD gives a command: “The great house will be smashed to pieces, and the small house to rubble.”'),
('AMO', 6, 12, 'AMO.6.12', '“Do horses gallop on the cliffs? Does one plow the sea with oxen? But you have turned justice into poison and the fruit of righteousness into wormwood—'),
('AMO', 6, 13, 'AMO.6.13', 'you who rejoice in Lo-debar and say, ‘Did we not take Karnaim by our own strength?’'),
('AMO', 6, 14, 'AMO.6.14', 'For behold, I will raise up a nation against you, O house of Israel,” declares the LORD, the God of Hosts, “and they will oppress you from Lebo-hamath to the Brook of the Arabah.”'),
('AMO', 7, 1, 'AMO.7.1', 'This is what the Lord GOD showed me: He was preparing swarms of locusts just after the king’s harvest, as the late spring crop was coming up.'),
('AMO', 7, 2, 'AMO.7.2', 'And when the locusts had eaten every green plant in the land, I said, “Lord GOD, please forgive! How will Jacob survive, since he is so small?”'),
('AMO', 7, 3, 'AMO.7.3', 'So the LORD relented from this plan. “It will not happen,” He said.'),
('AMO', 7, 4, 'AMO.7.4', 'This is what the Lord GOD showed me: The Lord GOD was calling for judgment by fire. It consumed the great deep and devoured the land.'),
('AMO', 7, 5, 'AMO.7.5', 'Then I said, “Lord GOD, please stop! How will Jacob survive, since he is so small?”'),
('AMO', 7, 6, 'AMO.7.6', 'So the LORD relented from this plan. “It will not happen either,” said the Lord GOD.'),
('AMO', 7, 7, 'AMO.7.7', 'This is what He showed me: Behold, the Lord was standing by a wall true to plumb, with a plumb line in His hand.'),
('AMO', 7, 8, 'AMO.7.8', '“Amos, what do you see?” asked the LORD. “A plumb line,” I replied. “Behold,” said the Lord, “I am setting a plumb line among My people Israel; I will no longer spare them:'),
('AMO', 7, 9, 'AMO.7.9', 'The high places of Isaac will be deserted, and the sanctuaries of Israel will be laid waste; and I will rise up against the house of Jeroboam with My sword.”'),
('AMO', 7, 10, 'AMO.7.10', 'Then Amaziah the priest of Bethel sent word to Jeroboam king of Israel, saying, “Amos has conspired against you in the midst of the house of Israel. The land cannot bear all his words,'),
('AMO', 7, 11, 'AMO.7.11', 'for this is what Amos has said: ‘Jeroboam will die by the sword, and Israel will surely go into exile, away from their homeland.’”'),
('AMO', 7, 12, 'AMO.7.12', 'And Amaziah said to Amos, “Go away, you seer! Flee to the land of Judah; earn your bread there and do your prophesying there.'),
('AMO', 7, 13, 'AMO.7.13', 'But never prophesy at Bethel again, because it is the sanctuary of the king and the temple of the kingdom.”'),
('AMO', 7, 14, 'AMO.7.14', '“I was not a prophet,” Amos replied, “nor was I the son of a prophet; rather, I was a herdsman and a tender of sycamore-fig trees.'),
('AMO', 7, 15, 'AMO.7.15', 'But the LORD took me from following the flock and said to me, ‘Go, prophesy to My people Israel.’'),
('AMO', 7, 16, 'AMO.7.16', 'Now, therefore, hear the word of the LORD. You say: ‘Do not prophesy against Israel; do not preach against the house of Isaac.’'),
('AMO', 7, 17, 'AMO.7.17', 'Therefore this is what the LORD says: ‘Your wife will become a prostitute in the city, and your sons and daughters will fall by the sword. Your land will be divided by a measuring line, and you yourself will die on pagan soil. And Israel will surely go into exile, away from their homeland.’”'),
('AMO', 8, 1, 'AMO.8.1', 'This is what the Lord GOD showed me: I saw a basket of summer fruit.'),
('AMO', 8, 2, 'AMO.8.2', '“Amos, what do you see?” He asked. “A basket of summer fruit,” I replied. So the LORD said to me, “The end has come for My people Israel; I will no longer spare them.”'),
('AMO', 8, 3, 'AMO.8.3', '“In that day,” declares the Lord GOD, “the songs of the temple will turn to wailing. Many will be the corpses, strewn in silence everywhere!”'),
('AMO', 8, 4, 'AMO.8.4', 'Hear this, you who trample the needy, who do away with the poor of the land,'),
('AMO', 8, 5, 'AMO.8.5', 'asking, “When will the New Moon be over, that we may sell grain? When will the Sabbath end, that we may market wheat? Let us reduce the ephah and increase the shekel; let us cheat with dishonest scales.'),
('AMO', 8, 6, 'AMO.8.6', 'Let us buy the poor with silver and the needy for a pair of sandals, selling even the chaff with the wheat!”'),
('AMO', 8, 7, 'AMO.8.7', 'The LORD has sworn by the Pride of Jacob: “I will never forget any of their deeds.'),
('AMO', 8, 8, 'AMO.8.8', 'Will not the land quake for this, and all its dwellers mourn? All of it will swell like the Nile; it will surge and then subside like the Nile in Egypt.'),
('AMO', 8, 9, 'AMO.8.9', 'And in that day, declares the Lord GOD, I will make the sun go down at noon, and I will darken the earth in the daytime.'),
('AMO', 8, 10, 'AMO.8.10', 'I will turn your feasts into mourning and all your songs into lamentation. I will cause everyone to wear sackcloth and every head to be shaved. I will make it like a time of mourning for an only son, and its outcome like a bitter day.'),
('AMO', 8, 11, 'AMO.8.11', 'Behold, the days are coming, declares the Lord GOD, when I will send a famine on the land—not a famine of bread or a thirst for water, but a famine of hearing the words of the LORD.'),
('AMO', 8, 12, 'AMO.8.12', 'People will stagger from sea to sea and roam from north to east, seeking the word of the LORD, but they will not find it.'),
('AMO', 8, 13, 'AMO.8.13', 'In that day the lovely young women—the young men as well—will faint from thirst.'),
('AMO', 8, 14, 'AMO.8.14', 'Those who swear by the guilt of Samaria and say, ‘As surely as your god lives, O Dan,’ or, ‘As surely as the way of Beersheba lives’—they will fall, never to rise again.”'),
('AMO', 9, 1, 'AMO.9.1', 'I saw the Lord standing beside the altar, and He said: “Strike the tops of the pillars so that the thresholds shake. Topple them on the heads of all the people, and I will kill the rest with the sword. None of those who flee will get away; none of the fugitives will escape.'),
('AMO', 9, 2, 'AMO.9.2', 'Though they dig down to Sheol, from there My hand will take them; and though they climb up to heaven, from there I will pull them down.'),
('AMO', 9, 3, 'AMO.9.3', 'Though they hide themselves atop Carmel, there I will track them and seize them; and though they hide from Me at the bottom of the sea, there I will command the serpent to bite them.'),
('AMO', 9, 4, 'AMO.9.4', 'Though they are driven by their enemies into captivity, there I will command the sword to slay them. I will fix My eyes upon them for harm and not for good.”'),
('AMO', 9, 5, 'AMO.9.5', 'The Lord GOD of Hosts, He who touches the earth and it melts, and all its dwellers mourn—all the land rises like the Nile, then sinks like the river of Egypt—'),
('AMO', 9, 6, 'AMO.9.6', 'He builds His upper rooms in the heavens and founds His vault upon the earth. He summons the waters of the sea and pours them over the face of the earth. The LORD is His name.'),
('AMO', 9, 7, 'AMO.9.7', '“Are you not like the Cushites to Me, O children of Israel?” declares the LORD. “Did I not bring Israel up from the land of Egypt, the Philistines from Caphtor, and the Arameans from Kir?'),
('AMO', 9, 8, 'AMO.9.8', 'Surely the eyes of the Lord GOD are on the sinful kingdom, and I will destroy it from the face of the earth. Yet I will not utterly destroy the house of Jacob,” declares the LORD.'),
('AMO', 9, 9, 'AMO.9.9', '“For surely I will give the command, and I will shake the house of Israel among all the nations as grain is sifted in a sieve; but not a pebble will reach the ground.'),
('AMO', 9, 10, 'AMO.9.10', 'All the sinners among My people will die by the sword—all those who say, ‘Disaster will never draw near or confront us.’”'),
('AMO', 9, 11, 'AMO.9.11', '“In that day I will restore the fallen tent of David. I will repair its gaps, restore its ruins, and rebuild it as in the days of old,'),
('AMO', 9, 12, 'AMO.9.12', 'that they may possess the remnant of Edom and all the nations that bear My name,” declares the LORD, who will do this.'),
('AMO', 9, 13, 'AMO.9.13', '“Behold, the days are coming,” declares the LORD, “when the plowman will overtake the reaper and the treader of grapes, the sower of seed. The mountains will drip with sweet wine, with which all the hills will flow.'),
('AMO', 9, 14, 'AMO.9.14', 'I will restore My people Israel from captivity; they will rebuild and inhabit the ruined cities. They will plant vineyards and drink their wine; they will make gardens and eat their fruit.'),
('AMO', 9, 15, 'AMO.9.15', 'I will firmly plant them in their own land, never again to be uprooted from the land that I have given them,” says the LORD your God.'),
('OBA', 1, 1, 'OBA.1.1', 'This is the vision of Obadiah: This is what the Lord GOD says about Edom—We have heard a message from the LORD; an envoy has been sent among the nations to say, “Rise up, and let us go to battle against her!”—'),
('OBA', 1, 2, 'OBA.1.2', '“Behold, I will make you small among the nations; you will be deeply despised.'),
('OBA', 1, 3, 'OBA.1.3', 'The pride of your heart has deceived you, O dwellers in the clefts of the rocks whose habitation is the heights, who say in your heart, ‘Who can bring me down to the ground?’'),
('OBA', 1, 4, 'OBA.1.4', 'Though you soar like the eagle and make your nest among the stars, even from there I will bring you down,” declares the LORD.'),
('OBA', 1, 5, 'OBA.1.5', '“If thieves came to you, if robbers by night—oh, how you will be ruined—would they not steal only what they wanted? If grape gatherers came to you, would they not leave some gleanings?'),
('OBA', 1, 6, 'OBA.1.6', 'But how Esau will be pillaged, his hidden treasures sought out!'),
('OBA', 1, 7, 'OBA.1.7', 'All the men allied with you will drive you to the border; the men at peace with you will deceive and overpower you. Those who eat your bread will set a trap for you without your awareness of it.'),
('OBA', 1, 8, 'OBA.1.8', 'In that day, declares the LORD, will I not destroy the wise men of Edom and the men of understanding in the mountains of Esau?'),
('OBA', 1, 9, 'OBA.1.9', 'Then your mighty men, O Teman, will be terrified, so that everyone in the mountains of Esau will be cut down in the slaughter.'),
('OBA', 1, 10, 'OBA.1.10', 'Because of the violence against your brother Jacob, you will be covered with shame and cut off forever.'),
('OBA', 1, 11, 'OBA.1.11', 'On the day you stood aloof while strangers carried off his wealth and foreigners entered his gate and cast lots for Jerusalem, you were just like one of them.'),
('OBA', 1, 12, 'OBA.1.12', 'But you should not gloat in that day, your brother’s day of misfortune, nor rejoice over the people of Judah in the day of their destruction, nor boast proudly in the day of their distress.'),
('OBA', 1, 13, 'OBA.1.13', 'You should not enter the gate of My people in the day of their disaster, nor gloat over their affliction in the day of their disaster, nor loot their wealth in the day of their disaster.'),
('OBA', 1, 14, 'OBA.1.14', 'Nor should you stand at the crossroads to cut off their fugitives, nor deliver up their survivors in the day of their distress.'),
('OBA', 1, 15, 'OBA.1.15', 'For the Day of the LORD is near for all the nations. As you have done, it will be done to you; your recompense will return upon your own head.'),
('OBA', 1, 16, 'OBA.1.16', 'For as you drank on My holy mountain, so all the nations will drink continually. They will drink and gulp it down; they will be as if they had never existed.'),
('OBA', 1, 17, 'OBA.1.17', 'But on Mount Zion there will be deliverance, and it will be holy, and the house of Jacob will reclaim their possession.'),
('OBA', 1, 18, 'OBA.1.18', 'Then the house of Jacob will be a blazing fire, and the house of Joseph a burning flame; but the house of Esau will be stubble—Jacob will set it ablaze and consume it. Therefore no survivor will remain from the house of Esau.” For the LORD has spoken.'),
('OBA', 1, 19, 'OBA.1.19', 'Those from the Negev will possess the mountains of Esau; those from the foothills will possess the land of the Philistines. They will occupy the fields of Ephraim and Samaria, and Benjamin will possess Gilead.'),
('OBA', 1, 20, 'OBA.1.20', 'And the exiles of this host of the Israelites will possess the land of the Canaanites as far as Zarephath; and the exiles from Jerusalem who are in Sepharad will possess the cities of the Negev.'),
('OBA', 1, 21, 'OBA.1.21', 'The deliverers will ascend Mount Zion to rule over the mountains of Esau. And the kingdom will belong to the LORD.'),
('JON', 1, 1, 'JON.1.1', 'Now the word of the LORD came to Jonah son of Amittai, saying,'),
('JON', 1, 2, 'JON.1.2', '“Get up! Go to the great city of Nineveh and preach against it, because its wickedness has come up before Me.”'),
('JON', 1, 3, 'JON.1.3', 'Jonah, however, got up to flee to Tarshish, away from the presence of the LORD. He went down to Joppa and found a ship bound for Tarshish. So he paid the fare and went aboard to sail for Tarshish, away from the presence of the LORD.'),
('JON', 1, 4, 'JON.1.4', 'Then the LORD hurled a great wind upon the sea, and such a violent storm arose that the ship was in danger of breaking apart.'),
('JON', 1, 5, 'JON.1.5', 'The sailors were afraid, and each cried out to his own god. And they threw the ship’s cargo into the sea to lighten the load. But Jonah had gone down to the lowest part of the vessel, where he lay down and fell into a deep sleep.'),
('JON', 1, 6, 'JON.1.6', 'The captain approached him and said, “How can you sleep? Get up and call upon your God. Perhaps this God will consider us, so that we may not perish.”'),
('JON', 1, 7, 'JON.1.7', '“Come!” said the sailors to one another. “Let us cast lots to find out who is responsible for this calamity that is upon us.” So they cast lots, and the lot fell on Jonah.'),
('JON', 1, 8, 'JON.1.8', '“Tell us now,” they demanded, “who is to blame for this calamity that is upon us? What is your occupation, and where have you come from? What is your country, and who are your people?”'),
('JON', 1, 9, 'JON.1.9', '“I am a Hebrew,” replied Jonah. “I worship the LORD, the God of the heavens, who made the sea and the dry land.”'),
('JON', 1, 10, 'JON.1.10', 'Then the men were even more afraid and said to him, “What have you done?” The men knew that he was fleeing from the presence of the LORD, because he had told them.'),
('JON', 1, 11, 'JON.1.11', 'Now the sea was growing worse and worse, so they said to Jonah, “What must we do to you to calm this sea for us?”'),
('JON', 1, 12, 'JON.1.12', '“Pick me up,” he answered, “and cast me into the sea, so it may quiet down for you. For I know that I am to blame for this violent storm that has come upon you.”'),
('JON', 1, 13, 'JON.1.13', 'Nevertheless, the men rowed hard to get back to dry land, but they could not, for the sea was raging against them more and more.'),
('JON', 1, 14, 'JON.1.14', 'So they cried out to the LORD: “Please, O LORD, do not let us perish on account of this man’s life! Do not charge us with innocent blood! For You, O LORD, have done as You pleased.”'),
('JON', 1, 15, 'JON.1.15', 'Then they picked up Jonah and cast him into the sea, and the raging sea grew calm.'),
('JON', 1, 16, 'JON.1.16', 'Then the men feared the LORD greatly, and they offered a sacrifice to the LORD and made vows to Him.'),
('JON', 1, 17, 'JON.1.17', 'Now the LORD had appointed a great fish to swallow Jonah, and Jonah spent three days and three nights in the belly of the fish.'),
('JON', 2, 1, 'JON.2.1', 'From inside the fish, Jonah prayed to the LORD his God,'),
('JON', 2, 2, 'JON.2.2', 'saying: “In my distress I called to the LORD, and He answered me. From the belly of Sheol I called for help, and You heard my voice.'),
('JON', 2, 3, 'JON.2.3', 'For You cast me into the deep, into the heart of the seas, and the current swirled about me; all Your breakers and waves swept over me.'),
('JON', 2, 4, 'JON.2.4', 'At this, I said, ‘I have been banished from Your sight; yet I will look once more toward Your holy temple.’'),
('JON', 2, 5, 'JON.2.5', 'The waters engulfed me to take my life; the watery depths closed around me; the seaweed wrapped around my head.'),
('JON', 2, 6, 'JON.2.6', 'To the roots of the mountains I descended; the earth beneath me barred me in forever! But You raised my life from the pit, O LORD my God!'),
('JON', 2, 7, 'JON.2.7', 'As my life was fading away, I remembered the LORD. My prayer went up to You, to Your holy temple.'),
('JON', 2, 8, 'JON.2.8', 'Those who cling to worthless idols forsake His loving devotion.'),
('JON', 2, 9, 'JON.2.9', 'But I, with the voice of thanksgiving, will sacrifice to You. I will fulfill what I have vowed. Salvation is from the LORD!”'),
('JON', 2, 10, 'JON.2.10', 'And the LORD commanded the fish, and it vomited Jonah onto dry land.'),
('JON', 3, 1, 'JON.3.1', 'Then the word of the LORD came to Jonah a second time:'),
('JON', 3, 2, 'JON.3.2', '“Get up! Go to the great city of Nineveh and proclaim to it the message that I give you.”'),
('JON', 3, 3, 'JON.3.3', 'This time Jonah got up and went to Nineveh, in accordance with the word of the LORD. Now Nineveh was an exceedingly great city, requiring a three-day journey.'),
('JON', 3, 4, 'JON.3.4', 'On the first day of his journey, Jonah set out into the city and proclaimed, “Forty more days and Nineveh will be overturned!”'),
('JON', 3, 5, 'JON.3.5', 'And the Ninevites believed God. They proclaimed a fast and dressed in sackcloth, from the greatest of them to the least.'),
('JON', 3, 6, 'JON.3.6', 'When word reached the king of Nineveh, he got up from his throne, took off his royal robe, covered himself with sackcloth, and sat in ashes.'),
('JON', 3, 7, 'JON.3.7', 'Then he issued a proclamation in Nineveh: “By the decree of the king and his nobles: Let no man or beast, herd or flock, taste anything at all. They must not eat or drink.'),
('JON', 3, 8, 'JON.3.8', 'Furthermore, let both man and beast be covered with sackcloth, and have everyone call out earnestly to God. Let each one turn from his evil ways and from the violence in his hands.'),
('JON', 3, 9, 'JON.3.9', 'Who knows? God may turn and relent; He may turn from His fierce anger, so that we will not perish.”'),
('JON', 3, 10, 'JON.3.10', 'When God saw their actions—that they had turned from their evil ways—He relented from the disaster He had threatened to bring upon them.'),
('JON', 4, 1, 'JON.4.1', 'Jonah, however, was greatly displeased, and he became angry.'),
('JON', 4, 2, 'JON.4.2', 'So he prayed to the LORD, saying, “O LORD, is this not what I said while I was still in my own country? This is why I was so quick to flee toward Tarshish. I knew that You are a gracious and compassionate God, slow to anger, abounding in loving devotion—One who relents from sending disaster.'),
('JON', 4, 3, 'JON.4.3', 'And now, O LORD, please take my life from me, for it is better for me to die than to live.”'),
('JON', 4, 4, 'JON.4.4', 'But the LORD replied, “Have you any right to be angry?”'),
('JON', 4, 5, 'JON.4.5', 'Then Jonah left the city and sat down east of it, where he made himself a shelter and sat in its shade to see what would happen to the city.'),
('JON', 4, 6, 'JON.4.6', 'So the LORD God appointed a vine, and it grew up to provide shade over Jonah’s head to ease his discomfort, and Jonah was greatly pleased with the plant.'),
('JON', 4, 7, 'JON.4.7', 'When dawn came the next day, God appointed a worm that attacked the plant so that it withered.'),
('JON', 4, 8, 'JON.4.8', 'As the sun was rising, God appointed a scorching east wind, and the sun beat down on Jonah’s head so that he grew faint and wished to die, saying, “It is better for me to die than to live.”'),
('JON', 4, 9, 'JON.4.9', 'Then God asked Jonah, “Have you any right to be angry about the plant?” “I do,” he replied. “I am angry enough to die!”'),
('JON', 4, 10, 'JON.4.10', 'But the LORD said, “You cared about the plant, which you neither tended nor made grow. It sprang up in a night and perished in a night.'),
('JON', 4, 11, 'JON.4.11', 'So should I not care about the great city of Nineveh, which has more than 120,000 people who cannot tell their right hand from their left, and many cattle as well?”'),
('MIC', 1, 1, 'MIC.1.1', 'This is the word of the LORD that came to Micah the Moreshite in the days of Jotham, Ahaz, and Hezekiah, kings of Judah—what he saw regarding Samaria and Jerusalem:'),
('MIC', 1, 2, 'MIC.1.2', 'Hear, O peoples, all of you; listen, O earth, and everyone in it! May the Lord GOD bear witness against you, the Lord from His holy temple.'),
('MIC', 1, 3, 'MIC.1.3', 'For behold, the LORD comes forth from His dwelling place; He will come down and tread on the high places of the earth.'),
('MIC', 1, 4, 'MIC.1.4', 'The mountains will melt beneath Him, and the valleys will split apart, like wax before the fire, like water rushing down a slope.'),
('MIC', 1, 5, 'MIC.1.5', 'All this is for the transgression of Jacob and the sins of the house of Israel. What is the transgression of Jacob? Is it not Samaria? And what is the high place of Judah? Is it not Jerusalem?'),
('MIC', 1, 6, 'MIC.1.6', 'Therefore I will make Samaria a heap of rubble in the open field, a planting area for a vineyard. I will pour her stones into the valley and expose her foundations.'),
('MIC', 1, 7, 'MIC.1.7', 'All her carved images will be smashed to pieces; all her wages will be burned in the fire, and I will destroy all her idols. Since she collected the wages of a prostitute, they will be used again on a prostitute.'),
('MIC', 1, 8, 'MIC.1.8', 'Because of this I will lament and wail; I will walk barefoot and naked. I will howl like a jackal and mourn like an ostrich.'),
('MIC', 1, 9, 'MIC.1.9', 'For her wound is incurable; it has reached even Judah; it has approached the gate of my people, as far as Jerusalem itself.'),
('MIC', 1, 10, 'MIC.1.10', 'Do not tell it in Gath; do not weep at all. Roll in the dust in Beth-leaphrah.'),
('MIC', 1, 11, 'MIC.1.11', 'Depart in shameful nakedness, O dwellers of Shaphir. The dwellers of Zaanan will not come out. Beth-ezel is in mourning; its support is taken from you.'),
('MIC', 1, 12, 'MIC.1.12', 'For the dwellers of Maroth pined for good, but calamity came down from the LORD, even to the gate of Jerusalem.'),
('MIC', 1, 13, 'MIC.1.13', 'Harness your chariot horses, O dweller of Lachish. You were the beginning of sin to the Daughter of Zion, for the transgressions of Israel were found in you.'),
('MIC', 1, 14, 'MIC.1.14', 'Therefore, send farewell gifts to Moresheth-gath; the houses of Achzib will prove deceptive to the kings of Israel.'),
('MIC', 1, 15, 'MIC.1.15', 'I will again bring a conqueror against you, O dweller of Mareshah. The glory of Israel will come to Adullam.'),
('MIC', 1, 16, 'MIC.1.16', 'Shave yourselves bald and cut off your hair in mourning for your precious children; make yourselves as bald as an eagle, for they will go from you into exile.'),
('MIC', 2, 1, 'MIC.2.1', 'Woe to those who devise iniquity and plot evil on their beds! At morning’s light they accomplish it because the power is in their hands.'),
('MIC', 2, 2, 'MIC.2.2', 'They covet fields and seize them; they take away houses. They deprive a man of his home, a fellow man of his inheritance.'),
('MIC', 2, 3, 'MIC.2.3', 'Therefore this is what the LORD says: “I am planning against this nation a disaster from which you cannot free your necks. Then you will not walk so proudly, for it will be a time of calamity.'),
('MIC', 2, 4, 'MIC.2.4', 'In that day they will take up a proverb against you and taunt you with this bitter lamentation: ‘We are utterly ruined! He has changed the portion of my people. How He has removed it from me! He has allotted our fields to traitors.’”'),
('MIC', 2, 5, 'MIC.2.5', 'Therefore, you will have no one in the assembly of the LORD to divide the land by lot.'),
('MIC', 2, 6, 'MIC.2.6', '“Do not preach,” they preach. “Do not preach these things; disgrace will not overtake us.”'),
('MIC', 2, 7, 'MIC.2.7', 'Should it be said, O house of Jacob, “Is the Spirit of the LORD impatient? Are these the things He does?” Do not My words bring good to him who walks uprightly?'),
('MIC', 2, 8, 'MIC.2.8', 'But of late My people have risen up like an enemy: You strip off the splendid robe from unsuspecting passersby like men returning from battle.'),
('MIC', 2, 9, 'MIC.2.9', 'You drive the women of My people from their pleasant homes. You take away My blessing from their children forever.'),
('MIC', 2, 10, 'MIC.2.10', 'Arise and depart, for this is not your place of rest, because its defilement brings destruction—a grievous destruction!'),
('MIC', 2, 11, 'MIC.2.11', 'If a man of wind were to come and say falsely, “I will preach to you of wine and strong drink,” he would be just the preacher for this people!'),
('MIC', 2, 12, 'MIC.2.12', 'I will surely gather all of you, O Jacob; I will collect the remnant of Israel. I will bring them together like sheep in a pen, like a flock in the midst of its pasture—a noisy throng.'),
('MIC', 2, 13, 'MIC.2.13', 'One who breaks open the way will go up before them; they will break through the gate, and go out by it. Their King will pass through before them, the LORD as their leader.'),
('MIC', 3, 1, 'MIC.3.1', 'Then I said: “Hear now, O leaders of Jacob, you rulers of the house of Israel. Should you not know justice?'),
('MIC', 3, 2, 'MIC.3.2', 'You hate good and love evil. You tear the skin from my people and strip the flesh from their bones.'),
('MIC', 3, 3, 'MIC.3.3', 'You eat the flesh of my people after stripping off their skin and breaking their bones. You chop them up like flesh for the cooking pot, like meat in a cauldron.”'),
('MIC', 3, 4, 'MIC.3.4', 'Then they will cry out to the LORD, but He will not answer them. At that time He will hide His face from them because of the evil they have done.'),
('MIC', 3, 5, 'MIC.3.5', 'This is what the LORD says: “As for the prophets who lead My people astray, who proclaim peace while they chew with their teeth, but declare war against one who puts nothing in their mouths:'),
('MIC', 3, 6, 'MIC.3.6', 'Therefore night will come over you without visions, and darkness without divination. The sun will set on these prophets, and the daylight will turn black over them.'),
('MIC', 3, 7, 'MIC.3.7', 'Then the seers will be ashamed and the diviners will be disgraced. They will all cover their mouths because there is no answer from God.”'),
('MIC', 3, 8, 'MIC.3.8', 'As for me, however, I am filled with power by the Spirit of the LORD, with justice and courage, to declare to Jacob his transgression and to Israel his sin.'),
('MIC', 3, 9, 'MIC.3.9', 'Now hear this, O leaders of the house of Jacob and rulers of the house of Israel, who despise justice and pervert all that is right,'),
('MIC', 3, 10, 'MIC.3.10', 'who build Zion with bloodshed and Jerusalem with iniquity.'),
('MIC', 3, 11, 'MIC.3.11', 'Her leaders judge for a bribe, her priests teach for a price, and her prophets practice divination for money. Yet they lean upon the LORD, saying, “Is not the LORD among us? No disaster can come upon us.”'),
('MIC', 3, 12, 'MIC.3.12', 'Therefore, because of you, Zion will be plowed like a field, Jerusalem will become a heap of rubble, and the temple mount a wooded ridge.'),
('MIC', 4, 1, 'MIC.4.1', 'In the last days the mountain of the house of the LORD will be established as the chief of the mountains; it will be raised above the hills, and the peoples will stream to it.'),
('MIC', 4, 2, 'MIC.4.2', 'And many nations will come and say: “Come, let us go up to the mountain of the LORD, to the house of the God of Jacob. He will teach us His ways, so that we may walk in His paths.” For the law will go forth from Zion and the word of the LORD from Jerusalem.'),
('MIC', 4, 3, 'MIC.4.3', 'Then He will judge between many peoples and arbitrate for strong nations far and wide. Then they will beat their swords into plowshares and their spears into pruning hooks. Nation will no longer take up the sword against nation, nor will they train anymore for war.'),
('MIC', 4, 4, 'MIC.4.4', 'And each man will sit under his own vine and under his own fig tree, with no one to frighten him. For the mouth of the LORD of Hosts has spoken.'),
('MIC', 4, 5, 'MIC.4.5', 'Though all the nations may walk in the name of their gods, yet we will walk in the name of the LORD our God forever and ever.'),
('MIC', 4, 6, 'MIC.4.6', '“On that day,” declares the LORD, “I will gather the lame; I will assemble the outcast, even those whom I have afflicted.'),
('MIC', 4, 7, 'MIC.4.7', 'And I will make the lame into a remnant, the outcast into a strong nation. Then the LORD will rule over them in Mount Zion from that day and forever.'),
('MIC', 4, 8, 'MIC.4.8', 'And you, O watchtower of the flock, O stronghold of the Daughter of Zion—the former dominion will be restored to you; sovereignty will come to the Daughter of Jerusalem.”'),
('MIC', 4, 9, 'MIC.4.9', 'Why do you now cry aloud? Is there no king among you? Has your counselor perished so that anguish grips you like a woman in labor?'),
('MIC', 4, 10, 'MIC.4.10', 'Writhe in agony, O Daughter of Zion, like a woman in labor. For now you will leave the city and camp in the open fields. You will go to Babylon; there you will be rescued; there the LORD will redeem you from the hand of your enemies!'),
('MIC', 4, 11, 'MIC.4.11', 'But now many nations have assembled against you, saying, “Let her be defiled, and let us feast our eyes on Zion.”'),
('MIC', 4, 12, 'MIC.4.12', 'But they do not know the thoughts of the LORD or understand His plan, for He has gathered them like sheaves to the threshing floor.'),
('MIC', 4, 13, 'MIC.4.13', 'Rise and thresh, O Daughter of Zion, for I will give you horns of iron and hooves of bronze to break to pieces many peoples. Then you will devote their gain to the LORD, their wealth to the Lord of all the earth.'),
('MIC', 5, 1, 'MIC.5.1', 'Now, O daughter of troops, mobilize your troops; for a siege is laid against us! With a rod they will strike the cheek of the judge of Israel.'),
('MIC', 5, 2, 'MIC.5.2', 'But you, Bethlehem Ephrathah, who are small among the clans of Judah, out of you will come forth for Me One to be ruler over Israel—One whose origins are of old, from the days of eternity.'),
('MIC', 5, 3, 'MIC.5.3', 'Therefore Israel will be abandoned until she who is in labor has given birth; then the rest of His brothers will return to the children of Israel.'),
('MIC', 5, 4, 'MIC.5.4', 'He will stand and shepherd His flock in the strength of the LORD, in the majestic name of the LORD His God. And they will dwell securely, for then His greatness will extend to the ends of the earth.'),
('MIC', 5, 5, 'MIC.5.5', 'And He will be our peace when Assyria invades our land and tramples our citadels. We will raise against it seven shepherds, even eight leaders of men.'),
('MIC', 5, 6, 'MIC.5.6', 'And they will rule the land of Assyria with the sword, and the land of Nimrod with the blade drawn. So He will deliver us when Assyria invades our land and marches into our borders.'),
('MIC', 5, 7, 'MIC.5.7', 'Then the remnant of Jacob will be in the midst of many peoples like dew from the LORD, like showers on the grass, which do not wait for man or linger for mankind.'),
('MIC', 5, 8, 'MIC.5.8', 'Then the remnant of Jacob will be among the nations, in the midst of many peoples, like a lion among the beasts of the forest, like a young lion among flocks of sheep, which tramples and tears as it passes through, with no one to rescue them.'),
('MIC', 5, 9, 'MIC.5.9', 'Your hand will be lifted over your foes, and all your enemies will be cut off.'),
('MIC', 5, 10, 'MIC.5.10', '“In that day,” declares the LORD, “I will remove your horses from among you and wreck your chariots.'),
('MIC', 5, 11, 'MIC.5.11', 'I will remove the cities of your land and tear down all your strongholds.'),
('MIC', 5, 12, 'MIC.5.12', 'I will cut the sorceries from your hand, and you will have no fortune-tellers.'),
('MIC', 5, 13, 'MIC.5.13', 'I will also cut off the carved images and sacred pillars from among you, so that you will no longer bow down to the work of your own hands.'),
('MIC', 5, 14, 'MIC.5.14', 'I will root out the Asherah poles from your midst and demolish your cities.'),
('MIC', 5, 15, 'MIC.5.15', 'I will take vengeance in anger and wrath upon the nations that have not obeyed Me.”'),
('MIC', 6, 1, 'MIC.6.1', 'Hear now what the LORD says: “Arise, plead your case before the mountains, and let the hills hear your voice.'),
('MIC', 6, 2, 'MIC.6.2', 'Hear, O mountains, the LORD’s indictment, you enduring foundations of the earth. For the LORD has a case against His people, and He will argue it against Israel:'),
('MIC', 6, 3, 'MIC.6.3', '‘My people, what have I done to you? Testify against Me how I have wearied you!'),
('MIC', 6, 4, 'MIC.6.4', 'For I brought you up from the land of Egypt and redeemed you from the house of slavery. I sent Moses before you, as well as Aaron and Miriam.'),
('MIC', 6, 5, 'MIC.6.5', 'My people, remember what Balak king of Moab counseled and what Balaam son of Beor answered. Remember your journey from Shittim to Gilgal, so that you may acknowledge the righteousness of the LORD.’”'),
('MIC', 6, 6, 'MIC.6.6', 'With what shall I come before the LORD when I bow before the God on high? Should I come to Him with burnt offerings, with year-old calves?'),
('MIC', 6, 7, 'MIC.6.7', 'Would the LORD be pleased with thousands of rams, with ten thousand rivers of oil? Shall I present my firstborn for my transgression, the fruit of my body for the sin of my soul?'),
('MIC', 6, 8, 'MIC.6.8', 'He has shown you, O man, what is good. And what does the LORD require of you but to act justly, to love mercy, and to walk humbly with your God?'),
('MIC', 6, 9, 'MIC.6.9', 'The voice of the LORD calls out to the city (and it is sound wisdom to fear Your name): “Heed the rod and the One who ordained it.'),
('MIC', 6, 10, 'MIC.6.10', 'Can I forget any longer, O house of the wicked, the treasures of wickedness and the short ephah, which is accursed?'),
('MIC', 6, 11, 'MIC.6.11', 'Can I excuse dishonest scales or bags of false weights?'),
('MIC', 6, 12, 'MIC.6.12', 'For the wealthy of the city are full of violence, and its residents speak lies; their tongues are deceitful in their mouths.'),
('MIC', 6, 13, 'MIC.6.13', 'Therefore I am striking you severely, to ruin you because of your sins.'),
('MIC', 6, 14, 'MIC.6.14', 'You will eat but not be satisfied, and your hunger will remain with you. What you acquire, you will not preserve; and what you save, I will give to the sword.'),
('MIC', 6, 15, 'MIC.6.15', 'You will sow but not reap; you will press olives but not anoint yourselves with oil; you will tread grapes but not drink the wine.'),
('MIC', 6, 16, 'MIC.6.16', 'You have kept the statutes of Omri and all the practices of Ahab’s house; you have followed their counsel. Therefore I will make you a desolation, and your inhabitants an object of contempt; you will bear the scorn of the nations.”'),
('MIC', 7, 1, 'MIC.7.1', 'Woe is me! For I am like one gathering summer fruit at the gleaning of the vineyard; there is no cluster to eat, no early fig that I crave.'),
('MIC', 7, 2, 'MIC.7.2', 'The godly man has perished from the earth; there is no one upright among men. They all lie in wait for blood; they hunt one another with a net.'),
('MIC', 7, 3, 'MIC.7.3', 'Both hands are skilled at evil; the prince and the judge demand a bribe. When the powerful utters his evil desire, they all conspire together.'),
('MIC', 7, 4, 'MIC.7.4', 'The best of them is like a brier; the most upright is sharper than a hedge of thorns. The day for your watchmen has come, the day of your visitation. Now is the time of their confusion.'),
('MIC', 7, 5, 'MIC.7.5', 'Do not rely on a friend; do not trust in a companion. Seal the doors of your mouth from her who lies in your arms.'),
('MIC', 7, 6, 'MIC.7.6', 'For a son dishonors his father, a daughter rises against her mother, and a daughter-in-law against her mother-in-law. A man’s enemies are the members of his own household.'),
('MIC', 7, 7, 'MIC.7.7', 'But as for me, I will look to the LORD; I will wait for the God of my salvation. My God will hear me.'),
('MIC', 7, 8, 'MIC.7.8', 'Do not gloat over me, my enemy! Though I have fallen, I will arise; though I sit in darkness, the LORD will be my light.'),
('MIC', 7, 9, 'MIC.7.9', 'Because I have sinned against Him, I must endure the rage of the LORD, until He argues my case and executes justice for me. He will bring me into the light; I will see His righteousness.'),
('MIC', 7, 10, 'MIC.7.10', 'Then my enemy will see and will be covered with shame—she who said to me, “Where is the LORD your God?” My eyes will see her; at that time she will be trampled like mud in the streets.'),
('MIC', 7, 11, 'MIC.7.11', 'The day for rebuilding your walls will come—the day for extending your boundary.'),
('MIC', 7, 12, 'MIC.7.12', 'On that day they will come to you from Assyria and the cities of Egypt, even from Egypt to the Euphrates, from sea to sea and mountain to mountain.'),
('MIC', 7, 13, 'MIC.7.13', 'Then the earth will become desolate because of its inhabitants, as the fruit of their deeds.'),
('MIC', 7, 14, 'MIC.7.14', 'Shepherd with Your staff Your people, the flock of Your inheritance. They live alone in a woodland, surrounded by pastures. Let them graze in Bashan and Gilead, as in the days of old.'),
('MIC', 7, 15, 'MIC.7.15', 'As in the days when you came out of Egypt, I will show My wonders.'),
('MIC', 7, 16, 'MIC.7.16', 'Nations will see and be ashamed, deprived of all their might. They will put their hands over their mouths, and their ears will become deaf.'),
('MIC', 7, 17, 'MIC.7.17', 'They will lick the dust like a snake, like reptiles slithering on the ground. They will come trembling from their strongholds in the presence of the LORD our God; they will tremble in fear of You.'),
('MIC', 7, 18, 'MIC.7.18', 'Who is a God like You, who pardons iniquity and passes over the transgression of the remnant of His inheritance—who does not retain His anger forever, because He delights in loving devotion?'),
('MIC', 7, 19, 'MIC.7.19', 'He will again have compassion on us; He will vanquish our iniquities. You will cast out all our sins into the depths of the sea.'),
('MIC', 7, 20, 'MIC.7.20', 'You will show faithfulness to Jacob and loving devotion to Abraham, as You swore to our fathers from the days of old.'),
('NAM', 1, 1, 'NAM.1.1', 'This is the burden against Nineveh, the book of the vision of Nahum the Elkoshite:'),
('NAM', 1, 2, 'NAM.1.2', 'The LORD is a jealous and avenging God; the LORD is avenging and full of wrath. The LORD takes vengeance on His foes and reserves wrath for His enemies.'),
('NAM', 1, 3, 'NAM.1.3', 'The LORD is slow to anger and great in power; the LORD will by no means leave the guilty unpunished. His path is in the whirlwind and storm, and clouds are the dust beneath His feet.'),
('NAM', 1, 4, 'NAM.1.4', 'He rebukes the sea and dries it up; He makes all the rivers run dry. Bashan and Carmel wither, and the flower of Lebanon wilts.'),
('NAM', 1, 5, 'NAM.1.5', 'The mountains quake before Him, and the hills melt away; the earth trembles at His presence—the world and all its dwellers.'),
('NAM', 1, 6, 'NAM.1.6', 'Who can withstand His indignation? Who can endure His burning anger? His wrath is poured out like fire; even rocks are shattered before Him.'),
('NAM', 1, 7, 'NAM.1.7', 'The LORD is good, a stronghold in the day of distress; He cares for those who trust in Him.'),
('NAM', 1, 8, 'NAM.1.8', 'But with an overwhelming flood He will make an end of Nineveh and pursue His enemies into darkness.'),
('NAM', 1, 9, 'NAM.1.9', 'Whatever you plot against the LORD, He will bring to an end. Affliction will not rise up a second time.'),
('NAM', 1, 10, 'NAM.1.10', 'For they will be entangled as with thorns and consumed like the drink of a drunkard—like stubble that is fully dry.'),
('NAM', 1, 11, 'NAM.1.11', 'From you, O Nineveh, comes forth a plotter of evil against the LORD, a counselor of wickedness.'),
('NAM', 1, 12, 'NAM.1.12', 'This is what the LORD says: “Though they are allied and numerous, yet they will be cut down and pass away. Though I have afflicted you, O Judah, I will afflict you no longer.'),
('NAM', 1, 13, 'NAM.1.13', 'For I will now break their yoke from your neck and tear away your shackles.”'),
('NAM', 1, 14, 'NAM.1.14', 'The LORD has issued a command concerning you, O Nineveh: “There will be no descendants to carry on your name. I will cut off the carved image and cast idol from the house of your gods; I will prepare your grave, for you are contemptible.”'),
('NAM', 1, 15, 'NAM.1.15', 'Look to the mountains—the feet of one who brings good news, who proclaims peace! Celebrate your feasts, O Judah; fulfill your vows. For the wicked will never again march through you; they will be utterly cut off.'),
('NAM', 2, 1, 'NAM.2.1', 'One who scatters advances against you, O Nineveh. Guard the fortress! Watch the road! Brace yourselves! Summon all your strength!'),
('NAM', 2, 2, 'NAM.2.2', 'For the LORD will restore the splendor of Jacob like the splendor of Israel, though destroyers have laid them waste and ruined the branches of their vine.'),
('NAM', 2, 3, 'NAM.2.3', 'The shields of his mighty men are red; the valiant warriors are dressed in scarlet. The fittings of the chariots flash like fire on the day they are prepared, and the spears of cypress have been brandished.'),
('NAM', 2, 4, 'NAM.2.4', 'The chariots dash through the streets; they rush around the plazas, appearing like torches, darting about like lightning.'),
('NAM', 2, 5, 'NAM.2.5', 'He summons his nobles; they stumble as they advance. They race to its wall; the protective shield is set in place.'),
('NAM', 2, 6, 'NAM.2.6', 'The river gates are thrown open and the palace collapses.'),
('NAM', 2, 7, 'NAM.2.7', 'It is decreed that the city be exiled and carried away; her maidservants moan like doves, and beat upon their breasts.'),
('NAM', 2, 8, 'NAM.2.8', 'Nineveh has been like a pool of water throughout her days, but now it is draining away. “Stop! Stop!” they cry, but no one turns back.'),
('NAM', 2, 9, 'NAM.2.9', '“Plunder the silver! Plunder the gold!” There is no end to the treasure, an abundance of every precious thing.'),
('NAM', 2, 10, 'NAM.2.10', 'She is emptied! Yes, she is desolate and laid waste! Hearts melt, knees knock, bodies tremble, and every face grows pale!'),
('NAM', 2, 11, 'NAM.2.11', 'Where is the lions’ lair or the feeding ground of the young lions, where the lion and lioness prowled with their cubs, with nothing to frighten them away?'),
('NAM', 2, 12, 'NAM.2.12', 'The lion mauled enough for its cubs and strangled prey for the lioness. It filled its dens with the kill, and its lairs with mauled prey.'),
('NAM', 2, 13, 'NAM.2.13', '“Behold, I am against you,” declares the LORD of Hosts. “I will reduce your chariots to cinders, and the sword will devour your young lions. I will cut off your prey from the earth, and the voices of your messengers will no longer be heard.”'),
('NAM', 3, 1, 'NAM.3.1', 'Woe to the city of blood, full of lies, full of plunder, never without prey.'),
('NAM', 3, 2, 'NAM.3.2', 'The crack of the whip, the rumble of the wheel, galloping horse and bounding chariot!'),
('NAM', 3, 3, 'NAM.3.3', 'Charging horseman, flashing sword, shining spear; heaps of slain, mounds of corpses, dead bodies without end—they stumble over their dead—'),
('NAM', 3, 4, 'NAM.3.4', 'because of the many harlotries of the harlot, the seductive mistress of sorcery, who betrays nations by her prostitution and clans by her witchcraft.'),
('NAM', 3, 5, 'NAM.3.5', '“Behold, I am against you,” declares the LORD of Hosts. “I will lift your skirts over your face. I will show your nakedness to the nations and your shame to the kingdoms.'),
('NAM', 3, 6, 'NAM.3.6', 'I will pelt you with filth and treat you with contempt; I will make a spectacle of you.'),
('NAM', 3, 7, 'NAM.3.7', 'Then all who see you will recoil from you and say, ‘Nineveh is devastated; who will grieve for her?’ Where can I find comforters for you?”'),
('NAM', 3, 8, 'NAM.3.8', 'Are you better than Thebes, stationed by the Nile with water around her, whose rampart was the sea, whose wall was the water?'),
('NAM', 3, 9, 'NAM.3.9', 'Cush and Egypt were her boundless strength; Put and Libya were her allies.'),
('NAM', 3, 10, 'NAM.3.10', 'Yet she became an exile; she went into captivity. Her infants were dashed to pieces at the head of every street. They cast lots for her dignitaries, and all her nobles were bound in chains.'),
('NAM', 3, 11, 'NAM.3.11', 'You too will become drunk; you will go into hiding and seek refuge from the enemy.'),
('NAM', 3, 12, 'NAM.3.12', 'All your fortresses are fig trees with the first ripe figs; when shaken, they fall into the mouth of the eater!'),
('NAM', 3, 13, 'NAM.3.13', 'Look at your troops—they are like your women! The gates of your land are wide open to your enemies; fire consumes their bars.'),
('NAM', 3, 14, 'NAM.3.14', 'Draw your water for the siege; strengthen your fortresses. Work the clay and tread the mortar; repair the brick kiln!'),
('NAM', 3, 15, 'NAM.3.15', 'There the fire will devour you; the sword will cut you down and consume you like a young locust. Make yourself many like the young locust; make yourself many like the swarming locust!'),
('NAM', 3, 16, 'NAM.3.16', 'You have multiplied your merchants more than the stars of the sky. The young locust strips the land and flies away.'),
('NAM', 3, 17, 'NAM.3.17', 'Your guards are like the swarming locust, and your scribes like clouds of locusts that settle on the walls on a cold day. When the sun rises, they fly away, and no one knows where.'),
('NAM', 3, 18, 'NAM.3.18', 'O king of Assyria, your shepherds slumber; your officers sleep. Your people are scattered on the mountains with no one to gather them.'),
('NAM', 3, 19, 'NAM.3.19', 'There is no healing for your injury; your wound is severe. All who hear the news of you applaud your downfall, for who has not experienced your constant cruelty?'),
('HAB', 1, 1, 'HAB.1.1', 'This is the burden that Habakkuk the prophet received in a vision:'),
('HAB', 1, 2, 'HAB.1.2', 'How long, O LORD, must I call for help but You do not hear, or cry out to You, “Violence!” but You do not save?'),
('HAB', 1, 3, 'HAB.1.3', 'Why do You make me see iniquity? Why do You tolerate wrongdoing? Destruction and violence are before me. Strife is ongoing, and conflict abounds.'),
('HAB', 1, 4, 'HAB.1.4', 'Therefore the law is paralyzed, and justice never goes forth. For the wicked hem in the righteous, so that justice is perverted.'),
('HAB', 1, 5, 'HAB.1.5', '“Look at the nations and observe—be utterly astounded! For I am doing a work in your days that you would never believe even if someone told you.'),
('HAB', 1, 6, 'HAB.1.6', 'For behold, I am raising up the Chaldeans—that ruthless and impetuous nation which marches through the breadth of the earth to seize dwellings not their own.'),
('HAB', 1, 7, 'HAB.1.7', 'They are dreaded and feared; from themselves they derive justice and sovereignty.'),
('HAB', 1, 8, 'HAB.1.8', 'Their horses are swifter than leopards, fiercer than wolves of the night. Their horsemen charge ahead, and their cavalry comes from afar. They fly like a vulture, swooping down to devour.'),
('HAB', 1, 9, 'HAB.1.9', 'All of them come bent on violence; their hordes advance like the east wind; they gather prisoners like sand.'),
('HAB', 1, 10, 'HAB.1.10', 'They scoff at kings and make rulers an object of scorn. They laugh at every fortress and build up siege ramps to seize it.'),
('HAB', 1, 11, 'HAB.1.11', 'Then they sweep by like the wind and pass through. They are guilty; their own strength is their god.”'),
('HAB', 1, 12, 'HAB.1.12', 'Are You not from everlasting, O LORD, my God, my Holy One? We will not die. O LORD, You have appointed them to execute judgment; O Rock, You have established them for correction.'),
('HAB', 1, 13, 'HAB.1.13', 'Your eyes are too pure to look upon evil, and You cannot tolerate wrongdoing. So why do You tolerate the faithless? Why are You silent while the wicked swallow up those more righteous than themselves?'),
('HAB', 1, 14, 'HAB.1.14', 'You have made men like the fish of the sea, like creeping things that have no ruler.'),
('HAB', 1, 15, 'HAB.1.15', 'The foe pulls all of them up with a hook; he catches them in his dragnet, and gathers them in his fishing net; so he rejoices gladly.'),
('HAB', 1, 16, 'HAB.1.16', 'Therefore he sacrifices to his dragnet and burns incense to his fishing net, for by these things his portion is sumptuous and his food is rich.'),
('HAB', 1, 17, 'HAB.1.17', 'Will he, therefore, empty his net and continue to slay nations without mercy?'),
('HAB', 2, 1, 'HAB.2.1', 'I will stand at my guard post and station myself on the ramparts. I will watch to see what He will say to me, and how I should answer when corrected.'),
('HAB', 2, 2, 'HAB.2.2', 'Then the LORD answered me: “Write down this vision and clearly inscribe it on tablets, so that a herald may run with it.'),
('HAB', 2, 3, 'HAB.2.3', 'For the vision awaits an appointed time; it testifies of the end and does not lie. Though it lingers, wait for it, since it will surely come and will not delay.'),
('HAB', 2, 4, 'HAB.2.4', 'Look at the proud one; his soul is not upright—but the righteous will live by faith—'),
('HAB', 2, 5, 'HAB.2.5', 'and wealth indeed betrays him. He is an arrogant man never at rest. He enlarges his appetite like Sheol, and like Death, he is never satisfied. He gathers all the nations to himself and collects all the peoples as his own.'),
('HAB', 2, 6, 'HAB.2.6', 'Will not all of these take up a taunt against him, speaking with mockery and derision: ‘Woe to him who amasses what is not his and makes himself rich with many loans! How long will this go on?’'),
('HAB', 2, 7, 'HAB.2.7', 'Will not your creditors suddenly arise and those who disturb you awaken? Then you will become their prey.'),
('HAB', 2, 8, 'HAB.2.8', 'Because you have plundered many nations, the remnant of the people will plunder you—because of your bloodshed against man and your violence against the land, the city, and all their dwellers.'),
('HAB', 2, 9, 'HAB.2.9', 'Woe to him who builds his house by unjust gain, to place his nest on high and escape the hand of disaster!'),
('HAB', 2, 10, 'HAB.2.10', 'You have plotted shame for your house by cutting off many peoples and forfeiting your life.'),
('HAB', 2, 11, 'HAB.2.11', 'For the stones will cry out from the wall, and the rafters will echo it from the woodwork.'),
('HAB', 2, 12, 'HAB.2.12', 'Woe to him who builds a city with bloodshed and establishes a town by iniquity!'),
('HAB', 2, 13, 'HAB.2.13', 'Is it not indeed from the LORD of Hosts that the labor of the people only feeds the fire, and the nations weary themselves in vain?'),
('HAB', 2, 14, 'HAB.2.14', 'For the earth will be filled with the knowledge of the glory of the LORD as the waters cover the sea.'),
('HAB', 2, 15, 'HAB.2.15', 'Woe to him who gives drink to his neighbors, pouring it from the wineskin until they are drunk, in order to gaze at their nakedness!'),
('HAB', 2, 16, 'HAB.2.16', 'You will be filled with shame instead of glory. You too must drink and expose your uncircumcision! The cup in the LORD’s right hand will come around to you, and utter disgrace will cover your glory.'),
('HAB', 2, 17, 'HAB.2.17', 'For your violence against Lebanon will overwhelm you, and the destruction of animals will terrify you, because of your bloodshed against men and your violence against the land, the city, and all their dwellers.'),
('HAB', 2, 18, 'HAB.2.18', 'What use is an idol, that a craftsman should carve it—or an image, a teacher of lies? For its maker trusts in his own creation; he makes idols that cannot speak.'),
('HAB', 2, 19, 'HAB.2.19', 'Woe to him who says to wood, ‘Awake!’ or to silent stone, ‘Arise!’ Can it give guidance? Behold, it is overlaid with gold and silver, yet there is no breath in it at all.”'),
('HAB', 2, 20, 'HAB.2.20', 'But the LORD is in His holy temple; let all the earth be silent before Him.'),
('HAB', 3, 1, 'HAB.3.1', 'This is a prayer of Habakkuk the prophet, according to Shigionoth:'),
('HAB', 3, 2, 'HAB.3.2', 'O LORD, I have heard the report of You; I stand in awe, O LORD, of Your deeds. Revive them in these years; make them known in these years. In Your wrath, remember mercy!'),
('HAB', 3, 3, 'HAB.3.3', 'God came from Teman, and the Holy One from Mount Paran. Selah His glory covered the heavens, and His praise filled the earth.'),
('HAB', 3, 4, 'HAB.3.4', 'His radiance was like the sunlight; rays flashed from His hand, where His power is hidden.'),
('HAB', 3, 5, 'HAB.3.5', 'Plague went before Him, and fever followed in His steps.'),
('HAB', 3, 6, 'HAB.3.6', 'He stood and measured the earth; He looked and startled the nations; the ancient mountains crumbled; the perpetual hills collapsed. His ways are everlasting.'),
('HAB', 3, 7, 'HAB.3.7', 'I saw the tents of Cushan in distress; the curtains of Midian were trembling.'),
('HAB', 3, 8, 'HAB.3.8', 'Were You angry at the rivers, O LORD? Was Your wrath against the streams? Did You rage against the sea when You rode on Your horses, on Your chariots of salvation?'),
('HAB', 3, 9, 'HAB.3.9', 'You brandished Your bow; You called for many arrows. Selah You split the earth with rivers.'),
('HAB', 3, 10, 'HAB.3.10', 'The mountains saw You and quaked; torrents of water swept by. The deep roared with its voice and lifted its hands on high.'),
('HAB', 3, 11, 'HAB.3.11', 'Sun and moon stood still in their places at the flash of Your flying arrows, at the brightness of Your shining spear.'),
('HAB', 3, 12, 'HAB.3.12', 'You marched across the earth with fury; You threshed the nations in wrath.'),
('HAB', 3, 13, 'HAB.3.13', 'You went forth for the salvation of Your people, to save Your anointed. You crushed the head of the house of the wicked and stripped him from head to toe. Selah'),
('HAB', 3, 14, 'HAB.3.14', 'With his own spear You pierced his head, when his warriors stormed out to scatter us, gloating as though ready to secretly devour the weak.'),
('HAB', 3, 15, 'HAB.3.15', 'You trampled the sea with Your horses, churning the great waters.'),
('HAB', 3, 16, 'HAB.3.16', 'I heard and trembled within; my lips quivered at the sound. Decay entered my bones; I trembled where I stood. Yet I must wait patiently for the day of distress to come upon the people who invade us.'),
('HAB', 3, 17, 'HAB.3.17', 'Though the fig tree does not bud and no fruit is on the vines, though the olive crop fails and the fields produce no food, though the sheep are cut off from the fold and no cattle are in the stalls,'),
('HAB', 3, 18, 'HAB.3.18', 'yet I will exult in the LORD; I will rejoice in the God of my salvation!'),
('HAB', 3, 19, 'HAB.3.19', 'GOD the Lord is my strength; He makes my feet like those of a deer; He makes me walk upon the heights! For the choirmaster. With stringed instruments.'),
('ZEP', 1, 1, 'ZEP.1.1', 'This is the word of the LORD that came to Zephaniah son of Cushi, the son of Gedaliah, the son of Amariah, the son of Hezekiah, in the days of Josiah son of Amon king of Judah:'),
('ZEP', 1, 2, 'ZEP.1.2', '“I will completely sweep away everything from the face of the earth,” declares the LORD.'),
('ZEP', 1, 3, 'ZEP.1.3', '“I will sweep away man and beast; I will sweep away the birds of the air, and the fish of the sea, and the idols with their wicked worshipers. I will cut off mankind from the face of the earth,” declares the LORD.'),
('ZEP', 1, 4, 'ZEP.1.4', '“I will stretch out My hand against Judah and against all who dwell in Jerusalem. I will cut off from this place every remnant of Baal, the names of the idolatrous and pagan priests—'),
('ZEP', 1, 5, 'ZEP.1.5', 'those who bow on the rooftops to worship the host of heaven, those who bow down and swear by the LORD but also swear by Milcom,'),
('ZEP', 1, 6, 'ZEP.1.6', 'and those who turn back from following the LORD, neither seeking the LORD nor inquiring of Him.”'),
('ZEP', 1, 7, 'ZEP.1.7', 'Be silent in the presence of the Lord GOD, for the Day of the LORD is near. Indeed, the LORD has prepared a sacrifice; He has consecrated His guests.'),
('ZEP', 1, 8, 'ZEP.1.8', '“On the Day of the LORD’s sacrifice I will punish the princes, the sons of the king, and all who are dressed in foreign apparel.'),
('ZEP', 1, 9, 'ZEP.1.9', 'On that day I will punish all who leap over the threshold, who fill the house of their master with violence and deceit.'),
('ZEP', 1, 10, 'ZEP.1.10', 'On that day,” declares the LORD, “a cry will go up from the Fish Gate, a wail from the Second District, and a loud crashing from the hills.'),
('ZEP', 1, 11, 'ZEP.1.11', 'Wail, O dwellers of the Hollow, for all your merchants will be silenced; all who weigh out silver will be cut off.'),
('ZEP', 1, 12, 'ZEP.1.12', 'And at that time I will search Jerusalem with lamps and punish the men settled in complacency, who say to themselves, ‘The LORD will do nothing, either good or bad.’'),
('ZEP', 1, 13, 'ZEP.1.13', 'Their wealth will be plundered and their houses laid waste. They will build houses but not inhabit them, and plant vineyards but never drink their wine.'),
('ZEP', 1, 14, 'ZEP.1.14', 'The great Day of the LORD is near—near and coming quickly. Listen, the Day of the LORD! Then the cry of the mighty will be bitter.'),
('ZEP', 1, 15, 'ZEP.1.15', 'That day will be a day of wrath, a day of trouble and distress, a day of destruction and desolation, a day of darkness and gloom, a day of clouds and blackness,'),
('ZEP', 1, 16, 'ZEP.1.16', 'a day of horn blast and battle cry against the fortified cities, and against the high corner towers.'),
('ZEP', 1, 17, 'ZEP.1.17', 'I will bring such distress on mankind that they will walk like the blind, because they have sinned against the LORD. Their blood will be poured out like dust and their flesh like dung.'),
('ZEP', 1, 18, 'ZEP.1.18', 'Neither their silver nor their gold will be able to deliver them on the Day of the LORD’s wrath. The whole earth will be consumed by the fire of His jealousy.” For indeed, He will make a sudden end of all who dwell on the earth.'),
('ZEP', 2, 1, 'ZEP.2.1', 'Gather yourselves, gather together, O shameful nation,'),
('ZEP', 2, 2, 'ZEP.2.2', 'before the decree takes effect and the day passes like chaff, before the burning anger of the LORD comes upon you, before the Day of the LORD’s anger comes upon you.'),
('ZEP', 2, 3, 'ZEP.2.3', 'Seek the LORD, all you humble of the earth who carry out His justice. Seek righteousness; seek humility. Perhaps you will be sheltered on the day of the LORD’s anger.'),
('ZEP', 2, 4, 'ZEP.2.4', 'For Gaza will be abandoned, and Ashkelon left in ruins. Ashdod will be driven out at noon, and Ekron will be uprooted.'),
('ZEP', 2, 5, 'ZEP.2.5', 'Woe to the dwellers of the seacoast, O nation of the Cherethites! The word of the LORD is against you, O Canaan, land of the Philistines: “I will destroy you, and no one will be left.”'),
('ZEP', 2, 6, 'ZEP.2.6', 'So the seacoast will become a land of pastures, with wells for shepherds and folds for sheep.'),
('ZEP', 2, 7, 'ZEP.2.7', 'The coast will belong to the remnant of the house of Judah; there they will find pasture. They will lie down in the evening among the houses of Ashkelon, for the LORD their God will attend to them and restore their captives.'),
('ZEP', 2, 8, 'ZEP.2.8', '“I have heard the reproach of Moab and the insults of the Ammonites, who have taunted My people and threatened their borders.'),
('ZEP', 2, 9, 'ZEP.2.9', 'Therefore, as surely as I live,” declares the LORD of Hosts, the God of Israel, “surely Moab will be like Sodom and the Ammonites like Gomorrah—a place of weeds and salt pits, a perpetual wasteland. The remnant of My people will plunder them; the remainder of My nation will dispossess them.”'),
('ZEP', 2, 10, 'ZEP.2.10', 'This they shall have in return for their pride, for taunting and mocking the people of the LORD of Hosts.'),
('ZEP', 2, 11, 'ZEP.2.11', 'The LORD will be terrifying to them when He starves all the gods of the earth. Then the nations of every shore will bow in worship to Him, each in its own place.'),
('ZEP', 2, 12, 'ZEP.2.12', '“You too, O Cushites, will be slain by My sword.”'),
('ZEP', 2, 13, 'ZEP.2.13', 'And He will stretch out His hand against the north and destroy Assyria; He will make Nineveh a desolation, as dry as a desert.'),
('ZEP', 2, 14, 'ZEP.2.14', 'Herds will lie down in her midst, creatures of every kind. Both the desert owl and screech owl will roost atop her pillars. Their calls will sound from the window, but desolation will lie on the threshold, for He will expose the beams of cedar.'),
('ZEP', 2, 15, 'ZEP.2.15', 'This carefree city that dwells securely, that thinks to herself: “I am it, and there is none besides me,” what a ruin she has become, a resting place for beasts. Everyone who passes by her hisses and shakes his fist.'),
('ZEP', 3, 1, 'ZEP.3.1', 'Woe to the city of oppressors, rebellious and defiled!'),
('ZEP', 3, 2, 'ZEP.3.2', 'She heeded no voice; she accepted no correction. She does not trust in the LORD; she has not drawn near to her God.'),
('ZEP', 3, 3, 'ZEP.3.3', 'Her princes are roaring lions; her judges are evening wolves, leaving nothing for the morning.'),
('ZEP', 3, 4, 'ZEP.3.4', 'Her prophets are reckless, faithless men. Her priests profane the sanctuary; they do violence to the law.'),
('ZEP', 3, 5, 'ZEP.3.5', 'The LORD within her is righteous; He does no wrong. He applies His justice morning by morning; He does not fail at dawn, yet the unjust know no shame.'),
('ZEP', 3, 6, 'ZEP.3.6', '“I have cut off the nations; their corner towers are destroyed. I have made their streets deserted with no one to pass through. Their cities are laid waste, with no man, no inhabitant.'),
('ZEP', 3, 7, 'ZEP.3.7', 'I said, ‘Surely you will fear Me and accept correction.’ Then her dwelling place would not be cut off despite all for which I punished her. But they rose early to corrupt all their deeds.'),
('ZEP', 3, 8, 'ZEP.3.8', 'Therefore wait for Me,” declares the LORD, “until the day I rise to testify. For My decision is to gather nations, to assemble kingdoms, to pour out upon them My indignation—all My burning anger. For all the earth will be consumed by the fire of My jealousy.'),
('ZEP', 3, 9, 'ZEP.3.9', 'For then I will restore pure lips to the peoples, that all may call upon the name of the LORD and serve Him shoulder to shoulder.'),
('ZEP', 3, 10, 'ZEP.3.10', 'From beyond the rivers of Cush My worshipers, My scattered people, will bring Me an offering.'),
('ZEP', 3, 11, 'ZEP.3.11', 'On that day you will not be put to shame for any of the deeds by which you have transgressed against Me. For then I will remove from among you those who rejoice in their pride, and you will never again be haughty on My holy mountain.'),
('ZEP', 3, 12, 'ZEP.3.12', 'But I will leave within you a meek and humble people, and they will trust in the name of the LORD.'),
('ZEP', 3, 13, 'ZEP.3.13', 'The remnant of Israel will no longer do wrong or speak lies, nor will a deceitful tongue be found in their mouths. But they will feed and lie down, with no one to make them tremble.”'),
('ZEP', 3, 14, 'ZEP.3.14', 'Sing for joy, O Daughter of Zion; shout aloud, O Israel! Be glad and rejoice with all your heart, O Daughter of Jerusalem!'),
('ZEP', 3, 15, 'ZEP.3.15', 'The LORD has taken away your punishment; He has turned back your enemy. Israel’s King, the LORD, is among you; no longer will you fear any harm.'),
('ZEP', 3, 16, 'ZEP.3.16', 'On that day they will say to Jerusalem: “Do not fear, O Zion; do not let your hands fall limp.'),
('ZEP', 3, 17, 'ZEP.3.17', 'The LORD your God is among you; He is mighty to save. He will rejoice over you with gladness; He will quiet you with His love; He will rejoice over you with singing.”'),
('ZEP', 3, 18, 'ZEP.3.18', '“I will gather those among you who grieve over the appointed feasts, so that you will no longer suffer reproach.'),
('ZEP', 3, 19, 'ZEP.3.19', 'Behold, at that time, I will deal with all who afflict you. I will save the lame and gather the scattered; and I will appoint praise and fame for the disgraced throughout the earth.'),
('ZEP', 3, 20, 'ZEP.3.20', 'At that time I will bring you in; yes, at that time I will gather you. For I will give you fame and praise among all the peoples of the earth when I restore your captives before your very eyes,” says the LORD.'),
('HAG', 1, 1, 'HAG.1.1', 'In the second year of the reign of Darius, on the first day of the sixth month, the word of the LORD came through Haggai the prophet to Zerubbabel son of Shealtiel, governor of Judah, and to Joshua son of Jehozadak, the high priest, stating'),
('HAG', 1, 2, 'HAG.1.2', 'that this is what the LORD of Hosts says: “These people say, ‘The time has not yet come to rebuild the house of the LORD.’”'),
('HAG', 1, 3, 'HAG.1.3', 'Then the word of the LORD came through Haggai the prophet, saying:'),
('HAG', 1, 4, 'HAG.1.4', '“Is it a time for you yourselves to live in your paneled houses, while this house lies in ruins?”'),
('HAG', 1, 5, 'HAG.1.5', 'Now this is what the LORD of Hosts says: “Consider carefully your ways.'),
('HAG', 1, 6, 'HAG.1.6', 'You have planted much but harvested little. You eat but never have enough. You drink but never have your fill. You put on clothes but never get warm. You earn wages to put into a bag pierced through.”'),
('HAG', 1, 7, 'HAG.1.7', 'This is what the LORD of Hosts says: “Consider carefully your ways.'),
('HAG', 1, 8, 'HAG.1.8', 'Go up into the hills, bring down lumber, and build the house, so that I may take pleasure in it and be glorified, says the LORD.'),
('HAG', 1, 9, 'HAG.1.9', 'You expected much, but behold, it amounted to little. And what you brought home, I blew away. Why? declares the LORD of Hosts. Because My house still lies in ruins, while each of you is busy with his own house.'),
('HAG', 1, 10, 'HAG.1.10', 'Therefore, on account of you the heavens have withheld their dew and the earth has withheld its crops.'),
('HAG', 1, 11, 'HAG.1.11', 'I have summoned a drought on the fields and on the mountains, on the grain, new wine, and oil, and on whatever the ground yields, on man and beast, and on all the labor of your hands.”'),
('HAG', 1, 12, 'HAG.1.12', 'Then Zerubbabel son of Shealtiel and Joshua son of Jehozadak, the high priest, as well as all the remnant of the people, obeyed the voice of the LORD their God and the words of the prophet Haggai, because the LORD their God had sent him. So the people feared the LORD.'),
('HAG', 1, 13, 'HAG.1.13', 'Haggai, the messenger of the LORD, delivered the message of the LORD to the people: “I am with you,” declares the LORD.'),
('HAG', 1, 14, 'HAG.1.14', 'So the LORD stirred the spirit of Zerubbabel son of Shealtiel, governor of Judah, and the spirit of Joshua son of Jehozadak, the high priest, as well as the spirit of all the remnant of the people. And they came and began the work on the house of the LORD of Hosts, their God,'),
('HAG', 1, 15, 'HAG.1.15', 'on the twenty-fourth day of the sixth month, in the second year of King Darius.'),
('HAG', 2, 1, 'HAG.2.1', 'On the twenty-first day of the seventh month, the word of the LORD came through Haggai the prophet, saying:'),
('HAG', 2, 2, 'HAG.2.2', '“Speak to Zerubbabel son of Shealtiel, governor of Judah, and to Joshua son of Jehozadak, the high priest, and also to the remnant of the people. Ask them,'),
('HAG', 2, 3, 'HAG.2.3', '‘Who is left among you who saw this house in its former glory? How does it look to you now? Does it not appear to you like nothing in comparison?’'),
('HAG', 2, 4, 'HAG.2.4', 'But now be strong, O Zerubbabel, declares the LORD. Be strong, O Joshua son of Jehozadak, the high priest. And be strong, all you people of the land, declares the LORD. Work! For I am with you, declares the LORD of Hosts.'),
('HAG', 2, 5, 'HAG.2.5', 'This is the promise I made to you when you came out of Egypt. And My Spirit remains among you; do not be afraid.”'),
('HAG', 2, 6, 'HAG.2.6', 'For this is what the LORD of Hosts says: “Once more, in a little while, I will shake the heavens and the earth, the sea and the dry land.'),
('HAG', 2, 7, 'HAG.2.7', 'I will shake all the nations, and they will come with all their treasures, and I will fill this house with glory, says the LORD of Hosts.'),
('HAG', 2, 8, 'HAG.2.8', 'The silver is Mine, and the gold is Mine, declares the LORD of Hosts.'),
('HAG', 2, 9, 'HAG.2.9', 'The latter glory of this house will be greater than the former, says the LORD of Hosts. And in this place I will provide peace, declares the LORD of Hosts.”'),
('HAG', 2, 10, 'HAG.2.10', 'On the twenty-fourth day of the ninth month, in the second year of Darius, the word of the LORD came to Haggai the prophet, saying,'),
('HAG', 2, 11, 'HAG.2.11', '“This is what the LORD of Hosts says: ‘Ask the priests for a ruling.'),
('HAG', 2, 12, 'HAG.2.12', 'If a man carries consecrated meat in the fold of his garment, and it touches bread, stew, wine, oil, or any other food, does that item become holy?’” “No,” replied the priests.'),
('HAG', 2, 13, 'HAG.2.13', 'So Haggai asked, “If one who is defiled by contact with a corpse touches any of these, does it become defiled?” “Yes, it becomes defiled,” the priests answered.'),
('HAG', 2, 14, 'HAG.2.14', 'Then Haggai replied, “So it is with this people and this nation before Me, declares the LORD, and so it is with every work of their hands; whatever they offer there is defiled.'),
('HAG', 2, 15, 'HAG.2.15', 'Now consider carefully from this day forward: Before one stone was placed on another in the temple of the LORD,'),
('HAG', 2, 16, 'HAG.2.16', 'from that time, when one came expecting a heap of twenty ephahs of grain, there were but ten. When one came to the winepress to draw out fifty baths, there were but twenty.'),
('HAG', 2, 17, 'HAG.2.17', 'I struck you—all the work of your hands—with blight, mildew, and hail, but you did not turn to Me, declares the LORD.'),
('HAG', 2, 18, 'HAG.2.18', 'Consider carefully from this day forward—from the twenty-fourth day of the ninth month, the day the foundation of the LORD’s temple was laid—consider carefully:'),
('HAG', 2, 19, 'HAG.2.19', 'Is there still seed in the barn? The vine, the fig, the pomegranate, and the olive tree have not yet yielded fruit. But from this day on, I will bless you.”'),
('HAG', 2, 20, 'HAG.2.20', 'For the second time that day, the twenty-fourth day of the month, the word of the LORD came to Haggai, saying,'),
('HAG', 2, 21, 'HAG.2.21', '“Tell Zerubbabel governor of Judah that I am about to shake the heavens and the earth:'),
('HAG', 2, 22, 'HAG.2.22', 'I will overturn royal thrones and destroy the power of the kingdoms of the nations. I will overturn chariots and their riders; horses and their riders will fall, each by the sword of his brother.'),
('HAG', 2, 23, 'HAG.2.23', 'On that day, declares the LORD of Hosts, I will take you, My servant, Zerubbabel son of Shealtiel, declares the LORD, and I will make you like My signet ring, for I have chosen you, declares the LORD of Hosts.”'),
('ZEC', 1, 1, 'ZEC.1.1', 'In the eighth month of the second year of Darius, the word of the LORD came to the prophet Zechariah son of Berechiah, the son of Iddo, saying:'),
('ZEC', 1, 2, 'ZEC.1.2', '“The LORD was very angry with your fathers.'),
('ZEC', 1, 3, 'ZEC.1.3', 'So tell the people that this is what the LORD of Hosts says: ‘Return to Me, declares the LORD of Hosts, and I will return to you, says the LORD of Hosts.’'),
('ZEC', 1, 4, 'ZEC.1.4', 'Do not be like your fathers, to whom the former prophets proclaimed that this is what the LORD of Hosts says: ‘Turn now from your evil ways and deeds.’ But they did not listen or pay attention to Me, declares the LORD.'),
('ZEC', 1, 5, 'ZEC.1.5', 'Where are your fathers now? And the prophets, do they live forever?'),
('ZEC', 1, 6, 'ZEC.1.6', 'But did not My words and My statutes, which I commanded My servants the prophets, overtake your fathers? They repented and said, ‘Just as the LORD of Hosts purposed to do to us according to our ways and deeds, so He has done to us.’”'),
('ZEC', 1, 7, 'ZEC.1.7', 'On the twenty-fourth day of the eleventh month, the month of Shebat, in the second year of Darius, the word of the LORD came to the prophet Zechariah son of Berechiah, the son of Iddo.'),
('ZEC', 1, 8, 'ZEC.1.8', 'I looked out into the night and saw a man riding on a red horse. He was standing among the myrtle trees in the hollow, and behind him were red, sorrel, and white horses.'),
('ZEC', 1, 9, 'ZEC.1.9', '“What are these, my lord?” I asked. And the angel who was speaking with me replied, “I will show you what they are.”'),
('ZEC', 1, 10, 'ZEC.1.10', 'Then the man standing among the myrtle trees explained, “They are the ones the LORD has sent to patrol the earth.”'),
('ZEC', 1, 11, 'ZEC.1.11', 'And the riders answered the angel of the LORD who was standing among the myrtle trees, “We have patrolled the earth, and behold, all the earth is at rest and tranquil.”'),
('ZEC', 1, 12, 'ZEC.1.12', 'Then the angel of the LORD said, “How long, O LORD of Hosts, will You withhold mercy from Jerusalem and the cities of Judah, with which You have been angry these seventy years?”'),
('ZEC', 1, 13, 'ZEC.1.13', 'So the LORD spoke kind and comforting words to the angel who was speaking with me.'),
('ZEC', 1, 14, 'ZEC.1.14', 'Then the angel who was speaking with me said, “Proclaim this word: This is what the LORD of Hosts says: ‘I am very jealous for Jerusalem and Zion,'),
('ZEC', 1, 15, 'ZEC.1.15', 'but I am fiercely angry with the nations that are at ease. For I was a little angry, but they have added to the calamity.’'),
('ZEC', 1, 16, 'ZEC.1.16', 'Therefore this is what the LORD says: ‘I will return to Jerusalem with mercy, and there My house will be rebuilt, declares the LORD of Hosts, and a measuring line will be stretched out over Jerusalem.’'),
('ZEC', 1, 17, 'ZEC.1.17', 'Proclaim further that this is what the LORD of Hosts says: ‘My cities will again overflow with prosperity; the LORD will again comfort Zion and choose Jerusalem.’”'),
('ZEC', 1, 18, 'ZEC.1.18', 'Then I looked up and saw four horns.'),
('ZEC', 1, 19, 'ZEC.1.19', 'So I asked the angel who was speaking with me, “What are these?” And he told me, “These are the horns that have scattered Judah, Israel, and Jerusalem.”'),
('ZEC', 1, 20, 'ZEC.1.20', 'Then the LORD showed me four craftsmen.'),
('ZEC', 1, 21, 'ZEC.1.21', '“What are these coming to do?” I asked. And He replied, “These are the horns that scattered Judah so that no one could raise his head; but the craftsmen have come to terrify them and throw down these horns of the nations that have lifted up their horns against the land of Judah to scatter it.”'),
('ZEC', 2, 1, 'ZEC.2.1', 'Then I lifted up my eyes and saw a man with a measuring line in his hand.'),
('ZEC', 2, 2, 'ZEC.2.2', '“Where are you going?” I asked. “To measure Jerusalem,” he replied, “and to determine its width and length.”'),
('ZEC', 2, 3, 'ZEC.2.3', 'Then the angel who was speaking with me went forth, and another angel came forward to meet him'),
('ZEC', 2, 4, 'ZEC.2.4', 'and said to him, “Run and tell that young man: ‘Jerusalem will be a city without walls because of the multitude of men and livestock within it.'),
('ZEC', 2, 5, 'ZEC.2.5', 'For I will be a wall of fire around it, declares the LORD, and I will be the glory within it.’”'),
('ZEC', 2, 6, 'ZEC.2.6', '“Get up! Get up! Flee from the land of the north,” declares the LORD, “for I have scattered you like the four winds of heaven,” declares the LORD.'),
('ZEC', 2, 7, 'ZEC.2.7', '“Get up, O Zion! Escape, you who dwell with the Daughter of Babylon!”'),
('ZEC', 2, 8, 'ZEC.2.8', 'For this is what the LORD of Hosts says: “After His Glory has sent Me against the nations that have plundered you—for whoever touches you touches the apple of His eye—'),
('ZEC', 2, 9, 'ZEC.2.9', 'I will surely wave My hand over them, so that they will become plunder for their own servants. Then you will know that the LORD of Hosts has sent Me.”'),
('ZEC', 2, 10, 'ZEC.2.10', '“Shout for joy and be glad, O Daughter of Zion, for I am coming to dwell among you,” declares the LORD.'),
('ZEC', 2, 11, 'ZEC.2.11', '“On that day many nations will join themselves to the LORD, and they will become My people. I will dwell among you, and you will know that the LORD of Hosts has sent Me to you.'),
('ZEC', 2, 12, 'ZEC.2.12', 'And the LORD will take possession of Judah as His portion in the Holy Land, and He will once again choose Jerusalem.'),
('ZEC', 2, 13, 'ZEC.2.13', 'Be silent before the LORD, all people, for He has roused Himself from His holy dwelling.”'),
('ZEC', 3, 1, 'ZEC.3.1', 'Then the angel showed me Joshua the high priest standing before the angel of the LORD, with Satan standing at his right hand to accuse him.'),
('ZEC', 3, 2, 'ZEC.3.2', 'And the LORD said to Satan: “The LORD rebukes you, Satan! Indeed, the LORD, who has chosen Jerusalem, rebukes you! Is not this man a firebrand snatched from the fire?”'),
('ZEC', 3, 3, 'ZEC.3.3', 'Now Joshua was dressed in filthy garments as he stood before the angel.'),
('ZEC', 3, 4, 'ZEC.3.4', 'So the angel said to those standing before him, “Take off his filthy clothes!” Then he said to Joshua, “See, I have removed your iniquity, and I will clothe you with splendid robes.”'),
('ZEC', 3, 5, 'ZEC.3.5', 'Then I said, “Let them put a clean turban on his head.” So a clean turban was placed on his head, and they clothed him, as the angel of the LORD stood by.'),
('ZEC', 3, 6, 'ZEC.3.6', 'Then the angel of the LORD gave this charge to Joshua:'),
('ZEC', 3, 7, 'ZEC.3.7', '“This is what the LORD of Hosts says: ‘If you walk in My ways and keep My instructions, then you will govern My house and will also have charge of My courts; and I will give you a place among these who are standing here.'),
('ZEC', 3, 8, 'ZEC.3.8', 'Hear now, O high priest Joshua, you and your companions seated before you, who are indeed a sign. For behold, I am going to bring My servant, the Branch.'),
('ZEC', 3, 9, 'ZEC.3.9', 'See the stone I have set before Joshua; on that one stone are seven eyes. Behold, I will engrave on it an inscription, declares the LORD of Hosts, and I will remove the iniquity of this land in a single day.'),
('ZEC', 3, 10, 'ZEC.3.10', 'On that day, declares the LORD of Hosts, you will each invite your neighbor to sit under your own vine and fig tree.’”'),
('ZEC', 4, 1, 'ZEC.4.1', 'Then the angel who was speaking with me returned and woke me, as a man is awakened from his sleep.'),
('ZEC', 4, 2, 'ZEC.4.2', '“What do you see?” he asked. “I see a solid gold lampstand,” I replied, “with a bowl at the top and seven lamps on it, with seven spouts to the lamps.'),
('ZEC', 4, 3, 'ZEC.4.3', 'There are also two olive trees beside it, one on the right side of the bowl and the other on its left.”'),
('ZEC', 4, 4, 'ZEC.4.4', '“What are these, my lord?” I asked the angel who was speaking with me.'),
('ZEC', 4, 5, 'ZEC.4.5', '“Do you not know what they are?” replied the angel. “No, my lord,” I answered.'),
('ZEC', 4, 6, 'ZEC.4.6', 'So he said to me, “This is the word of the LORD to Zerubbabel: Not by might nor by power, but by My Spirit, says the LORD of Hosts.'),
('ZEC', 4, 7, 'ZEC.4.7', 'What are you, O great mountain? Before Zerubbabel you will become a plain. Then he will bring forth the capstone accompanied by shouts of ‘Grace, grace to it!’”'),
('ZEC', 4, 8, 'ZEC.4.8', 'Then the word of the LORD came to me, saying,'),
('ZEC', 4, 9, 'ZEC.4.9', '“The hands of Zerubbabel have laid the foundation of this house, and his hands will complete it. Then you will know that the LORD of Hosts has sent me to you.'),
('ZEC', 4, 10, 'ZEC.4.10', 'For who has despised the day of small things? But these seven eyes of the LORD, which scan the whole earth, will rejoice when they see the plumb line in the hand of Zerubbabel.”'),
('ZEC', 4, 11, 'ZEC.4.11', 'Then I asked the angel, “What are the two olive trees on the right and left of the lampstand?”'),
('ZEC', 4, 12, 'ZEC.4.12', 'And I questioned him further, “What are the two olive branches beside the two gold pipes from which the golden oil pours?”'),
('ZEC', 4, 13, 'ZEC.4.13', '“Do you not know what these are?” he inquired. “No, my lord,” I replied.'),
('ZEC', 4, 14, 'ZEC.4.14', 'So he said, “These are the two anointed ones who are standing beside the Lord of all the earth.”'),
('ZEC', 5, 1, 'ZEC.5.1', 'Again I lifted up my eyes and saw before me a flying scroll.'),
('ZEC', 5, 2, 'ZEC.5.2', '“What do you see?” asked the angel. “I see a flying scroll,” I replied, “twenty cubits long and ten cubits wide.”'),
('ZEC', 5, 3, 'ZEC.5.3', 'Then he told me, “This is the curse that is going out over the face of all the land, for according to one side of the scroll, every thief will be removed; and according to the other side, every perjurer will be removed.'),
('ZEC', 5, 4, 'ZEC.5.4', 'I will send it out, declares the LORD of Hosts, and it will enter the house of the thief and the house of him who swears falsely by My name. It will remain inside his house and destroy it, down to its timbers and stones.”'),
('ZEC', 5, 5, 'ZEC.5.5', 'Then the angel who was speaking with me came forward and told me, “Now lift up your eyes and see what is approaching.”'),
('ZEC', 5, 6, 'ZEC.5.6', '“What is it?” I asked. And he replied, “A measuring basket is going forth.” Then he continued, “This is their iniquity in all the land.”'),
('ZEC', 5, 7, 'ZEC.5.7', 'And behold, the cover of lead was raised, and there was a woman sitting inside the basket.'),
('ZEC', 5, 8, 'ZEC.5.8', '“This is Wickedness,” he said. And he shoved her down into the basket, pushing down the lead cover over its opening.'),
('ZEC', 5, 9, 'ZEC.5.9', 'Then I lifted up my eyes and saw two women approaching, with the wind in their wings. Their wings were like those of a stork, and they lifted up the basket between heaven and earth.'),
('ZEC', 5, 10, 'ZEC.5.10', '“Where are they taking the basket?” I asked the angel who was speaking with me.'),
('ZEC', 5, 11, 'ZEC.5.11', '“To build a house for it in the land of Shinar,” he told me. “And when it is ready, the basket will be set there on its pedestal.”'),
('ZEC', 6, 1, 'ZEC.6.1', 'And again I lifted up my eyes and saw four chariots coming out from between two mountains—mountains of bronze.'),
('ZEC', 6, 2, 'ZEC.6.2', 'The first chariot had red horses, the second black horses,'),
('ZEC', 6, 3, 'ZEC.6.3', 'the third white horses, and the fourth dappled horses—all of them strong.'),
('ZEC', 6, 4, 'ZEC.6.4', 'So I inquired of the angel who was speaking with me, “What are these, my lord?”'),
('ZEC', 6, 5, 'ZEC.6.5', 'And the angel told me, “These are the four spirits of heaven, going forth from their station before the Lord of all the earth.'),
('ZEC', 6, 6, 'ZEC.6.6', 'The one with the black horses is going toward the land of the north, the one with the white horses toward the west, and the one with the dappled horses toward the south.”'),
('ZEC', 6, 7, 'ZEC.6.7', 'As the strong horses went out, they were eager to go and patrol the earth; and the LORD said, “Go and patrol the earth.” So they patrolled the earth.'),
('ZEC', 6, 8, 'ZEC.6.8', 'Then the LORD summoned me and said, “Behold, those going to the land of the north have given rest to My Spirit in the land of the north.”'),
('ZEC', 6, 9, 'ZEC.6.9', 'The word of the LORD also came to me, saying,'),
('ZEC', 6, 10, 'ZEC.6.10', '“Take an offering from the exiles—from Heldai, Tobijah, and Jedaiah, who have arrived from Babylon—and go that same day to the house of Josiah son of Zephaniah.'),
('ZEC', 6, 11, 'ZEC.6.11', 'Take silver and gold, make an ornate crown, and set it on the head of the high priest, Joshua son of Jehozadak.'),
('ZEC', 6, 12, 'ZEC.6.12', 'And you are to tell him that this is what the LORD of Hosts says: ‘Here is a man whose name is the Branch, and He will branch out from His place and build the temple of the LORD.'),
('ZEC', 6, 13, 'ZEC.6.13', 'Yes, He will build the temple of the LORD; He will be clothed in splendor and will sit on His throne and rule. And He will be a priest on His throne, and there will be peaceful counsel between the two.’'),
('ZEC', 6, 14, 'ZEC.6.14', 'The crown will reside in the temple of the LORD as a memorial to Helem, Tobijah, Jedaiah, and the gracious son of Zephaniah.'),
('ZEC', 6, 15, 'ZEC.6.15', 'Even those far away will come and build the temple of the LORD, and you will know that the LORD of Hosts has sent Me to you. This will happen if you diligently obey the voice of the LORD your God.”'),
('ZEC', 7, 1, 'ZEC.7.1', 'In the fourth year of King Darius, the word of the LORD came to Zechariah on the fourth day of the ninth month, the month of Chislev.'),
('ZEC', 7, 2, 'ZEC.7.2', 'Now the people of Bethel had sent Sharezer and Regem-melech, along with their men, to plead before the LORD'),
('ZEC', 7, 3, 'ZEC.7.3', 'by asking the priests of the house of the LORD of Hosts, as well as the prophets, “Should I weep and fast in the fifth month, as I have done these many years?”'),
('ZEC', 7, 4, 'ZEC.7.4', 'Then the word of the LORD of Hosts came to me, saying,'),
('ZEC', 7, 5, 'ZEC.7.5', '“Ask all the people of the land and the priests, ‘When you fasted and mourned in the fifth and seventh months for these seventy years, was it really for Me that you fasted?'),
('ZEC', 7, 6, 'ZEC.7.6', 'And when you were eating and drinking, were you not doing so simply for yourselves?'),
('ZEC', 7, 7, 'ZEC.7.7', 'Are these not the words that the LORD proclaimed through the earlier prophets, when Jerusalem and its surrounding towns were populous and prosperous, and the Negev and the foothills were inhabited?’”'),
('ZEC', 7, 8, 'ZEC.7.8', 'Then the word of the LORD came to Zechariah, saying,'),
('ZEC', 7, 9, 'ZEC.7.9', '“This is what the LORD of Hosts says: ‘Administer true justice. Show loving devotion and compassion to one another.'),
('ZEC', 7, 10, 'ZEC.7.10', 'Do not oppress the widow or the fatherless, the foreigner or the poor. And do not plot evil in your hearts against one another.’'),
('ZEC', 7, 11, 'ZEC.7.11', 'But they refused to pay attention and turned a stubborn shoulder; they stopped up their ears from hearing.'),
('ZEC', 7, 12, 'ZEC.7.12', 'They made their hearts like flint and would not listen to the law or to the words that the LORD of Hosts had sent by His Spirit through the earlier prophets. Therefore great anger came from the LORD of Hosts.'),
('ZEC', 7, 13, 'ZEC.7.13', 'And just as I had called and they would not listen, so when they called I would not listen, says the LORD of Hosts.'),
('ZEC', 7, 14, 'ZEC.7.14', 'But I scattered them with a whirlwind among all the nations that they had not known, and the land was left desolate behind them so that no one could come or go. Thus they turned the pleasant land into a desolation.”'),
('ZEC', 8, 1, 'ZEC.8.1', 'Again the word of the LORD of Hosts came to me, saying:'),
('ZEC', 8, 2, 'ZEC.8.2', 'This is what the LORD of Hosts says: “I am jealous for Zion with great zeal; I am jealous for her with great fervor.”'),
('ZEC', 8, 3, 'ZEC.8.3', 'This is what the LORD says: “I will return to Zion and dwell in Jerusalem. Then Jerusalem will be called the City of Truth, and the mountain of the LORD of Hosts will be called the Holy Mountain.”'),
('ZEC', 8, 4, 'ZEC.8.4', 'This is what the LORD of Hosts says: “Old men and old women will again sit along the streets of Jerusalem, each with a staff in hand because of great age.'),
('ZEC', 8, 5, 'ZEC.8.5', 'And the streets of the city will be filled with boys and girls playing there.”'),
('ZEC', 8, 6, 'ZEC.8.6', 'This is what the LORD of Hosts says: “If this is impossible in the eyes of the remnant of this people in these days, should it also be impossible in My eyes?” declares the LORD of Hosts.'),
('ZEC', 8, 7, 'ZEC.8.7', 'This is what the LORD of Hosts says: “I will save My people from the land of the east and from the land of the west.'),
('ZEC', 8, 8, 'ZEC.8.8', 'I will bring them back to dwell in Jerusalem, where they will be My people, and I will be their faithful and righteous God.”'),
('ZEC', 8, 9, 'ZEC.8.9', 'This is what the LORD of Hosts says: “Let your hands be strong, you who now hear these words spoken by the prophets who were present when the foundations were laid to rebuild the temple, the house of the LORD of Hosts.'),
('ZEC', 8, 10, 'ZEC.8.10', 'For before those days neither man nor beast received wages, nor was there safety from the enemy for anyone who came or went, for I had turned every man against his neighbor.'),
('ZEC', 8, 11, 'ZEC.8.11', 'But now I will not treat the remnant of this people as I did in the past,” declares the LORD of Hosts.'),
('ZEC', 8, 12, 'ZEC.8.12', '“For the seed will be prosperous, the vine will yield its fruit, the ground will yield its produce, and the skies will give their dew. To the remnant of this people I will give all these things as an inheritance.'),
('ZEC', 8, 13, 'ZEC.8.13', 'As you have been a curse among the nations, O house of Judah and house of Israel, so I will save you, and you will be a blessing. Do not be afraid; let your hands be strong.”'),
('ZEC', 8, 14, 'ZEC.8.14', 'For this is what the LORD of Hosts says: “Just as I resolved to bring disaster upon you when your fathers provoked Me to anger, and I did not relent,” says the LORD of Hosts,'),
('ZEC', 8, 15, 'ZEC.8.15', '“so now I have resolved to do good again to Jerusalem and Judah. Do not be afraid.'),
('ZEC', 8, 16, 'ZEC.8.16', 'These are the things you must do: Speak truth to one another, render true and sound judgments in your gates,'),
('ZEC', 8, 17, 'ZEC.8.17', 'do not plot evil in your hearts against your neighbor, and do not love to swear falsely, for I hate all these things,” declares the LORD.'),
('ZEC', 8, 18, 'ZEC.8.18', 'Then the word of the LORD of Hosts came to me, saying,'),
('ZEC', 8, 19, 'ZEC.8.19', '“This is what the LORD of Hosts says: The fasts of the fourth, the fifth, the seventh, and the tenth months will become times of joy and gladness, cheerful feasts for the house of Judah. Therefore you are to love both truth and peace.”'),
('ZEC', 8, 20, 'ZEC.8.20', 'This is what the LORD of Hosts says: “Peoples will yet come—the residents of many cities—'),
('ZEC', 8, 21, 'ZEC.8.21', 'and the residents of one city will go to another, saying: ‘Let us go at once to plead before the LORD and to seek the LORD of Hosts. I myself am going.’'),
('ZEC', 8, 22, 'ZEC.8.22', 'And many peoples and strong nations will come to seek the LORD of Hosts in Jerusalem and to plead before the LORD.”'),
('ZEC', 8, 23, 'ZEC.8.23', 'This is what the LORD of Hosts says: “In those days ten men from the nations of every tongue will tightly grasp the robe of a Jew, saying, ‘Let us go with you, for we have heard that God is with you.’”'),
('ZEC', 9, 1, 'ZEC.9.1', 'This is the burden of the word of the LORD against the land of Hadrach and Damascus its resting place—for the eyes of men and of all the tribes of Israel are upon the LORD—'),
('ZEC', 9, 2, 'ZEC.9.2', 'and also against Hamath, which borders it, as well as Tyre and Sidon, though they are very shrewd.'),
('ZEC', 9, 3, 'ZEC.9.3', 'Tyre has built herself a fortress; she has heaped up silver like dust, and gold like the dirt of the streets.'),
('ZEC', 9, 4, 'ZEC.9.4', 'Behold, the Lord will impoverish her and cast her wealth into the sea, and she will be consumed by fire.'),
('ZEC', 9, 5, 'ZEC.9.5', 'Ashkelon will see and fear; Gaza will writhe in agony, as will Ekron, for her hope will wither. There will cease to be a king in Gaza, and Ashkelon will be uninhabited.'),
('ZEC', 9, 6, 'ZEC.9.6', 'A mixed race will occupy Ashdod, and I will cut off the pride of the Philistines.'),
('ZEC', 9, 7, 'ZEC.9.7', 'I will remove the blood from their mouths and the abominations from between their teeth. Then they too will become a remnant for our God; they will become like a clan in Judah, and Ekron will be like the Jebusites.'),
('ZEC', 9, 8, 'ZEC.9.8', 'But I will camp around My house because of an army, because of those who march to and fro, and never again will an oppressor overrun My people, for now I keep watch with My own eyes.'),
('ZEC', 9, 9, 'ZEC.9.9', 'Rejoice greatly, O Daughter of Zion! Shout in triumph, O Daughter of Jerusalem! See, your King comes to you, righteous and victorious, humble and riding on a donkey, on a colt, the foal of a donkey.'),
('ZEC', 9, 10, 'ZEC.9.10', 'And I will cut off the chariot from Ephraim and the horse from Jerusalem, and the bow of war will be broken. Then He will proclaim peace to the nations. His dominion will extend from sea to sea, and from the Euphrates to the ends of the earth.'),
('ZEC', 9, 11, 'ZEC.9.11', 'As for you, because of the blood of My covenant, I will release your prisoners from the waterless pit.'),
('ZEC', 9, 12, 'ZEC.9.12', 'Return to your stronghold, O prisoners of hope; even today I declare that I will restore to you double.'),
('ZEC', 9, 13, 'ZEC.9.13', 'For I will bend Judah as My bow and fit it with Ephraim. I will rouse your sons, O Zion, against the sons of Greece. I will make you like the sword of a mighty man.'),
('ZEC', 9, 14, 'ZEC.9.14', 'Then the LORD will appear over them, and His arrow will go forth like lightning. The Lord GOD will sound the ram’s horn and advance in the whirlwinds of the south.'),
('ZEC', 9, 15, 'ZEC.9.15', 'The LORD of Hosts will shield them. They will destroy and conquer with slingstones; they will drink and roar as with wine. And they will be filled like sprinkling bowls, drenched like the corners of the altar.'),
('ZEC', 9, 16, 'ZEC.9.16', 'On that day the LORD their God will save them as the flock of His people; for like jewels in a crown they will sparkle over His land.'),
('ZEC', 9, 17, 'ZEC.9.17', 'How lovely they will be, and how beautiful! Grain will make the young men flourish, and new wine, the young women.'),
('ZEC', 10, 1, 'ZEC.10.1', 'Ask the LORD for rain in springtime; the LORD makes the storm clouds, and He will give everyone showers of rain and crops in the field.'),
('ZEC', 10, 2, 'ZEC.10.2', 'For idols speak deceit and diviners see illusions; they tell false dreams and offer empty comfort. Therefore the people wander like sheep, oppressed for lack of a shepherd.'),
('ZEC', 10, 3, 'ZEC.10.3', '“My anger burns against the shepherds, and I will punish the leaders. For the LORD of Hosts attends to His flock, the house of Judah; He will make them like His royal steed in battle.'),
('ZEC', 10, 4, 'ZEC.10.4', 'The cornerstone will come from Judah, the tent peg from him, as well as the battle bow and every ruler together.'),
('ZEC', 10, 5, 'ZEC.10.5', 'They will be like mighty men in battle, trampling the enemy in the mire of the streets. They will fight because the LORD is with them, and they will put the horsemen to shame.'),
('ZEC', 10, 6, 'ZEC.10.6', 'I will strengthen the house of Judah and save the house of Joseph. I will restore them because I have compassion on them, and they will be as though I had not rejected them. For I am the LORD their God, and I will answer them.'),
('ZEC', 10, 7, 'ZEC.10.7', 'Ephraim will be like a mighty man, and their hearts will be glad as with wine. Their children will see it and be joyful; their hearts will rejoice in the LORD.'),
('ZEC', 10, 8, 'ZEC.10.8', 'I will whistle for them to gather, for I have redeemed them; and they will be as numerous as they once were.'),
('ZEC', 10, 9, 'ZEC.10.9', 'Though I sow them among the nations, they will remember Me in distant lands; they and their children will live and return.'),
('ZEC', 10, 10, 'ZEC.10.10', 'I will bring them back from Egypt and gather them from Assyria. I will bring them to Gilead and Lebanon until no more room is found for them.'),
('ZEC', 10, 11, 'ZEC.10.11', 'They will pass through the sea of distress and strike the waves of the sea; all the depths of the Nile will dry up. The pride of Assyria will be brought down, and the scepter of Egypt will depart.'),
('ZEC', 10, 12, 'ZEC.10.12', 'I will strengthen them in the LORD, and in His name they will walk,” declares the LORD.'),
('ZEC', 11, 1, 'ZEC.11.1', 'Open your doors, O Lebanon, that the fire may consume your cedars!'),
('ZEC', 11, 2, 'ZEC.11.2', 'Wail, O cypress, for the cedar has fallen; the majestic trees are ruined! Wail, O oaks of Bashan, for the dense forest has been cut down!'),
('ZEC', 11, 3, 'ZEC.11.3', 'Listen to the wailing of the shepherds, for their glory is in ruins. Listen to the roaring of the young lions, for the thickets of the Jordan are destroyed.'),
('ZEC', 11, 4, 'ZEC.11.4', 'This is what the LORD my God says: “Pasture the flock marked for slaughter,'),
('ZEC', 11, 5, 'ZEC.11.5', 'whose buyers slaughter them without remorse. Those who sell them say, ‘Blessed be the LORD, for I am rich!’ Even their own shepherds have no compassion on them.'),
('ZEC', 11, 6, 'ZEC.11.6', 'For I will no longer have compassion on the people of the land, declares the LORD, but behold, I will cause each man to fall into the hands of his neighbor and his king, who will devastate the land, and I will not deliver it from their hands.”'),
('ZEC', 11, 7, 'ZEC.11.7', 'So I pastured the flock marked for slaughter, especially the afflicted of the flock. Then I took for myself two staffs, calling one Favor and the other Union, and I pastured the flock.'),
('ZEC', 11, 8, 'ZEC.11.8', 'And in one month I dismissed three shepherds. My soul grew impatient with the flock, and their souls also detested me.'),
('ZEC', 11, 9, 'ZEC.11.9', 'Then I said, “I will no longer shepherd you. Let the dying die, and the perishing perish; and let those who remain devour one another’s flesh.”'),
('ZEC', 11, 10, 'ZEC.11.10', 'Next I took my staff called Favor and cut it in two, revoking the covenant I had made with all the nations.'),
('ZEC', 11, 11, 'ZEC.11.11', 'It was revoked on that day, and so the afflicted of the flock who were watching me knew that it was the word of the LORD.'),
('ZEC', 11, 12, 'ZEC.11.12', 'Then I told them, “If it seems right to you, give me my wages; but if not, keep them.” So they weighed out my wages, thirty pieces of silver.'),
('ZEC', 11, 13, 'ZEC.11.13', 'And the LORD said to me, “Throw it to the potter”—this magnificent price at which they valued me. So I took the thirty pieces of silver and threw them to the potter in the house of the LORD.'),
('ZEC', 11, 14, 'ZEC.11.14', 'Then I cut in two my second staff called Union, breaking the brotherhood between Judah and Israel.'),
('ZEC', 11, 15, 'ZEC.11.15', 'And the LORD said to me: “Take up once more the equipment of a foolish shepherd.'),
('ZEC', 11, 16, 'ZEC.11.16', 'For behold, I will raise up a shepherd in the land who will neither care for the lost, nor seek the young, nor heal the broken, nor sustain the healthy, but he will devour the flesh of the choice sheep and tear off their hooves.'),
('ZEC', 11, 17, 'ZEC.11.17', 'Woe to the worthless shepherd, who deserts the flock! May a sword strike his arm and his right eye! May his arm be completely withered and his right eye utterly blinded!”'),
('ZEC', 12, 1, 'ZEC.12.1', 'This is the burden of the word of the LORD concerning Israel. Thus declares the LORD, who stretches out the heavens and lays the foundation of the earth, who forms the spirit of man within him:'),
('ZEC', 12, 2, 'ZEC.12.2', '“Behold, I will make Jerusalem a cup of drunkenness to all the surrounding peoples. Judah will be besieged, as well as Jerusalem.'),
('ZEC', 12, 3, 'ZEC.12.3', 'On that day, when all the nations of the earth gather against her, I will make Jerusalem a heavy stone for all the peoples; all who would heave it away will be severely injured.'),
('ZEC', 12, 4, 'ZEC.12.4', 'On that day, declares the LORD, I will strike every horse with panic, and every rider with madness. I will keep a watchful eye on the house of Judah, but I will strike with blindness all the horses of the nations.'),
('ZEC', 12, 5, 'ZEC.12.5', 'Then the leaders of Judah will say in their hearts: ‘The people of Jerusalem are my strength, for the LORD of Hosts is their God.’'),
('ZEC', 12, 6, 'ZEC.12.6', 'On that day I will make the clans of Judah like a firepot in a woodpile, like a flaming torch among the sheaves; they will consume all the peoples around them on the right and on the left, while the people of Jerusalem remain secure there.'),
('ZEC', 12, 7, 'ZEC.12.7', 'The LORD will save the tents of Judah first, so that the glory of the house of David and of the people of Jerusalem may not be greater than that of Judah.'),
('ZEC', 12, 8, 'ZEC.12.8', 'On that day the LORD will defend the people of Jerusalem, so that the weakest among them will be like David, and the house of David will be like God, like the angel of the LORD going before them.'),
('ZEC', 12, 9, 'ZEC.12.9', 'So on that day I will set out to destroy all the nations that come against Jerusalem.'),
('ZEC', 12, 10, 'ZEC.12.10', 'Then I will pour out on the house of David and on the people of Jerusalem a spirit of grace and prayer, and they will look on Me, the One they have pierced. They will mourn for Him as one mourns for an only child, and grieve bitterly for Him as one grieves for a firstborn son.'),
('ZEC', 12, 11, 'ZEC.12.11', 'On that day the wailing in Jerusalem will be as great as the wailing of Hadad-rimmon in the plain of Megiddo.'),
('ZEC', 12, 12, 'ZEC.12.12', 'The land will mourn, each clan on its own: the clan of the house of David and their wives, the clan of the house of Nathan and their wives,'),
('ZEC', 12, 13, 'ZEC.12.13', 'the clan of the house of Levi and their wives, the clan of Shimei and their wives,'),
('ZEC', 12, 14, 'ZEC.12.14', 'and all the remaining clans and their wives.'),
('ZEC', 13, 1, 'ZEC.13.1', '“On that day a fountain will be opened to the house of David and the people of Jerusalem, to cleanse them from sin and impurity.'),
('ZEC', 13, 2, 'ZEC.13.2', 'And on that day, declares the LORD of Hosts, I will erase the names of the idols from the land, and they will no longer be remembered. I will also remove the prophets and the spirit of impurity from the land.'),
('ZEC', 13, 3, 'ZEC.13.3', 'And if anyone still prophesies, his father and mother who bore him will say to him, ‘You shall not remain alive, because you have spoken falsely in the name of the LORD.’ When he prophesies, his father and mother who bore him will pierce him through.'),
('ZEC', 13, 4, 'ZEC.13.4', 'And on that day every prophet who prophesies will be ashamed of his vision, and he will not put on a hairy cloak in order to deceive.'),
('ZEC', 13, 5, 'ZEC.13.5', 'He will say, ‘I am not a prophet; I work the land, for I was purchased as a servant in my youth.’'),
('ZEC', 13, 6, 'ZEC.13.6', 'If someone asks him, ‘What are these wounds on your chest?’ he will answer, ‘These are the wounds I received in the house of my friends.’'),
('ZEC', 13, 7, 'ZEC.13.7', 'Awake, O sword, against My Shepherd, against the man who is My Companion, declares the LORD of Hosts. Strike the Shepherd, and the sheep will be scattered, and I will turn My hand against the little ones.'),
('ZEC', 13, 8, 'ZEC.13.8', 'And in all the land, declares the LORD, two-thirds will be cut off and perish, but a third will be left in it.'),
('ZEC', 13, 9, 'ZEC.13.9', 'This third I will bring through the fire; I will refine them like silver and test them like gold. They will call on My name, and I will answer them. I will say, ‘They are My people,’ and they will say, ‘The LORD is our God.’”'),
('ZEC', 14, 1, 'ZEC.14.1', 'Behold, a day of the LORD is coming when your plunder will be divided in your presence.'),
('ZEC', 14, 2, 'ZEC.14.2', 'For I will gather all the nations for battle against Jerusalem, and the city will be captured, the houses looted, and the women ravished. Half of the city will go into exile, but the rest of the people will not be removed from the city.'),
('ZEC', 14, 3, 'ZEC.14.3', 'Then the LORD will go out to fight against those nations, as He fights in the day of battle.'),
('ZEC', 14, 4, 'ZEC.14.4', 'On that day His feet will stand on the Mount of Olives, east of Jerusalem, and the Mount of Olives will be split in two from east to west, forming a great valley, with half the mountain moving to the north and half to the south.'),
('ZEC', 14, 5, 'ZEC.14.5', 'You will flee by My mountain valley, for it will extend to Azal. You will flee as you fled from the earthquake in the days of Uzziah king of Judah. Then the LORD my God will come, and all the holy ones with Him.'),
('ZEC', 14, 6, 'ZEC.14.6', 'On that day there will be no light, no cold or frost.'),
('ZEC', 14, 7, 'ZEC.14.7', 'It will be a unique day known only to the LORD, without day or night; but when evening comes, there will be light.'),
('ZEC', 14, 8, 'ZEC.14.8', 'And on that day living water will flow out from Jerusalem, half of it toward the Eastern Sea and the other half toward the Western Sea, in summer and winter alike.'),
('ZEC', 14, 9, 'ZEC.14.9', 'On that day the LORD will become King over all the earth—the LORD alone, and His name alone.'),
('ZEC', 14, 10, 'ZEC.14.10', 'All the land from Geba to Rimmon south of Jerusalem will be turned into a plain, but Jerusalem will be raised up and will remain in her place, from the Benjamin Gate to the site of the First Gate to the Corner Gate, and from the Tower of Hananel to the royal winepresses.'),
('ZEC', 14, 11, 'ZEC.14.11', 'People will live there, and never again will there be an utter destruction. So Jerusalem will dwell securely.'),
('ZEC', 14, 12, 'ZEC.14.12', 'And this will be the plague with which the LORD strikes all the peoples who have warred against Jerusalem: Their flesh will rot while they stand on their feet, their eyes will rot in their sockets, and their tongues will rot in their mouths.'),
('ZEC', 14, 13, 'ZEC.14.13', 'On that day a great panic from the LORD will come upon them, so that each will seize the hand of another, and the hand of one will rise against the other.'),
('ZEC', 14, 14, 'ZEC.14.14', 'Judah will also fight at Jerusalem, and the wealth of all the surrounding nations will be collected—gold, silver, and apparel in great abundance.'),
('ZEC', 14, 15, 'ZEC.14.15', 'And a similar plague will strike the horses and mules, camels and donkeys, and all the animals in those camps.'),
('ZEC', 14, 16, 'ZEC.14.16', 'Then all the survivors from the nations that came against Jerusalem will go up year after year to worship the King, the LORD of Hosts, and to celebrate the Feast of Tabernacles.'),
('ZEC', 14, 17, 'ZEC.14.17', 'And should any of the families of the earth not go up to Jerusalem to worship the King, the LORD of Hosts, then the rain will not fall on them.'),
('ZEC', 14, 18, 'ZEC.14.18', 'And if the people of Egypt will not go up and enter in, then the rain will not fall on them; this will be the plague with which the LORD strikes the nations who do not go up to celebrate the Feast of Tabernacles.'),
('ZEC', 14, 19, 'ZEC.14.19', 'This will be the punishment of Egypt and of all the nations that do not go up to celebrate the Feast of Tabernacles.'),
('ZEC', 14, 20, 'ZEC.14.20', 'On that day, HOLY TO THE LORD will be inscribed on the bells of the horses, and the cooking pots in the house of the LORD will be like the sprinkling bowls before the altar.'),
('ZEC', 14, 21, 'ZEC.14.21', 'Indeed, every pot in Jerusalem and Judah will be holy to the LORD of Hosts, and all who sacrifice will come and take some pots and cook in them. And on that day there will no longer be a Canaanite in the house of the LORD of Hosts.'),
('MAL', 1, 1, 'MAL.1.1', 'This is the burden of the word of the LORD to Israel through Malachi:'),
('MAL', 1, 2, 'MAL.1.2', '“I have loved you,” says the LORD. But you ask, “How have You loved us?” “Was not Esau Jacob’s brother?” declares the LORD. “Yet Jacob I have loved,'),
('MAL', 1, 3, 'MAL.1.3', 'but Esau I have hated, and I have made his mountains a wasteland and left his inheritance to the desert jackals.”'),
('MAL', 1, 4, 'MAL.1.4', 'Though Edom may say, “We have been devastated, but we will rebuild the ruins,” this is what the LORD of Hosts says: “They may build, but I will demolish. They will be called the Land of Wickedness, and a people with whom the LORD is indignant forever.'),
('MAL', 1, 5, 'MAL.1.5', 'You will see this with your own eyes, and you yourselves will say, ‘The LORD is great—even beyond the borders of Israel.’”'),
('MAL', 1, 6, 'MAL.1.6', '“A son honors his father, and a servant his master. But if I am a father, where is My honor? And if I am a master, where is your fear of Me?” says the LORD of Hosts to you priests who despise My name. “But you ask, ‘How have we despised Your name?’'),
('MAL', 1, 7, 'MAL.1.7', 'By presenting defiled food on My altar. But you ask, ‘How have we defiled You?’ By saying that the table of the LORD is contemptible.'),
('MAL', 1, 8, 'MAL.1.8', 'When you offer blind animals for sacrifice, is it not wrong? And when you present the lame and sick ones, is it not wrong? Try offering them to your governor! Would he be pleased with you or show you favor?” asks the LORD of Hosts.'),
('MAL', 1, 9, 'MAL.1.9', '“But ask now for God’s favor. Will He be gracious? Since this has come from your hands, will He show you favor?” asks the LORD of Hosts.'),
('MAL', 1, 10, 'MAL.1.10', '“Oh, that one of you would shut the temple doors, so that you would no longer kindle useless fires on My altar! I take no pleasure in you,” says the LORD of Hosts, “and I will accept no offering from your hands.'),
('MAL', 1, 11, 'MAL.1.11', 'For My name will be great among the nations, from where the sun rises to where it sets. In every place, incense and pure offerings will be presented in My name, because My name will be great among the nations,” says the LORD of Hosts.'),
('MAL', 1, 12, 'MAL.1.12', '“But you profane it when you say, ‘The table of the Lord is defiled, and as for its fruit, its food is contemptible.’'),
('MAL', 1, 13, 'MAL.1.13', 'You also say: ‘Oh, what a nuisance!’ And you turn up your nose at it,” says the LORD of Hosts. “You bring offerings that are stolen, lame, or sick! Should I accept these from your hands?” asks the LORD.'),
('MAL', 1, 14, 'MAL.1.14', '“But cursed is the deceiver who has an acceptable male in his flock and vows to give it, but sacrifices a defective animal to the Lord. For I am a great King,” says the LORD of Hosts, “and My name is to be feared among the nations.'),
('MAL', 2, 1, 'MAL.2.1', '“And now this decree is for you, O priests:'),
('MAL', 2, 2, 'MAL.2.2', 'If you do not listen, and if you do not take it to heart to honor My name,” says the LORD of Hosts, “I will send a curse among you, and I will curse your blessings. Yes, I have already begun to curse them, because you are not taking it to heart.'),
('MAL', 2, 3, 'MAL.2.3', 'Behold, I will rebuke your descendants, and I will spread dung on your faces, the waste from your feasts, and you will be carried off with it.'),
('MAL', 2, 4, 'MAL.2.4', 'Then you will know that I have sent you this commandment so that My covenant with Levi may continue,” says the LORD of Hosts.'),
('MAL', 2, 5, 'MAL.2.5', '“My covenant with him was one of life and peace, which I gave to him; it called for reverence, and he revered Me and stood in awe of My name.'),
('MAL', 2, 6, 'MAL.2.6', 'True instruction was in his mouth, and nothing false was found on his lips. He walked with Me in peace and uprightness, and he turned many from iniquity.'),
('MAL', 2, 7, 'MAL.2.7', 'For the lips of a priest should preserve knowledge, and people should seek instruction from his mouth, because he is the messenger of the LORD of Hosts.'),
('MAL', 2, 8, 'MAL.2.8', 'But you have departed from the way, and your instruction has caused many to stumble. You have violated the covenant of Levi,” says the LORD of Hosts.'),
('MAL', 2, 9, 'MAL.2.9', '“So I in turn have made you despised and humiliated before all the people, because you have not kept My ways, but have shown partiality in matters of the law.”'),
('MAL', 2, 10, 'MAL.2.10', 'Do we not all have one Father? Did not one God create us? Why then do we break faith with one another so as to profane the covenant of our fathers?'),
('MAL', 2, 11, 'MAL.2.11', 'Judah has broken faith; an abomination has been committed in Israel and in Jerusalem. For Judah has profaned the LORD’s beloved sanctuary by marrying the daughter of a foreign god.'),
('MAL', 2, 12, 'MAL.2.12', 'As for the man who does this, may the LORD cut off from the tents of Jacob everyone who is awake and aware—even if he brings an offering to the LORD of Hosts.'),
('MAL', 2, 13, 'MAL.2.13', 'And this is another thing you do: You cover the altar of the LORD with tears, with weeping and groaning, because He no longer regards your offerings or receives them gladly from your hands.'),
('MAL', 2, 14, 'MAL.2.14', 'Yet you ask, “Why?” It is because the LORD has been a witness between you and the wife of your youth, against whom you have broken faith, though she is your companion and your wife by covenant.'),
('MAL', 2, 15, 'MAL.2.15', 'Has not the LORD made them one, having a portion of the Spirit? And why one? Because He seeks godly offspring. So guard yourselves in your spirit and do not break faith with the wife of your youth.'),
('MAL', 2, 16, 'MAL.2.16', '“For I hate divorce,” says the LORD, the God of Israel. “He who divorces his wife covers his garment with violence,” says the LORD of Hosts. So guard yourselves in your spirit and do not break faith.'),
('MAL', 2, 17, 'MAL.2.17', 'You have wearied the LORD with your words; yet you ask, “How have we wearied Him?” By saying, “All who do evil are good in the sight of the LORD, and in them He delights,” or, “Where is the God of justice?”'),
('MAL', 3, 1, 'MAL.3.1', '“Behold, I will send My messenger, who will prepare the way before Me. Then the Lord whom you seek will suddenly come to His temple—the Messenger of the covenant, in whom you delight—see, He is coming,” says the LORD of Hosts.'),
('MAL', 3, 2, 'MAL.3.2', 'But who can endure the day of His coming? And who can stand when He appears? For He will be like a refiner’s fire, like a launderer’s soap.'),
('MAL', 3, 3, 'MAL.3.3', 'And He will sit as a refiner and purifier of silver; He will purify the sons of Levi and refine them like gold and silver. Then they will present offerings to the LORD in righteousness.'),
('MAL', 3, 4, 'MAL.3.4', 'Then the offerings of Judah and Jerusalem will please the LORD, as in days of old and years gone by.'),
('MAL', 3, 5, 'MAL.3.5', '“Then I will draw near to you for judgment. And I will be a swift witness against sorcerers and adulterers and perjurers, against oppressors of the widowed and fatherless, and against those who defraud laborers of their wages and deny justice to the foreigner but do not fear Me,” says the LORD of Hosts.'),
('MAL', 3, 6, 'MAL.3.6', '“Because I, the LORD, do not change, you descendants of Jacob have not been destroyed.'),
('MAL', 3, 7, 'MAL.3.7', 'Yet from the days of your fathers, you have turned away from My statutes and have not kept them. Return to Me, and I will return to you,” says the LORD of Hosts. “But you ask, ‘How can we return?’'),
('MAL', 3, 8, 'MAL.3.8', 'Will a man rob God? Yet you are robbing Me! But you ask, ‘How do we rob You?’ In tithes and offerings.'),
('MAL', 3, 9, 'MAL.3.9', 'You are cursed with a curse, yet you—the whole nation—are still robbing Me.'),
('MAL', 3, 10, 'MAL.3.10', 'Bring the full tithe into the storehouse, so that there may be food in My house. Test Me in this,” says the LORD of Hosts. “See if I will not open the windows of heaven and pour out for you blessing without measure.'),
('MAL', 3, 11, 'MAL.3.11', 'I will rebuke the devourer for you, so that it will not destroy the fruits of your land, and the vine in your field will not fail to produce fruit,” says the LORD of Hosts.'),
('MAL', 3, 12, 'MAL.3.12', '“Then all the nations will call you blessed, for you will be a land of delight,” says the LORD of Hosts.'),
('MAL', 3, 13, 'MAL.3.13', '“Your words against Me have been harsh,” says the LORD. “Yet you ask, ‘What have we spoken against You?’'),
('MAL', 3, 14, 'MAL.3.14', 'You have said, ‘It is futile to serve God. What have we gained by keeping His requirements and walking mournfully before the LORD of Hosts?'),
('MAL', 3, 15, 'MAL.3.15', 'So now we call the arrogant blessed. Not only do evildoers prosper, they even test God and escape.’”'),
('MAL', 3, 16, 'MAL.3.16', 'At that time those who feared the LORD spoke with one another, and the LORD listened and heard them. So a scroll of remembrance was written before Him regarding those who feared the LORD and honored His name.'),
('MAL', 3, 17, 'MAL.3.17', '“They will be Mine,” says the LORD of Hosts, “on the day when I prepare My treasured possession. And I will spare them as a man spares his own son who serves him.'),
('MAL', 3, 18, 'MAL.3.18', 'So you will again distinguish between the righteous and the wicked, between those who serve God and those who do not.”'),
('MAL', 4, 1, 'MAL.4.1', '“For behold, the day is coming, burning like a furnace, when all the arrogant and every evildoer will be stubble; the day is coming when I will set them ablaze,” says the LORD of Hosts. “Not a root or branch will be left to them.”'),
('MAL', 4, 2, 'MAL.4.2', '“But for you who fear My name, the sun of righteousness will rise with healing in its wings, and you will go out and leap like calves from the stall.'),
('MAL', 4, 3, 'MAL.4.3', 'Then you will trample the wicked, for they will be ashes under the soles of your feet on the day I am preparing,” says the LORD of Hosts.'),
('MAL', 4, 4, 'MAL.4.4', '“Remember the law of My servant Moses, the statutes and ordinances I commanded him for all Israel at Horeb.'),
('MAL', 4, 5, 'MAL.4.5', 'Behold, I will send you Elijah the prophet before the coming of the great and awesome Day of the LORD.'),
('MAL', 4, 6, 'MAL.4.6', 'And he will turn the hearts of the fathers to their children, and the hearts of the children to their fathers. Otherwise, I will come and strike the land with a curse.”'),
('MAT', 1, 1, 'MAT.1.1', 'This is the record of the genealogy of Jesus Christ, the son of David, the son of Abraham:'),
('MAT', 1, 2, 'MAT.1.2', 'Abraham was the father of Isaac, Isaac the father of Jacob, and Jacob the father of Judah and his brothers.'),
('MAT', 1, 3, 'MAT.1.3', 'Judah was the father of Perez and Zerah by Tamar, Perez the father of Hezron, and Hezron the father of Ram.'),
('MAT', 1, 4, 'MAT.1.4', 'Ram was the father of Amminadab, Amminadab the father of Nahshon, and Nahshon the father of Salmon.'),
('MAT', 1, 5, 'MAT.1.5', 'Salmon was the father of Boaz by Rahab, Boaz the father of Obed by Ruth, Obed the father of Jesse,'),
('MAT', 1, 6, 'MAT.1.6', 'and Jesse the father of David the king. Next: David was the father of Solomon by Uriah’s wife,'),
('MAT', 1, 7, 'MAT.1.7', 'Solomon the father of Rehoboam, Rehoboam the father of Abijah, and Abijah the father of Asa.'),
('MAT', 1, 8, 'MAT.1.8', 'Asa was the father of Jehoshaphat, Jehoshaphat the father of Joram, and Joram the father of Uzziah.'),
('MAT', 1, 9, 'MAT.1.9', 'Uzziah was the father of Jotham, Jotham the father of Ahaz, and Ahaz the father of Hezekiah.'),
('MAT', 1, 10, 'MAT.1.10', 'Hezekiah was the father of Manasseh, Manasseh the father of Amon, Amon the father of Josiah,'),
('MAT', 1, 11, 'MAT.1.11', 'and Josiah the father of Jeconiah and his brothers at the time of the exile to Babylon.'),
('MAT', 1, 12, 'MAT.1.12', 'After the exile to Babylon: Jeconiah was the father of Shealtiel, Shealtiel the father of Zerubbabel,'),
('MAT', 1, 13, 'MAT.1.13', 'Zerubbabel the father of Abiud, Abiud the father of Eliakim, and Eliakim the father of Azor.'),
('MAT', 1, 14, 'MAT.1.14', 'Azor was the father of Zadok, Zadok the father of Achim, and Achim the father of Eliud.'),
('MAT', 1, 15, 'MAT.1.15', 'Eliud was the father of Eleazar, Eleazar the father of Matthan, Matthan the father of Jacob,'),
('MAT', 1, 16, 'MAT.1.16', 'and Jacob the father of Joseph, the husband of Mary, of whom was born Jesus, who is called Christ.'),
('MAT', 1, 17, 'MAT.1.17', 'In all, then, there were fourteen generations from Abraham to David, fourteen from David to the exile to Babylon, and fourteen from the exile to the Christ.'),
('MAT', 1, 18, 'MAT.1.18', 'This is how the birth of Jesus Christ came about: His mother Mary was pledged in marriage to Joseph, but before they came together, she was found to be with child through the Holy Spirit.'),
('MAT', 1, 19, 'MAT.1.19', 'Because Joseph her husband was a righteous man and was unwilling to disgrace her publicly, he resolved to divorce her quietly.'),
('MAT', 1, 20, 'MAT.1.20', 'But after he had pondered these things, an angel of the Lord appeared to him in a dream and said, “Joseph, son of David, do not be afraid to embrace Mary as your wife, for the One conceived in her is from the Holy Spirit.'),
('MAT', 1, 21, 'MAT.1.21', 'She will give birth to a Son, and you are to give Him the name Jesus, because He will save His people from their sins.”'),
('MAT', 1, 22, 'MAT.1.22', 'All this took place to fulfill what the Lord had said through the prophet:'),
('MAT', 1, 23, 'MAT.1.23', '“Behold, the virgin will be with child and will give birth to a son, and they will call Him Immanuel” (which means, “God with us”).'),
('MAT', 1, 24, 'MAT.1.24', 'When Joseph woke up, he did as the angel of the Lord had commanded him and embraced Mary as his wife.'),
('MAT', 1, 25, 'MAT.1.25', 'But he had no union with her until she gave birth to a Son. And he gave Him the name Jesus.'),
('MAT', 2, 1, 'MAT.2.1', 'After Jesus was born in Bethlehem in Judea, during the time of King Herod, Magi from the east arrived in Jerusalem,'),
('MAT', 2, 2, 'MAT.2.2', 'asking, “Where is the One who has been born King of the Jews? We saw His star in the east and have come to worship Him.”'),
('MAT', 2, 3, 'MAT.2.3', 'When King Herod heard this, he was disturbed, and all Jerusalem with him.'),
('MAT', 2, 4, 'MAT.2.4', 'And when he had assembled all the chief priests and scribes of the people, he asked them where the Christ was to be born.'),
('MAT', 2, 5, 'MAT.2.5', '“In Bethlehem in Judea,” they replied, “for this is what the prophet has written:'),
('MAT', 2, 6, 'MAT.2.6', '‘But you, Bethlehem, in the land of Judah, are by no means least among the rulers of Judah, for out of you will come a ruler who will be the shepherd of My people Israel.’”'),
('MAT', 2, 7, 'MAT.2.7', 'Then Herod called the Magi secretly and learned from them the exact time the star had appeared.'),
('MAT', 2, 8, 'MAT.2.8', 'And sending them to Bethlehem, he said: “Go and search carefully for the Child, and when you find Him, report to me, so that I too may go and worship Him.”'),
('MAT', 2, 9, 'MAT.2.9', 'After they had heard the king, they went on their way, and the star they had seen in the east went ahead of them until it stood over the place where the Child was.'),
('MAT', 2, 10, 'MAT.2.10', 'When they saw the star, they rejoiced with great delight.'),
('MAT', 2, 11, 'MAT.2.11', 'On coming to the house, they saw the Child with His mother Mary, and they fell down and worshiped Him. Then they opened their treasures and presented Him with gifts of gold and frankincense and myrrh.'),
('MAT', 2, 12, 'MAT.2.12', 'And having been warned in a dream not to return to Herod, they withdrew to their country by another route.'),
('MAT', 2, 13, 'MAT.2.13', 'When the Magi had gone, an angel of the Lord appeared to Joseph in a dream. “Get up!” he said. “Take the Child and His mother and flee to Egypt. Stay there until I tell you, for Herod is going to search for the Child to kill Him.”'),
('MAT', 2, 14, 'MAT.2.14', 'So he got up, took the Child and His mother by night, and withdrew to Egypt,'),
('MAT', 2, 15, 'MAT.2.15', 'where he stayed until the death of Herod. This fulfilled what the Lord had spoken through the prophet: “Out of Egypt I called My Son.”'),
('MAT', 2, 16, 'MAT.2.16', 'When Herod saw that he had been outwitted by the Magi, he was filled with rage. Sending orders, he put to death all the boys in Bethlehem and its vicinity who were two years old and under, according to the time he had learned from the Magi.'),
('MAT', 2, 17, 'MAT.2.17', 'Then what was spoken through the prophet Jeremiah was fulfilled:'),
('MAT', 2, 18, 'MAT.2.18', '“A voice is heard in Ramah, weeping and great mourning, Rachel weeping for her children and refusing to be comforted, because they are no more.”'),
('MAT', 2, 19, 'MAT.2.19', 'After Herod died, an angel of the Lord appeared in a dream to Joseph in Egypt.'),
('MAT', 2, 20, 'MAT.2.20', '“Get up!” he said. “Take the Child and His mother and go to the land of Israel, for those seeking the Child’s life are now dead.”'),
('MAT', 2, 21, 'MAT.2.21', 'So Joseph got up, took the Child and His mother, and went to the land of Israel.'),
('MAT', 2, 22, 'MAT.2.22', 'But when he learned that Archelaus was reigning in Judea in place of his father Herod, he was afraid to go there. And having been warned in a dream, he withdrew to the district of Galilee,'),
('MAT', 2, 23, 'MAT.2.23', 'and he went and lived in a town called Nazareth. So was fulfilled what was spoken through the prophets: “He will be called a Nazarene.”'),
('MAT', 3, 1, 'MAT.3.1', 'In those days John the Baptist came, preaching in the wilderness of Judea'),
('MAT', 3, 2, 'MAT.3.2', 'and saying, “Repent, for the kingdom of heaven is near.”'),
('MAT', 3, 3, 'MAT.3.3', 'This is he who was spoken of through the prophet Isaiah: “A voice of one calling in the wilderness, ‘Prepare the way for the Lord, make straight paths for Him.’”'),
('MAT', 3, 4, 'MAT.3.4', 'John wore a garment of camel’s hair, with a leather belt around his waist. His food was locusts and wild honey.'),
('MAT', 3, 5, 'MAT.3.5', 'People went out to him from Jerusalem and all Judea and the whole region around the Jordan.'),
('MAT', 3, 6, 'MAT.3.6', 'Confessing their sins, they were baptized by him in the Jordan River.'),
('MAT', 3, 7, 'MAT.3.7', 'But when John saw many of the Pharisees and Sadducees coming to his place of baptism, he said to them, “You brood of vipers, who warned you to flee from the coming wrath?'),
('MAT', 3, 8, 'MAT.3.8', 'Produce fruit, then, in keeping with repentance.'),
('MAT', 3, 9, 'MAT.3.9', 'And do not presume to say to yourselves, ‘We have Abraham as our father.’ For I tell you that out of these stones God can raise up children for Abraham.'),
('MAT', 3, 10, 'MAT.3.10', 'The axe lies ready at the root of the trees, and every tree that does not produce good fruit will be cut down and thrown into the fire.'),
('MAT', 3, 11, 'MAT.3.11', 'I baptize you with water for repentance, but after me will come One more powerful than I, whose sandals I am not worthy to carry. He will baptize you with the Holy Spirit and with fire.'),
('MAT', 3, 12, 'MAT.3.12', 'His winnowing fork is in His hand to clear His threshing floor and to gather His wheat into the barn; but He will burn up the chaff with unquenchable fire.”'),
('MAT', 3, 13, 'MAT.3.13', 'At that time Jesus came from Galilee to the Jordan to be baptized by John.'),
('MAT', 3, 14, 'MAT.3.14', 'But John tried to prevent Him, saying, “I need to be baptized by You, and do You come to me?”'),
('MAT', 3, 15, 'MAT.3.15', '“Let it be so now,” Jesus replied. “It is fitting for us to fulfill all righteousness in this way.” Then John permitted Him.'),
('MAT', 3, 16, 'MAT.3.16', 'As soon as Jesus was baptized, He went up out of the water. Suddenly the heavens were opened, and He saw the Spirit of God descending like a dove and resting on Him.'),
('MAT', 3, 17, 'MAT.3.17', 'And a voice from heaven said, “This is My beloved Son, in whom I am well pleased!”'),
('MAT', 4, 1, 'MAT.4.1', 'Then Jesus was led by the Spirit into the wilderness to be tempted by the devil.'),
('MAT', 4, 2, 'MAT.4.2', 'After fasting forty days and forty nights, He was hungry.'),
('MAT', 4, 3, 'MAT.4.3', 'The tempter came to Him and said, “If You are the Son of God, tell these stones to become bread.”'),
('MAT', 4, 4, 'MAT.4.4', 'But Jesus answered, “It is written: ‘Man shall not live on bread alone, but on every word that comes from the mouth of God.’”'),
('MAT', 4, 5, 'MAT.4.5', 'Then the devil took Him to the holy city and set Him on the pinnacle of the temple.'),
('MAT', 4, 6, 'MAT.4.6', '“If You are the Son of God,” he said, “throw Yourself down. For it is written: ‘He will command His angels concerning You, and they will lift You up in their hands, so that You will not strike Your foot against a stone.’”'),
('MAT', 4, 7, 'MAT.4.7', 'Jesus replied, “It is also written: ‘Do not put the Lord your God to the test.’”'),
('MAT', 4, 8, 'MAT.4.8', 'Again, the devil took Him to a very high mountain and showed Him all the kingdoms of the world and their glory.'),
('MAT', 4, 9, 'MAT.4.9', '“All this I will give You,” he said, “if You will fall down and worship me.”'),
('MAT', 4, 10, 'MAT.4.10', '“Away from Me, Satan!” Jesus told him. “For it is written: ‘Worship the Lord your God and serve Him only.’”'),
('MAT', 4, 11, 'MAT.4.11', 'Then the devil left Him, and angels came and ministered to Him.'),
('MAT', 4, 12, 'MAT.4.12', 'When Jesus heard that John had been imprisoned, He withdrew to Galilee.'),
('MAT', 4, 13, 'MAT.4.13', 'Leaving Nazareth, He went and lived in Capernaum, which is by the sea in the region of Zebulun and Naphtali,'),
('MAT', 4, 14, 'MAT.4.14', 'to fulfill what was spoken through the prophet Isaiah:'),
('MAT', 4, 15, 'MAT.4.15', '“Land of Zebulun and land of Naphtali, the Way of the Sea, beyond the Jordan, Galilee of the Gentiles—'),
('MAT', 4, 16, 'MAT.4.16', 'the people living in darkness have seen a great light; on those living in the land of the shadow of death, a light has dawned.”'),
('MAT', 4, 17, 'MAT.4.17', 'From that time on Jesus began to preach, “Repent, for the kingdom of heaven is near.”'),
('MAT', 4, 18, 'MAT.4.18', 'As Jesus was walking beside the Sea of Galilee, He saw two brothers, Simon called Peter and his brother Andrew. They were casting a net into the sea, for they were fishermen.'),
('MAT', 4, 19, 'MAT.4.19', '“Come, follow Me,” Jesus said, “and I will make you fishers of men.”'),
('MAT', 4, 20, 'MAT.4.20', 'And at once they left their nets and followed Him.'),
('MAT', 4, 21, 'MAT.4.21', 'Going on from there, He saw two other brothers, James son of Zebedee and his brother John. They were in a boat with their father Zebedee, mending their nets. Jesus called them,'),
('MAT', 4, 22, 'MAT.4.22', 'and immediately they left the boat and their father and followed Him.'),
('MAT', 4, 23, 'MAT.4.23', 'Jesus went throughout Galilee, teaching in their synagogues, preaching the gospel of the kingdom, and healing every disease and sickness among the people.'),
('MAT', 4, 24, 'MAT.4.24', 'News about Him spread all over Syria, and people brought to Him all who were ill with various diseases, those suffering acute pain, the demon-possessed, those having seizures, and the paralyzed, and He healed them.'),
('MAT', 4, 25, 'MAT.4.25', 'Large crowds followed Him, having come from Galilee, the Decapolis, Jerusalem, Judea, and beyond the Jordan.'),
('MAT', 5, 1, 'MAT.5.1', 'When Jesus saw the crowds, He went up on the mountain and sat down. His disciples came to Him,'),
('MAT', 5, 2, 'MAT.5.2', 'and He began to teach them, saying:'),
('MAT', 5, 3, 'MAT.5.3', '“Blessed are the poor in spirit, for theirs is the kingdom of heaven.'),
('MAT', 5, 4, 'MAT.5.4', 'Blessed are those who mourn, for they will be comforted.'),
('MAT', 5, 5, 'MAT.5.5', 'Blessed are the meek, for they will inherit the earth.'),
('MAT', 5, 6, 'MAT.5.6', 'Blessed are those who hunger and thirst for righteousness, for they will be filled.'),
('MAT', 5, 7, 'MAT.5.7', 'Blessed are the merciful, for they will be shown mercy.'),
('MAT', 5, 8, 'MAT.5.8', 'Blessed are the pure in heart, for they will see God.'),
('MAT', 5, 9, 'MAT.5.9', 'Blessed are the peacemakers, for they will be called sons of God.'),
('MAT', 5, 10, 'MAT.5.10', 'Blessed are those who are persecuted because of righteousness, for theirs is the kingdom of heaven.'),
('MAT', 5, 11, 'MAT.5.11', 'Blessed are you when people insult you, persecute you, and falsely say all kinds of evil against you because of Me.'),
('MAT', 5, 12, 'MAT.5.12', 'Rejoice and be glad, because great is your reward in heaven, for in the same way they persecuted the prophets before you.'),
('MAT', 5, 13, 'MAT.5.13', 'You are the salt of the earth. But if the salt loses its savor, how can it be made salty again? It is no longer good for anything, except to be thrown out and trampled by men.'),
('MAT', 5, 14, 'MAT.5.14', 'You are the light of the world. A city on a hill cannot be hidden.'),
('MAT', 5, 15, 'MAT.5.15', 'Neither do people light a lamp and put it under a basket. Instead, they set it on a stand, and it gives light to everyone in the house.'),
('MAT', 5, 16, 'MAT.5.16', 'In the same way, let your light shine before men, that they may see your good deeds and glorify your Father in heaven.'),
('MAT', 5, 17, 'MAT.5.17', 'Do not think that I have come to abolish the Law or the Prophets. I have not come to abolish them, but to fulfill them.'),
('MAT', 5, 18, 'MAT.5.18', 'For I tell you truly, until heaven and earth pass away, not a single jot, not a stroke of a pen, will disappear from the Law until everything is accomplished.'),
('MAT', 5, 19, 'MAT.5.19', 'So then, whoever breaks one of the least of these commandments and teaches others to do likewise will be called least in the kingdom of heaven; but whoever practices and teaches them will be called great in the kingdom of heaven.'),
('MAT', 5, 20, 'MAT.5.20', 'For I tell you that unless your righteousness exceeds that of the scribes and Pharisees, you will never enter the kingdom of heaven.'),
('MAT', 5, 21, 'MAT.5.21', 'You have heard that it was said to the ancients, ‘Do not murder’ and ‘Anyone who murders will be subject to judgment.’'),
('MAT', 5, 22, 'MAT.5.22', 'But I tell you that anyone who is angry with his brother will be subject to judgment. Again, anyone who says to his brother, ‘Raca,’ will be subject to the Sanhedrin. But anyone who says, ‘You fool!’ will be subject to the fire of hell.'),
('MAT', 5, 23, 'MAT.5.23', 'So if you are offering your gift at the altar and there remember that your brother has something against you,'),
('MAT', 5, 24, 'MAT.5.24', 'leave your gift there before the altar. First go and be reconciled to your brother; then come and offer your gift.'),
('MAT', 5, 25, 'MAT.5.25', 'Reconcile quickly with your adversary, while you are still on the way to court. Otherwise, he may hand you over to the judge, and the judge may hand you over to the officer, and you may be thrown into prison.'),
('MAT', 5, 26, 'MAT.5.26', 'Truly I tell you, you will not get out until you have paid the last penny.'),
('MAT', 5, 27, 'MAT.5.27', 'You have heard that it was said, ‘Do not commit adultery.’'),
('MAT', 5, 28, 'MAT.5.28', 'But I tell you that anyone who looks at a woman to lust after her has already committed adultery with her in his heart.'),
('MAT', 5, 29, 'MAT.5.29', 'If your right eye causes you to sin, gouge it out and throw it away. It is better for you to lose one part of your body than for your whole body to be thrown into hell.'),
('MAT', 5, 30, 'MAT.5.30', 'And if your right hand causes you to sin, cut it off and throw it away. It is better for you to lose one part of your body than for your whole body to depart into hell.'),
('MAT', 5, 31, 'MAT.5.31', 'It has also been said, ‘Whoever divorces his wife must give her a certificate of divorce.’'),
('MAT', 5, 32, 'MAT.5.32', 'But I tell you that anyone who divorces his wife, except for sexual immorality, brings adultery upon her. And he who marries a divorced woman commits adultery.'),
('MAT', 5, 33, 'MAT.5.33', 'Again, you have heard that it was said to the ancients, ‘Do not break your oath, but fulfill your vows to the Lord.’'),
('MAT', 5, 34, 'MAT.5.34', 'But I tell you not to swear at all: either by heaven, for it is God’s throne;'),
('MAT', 5, 35, 'MAT.5.35', 'or by the earth, for it is His footstool; or by Jerusalem, for it is the city of the great King.'),
('MAT', 5, 36, 'MAT.5.36', 'Nor should you swear by your head, for you cannot make a single hair white or black.'),
('MAT', 5, 37, 'MAT.5.37', 'Simply let your ‘Yes’ be ‘Yes,’ and your ‘No,’ ‘No.’ Anything more comes from the evil one.'),
('MAT', 5, 38, 'MAT.5.38', 'You have heard that it was said, ‘Eye for eye and tooth for tooth.’'),
('MAT', 5, 39, 'MAT.5.39', 'But I tell you not to resist an evil person. If someone slaps you on your right cheek, turn to him the other also;'),
('MAT', 5, 40, 'MAT.5.40', 'if someone wants to sue you and take your tunic, let him have your cloak as well;'),
('MAT', 5, 41, 'MAT.5.41', 'and if someone forces you to go one mile, go with him two miles.'),
('MAT', 5, 42, 'MAT.5.42', 'Give to the one who asks you, and do not turn away from the one who wants to borrow from you.'),
('MAT', 5, 43, 'MAT.5.43', 'You have heard that it was said, ‘Love your neighbor’ and ‘Hate your enemy.’'),
('MAT', 5, 44, 'MAT.5.44', 'But I tell you, love your enemies and pray for those who persecute you,'),
('MAT', 5, 45, 'MAT.5.45', 'that you may be sons of your Father in heaven. He causes His sun to rise on the evil and the good, and sends rain on the righteous and the unrighteous.'),
('MAT', 5, 46, 'MAT.5.46', 'If you love those who love you, what reward will you get? Do not even tax collectors do the same?'),
('MAT', 5, 47, 'MAT.5.47', 'And if you greet only your brothers, what are you doing more than others? Do not even Gentiles do the same?'),
('MAT', 5, 48, 'MAT.5.48', 'Be perfect, therefore, as your heavenly Father is perfect.'),
('MAT', 6, 1, 'MAT.6.1', '“Be careful not to perform your righteous acts before men to be seen by them. If you do, you will have no reward from your Father in heaven.'),
('MAT', 6, 2, 'MAT.6.2', 'So when you give to the needy, do not sound a trumpet before you, as the hypocrites do in the synagogues and on the streets, to be honored by men. Truly I tell you, they already have their full reward.'),
('MAT', 6, 3, 'MAT.6.3', 'But when you give to the needy, do not let your left hand know what your right hand is doing,'),
('MAT', 6, 4, 'MAT.6.4', 'so that your giving may be in secret. And your Father, who sees what is done in secret, will reward you.'),
('MAT', 6, 5, 'MAT.6.5', 'And when you pray, do not be like the hypocrites. For they love to pray standing in the synagogues and on the street corners to be seen by men. Truly I tell you, they already have their full reward.'),
('MAT', 6, 6, 'MAT.6.6', 'But when you pray, go into your inner room, shut your door, and pray to your Father, who is unseen. And your Father, who sees what is done in secret, will reward you.'),
('MAT', 6, 7, 'MAT.6.7', 'And when you pray, do not babble on like pagans, for they think that by their many words they will be heard.'),
('MAT', 6, 8, 'MAT.6.8', 'Do not be like them, for your Father knows what you need before you ask Him.'),
('MAT', 6, 9, 'MAT.6.9', 'So then, this is how you should pray: ‘Our Father in heaven, hallowed be Your name.'),
('MAT', 6, 10, 'MAT.6.10', 'Your kingdom come, Your will be done, on earth as it is in heaven.'),
('MAT', 6, 11, 'MAT.6.11', 'Give us this day our daily bread.'),
('MAT', 6, 12, 'MAT.6.12', 'And forgive us our debts, as we also have forgiven our debtors.'),
('MAT', 6, 13, 'MAT.6.13', 'And lead us not into temptation, but deliver us from the evil one.’'),
('MAT', 6, 14, 'MAT.6.14', 'For if you forgive men their trespasses, your heavenly Father will also forgive you.'),
('MAT', 6, 15, 'MAT.6.15', 'But if you do not forgive men their trespasses, neither will your Father forgive yours.'),
('MAT', 6, 16, 'MAT.6.16', 'When you fast, do not be somber like the hypocrites, for they disfigure their faces to show men they are fasting. Truly I tell you, they already have their full reward.'),
('MAT', 6, 17, 'MAT.6.17', 'But when you fast, anoint your head and wash your face,'),
('MAT', 6, 18, 'MAT.6.18', 'so that your fasting will not be obvious to men, but only to your Father, who is unseen. And your Father, who sees what is done in secret, will reward you.'),
('MAT', 6, 19, 'MAT.6.19', 'Do not store up for yourselves treasures on earth, where moth and rust destroy, and where thieves break in and steal.'),
('MAT', 6, 20, 'MAT.6.20', 'But store up for yourselves treasures in heaven, where moth and rust do not destroy, and where thieves do not break in and steal.'),
('MAT', 6, 21, 'MAT.6.21', 'For where your treasure is, there your heart will be also.'),
('MAT', 6, 22, 'MAT.6.22', 'The eye is the lamp of the body. If your eyes are good, your whole body will be full of light.'),
('MAT', 6, 23, 'MAT.6.23', 'But if your eyes are bad, your whole body will be full of darkness. If then the light within you is darkness, how great is that darkness!'),
('MAT', 6, 24, 'MAT.6.24', 'No one can serve two masters: Either he will hate the one and love the other, or he will be devoted to the one and despise the other. You cannot serve both God and money.'),
('MAT', 6, 25, 'MAT.6.25', 'Therefore I tell you, do not worry about your life, what you will eat or drink; or about your body, what you will wear. Is not life more than food, and the body more than clothes?'),
('MAT', 6, 26, 'MAT.6.26', 'Look at the birds of the air: They do not sow or reap or gather into barns, and yet your heavenly Father feeds them. Are you not much more valuable than they?'),
('MAT', 6, 27, 'MAT.6.27', 'Who of you by worrying can add a single hour to his life?'),
('MAT', 6, 28, 'MAT.6.28', 'And why do you worry about clothes? Consider how the lilies of the field grow: They do not labor or spin.'),
('MAT', 6, 29, 'MAT.6.29', 'Yet I tell you that not even Solomon in all his glory was adorned like one of these.'),
('MAT', 6, 30, 'MAT.6.30', 'If that is how God clothes the grass of the field, which is here today and tomorrow is thrown into the furnace, will He not much more clothe you, O you of little faith?'),
('MAT', 6, 31, 'MAT.6.31', 'Therefore do not worry, saying, ‘What shall we eat?’ or ‘What shall we drink?’ or ‘What shall we wear?’'),
('MAT', 6, 32, 'MAT.6.32', 'For the Gentiles strive after all these things, and your heavenly Father knows that you need them.'),
('MAT', 6, 33, 'MAT.6.33', 'But seek first the kingdom of God and His righteousness, and all these things will be added unto you.'),
('MAT', 6, 34, 'MAT.6.34', 'Therefore do not worry about tomorrow, for tomorrow will worry about itself. Today has enough trouble of its own.'),
('MAT', 7, 1, 'MAT.7.1', '“Do not judge, or you will be judged.'),
('MAT', 7, 2, 'MAT.7.2', 'For with the same judgment you pronounce, you will be judged, and with the measure you use, it will be measured to you.'),
('MAT', 7, 3, 'MAT.7.3', 'Why do you look at the speck in your brother’s eye but fail to notice the beam in your own eye?'),
('MAT', 7, 4, 'MAT.7.4', 'How can you say to your brother, ‘Let me take the speck out of your eye,’ while there is still a beam in your own eye?'),
('MAT', 7, 5, 'MAT.7.5', 'You hypocrite! First take the beam out of your own eye, and then you will see clearly to remove the speck from your brother’s eye.'),
('MAT', 7, 6, 'MAT.7.6', 'Do not give dogs what is holy; do not throw your pearls before swine. If you do, they may trample them under their feet, and then turn and tear you to pieces.'),
('MAT', 7, 7, 'MAT.7.7', 'Ask, and it will be given to you; seek, and you will find; knock, and the door will be opened to you.'),
('MAT', 7, 8, 'MAT.7.8', 'For everyone who asks receives; he who seeks finds; and to him who knocks, the door will be opened.'),
('MAT', 7, 9, 'MAT.7.9', 'Which of you, if his son asks for bread, will give him a stone?'),
('MAT', 7, 10, 'MAT.7.10', 'Or if he asks for a fish, will give him a snake?'),
('MAT', 7, 11, 'MAT.7.11', 'So if you who are evil know how to give good gifts to your children, how much more will your Father in heaven give good things to those who ask Him!'),
('MAT', 7, 12, 'MAT.7.12', 'In everything, then, do to others as you would have them do to you. For this is the essence of the Law and the Prophets.'),
('MAT', 7, 13, 'MAT.7.13', 'Enter through the narrow gate. For wide is the gate and broad is the way that leads to destruction, and many enter through it.'),
('MAT', 7, 14, 'MAT.7.14', 'But small is the gate and narrow the way that leads to life, and only a few find it.'),
('MAT', 7, 15, 'MAT.7.15', 'Beware of false prophets. They come to you in sheep’s clothing, but inwardly they are ravenous wolves.'),
('MAT', 7, 16, 'MAT.7.16', 'By their fruit you will recognize them. Are grapes gathered from thornbushes, or figs from thistles?'),
('MAT', 7, 17, 'MAT.7.17', 'Likewise, every good tree bears good fruit, but a bad tree bears bad fruit.'),
('MAT', 7, 18, 'MAT.7.18', 'A good tree cannot bear bad fruit, and a bad tree cannot bear good fruit.'),
('MAT', 7, 19, 'MAT.7.19', 'Every tree that does not bear good fruit is cut down and thrown into the fire.'),
('MAT', 7, 20, 'MAT.7.20', 'So then, by their fruit you will recognize them.'),
('MAT', 7, 21, 'MAT.7.21', 'Not everyone who says to Me, ‘Lord, Lord,’ will enter the kingdom of heaven, but only he who does the will of My Father in heaven.'),
('MAT', 7, 22, 'MAT.7.22', 'Many will say to Me on that day, ‘Lord, Lord, did we not prophesy in Your name, and in Your name drive out demons and perform many miracles?’'),
('MAT', 7, 23, 'MAT.7.23', 'Then I will tell them plainly, ‘I never knew you; depart from Me, you workers of lawlessness!’'),
('MAT', 7, 24, 'MAT.7.24', 'Therefore everyone who hears these words of Mine and acts on them is like a wise man who built his house on the rock.'),
('MAT', 7, 25, 'MAT.7.25', 'The rain fell, the torrents raged, and the winds blew and beat against that house; yet it did not fall, because its foundation was on the rock.'),
('MAT', 7, 26, 'MAT.7.26', 'But everyone who hears these words of Mine and does not act on them is like a foolish man who built his house on sand.'),
('MAT', 7, 27, 'MAT.7.27', 'The rain fell, the torrents raged, and the winds blew and beat against that house, and it fell—and great was its collapse!”'),
('MAT', 7, 28, 'MAT.7.28', 'When Jesus had finished saying these things, the crowds were astonished at His teaching,'),
('MAT', 7, 29, 'MAT.7.29', 'because He taught as one who had authority, and not as their scribes.'),
('MAT', 8, 1, 'MAT.8.1', 'When Jesus came down from the mountain, large crowds followed Him.'),
('MAT', 8, 2, 'MAT.8.2', 'Suddenly a leper came and knelt before Him, saying, “Lord, if You are willing, You can make me clean.”'),
('MAT', 8, 3, 'MAT.8.3', 'Jesus reached out His hand and touched the man. “I am willing,” He said. “Be clean!” And immediately his leprosy was cleansed.'),
('MAT', 8, 4, 'MAT.8.4', 'Then Jesus instructed him, “See that you don’t tell anyone. But go, show yourself to the priest and offer the gift prescribed by Moses, as a testimony to them.”'),
('MAT', 8, 5, 'MAT.8.5', 'When Jesus had entered Capernaum, a centurion came and pleaded with Him,'),
('MAT', 8, 6, 'MAT.8.6', '“Lord, my servant lies at home, paralyzed and in terrible agony.”'),
('MAT', 8, 7, 'MAT.8.7', '“I will go and heal him,” Jesus replied.'),
('MAT', 8, 8, 'MAT.8.8', 'The centurion answered, “Lord, I am not worthy to have You come under my roof. But just say the word, and my servant will be healed.'),
('MAT', 8, 9, 'MAT.8.9', 'For I myself am a man under authority, with soldiers under me. I tell one to go, and he goes, and another to come, and he comes. I tell my servant to do something, and he does it.”'),
('MAT', 8, 10, 'MAT.8.10', 'When Jesus heard this, He marveled and said to those following Him, “Truly I tell you, I have not found anyone in Israel with such great faith.'),
('MAT', 8, 11, 'MAT.8.11', 'I say to you that many will come from the east and the west to share the banquet with Abraham, Isaac, and Jacob in the kingdom of heaven.'),
('MAT', 8, 12, 'MAT.8.12', 'But the sons of the kingdom will be thrown into the outer darkness, where there will be weeping and gnashing of teeth.”'),
('MAT', 8, 13, 'MAT.8.13', 'Then Jesus said to the centurion, “Go! As you have believed, so will it be done for you.” And his servant was healed at that very hour.'),
('MAT', 8, 14, 'MAT.8.14', 'When Jesus arrived at Peter’s house, He saw Peter’s mother-in-law sick in bed with a fever.'),
('MAT', 8, 15, 'MAT.8.15', 'So He touched her hand, and the fever left her, and she got up and began to serve Him.'),
('MAT', 8, 16, 'MAT.8.16', 'When evening came, many who were demon-possessed were brought to Jesus, and He drove out the spirits with a word and healed all the sick.'),
('MAT', 8, 17, 'MAT.8.17', 'This was to fulfill what was spoken through the prophet Isaiah: “He took up our infirmities and carried our diseases.”'),
('MAT', 8, 18, 'MAT.8.18', 'When Jesus saw a large crowd around Him, He gave orders to cross to the other side of the sea.'),
('MAT', 8, 19, 'MAT.8.19', 'And one of the scribes came to Him and said, “Teacher, I will follow You wherever You go.”'),
('MAT', 8, 20, 'MAT.8.20', 'Jesus replied, “Foxes have dens and birds of the air have nests, but the Son of Man has no place to lay His head.”'),
('MAT', 8, 21, 'MAT.8.21', 'Another of His disciples requested, “Lord, first let me go and bury my father.”'),
('MAT', 8, 22, 'MAT.8.22', 'But Jesus told him, “Follow Me, and let the dead bury their own dead.”'),
('MAT', 8, 23, 'MAT.8.23', 'When He got into the boat, His disciples followed Him.'),
('MAT', 8, 24, 'MAT.8.24', 'Suddenly a violent storm came up on the sea, so that the boat was engulfed by the waves. But Jesus was sleeping.'),
('MAT', 8, 25, 'MAT.8.25', 'The disciples went and woke Him, saying, “Lord, save us! We are perishing!”'),
('MAT', 8, 26, 'MAT.8.26', '“You of little faith,” Jesus replied, “why are you so afraid?” Then He got up and rebuked the winds and the sea, and it was perfectly calm.'),
('MAT', 8, 27, 'MAT.8.27', 'The men were amazed and asked, “What kind of man is this? Even the winds and the sea obey Him!”'),
('MAT', 8, 28, 'MAT.8.28', 'When Jesus arrived on the other side in the region of the Gadarenes, He was met by two demon-possessed men coming from the tombs. They were so violent that no one could pass that way.'),
('MAT', 8, 29, 'MAT.8.29', '“What do You want with us, Son of God?” they shouted. “Have You come here to torture us before the appointed time?”'),
('MAT', 8, 30, 'MAT.8.30', 'In the distance a large herd of pigs was feeding.'),
('MAT', 8, 31, 'MAT.8.31', 'So the demons begged Jesus, “If You drive us out, send us into the herd of pigs.”'),
('MAT', 8, 32, 'MAT.8.32', '“Go!” He told them. So they came out and went into the pigs, and the whole herd rushed down the steep bank into the sea and died in the waters.'),
('MAT', 8, 33, 'MAT.8.33', 'Those tending the pigs ran off into the town and reported all this, including the account of the demon-possessed men.'),
('MAT', 8, 34, 'MAT.8.34', 'Then the whole town went out to meet Jesus. And when they saw Him, they begged Him to leave their region.'),
('MAT', 9, 1, 'MAT.9.1', 'Jesus got into a boat, crossed over, and came to His own town.'),
('MAT', 9, 2, 'MAT.9.2', 'Just then some men brought to Him a paralytic lying on a mat. When Jesus saw their faith, He said to the paralytic, “Take courage, son; your sins are forgiven.”'),
('MAT', 9, 3, 'MAT.9.3', 'On seeing this, some of the scribes said to themselves, “This man is blaspheming!”'),
('MAT', 9, 4, 'MAT.9.4', 'But Jesus knew what they were thinking and said, “Why do you harbor evil in your hearts?'),
('MAT', 9, 5, 'MAT.9.5', 'Which is easier: to say, ‘Your sins are forgiven,’ or to say, ‘Get up and walk’?'),
('MAT', 9, 6, 'MAT.9.6', 'But so that you may know that the Son of Man has authority on earth to forgive sins...” Then He said to the paralytic, “Get up, pick up your mat, and go home.”'),
('MAT', 9, 7, 'MAT.9.7', 'And the man got up and went home.'),
('MAT', 9, 8, 'MAT.9.8', 'When the crowds saw this, they were filled with awe and glorified God, who had given such authority to men.'),
('MAT', 9, 9, 'MAT.9.9', 'As Jesus went on from there, He saw a man named Matthew sitting at the tax booth. “Follow Me,” He told him, and Matthew got up and followed Him.'),
('MAT', 9, 10, 'MAT.9.10', 'Later, as Jesus was dining at Matthew’s house, many tax collectors and sinners came and ate with Him and His disciples.'),
('MAT', 9, 11, 'MAT.9.11', 'When the Pharisees saw this, they asked His disciples, “Why does your Teacher eat with tax collectors and sinners?”'),
('MAT', 9, 12, 'MAT.9.12', 'On hearing this, Jesus said, “It is not the healthy who need a doctor, but the sick.'),
('MAT', 9, 13, 'MAT.9.13', 'But go and learn what this means: ‘I desire mercy, not sacrifice.’ For I have not come to call the righteous, but sinners.”'),
('MAT', 9, 14, 'MAT.9.14', 'Then John’s disciples came to Jesus and asked, “Why is it that we and the Pharisees fast so often, but Your disciples do not fast?”'),
('MAT', 9, 15, 'MAT.9.15', 'Jesus replied, “How can the guests of the bridegroom mourn while He is with them? But the time will come when the bridegroom will be taken from them; then they will fast.'),
('MAT', 9, 16, 'MAT.9.16', 'No one sews a patch of unshrunk cloth on an old garment. For the patch will pull away from the garment, and a worse tear will result.'),
('MAT', 9, 17, 'MAT.9.17', 'Neither do men pour new wine into old wineskins. If they do, the skins will burst, the wine will spill, and the wineskins will be ruined. Instead, they pour new wine into new wineskins, and both are preserved.”'),
('MAT', 9, 18, 'MAT.9.18', 'While Jesus was saying these things, a synagogue leader came and knelt before Him. “My daughter has just died,” he said. “But come and place Your hand on her, and she will live.”'),
('MAT', 9, 19, 'MAT.9.19', 'So Jesus got up and went with him, along with His disciples.'),
('MAT', 9, 20, 'MAT.9.20', 'Suddenly a woman who had suffered from bleeding for twelve years came up behind Him and touched the fringe of His cloak.'),
('MAT', 9, 21, 'MAT.9.21', 'She said to herself, “If only I touch His cloak, I will be healed.”'),
('MAT', 9, 22, 'MAT.9.22', 'Jesus turned and saw her. “Take courage, daughter,” He said, “your faith has healed you.” And the woman was healed from that very hour.'),
('MAT', 9, 23, 'MAT.9.23', 'When Jesus entered the house of the synagogue leader, He saw the flute players and the noisy crowd.'),
('MAT', 9, 24, 'MAT.9.24', '“Go away,” He told them. “The girl is not dead, but asleep.” And they laughed at Him.'),
('MAT', 9, 25, 'MAT.9.25', 'After the crowd had been put outside, Jesus went in and took the girl by the hand, and she got up.'),
('MAT', 9, 26, 'MAT.9.26', 'And the news about this spread throughout that region.'),
('MAT', 9, 27, 'MAT.9.27', 'As Jesus went on from there, two blind men followed Him, crying out, “Have mercy on us, Son of David!”'),
('MAT', 9, 28, 'MAT.9.28', 'After Jesus had entered the house, the blind men came to Him. “Do you believe that I am able to do this?” He asked. “Yes, Lord,” they answered.'),
('MAT', 9, 29, 'MAT.9.29', 'Then He touched their eyes and said, “According to your faith will it be done to you.”'),
('MAT', 9, 30, 'MAT.9.30', 'And their eyes were opened. Jesus warned them sternly, “See that no one finds out about this!”'),
('MAT', 9, 31, 'MAT.9.31', 'But they went out and spread the news about Him throughout the land.'),
('MAT', 9, 32, 'MAT.9.32', 'As they were leaving, a demon-possessed man who was mute was brought to Jesus.'),
('MAT', 9, 33, 'MAT.9.33', 'And when the demon had been driven out, the man began to speak. The crowds were amazed and said, “Nothing like this has ever been seen in Israel!”'),
('MAT', 9, 34, 'MAT.9.34', 'But the Pharisees said, “It is by the prince of demons that He drives out demons.”'),
('MAT', 9, 35, 'MAT.9.35', 'Jesus went through all the towns and villages, teaching in their synagogues, preaching the gospel of the kingdom, and healing every disease and sickness.'),
('MAT', 9, 36, 'MAT.9.36', 'When He saw the crowds, He was moved with compassion for them, because they were harassed and helpless, like sheep without a shepherd.'),
('MAT', 9, 37, 'MAT.9.37', 'Then He said to His disciples, “The harvest is plentiful, but the workers are few.'),
('MAT', 9, 38, 'MAT.9.38', 'Ask the Lord of the harvest, therefore, to send out workers into His harvest.”'),
('MAT', 10, 1, 'MAT.10.1', 'And calling His twelve disciples to Him, Jesus gave them authority over unclean spirits, so that they could drive them out and heal every disease and sickness.'),
('MAT', 10, 2, 'MAT.10.2', 'These are the names of the twelve apostles: first Simon, called Peter, and his brother Andrew; James son of Zebedee, and his brother John;'),
('MAT', 10, 3, 'MAT.10.3', 'Philip and Bartholomew; Thomas and Matthew the tax collector; James son of Alphaeus, and Thaddaeus;'),
('MAT', 10, 4, 'MAT.10.4', 'Simon the Zealot, and Judas Iscariot, who betrayed Jesus.'),
('MAT', 10, 5, 'MAT.10.5', 'These twelve Jesus sent out with the following instructions: “Do not go onto the road of the Gentiles or enter any town of the Samaritans.'),
('MAT', 10, 6, 'MAT.10.6', 'Go rather to the lost sheep of Israel.'),
('MAT', 10, 7, 'MAT.10.7', 'As you go, preach this message: ‘The kingdom of heaven is near.’'),
('MAT', 10, 8, 'MAT.10.8', 'Heal the sick, raise the dead, cleanse the lepers, drive out demons. Freely you have received; freely give.'),
('MAT', 10, 9, 'MAT.10.9', 'Do not take along any gold or silver or copper in your belts.'),
('MAT', 10, 10, 'MAT.10.10', 'Take no bag for the road, or second tunic, or sandals, or staff; for the worker is worthy of his provisions.'),
('MAT', 10, 11, 'MAT.10.11', 'Whatever town or village you enter, find out who is worthy there and stay at his house until you move on.'),
('MAT', 10, 12, 'MAT.10.12', 'As you enter the home, greet its occupants.'),
('MAT', 10, 13, 'MAT.10.13', 'If the home is worthy, let your peace rest on it, but if it is not, let your peace return to you.'),
('MAT', 10, 14, 'MAT.10.14', 'And if anyone will not welcome you or heed your words, shake the dust off your feet when you leave that home or town.'),
('MAT', 10, 15, 'MAT.10.15', 'Truly I tell you, it will be more bearable for Sodom and Gomorrah on the day of judgment than for that town.'),
('MAT', 10, 16, 'MAT.10.16', 'Behold, I am sending you out like sheep among wolves; therefore be as shrewd as snakes and as innocent as doves.'),
('MAT', 10, 17, 'MAT.10.17', 'But beware of men, for they will hand you over to their councils and flog you in their synagogues.'),
('MAT', 10, 18, 'MAT.10.18', 'On My account you will be brought before governors and kings as witnesses to them and to the Gentiles.'),
('MAT', 10, 19, 'MAT.10.19', 'But when they hand you over, do not worry about how to respond or what to say. In that hour you will be given what to say.'),
('MAT', 10, 20, 'MAT.10.20', 'For it will not be you speaking, but the Spirit of your Father speaking through you.'),
('MAT', 10, 21, 'MAT.10.21', 'Brother will betray brother to death, and a father his child; children will rise against their parents and have them put to death.'),
('MAT', 10, 22, 'MAT.10.22', 'You will be hated by everyone because of My name, but the one who perseveres to the end will be saved.'),
('MAT', 10, 23, 'MAT.10.23', 'When they persecute you in one town, flee to the next. Truly I tell you, you will not reach all the towns of Israel before the Son of Man comes.'),
('MAT', 10, 24, 'MAT.10.24', 'A disciple is not above his teacher, nor a servant above his master.'),
('MAT', 10, 25, 'MAT.10.25', 'It is enough for a disciple to be like his teacher, and a servant like his master. If the head of the house has been called Beelzebul, how much more the members of his household!'),
('MAT', 10, 26, 'MAT.10.26', 'So do not be afraid of them. For there is nothing concealed that will not be disclosed, and nothing hidden that will not be made known.'),
('MAT', 10, 27, 'MAT.10.27', 'What I tell you in the dark, speak in the daylight; what is whispered in your ear, proclaim from the housetops.'),
('MAT', 10, 28, 'MAT.10.28', 'Do not be afraid of those who kill the body but cannot kill the soul. Instead, fear the One who can destroy both soul and body in hell.'),
('MAT', 10, 29, 'MAT.10.29', 'Are not two sparrows sold for a penny? Yet not one of them will fall to the ground apart from the will of your Father.'),
('MAT', 10, 30, 'MAT.10.30', 'And even the very hairs of your head are all numbered.'),
('MAT', 10, 31, 'MAT.10.31', 'So do not be afraid; you are worth more than many sparrows.'),
('MAT', 10, 32, 'MAT.10.32', 'Therefore everyone who confesses Me before men, I will also confess him before My Father in heaven.'),
('MAT', 10, 33, 'MAT.10.33', 'But whoever denies Me before men, I will also deny him before My Father in heaven.'),
('MAT', 10, 34, 'MAT.10.34', 'Do not assume that I have come to bring peace to the earth; I have not come to bring peace, but a sword.'),
('MAT', 10, 35, 'MAT.10.35', 'For I have come to turn ‘a man against his father, a daughter against her mother, a daughter-in-law against her mother-in-law.'),
('MAT', 10, 36, 'MAT.10.36', 'A man’s enemies will be the members of his own household.’'),
('MAT', 10, 37, 'MAT.10.37', 'Anyone who loves his father or mother more than Me is not worthy of Me; anyone who loves his son or daughter more than Me is not worthy of Me;'),
('MAT', 10, 38, 'MAT.10.38', 'and anyone who does not take up his cross and follow Me is not worthy of Me.'),
('MAT', 10, 39, 'MAT.10.39', 'Whoever finds his life will lose it, and whoever loses his life for My sake will find it.'),
('MAT', 10, 40, 'MAT.10.40', 'He who receives you receives Me, and he who receives Me receives the One who sent Me.'),
('MAT', 10, 41, 'MAT.10.41', 'Whoever receives a prophet because he is a prophet will receive a prophet’s reward, and whoever receives a righteous man because he is a righteous man will receive a righteous man’s reward.'),
('MAT', 10, 42, 'MAT.10.42', 'And if anyone gives even a cup of cold water to one of these little ones because he is My disciple, truly I tell you, he will never lose his reward.”'),
('MAT', 11, 1, 'MAT.11.1', 'After Jesus had finished instructing His twelve disciples, He went on from there to teach and preach in their cities.'),
('MAT', 11, 2, 'MAT.11.2', 'Meanwhile John heard in prison about the works of Christ, and he sent his disciples'),
('MAT', 11, 3, 'MAT.11.3', 'to ask Him, “Are You the One who was to come, or should we look for someone else?”'),
('MAT', 11, 4, 'MAT.11.4', 'Jesus replied, “Go back and report to John what you hear and see:'),
('MAT', 11, 5, 'MAT.11.5', 'The blind receive sight, the lame walk, the lepers are cleansed, the deaf hear, the dead are raised, and the good news is preached to the poor.'),
('MAT', 11, 6, 'MAT.11.6', 'Blessed is the one who does not fall away on account of Me.”'),
('MAT', 11, 7, 'MAT.11.7', 'As John’s disciples were leaving, Jesus began to speak to the crowds about John: “What did you go out into the wilderness to see? A reed swaying in the wind?'),
('MAT', 11, 8, 'MAT.11.8', 'Otherwise, what did you go out to see? A man dressed in fine clothes? Look, those who wear fine clothing are found in kings’ palaces.'),
('MAT', 11, 9, 'MAT.11.9', 'What then did you go out to see? A prophet? Yes, I tell you, and more than a prophet.'),
('MAT', 11, 10, 'MAT.11.10', 'This is the one about whom it is written: ‘Behold, I will send My messenger ahead of You, who will prepare Your way before You.’'),
('MAT', 11, 11, 'MAT.11.11', 'Truly I tell you, among those born of women there has risen no one greater than John the Baptist. Yet even the least in the kingdom of heaven is greater than he.'),
('MAT', 11, 12, 'MAT.11.12', 'From the days of John the Baptist until now, the kingdom of heaven has been subject to violence, and the violent lay claim to it.'),
('MAT', 11, 13, 'MAT.11.13', 'For all the Prophets and the Law prophesied until John.'),
('MAT', 11, 14, 'MAT.11.14', 'And if you are willing to accept it, he is the Elijah who was to come.'),
('MAT', 11, 15, 'MAT.11.15', 'He who has ears, let him hear.'),
('MAT', 11, 16, 'MAT.11.16', 'To what can I compare this generation? They are like children sitting in the marketplaces and calling out to others:'),
('MAT', 11, 17, 'MAT.11.17', '‘We played the flute for you, and you did not dance; we sang a dirge, and you did not mourn.’'),
('MAT', 11, 18, 'MAT.11.18', 'For John came neither eating nor drinking, and they say, ‘He has a demon!’'),
('MAT', 11, 19, 'MAT.11.19', 'The Son of Man came eating and drinking, and they say, ‘Look at this glutton and drunkard, a friend of tax collectors and sinners!’ But wisdom is vindicated by her actions.”'),
('MAT', 11, 20, 'MAT.11.20', 'Then Jesus began to denounce the cities in which most of His miracles had been performed, because they did not repent.'),
('MAT', 11, 21, 'MAT.11.21', '“Woe to you, Chorazin! Woe to you, Bethsaida! For if the miracles that were performed in you had been performed in Tyre and Sidon, they would have repented long ago in sackcloth and ashes.'),
('MAT', 11, 22, 'MAT.11.22', 'But I tell you, it will be more bearable for Tyre and Sidon on the day of judgment than for you.'),
('MAT', 11, 23, 'MAT.11.23', 'And you, Capernaum, will you be lifted up to heaven? No, you will be brought down to Hades! For if the miracles that were performed in you had been performed in Sodom, it would have remained to this day.'),
('MAT', 11, 24, 'MAT.11.24', 'But I tell you that it will be more bearable for Sodom on the day of judgment than for you.”'),
('MAT', 11, 25, 'MAT.11.25', 'At that time Jesus declared, “I praise You, Father, Lord of heaven and earth, because You have hidden these things from the wise and learned, and revealed them to little children.'),
('MAT', 11, 26, 'MAT.11.26', 'Yes, Father, for this was well-pleasing in Your sight.'),
('MAT', 11, 27, 'MAT.11.27', 'All things have been entrusted to Me by My Father. No one knows the Son except the Father, and no one knows the Father except the Son and those to whom the Son chooses to reveal Him.'),
('MAT', 11, 28, 'MAT.11.28', 'Come to Me, all you who are weary and burdened, and I will give you rest.'),
('MAT', 11, 29, 'MAT.11.29', 'Take My yoke upon you and learn from Me, for I am gentle and humble in heart, and you will find rest for your souls.'),
('MAT', 11, 30, 'MAT.11.30', 'For My yoke is easy and My burden is light.”'),
('MAT', 12, 1, 'MAT.12.1', 'At that time Jesus went through the grainfields on the Sabbath. His disciples were hungry and began to pick the heads of grain and eat them.'),
('MAT', 12, 2, 'MAT.12.2', 'When the Pharisees saw this, they said to Him, “Look, Your disciples are doing what is unlawful on the Sabbath.”'),
('MAT', 12, 3, 'MAT.12.3', 'Jesus replied, “Have you not read what David did when he and his companions were hungry?'),
('MAT', 12, 4, 'MAT.12.4', 'He entered the house of God, and he and his companions ate the consecrated bread, which was not lawful for them to eat, but only for the priests.'),
('MAT', 12, 5, 'MAT.12.5', 'Or haven’t you read in the Law that on the Sabbath the priests in the temple break the Sabbath and yet are innocent?'),
('MAT', 12, 6, 'MAT.12.6', 'But I tell you that One greater than the temple is here.'),
('MAT', 12, 7, 'MAT.12.7', 'If only you had known the meaning of ‘I desire mercy, not sacrifice,’ you would not have condemned the innocent.'),
('MAT', 12, 8, 'MAT.12.8', 'For the Son of Man is Lord of the Sabbath.”'),
('MAT', 12, 9, 'MAT.12.9', 'Moving on from there, Jesus entered their synagogue,'),
('MAT', 12, 10, 'MAT.12.10', 'and a man with a withered hand was there. In order to accuse Jesus, they asked Him, “Is it lawful to heal on the Sabbath?”'),
('MAT', 12, 11, 'MAT.12.11', 'He replied, “If one of you has a sheep and it falls into a pit on the Sabbath, will he not take hold of it and lift it out?'),
('MAT', 12, 12, 'MAT.12.12', 'How much more valuable is a man than a sheep! Therefore it is lawful to do good on the Sabbath.”'),
('MAT', 12, 13, 'MAT.12.13', 'Then Jesus said to the man, “Stretch out your hand.” So he stretched it out, and it was restored to full use, just like the other.'),
('MAT', 12, 14, 'MAT.12.14', 'But the Pharisees went out and plotted how they might kill Jesus.'),
('MAT', 12, 15, 'MAT.12.15', 'Aware of this, Jesus withdrew from that place. Large crowds followed Him, and He healed them all,'),
('MAT', 12, 16, 'MAT.12.16', 'warning them not to make Him known.'),
('MAT', 12, 17, 'MAT.12.17', 'This was to fulfill what was spoken through the prophet Isaiah:'),
('MAT', 12, 18, 'MAT.12.18', '“Here is My Servant, whom I have chosen, My beloved, in whom My soul delights. I will put My Spirit on Him, and He will proclaim justice to the nations.'),
('MAT', 12, 19, 'MAT.12.19', 'He will not quarrel or cry out; no one will hear His voice in the streets.'),
('MAT', 12, 20, 'MAT.12.20', 'A bruised reed He will not break, and a smoldering wick He will not extinguish, till He leads justice to victory.'),
('MAT', 12, 21, 'MAT.12.21', 'In His name the nations will put their hope.”'),
('MAT', 12, 22, 'MAT.12.22', 'Then a demon-possessed man who was blind and mute was brought to Jesus, and He healed the man so that he could speak and see.'),
('MAT', 12, 23, 'MAT.12.23', 'The crowds were astounded and asked, “Could this be the Son of David?”'),
('MAT', 12, 24, 'MAT.12.24', 'But when the Pharisees heard this, they said, “Only by Beelzebul, the prince of demons, does this man drive out demons.”'),
('MAT', 12, 25, 'MAT.12.25', 'Knowing their thoughts, Jesus said to them, “Every kingdom divided against itself will be laid waste, and every city or household divided against itself will not stand.'),
('MAT', 12, 26, 'MAT.12.26', 'If Satan drives out Satan, he is divided against himself. How then can his kingdom stand?'),
('MAT', 12, 27, 'MAT.12.27', 'And if I drive out demons by Beelzebul, by whom do your sons drive them out? So then, they will be your judges.'),
('MAT', 12, 28, 'MAT.12.28', 'But if I drive out demons by the Spirit of God, then the kingdom of God has come upon you.'),
('MAT', 12, 29, 'MAT.12.29', 'Or again, how can anyone enter a strong man’s house and steal his possessions, unless he first ties up the strong man? Then he can plunder his house.'),
('MAT', 12, 30, 'MAT.12.30', 'He who is not with Me is against Me, and he who does not gather with Me scatters.'),
('MAT', 12, 31, 'MAT.12.31', 'Therefore I tell you, every sin and blasphemy will be forgiven men, but the blasphemy against the Spirit will not be forgiven.'),
('MAT', 12, 32, 'MAT.12.32', 'Whoever speaks a word against the Son of Man will be forgiven, but whoever speaks against the Holy Spirit will not be forgiven, either in this age or in the one to come.'),
('MAT', 12, 33, 'MAT.12.33', 'Make a tree good and its fruit will be good, or make a tree bad and its fruit will be bad, for a tree is known by its fruit.'),
('MAT', 12, 34, 'MAT.12.34', 'You brood of vipers, how can you who are evil say anything good? For out of the overflow of the heart the mouth speaks.'),
('MAT', 12, 35, 'MAT.12.35', 'The good man brings good things out of his good store of treasure, and the evil man brings evil things out of his evil store of treasure.'),
('MAT', 12, 36, 'MAT.12.36', 'But I tell you that men will give an account on the day of judgment for every careless word they have spoken.'),
('MAT', 12, 37, 'MAT.12.37', 'For by your words you will be acquitted, and by your words you will be condemned.”'),
('MAT', 12, 38, 'MAT.12.38', 'Then some of the scribes and Pharisees said to Him, “Teacher, we want to see a sign from You.”'),
('MAT', 12, 39, 'MAT.12.39', 'Jesus replied, “A wicked and adulterous generation demands a sign, but none will be given it except the sign of the prophet Jonah.'),
('MAT', 12, 40, 'MAT.12.40', 'For as Jonah was three days and three nights in the belly of the great fish, so the Son of Man will be three days and three nights in the heart of the earth.'),
('MAT', 12, 41, 'MAT.12.41', 'The men of Nineveh will stand at the judgment with this generation and condemn it; for they repented at the preaching of Jonah, and now One greater than Jonah is here.'),
('MAT', 12, 42, 'MAT.12.42', 'The Queen of the South will rise at the judgment with this generation and condemn it; for she came from the ends of the earth to hear the wisdom of Solomon, and now One greater than Solomon is here.'),
('MAT', 12, 43, 'MAT.12.43', 'When an unclean spirit comes out of a man, it passes through arid places seeking rest and does not find it.'),
('MAT', 12, 44, 'MAT.12.44', 'Then it says, ‘I will return to the house I left.’ On its return, it finds the house vacant, swept clean, and put in order.'),
('MAT', 12, 45, 'MAT.12.45', 'Then it goes and brings with it seven other spirits more wicked than itself, and they go in and dwell there. And the final plight of that man is worse than the first. So will it be with this wicked generation.”'),
('MAT', 12, 46, 'MAT.12.46', 'While Jesus was still speaking to the crowds, His mother and brothers stood outside, wanting to speak to Him.'),
('MAT', 12, 47, 'MAT.12.47', 'Someone told Him, “Look, Your mother and brothers are standing outside, wanting to speak to You.”'),
('MAT', 12, 48, 'MAT.12.48', 'But Jesus replied, “Who is My mother, and who are My brothers?”'),
('MAT', 12, 49, 'MAT.12.49', 'Pointing to His disciples, He said, “Here are My mother and My brothers.'),
('MAT', 12, 50, 'MAT.12.50', 'For whoever does the will of My Father in heaven is My brother and sister and mother.”'),
('MAT', 13, 1, 'MAT.13.1', 'That same day Jesus went out of the house and sat by the sea.'),
('MAT', 13, 2, 'MAT.13.2', 'Such large crowds gathered around Him that He got into a boat and sat down, while all the people stood on the shore.'),
('MAT', 13, 3, 'MAT.13.3', 'And He told them many things in parables, saying, “A farmer went out to sow his seed.'),
('MAT', 13, 4, 'MAT.13.4', 'And as he was sowing, some seed fell along the path, and the birds came and devoured it.'),
('MAT', 13, 5, 'MAT.13.5', 'Some fell on rocky ground, where it did not have much soil. It sprang up quickly because the soil was shallow.'),
('MAT', 13, 6, 'MAT.13.6', 'But when the sun rose, the seedlings were scorched, and they withered because they had no root.'),
('MAT', 13, 7, 'MAT.13.7', 'Other seed fell among thorns, which grew up and choked the seedlings.'),
('MAT', 13, 8, 'MAT.13.8', 'Still other seed fell on good soil and produced a crop—a hundredfold, sixtyfold, or thirtyfold.'),
('MAT', 13, 9, 'MAT.13.9', 'He who has ears, let him hear.”'),
('MAT', 13, 10, 'MAT.13.10', 'Then the disciples came to Jesus and asked, “Why do You speak to the people in parables?”'),
('MAT', 13, 11, 'MAT.13.11', 'He replied, “The knowledge of the mysteries of the kingdom of heaven has been given to you, but not to them.'),
('MAT', 13, 12, 'MAT.13.12', 'Whoever has will be given more, and he will have an abundance. Whoever does not have, even what he has will be taken away from him.'),
('MAT', 13, 13, 'MAT.13.13', 'This is why I speak to them in parables: ‘Though seeing, they do not see; though hearing, they do not hear or understand.’'),
('MAT', 13, 14, 'MAT.13.14', 'In them the prophecy of Isaiah is fulfilled: ‘You will be ever hearing but never understanding; you will be ever seeing but never perceiving.'),
('MAT', 13, 15, 'MAT.13.15', 'For this people’s heart has grown callous; they hardly hear with their ears, and they have closed their eyes. Otherwise they might see with their eyes, hear with their ears, understand with their hearts, and turn, and I would heal them.’'),
('MAT', 13, 16, 'MAT.13.16', 'But blessed are your eyes because they see, and your ears because they hear.'),
('MAT', 13, 17, 'MAT.13.17', 'For truly I tell you, many prophets and righteous men longed to see what you see but did not see it, and to hear what you hear but did not hear it.'),
('MAT', 13, 18, 'MAT.13.18', 'Consider, then, the parable of the sower:'),
('MAT', 13, 19, 'MAT.13.19', 'When anyone hears the message of the kingdom but does not understand it, the evil one comes and snatches away what was sown in his heart. This is the seed sown along the path.'),
('MAT', 13, 20, 'MAT.13.20', 'The seed sown on rocky ground is the one who hears the word and at once receives it with joy.'),
('MAT', 13, 21, 'MAT.13.21', 'But since he has no root, he remains for only a season. When trouble or persecution comes because of the word, he quickly falls away.'),
('MAT', 13, 22, 'MAT.13.22', 'The seed sown among the thorns is the one who hears the word, but the worries of this life and the deceitfulness of wealth choke the word, and it becomes unfruitful.'),
('MAT', 13, 23, 'MAT.13.23', 'But the seed sown on good soil is the one who hears the word and understands it. He indeed bears fruit and produces a crop—a hundredfold, sixtyfold, or thirtyfold.”'),
('MAT', 13, 24, 'MAT.13.24', 'Jesus put before them another parable: “The kingdom of heaven is like a man who sowed good seed in his field.'),
('MAT', 13, 25, 'MAT.13.25', 'But while everyone was asleep, his enemy came and sowed weeds among the wheat, and slipped away.'),
('MAT', 13, 26, 'MAT.13.26', 'When the wheat sprouted and bore grain, then the weeds also appeared.'),
('MAT', 13, 27, 'MAT.13.27', 'The owner’s servants came to him and said, ‘Sir, didn’t you sow good seed in your field? Where then did the weeds come from?’'),
('MAT', 13, 28, 'MAT.13.28', '‘An enemy did this,’ he replied. So the servants asked him, ‘Do you want us to go and pull them up?’'),
('MAT', 13, 29, 'MAT.13.29', '‘No,’ he said, ‘if you pull the weeds now, you might uproot the wheat with them.'),
('MAT', 13, 30, 'MAT.13.30', 'Let both grow together until the harvest. At that time I will tell the harvesters: First collect the weeds and tie them in bundles to be burned; then gather the wheat into my barn.’”'),
('MAT', 13, 31, 'MAT.13.31', 'He put before them another parable: “The kingdom of heaven is like a mustard seed that a man took and planted in his field.'),
('MAT', 13, 32, 'MAT.13.32', 'Although it is the smallest of all seeds, yet it grows into the largest of garden plants and becomes a tree, so that the birds of the air come and nest in its branches.”'),
('MAT', 13, 33, 'MAT.13.33', 'He told them still another parable: “The kingdom of heaven is like leaven that a woman took and mixed into three measures of flour, until all of it was leavened.”'),
('MAT', 13, 34, 'MAT.13.34', 'Jesus spoke all these things to the crowds in parables. He did not tell them anything without using a parable.'),
('MAT', 13, 35, 'MAT.13.35', 'So was fulfilled what was spoken through the prophet: “I will open My mouth in parables; I will utter things hidden since the foundation of the world.”'),
('MAT', 13, 36, 'MAT.13.36', 'Then Jesus dismissed the crowds and went into the house. His disciples came to Him and said, “Explain to us the parable of the weeds in the field.”'),
('MAT', 13, 37, 'MAT.13.37', 'He replied, “The One who sows the good seed is the Son of Man.'),
('MAT', 13, 38, 'MAT.13.38', 'The field is the world, and the good seed represents the sons of the kingdom. The weeds are the sons of the evil one,'),
('MAT', 13, 39, 'MAT.13.39', 'and the enemy who sows them is the devil. The harvest is the end of the age, and the harvesters are angels.'),
('MAT', 13, 40, 'MAT.13.40', 'As the weeds are collected and burned in the fire, so will it be at the end of the age.'),
('MAT', 13, 41, 'MAT.13.41', 'The Son of Man will send out His angels, and they will weed out of His kingdom every cause of sin and all who practice lawlessness.'),
('MAT', 13, 42, 'MAT.13.42', 'And they will throw them into the fiery furnace, where there will be weeping and gnashing of teeth.'),
('MAT', 13, 43, 'MAT.13.43', 'Then the righteous will shine like the sun in the kingdom of their Father. He who has ears, let him hear.'),
('MAT', 13, 44, 'MAT.13.44', 'The kingdom of heaven is like treasure hidden in a field. When a man found it, he hid it again, and in his joy he went and sold all he had and bought that field.'),
('MAT', 13, 45, 'MAT.13.45', 'Again, the kingdom of heaven is like a merchant in search of fine pearls.'),
('MAT', 13, 46, 'MAT.13.46', 'When he found one very precious pearl, he went away and sold all he had and bought it.'),
('MAT', 13, 47, 'MAT.13.47', 'Once again, the kingdom of heaven is like a net that was cast into the sea and caught all kinds of fish.'),
('MAT', 13, 48, 'MAT.13.48', 'When it was full, the men pulled it ashore. Then they sat down and sorted the good fish into containers, but threw the bad away.'),
('MAT', 13, 49, 'MAT.13.49', 'So will it be at the end of the age: The angels will come and separate the wicked from the righteous'),
('MAT', 13, 50, 'MAT.13.50', 'and throw them into the fiery furnace, where there will be weeping and gnashing of teeth.'),
('MAT', 13, 51, 'MAT.13.51', 'Have you understood all these things?” “Yes,” they answered.'),
('MAT', 13, 52, 'MAT.13.52', 'Then He told them, “For this reason, every scribe who has been discipled in the kingdom of heaven is like a homeowner who brings out of his storeroom new treasures as well as old.”'),
('MAT', 13, 53, 'MAT.13.53', 'When Jesus had finished these parables, He withdrew from that place.'),
('MAT', 13, 54, 'MAT.13.54', 'Coming to His hometown, He taught the people in their synagogue, and they were astonished. “Where did this man get such wisdom and miraculous powers?” they asked.'),
('MAT', 13, 55, 'MAT.13.55', '“Isn’t this the carpenter’s son? Isn’t His mother’s name Mary, and aren’t His brothers James, Joseph, Simon, and Judas?'),
('MAT', 13, 56, 'MAT.13.56', 'Aren’t all His sisters with us as well? Where then did this man get all these things?”'),
('MAT', 13, 57, 'MAT.13.57', 'And they took offense at Him. But Jesus said to them, “Only in his hometown and in his own household is a prophet without honor.”'),
('MAT', 13, 58, 'MAT.13.58', 'And He did not do many miracles there, because of their unbelief.'),
('MAT', 14, 1, 'MAT.14.1', 'At that time Herod the tetrarch heard the reports about Jesus'),
('MAT', 14, 2, 'MAT.14.2', 'and said to his servants, “This is John the Baptist; he has risen from the dead! That is why miraculous powers are at work in him.”'),
('MAT', 14, 3, 'MAT.14.3', 'Now Herod had arrested John and bound him and put him in prison on account of Herodias, his brother Philip’s wife,'),
('MAT', 14, 4, 'MAT.14.4', 'because John had been telling him, “It is not lawful for you to have her.”'),
('MAT', 14, 5, 'MAT.14.5', 'Although Herod wanted to kill John, he was afraid of the people, because they regarded John as a prophet.'),
('MAT', 14, 6, 'MAT.14.6', 'On Herod’s birthday, however, the daughter of Herodias danced before them and pleased Herod'),
('MAT', 14, 7, 'MAT.14.7', 'so much that he promised with an oath to give to her whatever she asked.'),
('MAT', 14, 8, 'MAT.14.8', 'Prompted by her mother, she said, “Give me here on a platter the head of John the Baptist.”'),
('MAT', 14, 9, 'MAT.14.9', 'The king was grieved, but because of his oaths and his guests, he ordered that her wish be granted'),
('MAT', 14, 10, 'MAT.14.10', 'and sent to have John beheaded in the prison.'),
('MAT', 14, 11, 'MAT.14.11', 'John’s head was brought in on a platter and presented to the girl, who carried it to her mother.'),
('MAT', 14, 12, 'MAT.14.12', 'Then John’s disciples came and took his body and buried it. And they went and informed Jesus.'),
('MAT', 14, 13, 'MAT.14.13', 'When Jesus heard about John, He withdrew by boat privately to a solitary place. But the crowds found out about it and followed Him on foot from the towns.'),
('MAT', 14, 14, 'MAT.14.14', 'When He stepped ashore and saw a large crowd, He had compassion on them and healed their sick.'),
('MAT', 14, 15, 'MAT.14.15', 'When evening came, the disciples came to Him and said, “This is a desolate place, and the hour is already late. Dismiss the crowds so they can go to the villages and buy themselves some food.”'),
('MAT', 14, 16, 'MAT.14.16', '“They do not need to go away,” Jesus replied. “You give them something to eat.”'),
('MAT', 14, 17, 'MAT.14.17', '“We have here only five loaves of bread and two fish,” they answered.'),
('MAT', 14, 18, 'MAT.14.18', '“Bring them here to Me,” Jesus said.'),
('MAT', 14, 19, 'MAT.14.19', 'And He directed the crowds to sit down on the grass. Taking the five loaves and the two fish and looking up to heaven, He spoke a blessing. Then He broke the loaves and gave them to the disciples, and the disciples gave them to the people.'),
('MAT', 14, 20, 'MAT.14.20', 'They all ate and were satisfied, and the disciples picked up twelve basketfuls of broken pieces that were left over.'),
('MAT', 14, 21, 'MAT.14.21', 'About five thousand men were fed, besides women and children.'),
('MAT', 14, 22, 'MAT.14.22', 'Immediately Jesus made the disciples get into the boat and go on ahead of Him to the other side, while He dismissed the crowds.'),
('MAT', 14, 23, 'MAT.14.23', 'After He had dismissed them, He went up on the mountain by Himself to pray. When evening came, He was there alone,'),
('MAT', 14, 24, 'MAT.14.24', 'but the boat was already far from land, buffeted by the waves because the wind was against it.'),
('MAT', 14, 25, 'MAT.14.25', 'During the fourth watch of the night, Jesus went out to them, walking on the sea.'),
('MAT', 14, 26, 'MAT.14.26', 'When the disciples saw Him walking on the sea, they were terrified. “It’s a ghost!” they said, and cried out in fear.'),
('MAT', 14, 27, 'MAT.14.27', 'But Jesus spoke up at once: “Take courage! It is I. Do not be afraid.”'),
('MAT', 14, 28, 'MAT.14.28', '“Lord, if it is You,” Peter replied, “command me to come to You on the water.”'),
('MAT', 14, 29, 'MAT.14.29', '“Come,” said Jesus. Then Peter got down out of the boat, walked on the water, and came toward Jesus.'),
('MAT', 14, 30, 'MAT.14.30', 'But when he saw the strength of the wind, he was afraid and, beginning to sink, cried out, “Lord, save me!”'),
('MAT', 14, 31, 'MAT.14.31', 'Immediately Jesus reached out His hand and took hold of Peter. “You of little faith,” He said, “why did you doubt?”'),
('MAT', 14, 32, 'MAT.14.32', 'And when they had climbed back into the boat, the wind died down.'),
('MAT', 14, 33, 'MAT.14.33', 'Then those who were in the boat worshiped Him, saying, “Truly You are the Son of God!”'),
('MAT', 14, 34, 'MAT.14.34', 'When they had crossed over, they landed at Gennesaret.'),
('MAT', 14, 35, 'MAT.14.35', 'And when the men of that place recognized Jesus, they sent word to all the surrounding region. People brought all the sick to Him'),
('MAT', 14, 36, 'MAT.14.36', 'and begged Him just to let them touch the fringe of His cloak. And all who touched Him were healed.'),
('MAT', 15, 1, 'MAT.15.1', 'Then some Pharisees and scribes came to Jesus from Jerusalem and asked,'),
('MAT', 15, 2, 'MAT.15.2', '“Why do Your disciples break the tradition of the elders? They do not wash their hands before they eat.”'),
('MAT', 15, 3, 'MAT.15.3', 'Jesus replied, “And why do you break the command of God for the sake of your tradition?'),
('MAT', 15, 4, 'MAT.15.4', 'For God said, ‘Honor your father and mother’ and ‘Anyone who curses his father or mother must be put to death.’'),
('MAT', 15, 5, 'MAT.15.5', 'But you say that if anyone says to his father or mother, ‘Whatever you would have received from me is a gift devoted to God,’'),
('MAT', 15, 6, 'MAT.15.6', 'he need not honor his father or mother with it. Thus you nullify the word of God for the sake of your tradition.'),
('MAT', 15, 7, 'MAT.15.7', 'You hypocrites! Isaiah prophesied correctly about you:'),
('MAT', 15, 8, 'MAT.15.8', '‘These people honor Me with their lips, but their hearts are far from Me.'),
('MAT', 15, 9, 'MAT.15.9', 'They worship Me in vain; they teach as doctrine the precepts of men.’”'),
('MAT', 15, 10, 'MAT.15.10', 'Jesus called the crowd to Him and said, “Listen and understand.'),
('MAT', 15, 11, 'MAT.15.11', 'A man is not defiled by what enters his mouth, but by what comes out of it.”'),
('MAT', 15, 12, 'MAT.15.12', 'Then the disciples came to Him and said, “Are You aware that the Pharisees were offended when they heard this?”'),
('MAT', 15, 13, 'MAT.15.13', 'But Jesus replied, “Every plant that My heavenly Father has not planted will be pulled up by its roots.'),
('MAT', 15, 14, 'MAT.15.14', 'Disregard them! They are blind guides. If a blind man leads a blind man, both will fall into a pit.”'),
('MAT', 15, 15, 'MAT.15.15', 'Peter said to Him, “Explain this parable to us.”'),
('MAT', 15, 16, 'MAT.15.16', '“Do you still not understand?” Jesus asked.'),
('MAT', 15, 17, 'MAT.15.17', '“Do you not yet realize that whatever enters the mouth goes into the stomach and then is eliminated?'),
('MAT', 15, 18, 'MAT.15.18', 'But the things that come out of the mouth come from the heart, and these things defile a man.'),
('MAT', 15, 19, 'MAT.15.19', 'For out of the heart come evil thoughts, murder, adultery, sexual immorality, theft, false testimony, and slander.'),
('MAT', 15, 20, 'MAT.15.20', 'These are what defile a man, but eating with unwashed hands does not defile him.”'),
('MAT', 15, 21, 'MAT.15.21', 'Leaving that place, Jesus withdrew to the district of Tyre and Sidon.'),
('MAT', 15, 22, 'MAT.15.22', 'And a Canaanite woman from that region came to Him, crying out, “Lord, Son of David, have mercy on me! My daughter is miserably possessed by a demon.”'),
('MAT', 15, 23, 'MAT.15.23', 'But Jesus did not answer a word. So His disciples came and urged Him, “Send her away, for she keeps crying out after us.”'),
('MAT', 15, 24, 'MAT.15.24', 'He answered, “I was sent only to the lost sheep of the house of Israel.”'),
('MAT', 15, 25, 'MAT.15.25', 'The woman came and knelt before Him. “Lord, help me!” she said.'),
('MAT', 15, 26, 'MAT.15.26', 'But Jesus replied, “It is not right to take the children’s bread and toss it to the dogs.”'),
('MAT', 15, 27, 'MAT.15.27', '“Yes, Lord,” she said, “even the dogs eat the crumbs that fall from their master’s table.”'),
('MAT', 15, 28, 'MAT.15.28', '“O woman,” Jesus answered, “your faith is great! Let it be done for you as you desire.” And her daughter was healed from that very hour.'),
('MAT', 15, 29, 'MAT.15.29', 'Moving on from there, Jesus went along the Sea of Galilee. Then He went up on a mountain and sat down.'),
('MAT', 15, 30, 'MAT.15.30', 'Large crowds came to Him, bringing the lame, the blind, the crippled, the mute, and many others, and laid them at His feet, and He healed them.'),
('MAT', 15, 31, 'MAT.15.31', 'The crowd was amazed when they saw the mute speaking, the crippled restored, the lame walking, and the blind seeing. And they glorified the God of Israel.'),
('MAT', 15, 32, 'MAT.15.32', 'Then Jesus called His disciples to Him and said, “I have compassion for this crowd, because they have already been with Me three days and have nothing to eat. I do not want to send them away hungry, or they may faint along the way.”'),
('MAT', 15, 33, 'MAT.15.33', 'The disciples replied, “Where in this desolate place could we find enough bread to feed such a large crowd?”'),
('MAT', 15, 34, 'MAT.15.34', '“How many loaves do you have?” Jesus asked. “Seven,” they replied, “and a few small fish.”'),
('MAT', 15, 35, 'MAT.15.35', 'And He instructed the crowd to sit down on the ground.'),
('MAT', 15, 36, 'MAT.15.36', 'Taking the seven loaves and the fish, He gave thanks and broke them. Then He gave them to the disciples, and the disciples gave them to the people.'),
('MAT', 15, 37, 'MAT.15.37', 'They all ate and were satisfied, and the disciples picked up seven basketfuls of broken pieces that were left over.'),
('MAT', 15, 38, 'MAT.15.38', 'A total of four thousand men were fed, besides women and children.'),
('MAT', 15, 39, 'MAT.15.39', 'After Jesus had dismissed the crowds, He got into the boat and went to the region of Magadan.'),
('MAT', 16, 1, 'MAT.16.1', 'Then the Pharisees and Sadducees came and tested Jesus by asking Him to show them a sign from heaven.'),
('MAT', 16, 2, 'MAT.16.2', 'But He replied, “When evening comes, you say, ‘The weather will be fair, for the sky is red,’'),
('MAT', 16, 3, 'MAT.16.3', 'and in the morning, ‘Today it will be stormy, for the sky is red and overcast.’ You know how to interpret the appearance of the sky, but not the signs of the times.'),
('MAT', 16, 4, 'MAT.16.4', 'A wicked and adulterous generation demands a sign, but none will be given it except the sign of Jonah.” Then He left them and went away.'),
('MAT', 16, 5, 'MAT.16.5', 'When they crossed to the other side, the disciples forgot to take bread.'),
('MAT', 16, 6, 'MAT.16.6', '“Watch out!” Jesus told them. “Beware of the leaven of the Pharisees and Sadducees.”'),
('MAT', 16, 7, 'MAT.16.7', 'They discussed this among themselves and concluded, “It is because we did not bring any bread.”'),
('MAT', 16, 8, 'MAT.16.8', 'Aware of their conversation, Jesus said, “You of little faith, why are you debating among yourselves about having no bread?'),
('MAT', 16, 9, 'MAT.16.9', 'Do you still not understand? Do you not remember the five loaves for the five thousand, and how many basketfuls you gathered?'),
('MAT', 16, 10, 'MAT.16.10', 'Or the seven loaves for the four thousand, and how many basketfuls you gathered?'),
('MAT', 16, 11, 'MAT.16.11', 'How do you not understand that I was not telling you about bread? But beware of the leaven of the Pharisees and Sadducees.”'),
('MAT', 16, 12, 'MAT.16.12', 'Then they understood that He was not telling them to beware of the leaven used in bread, but of the teaching of the Pharisees and Sadducees.'),
('MAT', 16, 13, 'MAT.16.13', 'When Jesus came to the region of Caesarea Philippi, He questioned His disciples: “Who do people say the Son of Man is?”'),
('MAT', 16, 14, 'MAT.16.14', 'They replied, “Some say John the Baptist; others say Elijah; and still others, Jeremiah or one of the prophets.”'),
('MAT', 16, 15, 'MAT.16.15', '“But what about you?” Jesus asked. “Who do you say I am?”'),
('MAT', 16, 16, 'MAT.16.16', 'Simon Peter answered, “You are the Christ, the Son of the living God.”'),
('MAT', 16, 17, 'MAT.16.17', 'Jesus replied, “Blessed are you, Simon son of Jonah! For this was not revealed to you by flesh and blood, but by My Father in heaven.'),
('MAT', 16, 18, 'MAT.16.18', 'And I tell you that you are Peter, and on this rock I will build My church, and the gates of Hades will not prevail against it.'),
('MAT', 16, 19, 'MAT.16.19', 'I will give you the keys of the kingdom of heaven. Whatever you bind on earth will be bound in heaven, and whatever you loose on earth will be loosed in heaven.”'),
('MAT', 16, 20, 'MAT.16.20', 'Then He admonished the disciples not to tell anyone that He was the Christ.'),
('MAT', 16, 21, 'MAT.16.21', 'From that time on Jesus began to show His disciples that He must go to Jerusalem and suffer many things at the hands of the elders, chief priests, and scribes, and that He must be killed and on the third day be raised to life.'),
('MAT', 16, 22, 'MAT.16.22', 'Peter took Him aside and began to rebuke Him. “Far be it from You, Lord!” he said. “This shall never happen to You!”'),
('MAT', 16, 23, 'MAT.16.23', 'But Jesus turned and said to Peter, “Get behind Me, Satan! You are a stumbling block to Me. For you do not have in mind the things of God, but the things of men.”'),
('MAT', 16, 24, 'MAT.16.24', 'Then Jesus told His disciples, “If anyone wants to come after Me, he must deny himself and take up his cross and follow Me.'),
('MAT', 16, 25, 'MAT.16.25', 'For whoever wants to save his life will lose it, but whoever loses his life for My sake will find it.'),
('MAT', 16, 26, 'MAT.16.26', 'What will it profit a man if he gains the whole world, yet forfeits his soul? Or what can a man give in exchange for his soul?'),
('MAT', 16, 27, 'MAT.16.27', 'For the Son of Man will come in His Father’s glory with His angels, and then He will repay each one according to what he has done.'),
('MAT', 16, 28, 'MAT.16.28', 'Truly I tell you, some who are standing here will not taste death before they see the Son of Man coming in His kingdom.”'),
('MAT', 17, 1, 'MAT.17.1', 'After six days Jesus took with Him Peter, James, and John the brother of James, and led them up a high mountain by themselves.'),
('MAT', 17, 2, 'MAT.17.2', 'There He was transfigured before them. His face shone like the sun, and His clothes became as white as the light.'),
('MAT', 17, 3, 'MAT.17.3', 'Suddenly Moses and Elijah appeared before them, talking with Jesus.'),
('MAT', 17, 4, 'MAT.17.4', 'Peter said to Jesus, “Lord, it is good for us to be here. If You wish, I will put up three shelters—one for You, one for Moses, and one for Elijah.”'),
('MAT', 17, 5, 'MAT.17.5', 'While Peter was still speaking, a bright cloud enveloped them, and a voice from the cloud said, “This is My beloved Son, in whom I am well pleased. Listen to Him!”'),
('MAT', 17, 6, 'MAT.17.6', 'When the disciples heard this, they fell facedown in terror.'),
('MAT', 17, 7, 'MAT.17.7', 'Then Jesus came over and touched them. “Get up,” He said. “Do not be afraid.”'),
('MAT', 17, 8, 'MAT.17.8', 'And when they looked up, they saw no one except Jesus.'),
('MAT', 17, 9, 'MAT.17.9', 'As they were coming down the mountain, Jesus commanded them, “Do not tell anyone about this vision until the Son of Man has been raised from the dead.”'),
('MAT', 17, 10, 'MAT.17.10', 'The disciples asked Him, “Why then do the scribes say that Elijah must come first?”'),
('MAT', 17, 11, 'MAT.17.11', 'Jesus replied, “Elijah does indeed come, and he will restore all things.'),
('MAT', 17, 12, 'MAT.17.12', 'But I tell you that Elijah has already come, and they did not recognize him, but have done to him whatever they wished. In the same way, the Son of Man will suffer at their hands.”'),
('MAT', 17, 13, 'MAT.17.13', 'Then the disciples understood that He was speaking to them about John the Baptist.'),
('MAT', 17, 14, 'MAT.17.14', 'When they came to the crowd, a man came up to Jesus and knelt before Him.'),
('MAT', 17, 15, 'MAT.17.15', '“Lord, have mercy on my son,” he said. “He has seizures and is suffering terribly. He often falls into the fire or into the water.'),
('MAT', 17, 16, 'MAT.17.16', 'I brought him to Your disciples, but they could not heal him.”'),
('MAT', 17, 17, 'MAT.17.17', '“O unbelieving and perverse generation!” Jesus replied. “How long must I remain with you? How long must I put up with you? Bring the boy here to Me.”'),
('MAT', 17, 18, 'MAT.17.18', 'Then Jesus rebuked the demon, and it came out of the boy, and he was healed from that moment.'),
('MAT', 17, 19, 'MAT.17.19', 'Afterward the disciples came to Jesus privately and asked, “Why couldn’t we drive it out?”'),
('MAT', 17, 20, 'MAT.17.20', '“Because you have so little faith,” He answered. “For truly I tell you, if you have faith the size of a mustard seed, you can say to this mountain, ‘Move from here to there,’ and it will move. Nothing will be impossible for you.”'),
('MAT', 17, 22, 'MAT.17.22', 'When they gathered together in Galilee, Jesus told them, “The Son of Man is about to be delivered into the hands of men.'),
('MAT', 17, 23, 'MAT.17.23', 'They will kill Him, and on the third day He will be raised to life.” And the disciples were deeply grieved.'),
('MAT', 17, 24, 'MAT.17.24', 'After they had arrived in Capernaum, the collectors of the two-drachma tax came to Peter and asked, “Does your Teacher pay the two drachmas?”'),
('MAT', 17, 25, 'MAT.17.25', '“Yes,” he answered. When Peter entered the house, Jesus preempted him. “What do you think, Simon?” He asked. “From whom do the kings of the earth collect customs and taxes: from their own sons, or from others?”'),
('MAT', 17, 26, 'MAT.17.26', '“From others,” Peter answered. “Then the sons are exempt,” Jesus said to him.'),
('MAT', 17, 27, 'MAT.17.27', '“But so that we may not offend them, go to the sea, cast a hook, and take the first fish you catch. When you open its mouth, you will find a four-drachma coin. Take it and give it to them for My tax and yours.”'),
('MAT', 18, 1, 'MAT.18.1', 'At that time the disciples came to Jesus and asked, “Who then is the greatest in the kingdom of heaven?”'),
('MAT', 18, 2, 'MAT.18.2', 'Jesus invited a little child to stand among them.'),
('MAT', 18, 3, 'MAT.18.3', '“Truly I tell you,” He said, “unless you change and become like little children, you will never enter the kingdom of heaven.'),
('MAT', 18, 4, 'MAT.18.4', 'Therefore, whoever humbles himself like this little child is the greatest in the kingdom of heaven.'),
('MAT', 18, 5, 'MAT.18.5', 'And whoever welcomes a little child like this in My name welcomes Me.'),
('MAT', 18, 6, 'MAT.18.6', 'But if anyone causes one of these little ones who believe in Me to stumble, it would be better for him to have a large millstone hung around his neck and to be drowned in the depths of the sea.'),
('MAT', 18, 7, 'MAT.18.7', 'Woe to the world for the causes of sin. These stumbling blocks must come, but woe to the man through whom they come!'),
('MAT', 18, 8, 'MAT.18.8', 'If your hand or your foot causes you to sin, cut it off and throw it away. It is better for you to enter life crippled or lame than to have two hands and two feet and be thrown into the eternal fire.'),
('MAT', 18, 9, 'MAT.18.9', 'And if your eye causes you to sin, gouge it out and throw it away. It is better for you to enter life with one eye than to have two eyes and be thrown into the fire of hell.'),
('MAT', 18, 10, 'MAT.18.10', 'See that you do not look down on any of these little ones. For I tell you that their angels in heaven always see the face of My Father in heaven.'),
('MAT', 18, 12, 'MAT.18.12', 'What do you think? If a man has a hundred sheep and one of them goes astray, will he not leave the ninety-nine on the hills and go out to search for the one that is lost?'),
('MAT', 18, 13, 'MAT.18.13', 'And if he finds it, truly I tell you, he rejoices more over that one sheep than over the ninety-nine that did not go astray.'),
('MAT', 18, 14, 'MAT.18.14', 'In the same way, your Father in heaven is not willing that any of these little ones should perish.'),
('MAT', 18, 15, 'MAT.18.15', 'If your brother sins against you, go and confront him privately. If he listens to you, you have won your brother over.'),
('MAT', 18, 16, 'MAT.18.16', 'But if he will not listen, take one or two others along, so that ‘every matter may be established by the testimony of two or three witnesses.’'),
('MAT', 18, 17, 'MAT.18.17', 'If he refuses to listen to them, tell it to the church. And if he refuses to listen even to the church, regard him as you would a pagan or a tax collector.'),
('MAT', 18, 18, 'MAT.18.18', 'Truly I tell you, whatever you bind on earth will be bound in heaven, and whatever you loose on earth will be loosed in heaven.'),
('MAT', 18, 19, 'MAT.18.19', 'Again, I tell you truly that if two of you on the earth agree about anything you ask for, it will be done for you by My Father in heaven.'),
('MAT', 18, 20, 'MAT.18.20', 'For where two or three gather together in My name, there am I with them.”'),
('MAT', 18, 21, 'MAT.18.21', 'Then Peter came to Jesus and asked, “Lord, how many times shall I forgive my brother who sins against me? Up to seven times?”'),
('MAT', 18, 22, 'MAT.18.22', 'Jesus answered, “I tell you, not just seven times, but seventy-seven times!'),
('MAT', 18, 23, 'MAT.18.23', 'Because of this, the kingdom of heaven is like a king who wanted to settle accounts with his servants.'),
('MAT', 18, 24, 'MAT.18.24', 'As he began the settlements, a debtor owing ten thousand talents was brought to him.'),
('MAT', 18, 25, 'MAT.18.25', 'Since the man was unable to pay, the master ordered that he be sold to pay his debt, along with his wife and children and everything he owned.'),
('MAT', 18, 26, 'MAT.18.26', 'Then the servant fell on his knees before him. ‘Have patience with me,’ he begged, ‘and I will pay back everything.’'),
('MAT', 18, 27, 'MAT.18.27', 'His master had compassion on him, forgave his debt, and released him.'),
('MAT', 18, 28, 'MAT.18.28', 'But when that servant went out, he found one of his fellow servants who owed him a hundred denarii. He grabbed him and began to choke him, saying, ‘Pay back what you owe me!’'),
('MAT', 18, 29, 'MAT.18.29', 'So his fellow servant fell down and begged him, ‘Have patience with me, and I will pay you back.’'),
('MAT', 18, 30, 'MAT.18.30', 'But he refused. Instead, he went and had the man thrown into prison until he could pay his debt.'),
('MAT', 18, 31, 'MAT.18.31', 'When his fellow servants saw what had happened, they were greatly distressed, and they went and recounted all of this to their master.'),
('MAT', 18, 32, 'MAT.18.32', 'Then the master summoned him and said, ‘You wicked servant! I forgave all your debt because you begged me.'),
('MAT', 18, 33, 'MAT.18.33', 'Shouldn’t you have had mercy on your fellow servant, just as I had on you?’'),
('MAT', 18, 34, 'MAT.18.34', 'In anger his master turned him over to the jailers to be tortured, until he should repay all that he owed.'),
('MAT', 18, 35, 'MAT.18.35', 'That is how My heavenly Father will treat each of you unless you forgive your brother from your heart.”'),
('MAT', 19, 1, 'MAT.19.1', 'When Jesus had finished saying these things, He left Galilee and went into the region of Judea beyond the Jordan.'),
('MAT', 19, 2, 'MAT.19.2', 'Large crowds followed Him, and He healed them there.'),
('MAT', 19, 3, 'MAT.19.3', 'Then some Pharisees came and tested Him by asking, “Is it lawful for a man to divorce his wife for any reason?”'),
('MAT', 19, 4, 'MAT.19.4', 'Jesus answered, “Have you not read that from the beginning the Creator ‘made them male and female,’'),
('MAT', 19, 5, 'MAT.19.5', 'and said, ‘For this reason a man will leave his father and mother and be united to his wife, and the two will become one flesh’?'),
('MAT', 19, 6, 'MAT.19.6', 'So they are no longer two, but one flesh. Therefore what God has joined together, let man not separate.”'),
('MAT', 19, 7, 'MAT.19.7', '“Why then,” they asked, “did Moses order a man to give his wife a certificate of divorce and send her away?”'),
('MAT', 19, 8, 'MAT.19.8', 'Jesus replied, “Moses permitted you to divorce your wives because of your hardness of heart. But it was not this way from the beginning.'),
('MAT', 19, 9, 'MAT.19.9', 'Now I tell you that whoever divorces his wife, except for sexual immorality, and marries another woman commits adultery.”'),
('MAT', 19, 10, 'MAT.19.10', 'His disciples said to Him, “If this is the case between a man and his wife, it is better not to marry.”'),
('MAT', 19, 11, 'MAT.19.11', '“Not everyone can accept this word,” He replied, “but only those to whom it has been given.'),
('MAT', 19, 12, 'MAT.19.12', 'For there are eunuchs who were born that way; others were made that way by men; and still others live like eunuchs for the sake of the kingdom of heaven. The one who can accept this should accept it.”'),
('MAT', 19, 13, 'MAT.19.13', 'Then little children were brought to Jesus for Him to place His hands on them and pray for them. And the disciples rebuked those who brought them.'),
('MAT', 19, 14, 'MAT.19.14', 'But Jesus said, “Let the little children come to Me, and do not hinder them! For the kingdom of heaven belongs to such as these.”'),
('MAT', 19, 15, 'MAT.19.15', 'And after He had placed His hands on them, He went on from there.'),
('MAT', 19, 16, 'MAT.19.16', 'Just then a man came up to Jesus and inquired, “Teacher, what good thing must I do to obtain eternal life?”'),
('MAT', 19, 17, 'MAT.19.17', '“Why do you ask Me about what is good?” Jesus replied. “There is only One who is good. If you want to enter life, keep the commandments.”'),
('MAT', 19, 18, 'MAT.19.18', '“Which ones?” the man asked. Jesus answered, “‘Do not murder, do not commit adultery, do not steal, do not bear false witness,'),
('MAT', 19, 19, 'MAT.19.19', 'honor your father and mother, and love your neighbor as yourself.’”'),
('MAT', 19, 20, 'MAT.19.20', '“All these I have kept,” said the young man. “What do I still lack?”'),
('MAT', 19, 21, 'MAT.19.21', 'Jesus told him, “If you want to be perfect, go, sell your possessions and give to the poor, and you will have treasure in heaven. Then come, follow Me.”'),
('MAT', 19, 22, 'MAT.19.22', 'When the young man heard this, he went away in sorrow, because he had great wealth.'),
('MAT', 19, 23, 'MAT.19.23', 'Then Jesus said to His disciples, “Truly I tell you, it is hard for a rich man to enter the kingdom of heaven.'),
('MAT', 19, 24, 'MAT.19.24', 'Again I tell you, it is easier for a camel to pass through the eye of a needle than for a rich man to enter the kingdom of God.”'),
('MAT', 19, 25, 'MAT.19.25', 'When the disciples heard this, they were greatly astonished and asked, “Who then can be saved?”'),
('MAT', 19, 26, 'MAT.19.26', 'Jesus looked at them and said, “With man this is impossible, but with God all things are possible.”'),
('MAT', 19, 27, 'MAT.19.27', '“Look,” Peter replied, “we have left everything to follow You. What then will there be for us?”'),
('MAT', 19, 28, 'MAT.19.28', 'Jesus said to them, “Truly I tell you, in the renewal of all things, when the Son of Man sits on His glorious throne, you who have followed Me will also sit on twelve thrones, judging the twelve tribes of Israel.'),
('MAT', 19, 29, 'MAT.19.29', 'And everyone who has left houses or brothers or sisters or father or mother or wife or children or fields for the sake of My name will receive a hundredfold and will inherit eternal life.'),
('MAT', 19, 30, 'MAT.19.30', 'But many who are first will be last, and the last will be first.'),
('MAT', 20, 1, 'MAT.20.1', '“For the kingdom of heaven is like a landowner who went out early in the morning to hire workers for his vineyard.'),
('MAT', 20, 2, 'MAT.20.2', 'He agreed to pay them a denarius for the day and sent them into his vineyard.'),
('MAT', 20, 3, 'MAT.20.3', 'About the third hour he went out and saw others standing in the marketplace doing nothing.'),
('MAT', 20, 4, 'MAT.20.4', '‘You also go into my vineyard,’ he said, ‘and I will pay you whatever is right.’'),
('MAT', 20, 5, 'MAT.20.5', 'So they went. He went out again about the sixth hour and the ninth hour and did the same thing.'),
('MAT', 20, 6, 'MAT.20.6', 'About the eleventh hour he went out and found still others standing around. ‘Why have you been standing here all day long doing nothing?’ he asked.'),
('MAT', 20, 7, 'MAT.20.7', '‘Because no one has hired us,’ they answered. So he told them, ‘You also go into my vineyard.’'),
('MAT', 20, 8, 'MAT.20.8', 'When evening came, the owner of the vineyard said to his foreman, ‘Call the workers and pay them their wages, starting with the last ones hired and moving on to the first.’'),
('MAT', 20, 9, 'MAT.20.9', 'The workers who were hired about the eleventh hour came and each received a denarius.'),
('MAT', 20, 10, 'MAT.20.10', 'So when the original workers came, they assumed they would receive more. But each of them also received a denarius.'),
('MAT', 20, 11, 'MAT.20.11', 'On receiving their pay, they began to grumble against the landowner.'),
('MAT', 20, 12, 'MAT.20.12', '‘These men who were hired last worked only one hour,’ they said, ‘and you have made them equal to us who have borne the burden and the scorching heat of the day.’'),
('MAT', 20, 13, 'MAT.20.13', 'But he answered one of them, ‘Friend, I am not being unfair to you. Did you not agree with me on one denarius?'),
('MAT', 20, 14, 'MAT.20.14', 'Take your pay and go. I want to give this last man the same as I gave you.'),
('MAT', 20, 15, 'MAT.20.15', 'Do I not have the right to do as I please with what is mine? Or are you envious because I am generous?’'),
('MAT', 20, 16, 'MAT.20.16', 'So the last will be first, and the first will be last.”'),
('MAT', 20, 17, 'MAT.20.17', 'As Jesus was going up to Jerusalem, He took the twelve disciples aside and said,'),
('MAT', 20, 18, 'MAT.20.18', '“Look, we are going up to Jerusalem, and the Son of Man will be delivered over to the chief priests and scribes. They will condemn Him to death'),
('MAT', 20, 19, 'MAT.20.19', 'and will deliver Him over to the Gentiles to be mocked and flogged and crucified. And on the third day He will be raised to life.”'),
('MAT', 20, 20, 'MAT.20.20', 'Then the mother of Zebedee’s sons came to Jesus with her sons and knelt down to make a request of Him.'),
('MAT', 20, 21, 'MAT.20.21', '“What do you want?” He inquired. She answered, “Declare that in Your kingdom one of these two sons of mine may sit at Your right hand, and the other at Your left.”'),
('MAT', 20, 22, 'MAT.20.22', '“You do not know what you are asking,” Jesus replied. “Can you drink the cup I am going to drink?” “We can,” the brothers answered.'),
('MAT', 20, 23, 'MAT.20.23', '“You will indeed drink My cup,” Jesus said. “But to sit at My right or left is not Mine to grant. These seats belong to those for whom My Father has prepared them.”'),
('MAT', 20, 24, 'MAT.20.24', 'When the ten heard about this, they were indignant with the two brothers.'),
('MAT', 20, 25, 'MAT.20.25', 'But Jesus called them aside and said, “You know that the rulers of the Gentiles lord it over them, and their superiors exercise authority over them.'),
('MAT', 20, 26, 'MAT.20.26', 'It shall not be this way among you. Instead, whoever wants to become great among you must be your servant,'),
('MAT', 20, 27, 'MAT.20.27', 'and whoever wants to be first among you must be your slave—'),
('MAT', 20, 28, 'MAT.20.28', 'just as the Son of Man did not come to be served, but to serve, and to give His life as a ransom for many.”'),
('MAT', 20, 29, 'MAT.20.29', 'As they were leaving Jericho, a large crowd followed Him.'),
('MAT', 20, 30, 'MAT.20.30', 'And there were two blind men sitting beside the road. When they heard that Jesus was passing by, they cried out, “Lord, Son of David, have mercy on us!”'),
('MAT', 20, 31, 'MAT.20.31', 'The crowd admonished them to be silent, but they cried out all the louder, “Lord, Son of David, have mercy on us!”'),
('MAT', 20, 32, 'MAT.20.32', 'Jesus stopped and called them. “What do you want Me to do for you?” He asked.'),
('MAT', 20, 33, 'MAT.20.33', '“Lord,” they answered, “let our eyes be opened.”'),
('MAT', 20, 34, 'MAT.20.34', 'Moved with compassion, Jesus touched their eyes, and at once they received their sight and followed Him.'),
('MAT', 21, 1, 'MAT.21.1', 'As they approached Jerusalem and came to Bethphage on the Mount of Olives, Jesus sent out two disciples,'),
('MAT', 21, 2, 'MAT.21.2', 'saying to them, “Go into the village ahead of you, and at once you will find a donkey tied there, with her colt beside her. Untie them and bring them to Me.'),
('MAT', 21, 3, 'MAT.21.3', 'If anyone questions you, tell him that the Lord needs them, and he will send them right away.”'),
('MAT', 21, 4, 'MAT.21.4', 'This took place to fulfill what was spoken through the prophet:'),
('MAT', 21, 5, 'MAT.21.5', '“Say to the Daughter of Zion, ‘See, your King comes to you, gentle and riding on a donkey, on a colt, the foal of a donkey.’”'),
('MAT', 21, 6, 'MAT.21.6', 'So the disciples went and did as Jesus had directed them.'),
('MAT', 21, 7, 'MAT.21.7', 'They brought the donkey and the colt and laid their cloaks on them, and Jesus sat on them.'),
('MAT', 21, 8, 'MAT.21.8', 'A massive crowd spread their cloaks on the road, while others cut branches from the trees and spread them on the road.'),
('MAT', 21, 9, 'MAT.21.9', 'The crowds that went ahead of Him and those that followed were shouting: “Hosanna to the Son of David!” “Blessed is He who comes in the name of the Lord!” “Hosanna in the highest!”'),
('MAT', 21, 10, 'MAT.21.10', 'When Jesus had entered Jerusalem, the whole city was stirred and asked, “Who is this?”'),
('MAT', 21, 11, 'MAT.21.11', 'The crowds replied, “This is Jesus, the prophet from Nazareth in Galilee.”'),
('MAT', 21, 12, 'MAT.21.12', 'Then Jesus entered the temple courts and drove out all who were buying and selling there. He overturned the tables of the money changers and the seats of those selling doves.'),
('MAT', 21, 13, 'MAT.21.13', 'And He declared to them, “It is written: ‘My house will be called a house of prayer.’ But you are making it ‘a den of robbers.’”'),
('MAT', 21, 14, 'MAT.21.14', 'The blind and the lame came to Him at the temple, and He healed them.'),
('MAT', 21, 15, 'MAT.21.15', 'But the chief priests and scribes were indignant when they saw the wonders He performed and the children shouting in the temple courts, “Hosanna to the Son of David!”'),
('MAT', 21, 16, 'MAT.21.16', '“Do You hear what these children are saying?” they asked. “Yes,” Jesus answered. “Have you never read: ‘From the mouths of children and infants You have ordained praise’?”'),
('MAT', 21, 17, 'MAT.21.17', 'Then He left them and went out of the city to Bethany, where He spent the night.'),
('MAT', 21, 18, 'MAT.21.18', 'In the morning, as Jesus was returning to the city, He was hungry.'),
('MAT', 21, 19, 'MAT.21.19', 'Seeing a fig tree by the road, He went up to it but found nothing on it except leaves. “May you never bear fruit again!” He said. And immediately the tree withered.'),
('MAT', 21, 20, 'MAT.21.20', 'When the disciples saw this, they marveled and asked, “How did the fig tree wither so quickly?”'),
('MAT', 21, 21, 'MAT.21.21', '“Truly I tell you,” Jesus replied, “if you have faith and do not doubt, not only will you do what was done to the fig tree, but even if you say to this mountain, ‘Be lifted up and thrown into the sea,’ it will happen.'),
('MAT', 21, 22, 'MAT.21.22', 'If you believe, you will receive whatever you ask for in prayer.”'),
('MAT', 21, 23, 'MAT.21.23', 'When Jesus returned to the temple courts and began to teach, the chief priests and elders of the people came up to Him. “By what authority are You doing these things?” they asked. “And who gave You this authority?”'),
('MAT', 21, 24, 'MAT.21.24', '“I will also ask you one question,” Jesus replied, “and if you answer Me, I will tell you by what authority I am doing these things.'),
('MAT', 21, 25, 'MAT.21.25', 'What was the source of John’s baptism? Was it from heaven or from men?” They deliberated among themselves and said, “If we say, ‘From heaven,’ He will ask, ‘Why then did you not believe him?’'),
('MAT', 21, 26, 'MAT.21.26', 'But if we say, ‘From men,’ we are afraid of the people, for they all regard John as a prophet.”'),
('MAT', 21, 27, 'MAT.21.27', 'So they answered, “We do not know.” And Jesus replied, “Neither will I tell you by what authority I am doing these things.'),
('MAT', 21, 28, 'MAT.21.28', 'But what do you think? There was a man who had two sons. He went to the first one and said, ‘Son, go and work today in the vineyard.’'),
('MAT', 21, 29, 'MAT.21.29', '‘I will not,’ he replied. But later he changed his mind and went.'),
('MAT', 21, 30, 'MAT.21.30', 'Then the man went to the second son and told him the same thing. ‘I will, sir,’ he said. But he did not go.'),
('MAT', 21, 31, 'MAT.21.31', 'Which of the two did the will of his father?” “The first,” they answered. Jesus said to them, “Truly I tell you, the tax collectors and prostitutes are entering the kingdom of God before you.'),
('MAT', 21, 32, 'MAT.21.32', 'For John came to you in the way of righteousness, and you did not believe him, but the tax collectors and prostitutes did. And even after you saw this, you did not repent and believe him.'),
('MAT', 21, 33, 'MAT.21.33', 'Listen to another parable: There was a landowner who planted a vineyard. He put a wall around it, dug a winepress in it, and built a tower. Then he rented it out to some tenants and went away on a journey.'),
('MAT', 21, 34, 'MAT.21.34', 'When the harvest time drew near, he sent his servants to the tenants to collect his share of the fruit.'),
('MAT', 21, 35, 'MAT.21.35', 'But the tenants seized his servants. They beat one, killed another, and stoned a third.'),
('MAT', 21, 36, 'MAT.21.36', 'Again, he sent other servants, more than the first group. But the tenants did the same to them.'),
('MAT', 21, 37, 'MAT.21.37', 'Finally, he sent his son to them. ‘They will respect my son,’ he said.'),
('MAT', 21, 38, 'MAT.21.38', 'But when the tenants saw the son, they said to one another, ‘This is the heir. Come, let us kill him and take his inheritance.’'),
('MAT', 21, 39, 'MAT.21.39', 'So they seized him and threw him out of the vineyard and killed him.'),
('MAT', 21, 40, 'MAT.21.40', 'Therefore, when the owner of the vineyard returns, what will he do to those tenants?”'),
('MAT', 21, 41, 'MAT.21.41', '“He will bring those wretches to a wretched end,” they replied, “and will rent out the vineyard to other tenants who will give him his share of the fruit at harvest time.”'),
('MAT', 21, 42, 'MAT.21.42', 'Jesus said to them, “Have you never read in the Scriptures: ‘The stone the builders rejected has become the cornerstone. This is from the Lord, and it is marvelous in our eyes’?'),
('MAT', 21, 43, 'MAT.21.43', 'Therefore I tell you that the kingdom of God will be taken away from you and given to a people who will produce its fruit.'),
('MAT', 21, 44, 'MAT.21.44', 'He who falls on this stone will be broken to pieces, but he on whom it falls will be crushed.”'),
('MAT', 21, 45, 'MAT.21.45', 'When the chief priests and Pharisees heard His parables, they knew that Jesus was speaking about them.'),
('MAT', 21, 46, 'MAT.21.46', 'Although they wanted to arrest Him, they were afraid of the crowds, because the people regarded Him as a prophet.'),
('MAT', 22, 1, 'MAT.22.1', 'Once again, Jesus spoke to them in parables:'),
('MAT', 22, 2, 'MAT.22.2', '“The kingdom of heaven is like a king who prepared a wedding banquet for his son.'),
('MAT', 22, 3, 'MAT.22.3', 'He sent his servants to call those he had invited to the banquet, but they refused to come.'),
('MAT', 22, 4, 'MAT.22.4', 'Again, he sent other servants and said, ‘Tell those who have been invited that I have prepared my dinner. My oxen and fattened cattle have been killed, and everything is ready. Come to the wedding banquet.’'),
('MAT', 22, 5, 'MAT.22.5', 'But they paid no attention and went away, one to his field, another to his business.'),
('MAT', 22, 6, 'MAT.22.6', 'The rest seized his servants, mistreated them, and killed them.'),
('MAT', 22, 7, 'MAT.22.7', 'The king was enraged, and he sent his troops to destroy those murderers and burn their city.'),
('MAT', 22, 8, 'MAT.22.8', 'Then he said to his servants, ‘The wedding banquet is ready, but those I invited were not worthy.'),
('MAT', 22, 9, 'MAT.22.9', 'Go therefore to the crossroads and invite to the banquet as many as you can find.’'),
('MAT', 22, 10, 'MAT.22.10', 'So the servants went out into the streets and gathered everyone they could find, both evil and good, and the wedding hall was filled with guests.'),
('MAT', 22, 11, 'MAT.22.11', 'But when the king came in to see the guests, he spotted a man who was not dressed in wedding clothes.'),
('MAT', 22, 12, 'MAT.22.12', '‘Friend,’ he asked, ‘how did you get in here without wedding clothes?’ But the man was speechless.'),
('MAT', 22, 13, 'MAT.22.13', 'Then the king told the servants, ‘Tie him hand and foot, and throw him into the outer darkness, where there will be weeping and gnashing of teeth.’'),
('MAT', 22, 14, 'MAT.22.14', 'For many are called, but few are chosen.”'),
('MAT', 22, 15, 'MAT.22.15', 'Then the Pharisees went out and conspired to trap Jesus in His words.'),
('MAT', 22, 16, 'MAT.22.16', 'They sent their disciples to Him along with the Herodians. “Teacher,” they said, “we know that You are honest and that You teach the way of God in accordance with the truth. You seek favor from no one, because You pay no attention to external appearance.'),
('MAT', 22, 17, 'MAT.22.17', 'So tell us what You think: Is it lawful to pay taxes to Caesar or not?”'),
('MAT', 22, 18, 'MAT.22.18', 'But Jesus knew their evil intent and said, “You hypocrites, why are you testing Me?'),
('MAT', 22, 19, 'MAT.22.19', 'Show Me the coin used for the tax.” And they brought Him a denarius.'),
('MAT', 22, 20, 'MAT.22.20', '“Whose image is this,” He asked, “and whose inscription?”'),
('MAT', 22, 21, 'MAT.22.21', '“Caesar’s,” they answered. So Jesus told them, “Give to Caesar what is Caesar’s, and to God what is God’s.”'),
('MAT', 22, 22, 'MAT.22.22', 'And when they heard this, they were amazed. So they left Him and went away.'),
('MAT', 22, 23, 'MAT.22.23', 'That same day the Sadducees, who say there is no resurrection, came to Jesus and questioned Him.'),
('MAT', 22, 24, 'MAT.22.24', '“Teacher,” they said, “Moses declared that if a man dies without having children, his brother is to marry the widow and raise up offspring for him.'),
('MAT', 22, 25, 'MAT.22.25', 'Now there were seven brothers among us. The first one married and died without having children. So he left his wife to his brother.'),
('MAT', 22, 26, 'MAT.22.26', 'The same thing happened to the second and third brothers, down to the seventh.'),
('MAT', 22, 27, 'MAT.22.27', 'And last of all, the woman died.'),
('MAT', 22, 28, 'MAT.22.28', 'In the resurrection, then, whose wife will she be of the seven? For all of them were married to her.”'),
('MAT', 22, 29, 'MAT.22.29', 'Jesus answered, “You are mistaken because you do not know the Scriptures or the power of God.'),
('MAT', 22, 30, 'MAT.22.30', 'In the resurrection, people will neither marry nor be given in marriage. Instead, they will be like the angels in heaven.'),
('MAT', 22, 31, 'MAT.22.31', 'But concerning the resurrection of the dead, have you not read what God said to you:'),
('MAT', 22, 32, 'MAT.22.32', '‘I am the God of Abraham, the God of Isaac, and the God of Jacob’? He is not the God of the dead, but of the living.”'),
('MAT', 22, 33, 'MAT.22.33', 'When the crowds heard this, they were astonished at His teaching.'),
('MAT', 22, 34, 'MAT.22.34', 'And when the Pharisees heard that Jesus had silenced the Sadducees, they themselves gathered together.'),
('MAT', 22, 35, 'MAT.22.35', 'One of them, an expert in the law, tested Him with a question:'),
('MAT', 22, 36, 'MAT.22.36', '“Teacher, which commandment is the greatest in the Law?”'),
('MAT', 22, 37, 'MAT.22.37', 'Jesus declared, “‘Love the Lord your God with all your heart and with all your soul and with all your mind.’'),
('MAT', 22, 38, 'MAT.22.38', 'This is the first and greatest commandment.'),
('MAT', 22, 39, 'MAT.22.39', 'And the second is like it: ‘Love your neighbor as yourself.’'),
('MAT', 22, 40, 'MAT.22.40', 'All the Law and the Prophets hang on these two commandments.”'),
('MAT', 22, 41, 'MAT.22.41', 'While the Pharisees were assembled, Jesus questioned them:'),
('MAT', 22, 42, 'MAT.22.42', '“What do you think about the Christ? Whose son is He?” “David’s,” they answered.'),
('MAT', 22, 43, 'MAT.22.43', 'Jesus said to them, “How then does David in the Spirit call Him ‘Lord’? For he says:'),
('MAT', 22, 44, 'MAT.22.44', '‘The Lord said to my Lord, “Sit at My right hand until I put Your enemies under Your feet.”’'),
('MAT', 22, 45, 'MAT.22.45', 'So if David calls Him ‘Lord,’ how can He be David’s son?”'),
('MAT', 22, 46, 'MAT.22.46', 'No one was able to answer a word, and from that day on no one dared to question Him any further.'),
('MAT', 23, 1, 'MAT.23.1', 'Then Jesus spoke to the crowds and to His disciples:'),
('MAT', 23, 2, 'MAT.23.2', '“The scribes and Pharisees sit in Moses’ seat.'),
('MAT', 23, 3, 'MAT.23.3', 'So practice and observe everything they tell you. But do not do what they do, for they do not practice what they preach.'),
('MAT', 23, 4, 'MAT.23.4', 'They tie up heavy, burdensome loads and lay them on men’s shoulders, but they themselves are not willing to lift a finger to move them.'),
('MAT', 23, 5, 'MAT.23.5', 'All their deeds are done for men to see. They broaden their phylacteries and lengthen their tassels.'),
('MAT', 23, 6, 'MAT.23.6', 'They love the places of honor at banquets, the chief seats in the synagogues,'),
('MAT', 23, 7, 'MAT.23.7', 'the greetings in the marketplaces, and the title of ‘Rabbi’ by which they are addressed.'),
('MAT', 23, 8, 'MAT.23.8', 'But you are not to be called ‘Rabbi,’ for you have one Teacher, and you are all brothers.'),
('MAT', 23, 9, 'MAT.23.9', 'And do not call anyone on earth your father, for you have one Father, who is in heaven.')
) as x(osis, chapter, verse, ref, body)
join public.books b on b.osis_code = x.osis
join public.bible_versions v on v.id = b.version_id and v.code = 'BSB'
join public.chapters c on c.book_id = b.id and c.number = x.chapter
on conflict (chapter_id, number) do update set osis_ref = excluded.osis_ref, text = excluded.text;
